// ===== PMBOK 第8版 + 敏捷实践指南 知识内容库 =====
// 基于PMBOK第8版原文和敏捷实践指南提取
// 共76个节点：6原则 + 7域 + 5关注领域 + 43过程 + 15敏捷概念
// 每个节点包含3000-5000字符的完整教材内容（要点式+ITTO完整展开）

const KNOWLEDGE_CONTENT = {
  "principle-global-view": {
    overview: `"采用整体视角"是PMBOK第8版十二大项目管理原则之一（对应"识别、评估和响应系统交互"）。该原则要求，在理解和管理项目时，应将所有组件及其相互依赖关系作为更大系统的一部分进行考量。这种视角与系统思维的理念相契合，后者强调项目内各要素之间的关联性，而非孤立地看待每一个部分。

- **系统交互**：项目不是独立运转的孤岛，而是更大组织系统、社会环境的一部分；系统内部及系统之间持续发生交互，这些交互可能带来正面或负面的影响。
- **整体视角**：将项目视为一个相互关联的整体，洞察动态图景而非静态"切片"；局部优化未必带来整体最优，甚至可能损害项目整体价值。
- **整体大于部分之和**：系统的整体表现取决于各要素之间的相互作用方式，而非单个要素的独立表现；识别涌现属性和反馈回路，才能把握项目的真实状态。

采用整体视角对于管理项目复杂性至关重要，它能够帮助项目经理把握整体状况和不同项目组件之间的联系，精确地定位挑战的根本原因并高效应对。同时，将项目视为统一的整体，可更容易追溯问题根源，从而采取跨学科的方法，催生更具创新性和更高效的解决方案。`,
    details: {
      "📊 对项目管理的影响": `在项目管理中应用整体视角，可产生更加整合、更具协同性的实践方法，以实现项目目标。以整体视角管理项目，其主要特征包括：

- **与组织战略和目标保持一致**：项目更有可能为组织的战略目标做出积极贡献；整体视角帮助团队看清项目在组织战略组合中的位置，避免项目偏离组织方向。
- **整合式决策机制**：决策过程需要考虑整个项目生态系统内的不同观点，综合平衡范围、进度、成本、质量、风险等多维信息，确保输出能够带来更可持续且有效的成果，避免"头痛医头、脚痛医脚"式的局部修正。
- **高效的沟通体系**：在所有利益相关方之间进行清晰且一致的沟通，有助于确保每个人都了解情况并保持一致；整体视角要求建立畅通的信息流，使各方都能看到全局。
- **管理不确定性和复杂性**：在不确定性高的项目中，整体视角有助于在规划和执行中纳入相应技术，以渐进方式识别不确定性来源，化解可能损害项目价值主张的威胁。
- **主动且务实的风险管理**：通过从一开始就建立整体视角，项目管理团队能够更广泛、更清晰地理解项目的相互关联，从而高效地化解威胁并把握机遇。
- **防止范围蔓延和执行偏差**：整体视角要求团队明确每一项工作的边界及其与项目目标的关系，从系统层面遏制无计划的变更，确保变更服务于项目整体价值。`,
      "🤝 与其他原则的相互作用": `"采用整体视角"原则能够与所有项目管理绩效域相互作用，并提高这些绩效域的整体绩效。通过应用该原则，可更有效地管理各个绩效域，也有助于确保项目管理应用协同、整合的方法。

- **干系人绩效域**：系统思维要求把干系人及其诉求纳入整体系统看待，理解各干系人之间的相互影响，从而提升所有利益相关方的参与度。
- **团队绩效域**：整体视角下的团队成员被视为协作系统中的一环，跨职能、跨组织的协同有助于应对复杂问题。
- **开发方法和生命周期绩效域**：选择何种开发方法取决于项目所处系统环境的特性，整体视角为方法选择提供依据。
- **规划绩效域**：规划时考虑相互依赖关系，可提高进度计划的合理性，使计划更贴合系统的真实运行方式。
- **项目工作绩效域**：推动已完成工作的流动，避免不必要的资源冲突，提高项目执行的协同性。
- **交付绩效域**：从系统层面定义"完成"，确保可交付物在更大背景下真正满足需要。
- **测量绩效域**：测量指标应反映系统整体状态，而非孤立的局部指标。
- **不确定性绩效域**：通过识别和管理所有绩效域中的风险，实现主动的风险管理，应对系统层面涌现的不确定性。

此外，该原则与"聚焦于价值""驾驭复杂性""优化风险应对"等原则紧密相关：整体视角是识别复杂性和风险相互作用的前提，也是确保价值不被局部决策侵蚀的基础。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素**：
  - **系统思维的文化**：组织倡导从整体角度分析问题，鼓励识别组件间关联，为整体视角提供土壤。
  - **跨职能、跨部门的协作环境**：团队成员来自不同职能领域并愿意共享信息，使系统全貌得以呈现。
  - **透明的信息与沟通**：开放、及时、一致的信息流使各方能够看到全局，及时发现系统中的不协调。
  - **高层级组织的支持**：发起人、高层领导理解系统思维的价值，愿意为全局视角的决策提供资源。
  - **对动态性和涌现性的认知**：团队接受项目状态是动态变化的，不断重新评估系统交互。
- **阻碍因素**：
  - **部门孤岛与职能壁垒**：各部门仅关注自身局部目标，信息不共享，导致决策缺乏全局视野。
  - **短期业绩导向**：过分强调局部或短期目标，忽视长期、全局价值，导致局部优化损害整体。
  - **信息不对称**：关键信息滞留在少数人手中，团队无法获得系统的完整图景。
  - **抵制变革与僵化流程**：僵化的流程和管理制度抑制跨领域协同，使整体优化难以落地。
  - **只见树木不见森林**：管理者陷入局部细节，忽视系统的整体状态与相互影响。`,
      "✂️ 裁剪考虑": `- **项目规模与复杂度**：大型、跨部门、跨组织项目通常具有更多系统交互，更需要显式应用整体视角，投入更多精力进行系统分析；小型项目可以简化，仅在关键接口处考虑关联。
- **开发方法**：预测型项目中，整体视角体现在前期全面的整合规划与基线控制；敏捷型项目中，整体视角体现在对产品整体价值流和系统架构的持续关注；混合型项目需在两种形态间平衡。
- **行业与领域**：工程、基础设施等强依赖物理接口的行业，系统交互分析（如接口管理）至关重要；软件开发等行业则更关注组件间的逻辑与数据依赖。
- **组织结构**：矩阵型、项目型组织中权责边界不同，裁剪时应调整沟通与决策机制，确保整体视角贯穿其中。
- **干系人环境**：当干系人众多且诉求多元时，整体视角下的沟通与参与策略需要针对性裁剪。
- **项目组合与项目群环境**：在项目组合与项目群环境中，项目间的资源争夺与依赖更显著，整体视角要求项目经理关注项目之外的组织级交互。
- **裁剪本身即系统思考**：裁剪决策也应基于整体情境，而非照搬模板。`,
      "💼 实践案例": `为说明"采用整体视角"原则的实际应用，以某非营利性组织为例。该组织正在启动一个在社区推广公共卫生实践的项目，并由一支专业志愿者团队提供支持。

- 若采用传统的、单一视角的方法，项目将侧重于制作科普材料、组织相关活动，只关注项目内部的交付物。
- 然而，在项目推进过程中，该组织获悉，当地政府发起了一项目标相近的举措，并为协同一致的工作提供专项资金支持。
- 项目团队意识到，此举能大幅提高项目的影响力，于是调整沟通策略，以主动与政府举措保持一致，最终成功获得该笔资金。
- 尽管引入了更为严格的政策和沟通约束，但该项目拥有了更多的资源和更广的覆盖范围，使该组织能够对社区公共卫生产生更显著、更持久的影响。

这个案例说明：采用整体视角意味着跳出项目本身，审视项目所处的更大系统（政府、社区、政策环境），识别并利用系统间的协同机会，从而放大项目价值。`,
    },
    keyConcepts: `- **系统思维**：一种把对象视为由相互关联组件构成的整体的思维方式，强调组件间关系与反馈回路，是"采用整体视角"的理论基础。
- **整体视角**：从全局角度看待项目，将各组件、各绩效域、干系人和组织环境作为一个相互作用的整体来理解和管理。
- **相互依赖关系**：项目各组件（范围、进度、成本、质量、资源、风险等）之间以及项目与外部系统之间相互影响的联系。
- **涌现属性**：系统作为一个整体所表现出的、各组成部分单独不具备的新特性，是整体视角必须关注的对象。
- **局部优化**：仅改进系统中某一组成部分而忽视其对整体的影响，往往导致整体绩效下降，是整体视角需要避免的做法。
- **反馈回路**：系统内某组件的变化引发连锁反应并最终反作用于自身的机制，理解反馈回路有助于预测变更的影响。
- **动态图景**：项目状态随时间和交互持续变化，整体视角要求不断更新对系统全貌的认识，而非只看静态快照。`,
    examTips: `- **与所有绩效域相互作用**：考试中常问"该原则影响哪些绩效域"，答案是全部绩效域（干系人、团队、开发方法和生命周期、规划、项目工作、交付、测量、不确定性）。
- **情景题识别标志**：题干中出现跨领域、跨部门、跨组织的问题，或"多个组件相互影响""应从全局看问题"等表述时，应选择"整体视角/系统思维"。
- **系统思维是核心概念**：不要孤立地看待项目问题，要寻找各组件之间的相互依赖关系；"局部优化反而损害整体"是常见出题点。
- **常见陷阱**：将整体视角错误理解为"把所有细节都管起来"；或将"关注全局"与"忽视细节"混为一谈——整体视角是把握关键联系，而非事无巨细。
- **与其他原则区分**：识别系统交互（整体视角）强调"看清关联"，而"驾驭复杂性"强调"应对混乱与不可预测"，出题时注意分辨侧重。`
  },
  "principle-focus-value": {
    overview: `"聚焦于价值"是PMBOK第8版十二大项目管理原则之一。价值（又被称为项目价值）是衡量项目最终成功的核心指标和驱动因素。该原则要求项目团队始终围绕价值的创造与交付开展全部工作，而不是仅仅满足于交付规定的可交付物。

- **价值的定义**：价值可以通过可衡量的指标（如投资回报率）或定性观察（如客户口碑、社会效益等）来描述和评估；它体现了项目成果的整体价值及其为利益相关方带来的净收益。
- **价值的载体**：价值涵盖了可交付物及其相关成果，尤其要从关键利益相关方的视角来看；价值形式多种多样，包括对发起组织或接收组织的财务贡献、社会效益或客户对项目结果的感知收益。
- **价值与成本的关系**：无论形式如何，所有项目存在的目的都是追求特定的组织目标，其价值必须超过为实现这些目标所投入的成本，并且通常远高于其他投资方案可能带来的收益。
- **价值的动态性**：价值不是静态的，需要在整个项目生命周期中持续重新评估和更新。

项目论证和组织战略（通常在业务论证中详述）为项目团队提供了必要的信息，使其能做出符合或超出预期商业价值的决策。在整个项目生命周期中，应通过质量门、反馈循环和定期评审，对预期成果进行清晰描述、迭代评估和持续更新。项目团队需要适应变更，并持续评估其与预期输出、基准、业务论证和预期成果的一致性。若偏差持续存在或项目难以实现预期价值，终止该项目或为最佳选择。`,
    details: {
      "📊 对项目管理的影响": `将关注点从可交付物转向预期成果，能使项目团队实现项目愿景或目标，而非仅交付特定的可交付物。虽然可交付物可能支持预期项目成果，但未必能完全实现项目愿景或目标。例如，客户可能需要一款特定的软件，因为他们相信该软件能提高生产力，从而满足业务需要。该软件虽属于项目的输出，但其本身并不能提高生产力。若增加新的可交付物（如软件使用培训），则可实现更高价值的成果。若项目的输出未能实现预期的生产力提高，那么项目的价值主张将大打折扣，考虑到投入的时间和资源，甚至可能导致整个项目弊大于利。因此，项目团队、利益相关方，尤其是团队成员必须同时理解可交付物及其预期成果。

聚焦于价值对项目管理实践的影响还体现在：

- **价值驱动的决策**：每一项决策都以"是否创造或保护价值"为判断标准，范围、进度、成本、风险的权衡都服务于价值最大化。
- **成果导向的范围管理**：范围定义以预期成果而非"功能清单"为出发点，必要时增加或削减可交付物以达成成果。
- **持续的价值评估**：通过定期评审、反馈循环和质量门，不断验证项目是否仍在创造价值，及时纠偏。
- **价值敏感的风险管理**：在评估威胁与机遇时，重点关注对项目价值主张影响最大的不确定性。`,
      "🤝 与其他原则的相互作用": `"聚焦于价值"原则与所有项目管理绩效域的实践相互作用、相互提升。

- **干系人绩效域**：有助于理解利益相关方的需要和期望，将价值感知纳入参与策略，确保各方认可项目带来的收益。
- **团队绩效域**：明确的价值目标凝聚团队共识，使团队成员理解自己工作与最终价值的关系。
- **开发方法和生命周期绩效域**：迭代、增量交付与定期价值评估天然契合，有助于持续调整以逼近价值目标。
- **规划绩效域**：计划以价值交付为主线，价值目标成为进度、成本、范围计划对齐的基准。
- **项目工作绩效域**：所有项目工作围绕价值创造来组织，避免低价值的忙碌。
- **交付绩效域**：交付物及成果的验收以"是否实现预期价值"为准绳。
- **测量绩效域**：价值相关指标（如ROI、客户满意度）成为衡量绩效的重要维度。
- **不确定性绩效域**：有助于确保在应对项目不确定性时所采用的方法是切实可行的，避免为了"稳妥"而牺牲价值。

与其他原则的关系：价值是"整体视角"下判断系统优化方向的标尺；"将质量融入过程和可交付物"是保障价值不被返工和缺陷侵蚀的基础；"聚焦于价值"与"优化风险应对""为实现预期的未来状态促成变革"相辅相成，均服务于组织的战略价值目标。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素**：
  - **清晰的业务论证**：定义明确的目标、预期成果和衡量标准，为团队提供价值判断的依据。
  - **干系人价值共识**：关键干系人对"什么是有价值"有统一认识，减少价值理解的分歧。
  - **定期价值评审机制**：通过质量门、反馈循环和定期评审，使价值评估成为例行实践。
  - **组织对项目终止的开放态度**：组织允许并支持在价值不可实现时及时止损，避免沉没成本思维。
  - **与组织战略对齐**：项目组合管理和项目管理办公室（PMO）将项目与战略价值挂钩，为项目提供方向支撑。
- **阻碍因素**：
  - **沉迷于交付可交付物**：团队以"完成交付物"为成功标准，忽视成果是否创造价值。
  - **业务论证不清晰或过时**：缺乏明确价值定义，或业务论证未随环境变化更新，团队无所适从。
  - **干系人价值诉求冲突**：不同干系人对价值的期望相互矛盾，难以达成一致。
  - **沉没成本谬误**：因前期投入过大而不愿终止项目，持续投入却无法实现价值。
  - **短期指标压力**：组织过度关注短期财务指标，挤压长期价值创造的空间。`,
      "✂️ 裁剪考虑": `- **价值类型与衡量方式**：商业项目中价值多以ROI、NPV、IRR等财务指标衡量；政府与社会项目中价值更侧重社会效益、公共福祉；裁剪时需选择合适的价值度量。
- **项目生命周期长短**：短期项目价值相对明确，可在启动阶段一次定义；长期项目价值随环境演化，需在整个生命周期内迭代评估、持续更新业务论证。
- **开发方法与反馈频率**：敏捷项目中价值通过增量交付与迭代评审快速验证；预测型项目需通过阶段性评审（阶段关口）评估价值实现情况。
- **组织环境与治理**：矩阵型、职能型等不同治理结构下，价值决策的路径不同，需根据组织的治理结构裁剪。
- **价值的时间维度**：项目可能追求近期价值（如快速回款）或长期价值（如战略卡位），裁剪时明确价值的时间偏好并据此安排交付节奏。
- **不确定程度**：高不确定项目中，价值评估应更频繁、更渐进，采用"小步快跑"的方式验证价值假设。`,
      "💼 实践案例": `为说明"聚焦于价值"原则的实际应用，以某公司正在启动内部新技术系统的推广项目为例。

- 传统方法可能侧重于选择性价比最高的产品，再通过定制化来满足所有利益相关方的需求，把"产品交付"当作项目成功。
- 与之相对，聚焦于价值的方法则将项目目标与业务成果挂钩，例如使系统的使用率和普及率最大化——这才是真正创造价值的目标。
- 在深入剖析后可发现，该企业奉行快节奏的组织文化，更看重体验的简洁性而非功能的复杂性。
- 通过精简功能和定制化，更简化的解决方案反而能更好地契合组织文化，从而提高整体使用率和满意度，使项目真正实现了其业务价值。

这个案例说明：聚焦于价值要求项目团队明确"为什么要做这个项目"，以预期成果（使用率、满意度）而非"交付了什么"作为成功标准，并在范围与设计上做出相应取舍。`,
    },
    keyConcepts: `- **价值**：项目为组织、干系人和客户带来的净收益，是衡量项目最终成功与否的核心指标。
- **预期成果**：项目交付后希望达成的业务或社会结果（如生产力提升、使用率提升），与"可交付物"相对。
- **可交付物**：项目产生的有形的中间或最终产品（如软件、文档），是手段而非目的。
- **业务论证**：阐述项目为什么值得投入的文档，包含商业需要、目标、预期收益、成本与可行性分析，是价值决策的核心依据。
- **投资回报率（ROI）**：衡量项目收益相对投入的比率性财务指标。
- **净现值（NPV）**：将未来现金流折算为现值后的净额，大于零表明项目值得投资。
- **内部收益率（IRR）**：使项目净现值为零的折现率，反映项目投资的回报水平。
- **质量门/阶段关口**：在关键节点对项目是否继续投入进行评估的检查点，是持续评估价值的重要机制。
- **价值驱动**：以价值为导向进行决策和管理，而非以交付任务为导向。`,
    examTips: `- **区分"可交付物"与"预期成果"**：聚焦于价值意味着关注成果而非仅仅是输出的完成；软件本身不是价值，软件带来的生产力提升才是价值。
- **业务论证是价值决策的核心文件**：当项目与业务论证出现偏差时，应回归业务论证审视是否需要调整范围或终止项目。
- **终止项目可能是最佳选择**：当项目无法实现预期价值时，终止项目是负责任的决策——PMP情景题中经常出现，切勿选择"继续坚持"。
- **价值衡量手段多样**：既可以通过ROI、NPV、IRR等财务指标，也可以通过客户满意度、社会效益、品牌口碑等定性指标衡量。
- **常见陷阱**：将"按时、按预算交付"等同于项目成功；忽视价值的动态性，认为价值一经确定便不再变化；为沉没成本所困而不愿止损。`
  },
  "principle-quality": {
    overview: `"将质量融入过程和可交付物"是PMBOK第8版十二大项目管理原则之一。质量是指项目可交付物或过程的一系列固有特性满足或超出项目预期目标的程度。该原则的核心思想是：质量不是靠事后检查"检查"出来的，而是通过优良的过程"融入"产品和交付物之中的。

- **质量的融入**：在达到或超过既定效率目标的前提下，能够自然而然地满足客户和利益相关方明确或隐含的需要。
- **质量的对象**：既包括可交付物本身的质量，也包括实现可交付物的过程的质量；通过验收标准、完成的定义（DoD）、适用性和整体效率等维度进行衡量。
- **质量临界值**：质量临界值通常针对范围规范，但也可以应用于进度和成本，尤其适用于那些价值主张可能对这些因素高度敏感的项目。
- **持续改进**：采用持续改进的思维方式可以优化过程，提高效率，提升整个组织的成熟度，从而改善当前和未来项目的成果，助力组织的全面成功。
- **消除浪费**：将目标质量临界值融入过程的基础在于持续改进和消除浪费，使项目团队能够优化过程，提升资源利用率，并交付达到或超过预期目标的成果。

质量涵盖多个维度，既适用于可交付物也适用于过程，包括但不限于：绩效（是否按预期运作）、符合性（是否符合规范并适合使用）、可靠性（是否保持必要的一致性）、韧性（能否应对意外故障并快速恢复）、满意度（能否获得有价值的反馈）、一致性（在其他类似输出中是否表现一致）、效率（是否以最少投入实现最多产出）、可持续性（是否对经济、社会和环境产生积极贡献）和合规性（是否符合监管要求）。`,
    details: {
      "📊 对项目管理的影响": `质量活动的目标是确保可交付物符合客户和其他利益相关方的预期目标。其宗旨在于最大限度地减少资源浪费，同时提高实现预期成果的概率。此举将带来以下效果：

- 将可交付物顺利推进至交付节点，避免不必要的延误；
- 通过早期识别和预防缺陷，最大限度地减少返工需求和/或材料浪费。

无论面对的是前期已明确定义的需求集，还是渐进明细、增量交付的需求集，质量活动的目标始终如一。

质量管理流程与实践有助于产出符合项目目标的可交付物和成果。密切关注项目过程和可交付物的质量，能带来以下积极成果：

- **确保项目可交付物符合预定用途**：可交付物真正满足客户需要，达到"适用性"标准。
- **按时交付，强化成本控制**：质量稳定减少延误与返工，进度与成本更可预测。
- **减少返工、报废、客户投诉和其他形式的浪费**：质量成本总体下降，资源用于真正创造价值的工作。
- **实现高效的供应链整合**：与供应商的质量协同减少接口问题。
- **提高项目团队的士气和满意度**：少做返工、多出成果，团队成就感更高。
- **减少对环境的负面影响**：减少报废与资源浪费，支持可持续性。
- **实现更优的决策和持续的过程改进**：基于质量数据的决策更可靠，过程持续优化。`,
      "🤝 与其他原则的相互作用": `"将质量融入过程和可交付物"原则在所有项目管理绩效域中都至关重要。该原则应贯穿于项目的人员、过程和结构设计。不同的行业、企业和情境，有不同的质量管理方法，但在所有绩效域中，对达成恰当质量水平的承诺是所有项目实现成功成果的内在要求。在任何绩效域中，若缺乏对恰当质量水平的承诺，都将导致最终结果受损和项目成果不佳。具体而言：

- **干系人绩效域**：满足干系人明确与隐含的质量期望，是有效参与和满意度的基础。
- **团队绩效域**：团队对"完成的定义（DoD）"的共识，是质量融入交付流程的关键。
- **开发方法和生命周期绩效域**：迭代交付中每个增量都需满足质量门槛，DoD在敏捷中尤为核心。
- **规划绩效域**：将质量目标、质量标准和验收标准纳入规划，是质量管理的前提。
- **项目工作绩效域**：质量保证（QA）融入项目工作流程，确保过程合规、预防缺陷。
- **交付绩效域**：质量控制（QC）验证可交付物符合标准，DoD与验收标准是交付把关的依据。
- **测量绩效域**：质量指标（缺陷率、返工率、客户满意度）是绩效测量的重要组成部分。
- **不确定性绩效域**：质量管理减少由缺陷引发的不确定性与风险。

与其他原则的关系：质量是"聚焦于价值"实现的前提——低质量交付会侵蚀价值主张；持续改进体现"拥抱适应性和韧性"的精神；质量临界值的设定需结合"整体视角"在范围、进度、成本之间进行权衡。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素**：
  - **清晰的质量标准与验收标准**：在项目早期明确定义质量标准，使团队有据可依。
  - **完成的定义（DoD）共识**：团队对"怎样才算完成"达成一致，避免隐性质量门槛。
  - **持续改进文化**：组织鼓励识别浪费、优化过程，将质量改进视为常态。
  - **质量工具的应用**：运用统计过程控制、根本原因分析、PDCA循环等工具，用数据驱动质量改进。
  - **干系人的质量共识**：客户与干系人明确表达质量期望，避免后期分歧。
- **阻碍因素**：
  - **进度压力优先**：为赶进度而压缩质量活动（跳过评审、测试），导致缺陷后移。
  - **只检查不预防**：把质量工作简化为事后检查，忽视预防和过程改进，返工成本高。
  - **质量标准缺失或模糊**：验收标准不明确，导致交付争议与返工。
  - **忽视过程质量**：只关注最终产品是否"差不多"，忽视过程缺陷的蔓延效应。
  - **团队缺乏质量技能**：缺乏质量工具与方法的培训，质量活动流于形式。`,
      "✂️ 裁剪考虑": `- **行业与监管要求**：医疗、制药、航空等行业受严格监管，质量与合规标准必须严格遵守并形成文档证据；软件开发等行业可更多依赖自动化测试与持续集成来保障质量。
- **开发方法**：预测型项目中，质量通过前期需求定义、阶段评审与检验把关；敏捷型项目中，质量通过DoD、迭代评审、自动化测试与持续重构融入每个增量；混合型项目需平衡两种质量机制。
- **项目规模与复杂度**：大型项目的质量体系更正式（质量计划、质量保证审计）；小型项目可精简为关键检查与评审活动。
- **可交付物类型**：实物交付物（如建筑）需物理检验与验收；知识型交付物（如咨询报告、软件）需评审、测试与干系人确认。
- **风险暴露程度**：高风险、高价值的项目需投入更严格的质量保证与更频繁的质量控制活动。
- **质量标准的适用层级**：企业标准、行业标准与项目专属标准并存时，需裁剪确定适用的标准组合。`,
      "💼 实践案例": `为说明"将质量融入过程和可交付物"原则的实际应用，以某公司计划扩展的批发运输服务为例。

- 传统方法通常侧重于满足每个目标市场的政府运输规范，并确保符合监管要求，把"合规"当作质量的终点。
- 与之相对，质量驱动的方法将引导人们探究更广泛的利益相关方群体（包括目标分销商和零售商）的期望。
- 这种更深入的分析可能揭示：高价值客户的标准往往比监管机构更为严格，这将影响包装设计、交付时间或产品处理方式。
- 通过满足这些更高的标准，企业不仅能符合法律要求，更能超出客户期望，从而以更强的姿态进入市场。

这个案例说明：质量不仅意味着"符合规范"，更意味着"满足并超越干系人期望"。将质量融入过程（包装、交付、处理流程的设计）而非仅检查结果，能带来竞争性优势。`,
    },
    keyConcepts: `- **质量**：可交付物或过程的一系列固有特性满足或超出项目预期目标的程度。
- **完成的定义（DoD）**：敏捷环境中团队一致认可的"可交付物达到可验收状态"的标准清单，是质量融入交付的载体。
- **验收标准**：可交付物被接受所必须满足的条件，是质量衡量的直接依据。
- **适用性**：可交付物满足客户实际用途需求的程度，是质量的核心维度之一。
- **质量保证（QA）**：关注过程，通过审计过程、确保过程合规来预防缺陷，属于过程导向。
- **质量控制（QC）**：关注产品，通过检验、测试可交付物来发现和纠正缺陷，属于产品导向。
- **持续改进**：通过PDCA循环等机制不断优化过程、消除浪费、提升效率的组织实践。
- **消除浪费**：识别并移除不增值的活动（如返工、等待、过度处理），是质量改进的基础。
- **质量的九个维度**：绩效、符合性、可靠性、韧性、满意度、一致性、效率、可持续性、合规性。`,
    examTips: `- **DoD（完成的定义）是敏捷中质量的关键概念**：考试常考"团队如何确保增量达到可交付状态"，答案是依据DoD；DoD由团队共识制定，并随团队与项目演进。
- **预防胜于检查**：质量是"融入"而非"检查出来"的；关注过程（QA）以预防缺陷，比事后检验（QC）更有效、更节省成本。
- **质量的九个维度**：绩效、符合性、可靠性、韧性、满意度、一致性、效率、可持续性、合规性可能出现在考题中，需能识别对应场景。
- **QA与QC要区分清楚**：质量保证（QA）关注过程、预防缺陷；质量控制（QC）关注产品/结果、发现缺陷——两者对象不同，考试常设混淆陷阱。
- **常见陷阱**：把质量简单等同于"符合验收标准"而忽略干系人隐含期望；为赶进度削减质量活动；认为"敏捷不需要质量计划"——敏捷同样需要质量融入，只是机制不同。
- **质量成本（COQ）**：预防成本、评估成本、失败成本的关系是潜在考点——预防投入越多，失败成本越低。`
  },
  "principle-responsible-leader": {
    overview: `【原则定位】“成为负责任的领导者”原则强调：项目经理对项目及其结果负有根本责任，既要勇于担当，又要对项目的既定业务目标，以及自己所采取的行动和做出的决策负责。负责任的领导力是一种以诚信和担当为基础的持续行为方式，而非一个可以随意开启或关闭的角色。

【项目对领导力的独特需求】与角色和职责既明确且固定的常规业务运营不同，项目往往涉及多个不经常互动的组织、部门、职能机构或供应商，而且项目可能比日常运营承担更高的风险和更多的期望。因此，项目更依赖有效的领导力来凝聚各方力量、协调各方目标。

【关键特征（一）诚信、正直与公正】这是所有团队成员都应具备的价值观。秉持诚信与公正的领导者所做的决策着眼于共同利益，有助于与利益相关方建立信任。

【关键特征（二）自我认知】有效的领导者能通过理解自身动机、价值观和优势，将情感、思想与行动有机结合，避免因个人偏见而损害决策质量。

【关键特征（三）尊重、谦逊与开放】领导者应乐于接受反馈，为团队服务，支持其需求并尽可能清除障碍，这些价值观构成了服务型领导力理念的基础。

【关键特征（四）灵活性与适应性】领导者应具备根据情境和对象调整其领导力风格的能力，即情境领导力。

【关键特征（五）共享领导力】领导力并非任何特定角色所独有，高绩效项目的特点是多人共同运用领导力技能，在不同阶段由最合适的人承担领导职责。

【领导力有别于职权】职权是组织授予个人的控制权，而领导力则表现为通过以身作则来激励和鼓舞他人。拥有职权的人未必是有效的领导者。`,
    details: {
      "📊 对项目管理的影响": `- **塑造团队协作模式**：作为领导者，项目经理以其自身言行影响项目中的所有专业人员。项目经理综合运用领导力、有效沟通、决策制定、情商、问题解决、争取利益相关方参与和战略思维，来对项目和团队施加影响，其领导风格直接塑造团队的协作模式，激发积极性并左右整体绩效。

- **领导风格因情境而异**：不存在放之四海而皆准的最佳风格。常见的领导风格包括指导式、指挥式、参与式、支持式与教练式等。负责任的领导者会根据团队成熟度、任务紧迫性、风险水平与干系人期望，在不同风格之间灵活切换。

- **情商化解冲突与压力**：情商使项目经理能够觉察并管理自己与他人的情绪，从而化解冲突和压力；高情商的领导者更容易建立信任、凝聚团队并做出冷静理性的决策。

- **利益相关方深度参与**：有效的领导者善于识别关键干系人、理解其利益与期望，并通过及时透明的沟通获得支持与认同，减少项目实施中的阻力。

- **创造超出项目本身的价值**：负责任的领导者不仅交付成果，还致力于促进身边其他领导者的成长，并在自身影响范围内产生积极影响。

- **全面提升项目绩效**：该原则对项目经理和所有利益相关方有着深远且多元的影响，具体表现为：提高团队绩效、增强信任和士气、优化决策制定、增强利益相关方的信心、增强应对挑战的韧性。

- **支持七大绩效域**：在治理方面确保决策过程透明且合乎道德；在范围方面直面并化解范围分歧，促使干系人就项目的价值主张达成共识；在进度方面确保协作讨论包含所有参与方；在财务方面既不忽视也不草率处理财务考量；在利益相关方方面善于影响干系人和项目发起人；在资源方面以责任感和正直的品格管理资源；在风险方面灵活应对项目团队面临的机会或威胁。`,
      "🤝 与其他原则的相互作用": `- **与聚焦价值原则相互成就**：负责任的领导者把价值创造作为决策的终极标准，在范围、进度、成本与质量之间取舍时始终追问什么对组织最有价值，从而使聚焦价值落到实处。

- **与有效干系人参与原则相互支撑**：领导者通过影响力与沟通来争取干系人参与，而深入、真诚的干系人参与反过来又为领导决策提供信息与合法性支持，形成良性循环。

- **与构建赋能型文化原则相辅相成**：服务型领导是赋能文化的引擎，领导者为团队清除障碍、提供支持；被赋能的团队又放大领导者的影响，使领导力真正实现共享而非集中于一人。

- **与识别、评估并响应系统交互原则协同**：负责任的领导者以整体视角看待项目，理解组织、团队与干系人之间的相互依赖关系，其决策才能兼顾全局而不是顾此失彼。

- **与基于上下文裁剪原则呼应**：情境领导力本身就是基于上下文裁剪在领导层面的体现，领导方式必须依据项目环境、团队情况和干系人需求进行调整。

- **与尽责、尊重与关爱的管家原则一致**：负责任的领导者与尽责的管家都以诚信、尽责与对他人的尊重为行为基石，共同确保组织资源的妥善运用。

- **与将可持续性融入所有项目领域原则衔接**：负责任的领导者在做长期决策时必须考虑环境与社会影响，将可持续性纳入其判断标准，避免以短期利益损害长期责任。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素——组织授权与信任**：组织赋予项目经理与其职责相匹配的决策空间，高层信任并支持项目经理，是领导者发挥影响力的前提。

- **帮助因素——明确的价值观与伦理框架**：组织拥有清晰的行为准则和伦理规范时，领导者更容易做出诚信、公正的决策。

- **帮助因素——高情商的个人素养**：领导者具备自我觉察、自我管理、同理心和社会技能，能更有效地化解冲突与压力。

- **帮助因素——多样化的团队构成**：多元背景的团队成员带来丰富视角，为领导决策提供更多信息与备选方案。

- **帮助因素——教练辅导与反馈文化**：组织鼓励教练式辅导和及时反馈，领导者能够据此持续改进自身行为。

- **阻碍因素——命令控制式文化**：以职权压制而非以身作则的文化会扼杀信任，使团队成员不敢建言、不愿承担。

- **阻碍因素——角色与职责模糊**：各方权责不清时，领导者难以推动决策，容易出现推诿、越权和冲突。

- **阻碍因素——短视的考核指标**：若只考核短期产出而不评估长期影响，领导者会被迫做出短视甚至损害利益的决策。

- **阻碍因素——组织政治与派系**：派系斗争消耗领导者的精力与信任资本，使其难以凝聚团队。

- **阻碍因素——缺乏反馈机制**：没有畅通的反馈渠道，领导者无法及时发现自己行为对团队造成的负面影响，也难以成长。`,
      "✂️ 裁剪考虑": `- **按开发方法裁剪**：预测型项目中，领导者可能更多采用指导与决策方式；敏捷项目中更强调服务型领导与教练式辅导，让团队自组织；混合型项目则需在两者之间灵活切换。

- **按团队分布裁剪**：对分布式或虚拟团队，领导者需加强结构化沟通、定期同步与虚拟团队建设，以弥补面对面交流的缺失。

- **按项目复杂度与风险裁剪**：复杂、高风险项目需要更主动的决策与更频繁的方向校准；低风险常规项目则可适当放权。

- **按干系人成熟度裁剪**：面对经验丰富的发起人与干系人，领导者更多扮演协调与顾问角色；面对缺乏经验的干系人则需更多引导和解释。

- **按组织文化裁剪**：在层级分明、流程严谨的组织中，领导方式需更注重程序与合规；在扁平开放的组织中则可更多采用参与式决策。

- **按发展需求裁剪**：可裁剪领导力培养方式，如导师制、教练辅导、360度反馈与复盘，使其与个人和团队的发展阶段相匹配。`,
      "💼 实践案例": `【案例：跨供应商冲突的化解】某大型政府项目涉及多家供应商，项目团队因先前商定的轮班安排产生冲突。传统做法通常侧重于强制执行合同约定的劳动政策，并要求各供应商自行化解员工的不满。而应用“成为负责任的领导者”原则后，项目经理主动发起一系列跨供应商的讨论，探究冲突的根本原因，并推动各方就轮班安排的调整方案达成共识。这种协作方式不仅化解了眼前的冲突，更消除了可能损害质量和生产力的摩擦，打造出更具凝聚力和积极性的项目团队。启示：负责任的领导者在冲突中优先寻找根本原因与共同方案，而非单纯依赖合同条款与强制手段，最终为项目创造了超越交付成果的长期价值。`,
    },
    keyConcepts: `- **负责任的领导力**：以诚信和担当为核心，对项目目标、行动与决策负责的行为方式，是项目成功的关键驱动因素。

- **服务型领导力**：优先为团队服务、支持其需求并清除障碍，使团队能够自主高效工作的领导理念，是敏捷环境的核心理念。

- **情境领导力**：根据团队成熟度、任务性质与具体情境灵活调整领导风格的能力。

- **情商（Emotional Intelligence）**：识别、理解并管理自己及他人情绪的能力，是领导者化解冲突与压力的关键能力。

- **共享领导力**：领导力并非特定角色专属，高绩效项目中由多人根据情境共同承担领导职责。

- **领导力与职权**：职权是组织授予的控制权；领导力是通过以身作则激励和鼓舞他人，二者可以分离。

- **诚信、正直与公正**：领导者着眼于共同利益做决策的价值观基石，有助于与干系人建立信任。

- **自我认知**：理解自身动机、价值观与优势，使情感、思想与行动保持一致。

- **韧性**：领导者面对挫折时的恢复与适应能力，可带动团队共渡难关。

- **教练式辅导**：通过提问与引导而非直接指示，帮助团队成员成长并自主解决问题。`,
    examTips: `- **高频考点——领导力不等于职权**：题干描述某人拥有职权但团队不愿跟随，应选择以身作则赢得信任的选项，而不是行使职权强制执行。

- **敏捷核心理念是服务型领导**：情景题中团队遇到障碍时，项目经理的正确做法是为团队清除障碍、提供支持，而非下达命令。

- **情境领导力是原则性要求**：出现调整领导风格以适应团队的表述时，通常对应“成为负责任的领导者”原则。

- **情商是化解冲突的关键**：当情景题涉及团队冲突或压力时，优先选择体现觉察与管理情绪的选项。

- **共享领导力**：题干强调不同成员在不同阶段担任领导角色时，对应共享领导力，不要误判为权力下放失控。

- **识别正确行为**：负责任的领导者面对分歧时会发起对话、探究根本原因、促成共识，而非直接惩罚、回避或强行执行合同条款。

- **与全部绩效域互动**：该原则与所有7个绩效域都相互作用，情景题中出现跨领域问题时，往往需要领导者以整体视角统筹协调。`
  },
  "principle-sustainability": {
    overview: `【原则定位】“将可持续性融入所有项目领域”原则旨在既满足当前需要，又不损害子孙后代满足其自身需要的能力。它可能涉及负责任地采用技术以开创更美好的未来，同时系统性地识别并减轻项目对组织、社区和环境的任何不利影响。

【可持续性金字塔】项目应制定应对各类外部影响的策略，并按影响程度递增排列为“可持续性金字塔”：补偿负面后果 → 减轻负面后果 → 完全避免负面后果。越往上策略越积极，对长期价值的贡献越大。

【三大层面】可持续性涵盖环境、社会与经济三个维度：环境层面应对气候变化、生物多样性丧失与污染；社会层面关注社会公平、社区福祉与人的权益；经济层面关注长期繁荣与经济可行性。

【三重底线】通过将可持续性融入项目管理，组织能够遵循三重底线原则（Triple Bottom Line），在社会公平（人）、环境保护（地球）与经济繁荣（利润）之间实现平衡。

【战略意义】可持续性已成为应对全球性挑战的必然要求。它既强化了企业的社会责任，又促进创新和负责任的技术实践，从而有助于创造长期价值。

【双重视角】可持续性同时关注项目成果与实现过程两个方面：既要交付有价值的结果，也要控制实现结果过程中的社会与环境代价。`,
    details: {
      "📊 对项目管理的影响": `- **三个层面的体现**：可持续性体现在项目的战术、运营与战略层面。战略层面影响组织愿景与项目组合决策；运营层面体现为具体流程与实践；战术层面体现为资源选择与日常决策。

- **融入事业环境因素**：相关流程与实践可能已融入事业环境因素，如环保法规、组织ESG政策与社会责任标准，项目必须予以遵守。

- **贯穿项目全过程**：该原则影响项目从启动到收尾的全过程——启动时界定可持续目标，规划时设计绿色方案，执行时监控资源消耗，收尾时评估社会与环境绩效。

- **正式化可持续KPI**：可将与可持续性相关的关键绩效指标纳入项目范围说明书、项目章程、业务论证、合同或其他授权项目活动的正式文件，使其成为有约束力的交付要求。

- **组织收益**：员工满意度提高、绩效改善、人才留存率提高，以及招聘吸引力增强。

- **运营收益**：内部流程创新、生产力提高（通过最小化运营浪费）。

- **财务收益**：因降低物料和能源消耗而带来的直接成本节约、运营成本降低、废弃物减少。

- **客户与干系人收益**：满意度和创新能力提高、市场份额提升、声誉增强以及新的市场机遇。

- **影响各绩效域**：可持续实践可能需要额外资金，影响财务绩效域；通过主动识别并减轻环境、法规或社会等长期风险，对风险绩效域产生积极影响；可持续举措可激励团队开发资源节约型解决方案，创造创新机会；将社会和环境价值融入项目管理，有助于强化治理、范围和利益相关方绩效域。`,
      "🤝 与其他原则的相互作用": `- **与成为负责任的领导者原则相互促进**：负责任的领导者把长期责任纳入决策，将可持续目标视为自身担当的一部分；可持续实践反过来又检验领导者在短期利润与长期影响之间能否做出诚信选择。

- **与聚焦价值原则协同**：可持续性拓展了价值的维度，从单一财务价值扩展到社会与环境价值；坚持可持续的决策往往在项目全生命周期内创造更大的综合价值。

- **与识别、评估并响应系统交互原则一致**：可持续性问题本质上是系统性问题，项目的环境影响会沿供应链、社区与生态链条传播，需要以整体视角看待，这也与风险绩效域主动识别并减轻长期风险的思路一脉相承。

- **与有效干系人参与原则衔接**：社区、监管机构、环保组织等常常是重要的干系人，可持续策略的实施离不开与他们的持续对话与协同。

- **与构建赋能型文化原则呼应**：鼓励创新与包容的赋能文化能激发团队提出资源节约与负责任技术的方案，为可持续目标的落地提供人才基础。

- **与基于上下文裁剪原则结合**：选择补偿、减轻还是避免负面后果，本质上是对项目上下文的一种裁剪决策，需要结合行业、规模与风险偏好来确定。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素——组织ESG战略承诺**：组织将环境、社会与治理目标纳入战略时，可持续项目更容易获得资金与资源支持。

- **帮助因素——监管与合规要求**：环保法规、碳减排目标等强制要求为可持续实践提供了底线保障。

- **帮助因素——干系人期望**：客户、社区与投资者对可持续性的期望，形成推动项目绿色化的市场力量。

- **帮助因素——绿色供应链**：存在可持续供应商与可循环材料时，绿色采购成本更低、可行性更高。

- **帮助因素——可持续KPI与度量体系**：将可持续指标正式化并纳入考核，可持续行为才可被衡量、可被管理。

- **帮助因素——领导层支持**：高层以身作则践行可持续，项目团队才敢于在进度与成本上做出相应平衡。

- **阻碍因素——短期成本压力**：可持续方案前期投入往往更高，在预算紧张时最容易被最先削减。

- **阻碍因素——意识与知识不足**：团队不了解可持续工具和方法时，容易将其视为额外负担而消极应付。

- **阻碍因素——衡量困难**：社会与生态影响难以量化和货币化，导致可持续收益难以向决策者证明价值。

- **阻碍因素——供应链复杂性与惯性**：既有采购流程与廉价供应商形成的惯性，阻碍了向绿色来源的切换。

- **阻碍因素——目标冲突**：进度、成本与可持续目标相互竞争且缺乏优先级时，可持续目标最容易被放弃。`,
      "✂️ 裁剪考虑": `- **按行业裁剪**：建筑、能源等高环境影响行业应强化材料与能耗的可持续审查；IT与服务业则更侧重数据隐私、电子废弃物与社会责任。

- **按项目规模裁剪**：大型项目通常需要正式的可持续计划、专门的责任人与第三方审计；小型项目可简化为关键指标的清单式管理。

- **按开发方法裁剪**：预测型项目可在章程与范围说明书中固化可持续KPI；敏捷项目可通过产品待办事项列表并把可持续性纳入完成的定义（DoD）持续落实；混合型项目则分层处理。

- **按组织成熟度裁剪**：可持续体系成熟的组织可直接套用其ESG框架；成熟度较低的组织应从最易量化的指标起步，逐步扩展。

- **按策略层级裁剪**：根据项目影响程度与资源条件，在补偿、减轻、避免三个层级中选择适当的应对深度，能力有限时先做到补偿，但应始终向避免的方向努力。

- **按生命周期裁剪**：尽量将可持续决策前移，项目前期设计阶段对全生命周期环境影响最大，早介入的性价比最高。`,
      "💼 实践案例": `【案例：绿色建筑项目】某建筑项目需要采购大量外部自然资源材料。若忽视可持续性原则，团队可能选择最廉价的材料，从而危害环境和人类健康。遵循该原则后，团队不仅关注项目的价值和内部收益率，还展现出对环境可持续性以及负责任地使用材料和自然资源的承诺。具体工作包括：精心筹划所需材料，选择对环境影响最小的采购来源；寻求可融入自然循环、从自然构造中获得灵感的材料，例如采用木材建造城市建筑，或用再生混凝土替代天然石材。项目在控制成本的同时显著降低了碳足迹，提升了社区口碑与股东信任，并通过减少废料获得了长期成本节约。`,
    },
    keyConcepts: `- **可持续性**：既满足当前需要，又不损害子孙后代满足其自身需要的能力。

- **可持续性金字塔**：按影响程度递增排列的策略层次，即补偿负面后果、减轻负面后果、完全避免负面后果。

- **三重底线（Triple Bottom Line）**：同时关注社会公平（人）、环境保护（地球）与经济繁荣（利润）的绩效衡量框架。

- **ESG**：环境（Environmental）、社会（Social）与治理（Governance）三项非财务因素，是评估组织可持续表现的重要维度。

- **生命周期思维**：从材料获取、生产、使用到处置，全周期评估产品或项目的影响，避免影响被转嫁到其他阶段。

- **循环经济**：通过再使用、再制造与再生，最大限度减少废弃物与资源消耗的经济模式。

- **负责任的技术**：采用新技术时同步评估并减轻其社会与环境风险，使创新服务于更美好的未来。

- **长期价值**：超越单一财务回报、兼顾社会与环境成果的综合价值创造。

- **关键绩效指标（KPI）**：将可持续目标量化的正式指标，可纳入章程、范围说明书与合同等授权文件。`,
    examTips: `- **高频考点——可持续性金字塔**：三种策略按影响程度递增排列为补偿、减轻、避免，题目可能要求判断某一做法属于哪一层级。

- **高频考点——三重底线**：人（People）、地球（Planet）、利润（Profit）三要素常以3P形式考查，务必同时包含社会、环境与经济三个维度。

- **可持续性不只是环境问题**：社会公平、社区福祉与经济可持续同样属于可持续性范畴，选项只谈环境而忽略社会维度时需谨慎。

- **跨领域出题**：可持续性可能出现在采购（绿色采购）、风险（法规与环境风险）、干系人（社区与监管机构）、财务（长期成本节约）等任何领域的考题中。

- **长期思维**：情景题中能为长期价值而接受短期成本的选项通常更符合该原则，但也不能无限度牺牲进度与预算。

- **可持续不等于昂贵**：可持续方案常通过降低物料与能源消耗、减少废弃物来实现长期成本节约，并非纯粹的额外支出。

- **正确做法识别**：遵循该原则的项目团队会评估材料环境影响、选择绿色采购源、将可持续KPI纳入正式文件。`
  },
  "principle-empower-culture": {
    overview: `【原则定位】“构建赋能型文化”原则强调：项目环境应有利于利益相关方与项目团队成员之间建立信任，同时明确个人角色、职责、团队协议和指导流程。这些要素使个人能够协同工作，通过互动产生协同效应，从而使利益相关方能够更高效、更有效地协作，推动项目成功。

【赋能的前提】信任、明确的角色与职责、清晰的团队协议和有效的指导流程，是个人愿意主动承担、充分协作的基础。缺乏这些要素，授权只会带来混乱而非效率。

【推动领域一：多元化】多元化的项目团队能够汇集不同观点，丰富项目环境，营造更具包容性的空间。在全球经济环境下，团队成员可能由组织内部员工、签约贡献者、志愿者或外部协作者构成。营造尊重多元化并力求建设性利用多元化的团队环境，有助于营造可以有效管理冲突的氛围。

【推动领域二：流程定义】项目团队应定义能够完成任务和工作分配的流程，并与其他利益相关方互动，以理解、考虑、沟通并回应其利益、需要和意见。

【推动领域三：人际关系技能】项目团队成员和利益相关方应培养主动性、正直、诚实、协作、尊重、同理心和自信等一系列人际关系技能，这些技能有助于团队适应任务并相互配合。

【核心思想】赋能不等于放任，而是在清晰框架内赋予自主权——通过营造信任与包容的环境，让团队有能力、有意愿地为实现目标主动作为。`,
    details: {
      "📊 对项目管理的影响": `- **文化源于组织与运营环境**：项目利益相关方受项目所涉组织文化及其运营环境的影响，项目团队通常会在此基础上建立自己的文化规范。团队可以灵活调整其组织框架，从而在新的文化环境下以最优的方式实现预期项目目标。

- **组织结构知识**：构建赋能文化时，团队需要理解项目任务组件与组织程序之间的各种配置和关系，裁剪并采用各种框架，以促进个人贡献与项目任务的有序协同。

- **团队协议的作用**：团队协议是一套行为准则和工作规范，由项目团队制定，通过个人和团队的承诺来维护。它应在项目开始时制定，以确定促进持续协作成功所需的基本规范和实践，如会议节奏、沟通渠道、决策方式与冲突处理规则。

- **远程与虚拟团队的挑战**：由于工作风格不同、时区差异和缺乏面对面交流，远程团队和虚拟团队面临更大的挑战，这些因素可能阻碍协作和关系建立。赋能文化可为所有成员提供良好机会，帮助他们以有效且富有建设性的方式建立关系并进行协作，从而主动化解分歧、管理冲突。

- **促进自组织与高绩效**：在赋能文化中，团队被信任能够自我组织、自主决策，从而提升响应速度与士气；成员因被看见、被听见而更加投入，推动高质量交付。

- **支持七大绩效域**：在治理方面以主动协作方式与管理层建立积极透明的沟通；在范围方面进行开放式沟通、根据项目不断变化的需要主动适应；在进度方面被赋能团队可提出加速、延缓或停止关键活动的方案；在财务方面通过增加关注价值创造的步骤来减少或取消不必要的计划外支出；在利益相关方方面确定、影响甚至定义适当的参与程度与性质；在资源方面根据项目需求限制或允许对实物资源的获取；在风险方面定义风险临界值并参与后续的风险管理活动。`,
      "🤝 与其他原则的相互作用": `- **与成为负责任的领导者原则互为条件**：服务型领导者通过清除障碍、提供支持来赋能团队；反过来，只有在赋能文化中，共享领导力才能真正落地，领导力才会分散到团队之中。

- **与有效干系人参与原则相互促进**：赋能文化让团队成员和干系人感到被重视、被接纳，这种信任关系正是深入干系人参与的前提；清晰的参与流程又让赋能落到实处。

- **与聚焦价值原则协同**：被赋能的团队更主动地提出消除浪费、增加价值创造的建议，直接服务于聚焦价值原则，成员对价值主张的认同度也更高。

- **与识别、评估并响应系统交互原则一致**：赋能文化要求理解团队与组织程序之间的各种关系，这正是系统思维的体现；被赋能的团队也更能感知并响应系统中的反馈信号。

- **与将可持续性融入所有项目领域原则呼应**：包容、多元与尊重是可持续性的社会维度；鼓励创新的赋能文化也有助于提出资源节约与负责任技术的可持续方案。

- **与基于上下文裁剪原则结合**：团队协议、组织框架与沟通方式都应根据项目上下文进行裁剪，赋能程度（从完全授权到较多监督）也需因项目而异。`,
      "⚠️ 帮助与阻碍因素": `- **帮助因素——组织对授权的支持**：组织文化鼓励下放决策权、容忍合理的试错，团队才能真正被赋能。

- **帮助因素——信任基础**：管理层、团队与干系人之间的信任是赋能文化的基石，信任使授权和自主成为可能。

- **帮助因素——明确的角色与团队协议**：角色、职责与行为准则清晰，团队才知道在何种边界内自主行动。

- **帮助因素——心理安全**：成员敢于表达观点、承认错误而不用担心被惩罚，是多元化价值得以发挥的关键。

- **帮助因素——多样化的团队构成**：不同背景成员带来丰富的观点与解法，促进创新和更全面的决策。

- **帮助因素——开放式沟通**：顺畅、透明的沟通渠道使信息充分流通，赋能才不会因信息不对称而失效。

- **帮助因素——教练型管理**：管理者以教练而非命令的方式指导团队，帮助其建立自主能力。

- **阻碍因素——命令控制式组织文化**：高层习惯微观管理，会削弱团队的自主空间与主人翁意识。

- **阻碍因素——角色与职责模糊**：权责不清导致推诿或越权，授权反而引发混乱。

- **阻碍因素——缺乏信任**：管理层不信任团队会过度监控；成员之间缺乏信任则难以协作。

- **阻碍因素——远程沟通障碍**：时差、缺乏面对面交流与异步沟通不畅，阻碍关系建立，容易滋生误解。

- **阻碍因素——隐性偏见与排斥**：对某些背景成员的忽视会削弱多元化的价值，使部分成员感到不被看见。`,
      "✂️ 裁剪考虑": `- **按团队分布裁剪**：同地协作团队可依赖面对面互动；远程或虚拟团队需裁剪出更结构化的沟通节奏，如定期同步会、异步协作工具与虚拟团队建设，以弥补物理距离。

- **按组织层级与授权文化裁剪**：在高度集权的组织中，赋能应从有限的、明确的授权区间起步并逐步扩大；在扁平组织中则可快速推行团队自决策。

- **按开发方法裁剪**：敏捷项目强调自组织团队、团队协议与完成的定义，赋能程度最高；预测型项目则需在既定流程与分工内赋予执行层面的自主权；混合型项目按模块混合调整。

- **按团队成熟度裁剪**：新组建或低成熟度的团队需要更多指导流程和阶段性检查；成熟团队则可减少监督、扩大自主。

- **按团队规模裁剪**：小团队可更扁平、以口头共识为主；大型团队需要更正式的角色结构、沟通渠道与决策机制。

- **按文化敏感性裁剪**：跨国团队需裁剪沟通与反馈方式，尊重不同文化对权威、冲突与时间观念的差异。`,
      "💼 实践案例": `【案例：多元化跨国团队的文化赋能】某项目团队因人员背景复杂、所处地域多元，在争取利益相关方参与方面面临挑战。遵循“构建赋能型文化”原则后，团队自项目启动之初便主动识别每一位利益相关方，让他们感到被重视、被接纳，这种融入为干系人提供了实现价值和积极参与的指引，从而助力项目取得成功。团队营造出每个人都感到被倾听、被尊重的环境，充分利用多元化的优势，解决了因文化差异或地域分散带来的沟通障碍。同时，团队在项目开始时共同制定了团队协议（如会议节奏、决策方式与冲突处理规则），明确角色职责，使远程成员也能高效协作。最终，项目不仅顺利交付，还建立了可持续的合作关系。`,
    },
    keyConcepts: `- **赋能型文化**：以信任为基础、在明确角色与流程边界内赋予团队自主权，使成员主动协同创造价值的文化环境。

- **团队协议**：由项目团队在项目开始时共同制定并承诺遵守的行为准则与工作规范，如会议节奏、沟通渠道、决策方式与冲突处理规则。

- **心理安全**：成员可以安全地表达观点、提问与承认错误而不必担心受到惩罚或羞辱的氛围。

- **多元化**：团队成员在背景、经验、观点上的多样性，能够汇集不同视角、丰富项目环境。

- **流程定义**：为完成任务与分配工作而定义的清晰流程，包括与其他干系人互动以回应其利益与需要。

- **人际关系技能**：主动性、正直、诚实、协作、尊重、同理心和自信等有助于团队协作的个人素养。

- **自组织团队**：能够自主分配工作、做出决策并对结果负责的团队，是敏捷环境的重要特征。

- **T型人才**：在某个领域有深度、同时具备跨领域广度与协作能力的通才型专家，在敏捷团队中更受青睐。

- **虚拟团队**：跨越地点与时间的分布式团队，需要更多结构化的沟通与信任建设。

- **协同效应**：个体通过协作产生大于各自简单相加的集体成果。`,
    examTips: `- **高频考点——团队协议在项目开始时制定**：情景题中团队刚组建时，正确做法是共同制定团队协议，而不是等冲突出现后再补。

- **高频考点——多元化是资产**：题干强调团队背景多样时，应选择尊重并建设性利用多元化以丰富决策的选项，而不是统一观点、减少分歧。

- **赋能需要信任加明确角色加指导流程**：只有授权而无边界不是赋能，选项赋予自主权但保持清晰角色与协议更符合该原则。

- **T型人才更受青睐**：敏捷团队中既专又通、善于协作的成员比单纯深度专家更受青睐。

- **远程与虚拟团队挑战更大**：出现虚拟团队情景时，应选择增加结构化沟通、定期同步与信任建设的做法。

- **自组织不等于失控**：自组织团队仍需团队协议、明确职责与组织边界，选项完全没有监督通常过于绝对。

- **被赋能团队的行为信号**：主动提出加速或延缓方案、主动消除浪费、主动参与风险管理，都是赋能文化生效的迹象。`
  },
  "domain-governance": {
    overview: `项目治理适用于所有项目管理方法，包括预测型、适应型和混合型，并根据行业、组织环境和项目具体情况有所差异。治理由框架、职能和过程组成，用于指导项目管理的决策和活动，以优化项目的价值交付。这一治理框架具有整体性和整合性，并考虑了所有其他绩效域。

项目治理受执行组织的治理模型，以及客户和监管机构等利益相关方的共同影响。治理绩效域包含与战略一致性、决策制定与变更、项目成功标准相关的项目整合管理要素。此外，治理绩效域整合了风险和机会管理，有助于主动识别和化解潜在问题，同时利用机会提升价值。该绩效域还有助于确保项目与项目组合、组织战略及目标保持一致。

可根据不同的方法对治理进行裁剪：对于适应型项目，采用轻量级治理，减少文档和审批环节；对于混合型项目，可采用适度或组合式治理，在不同阶段采用不同的治理强度；对于大型、预测型项目组合、项目集和项目，采用全面治理，包括正式的上报机制和投资控制。为确保持续改进，应在治理框架中引入反馈循环，支持定期评审、经验教训总结和治理实践的迭代调整。治理并非一次性活动，而是贯穿整个项目生命周期持续运作。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `治理绩效域中的项目管理工作贯穿整个项目生命周期，涵盖以下关键活动：

- **建立治理框架**：根据组织治理模型、项目特点与所采用的生命周期方法，选择并建立适合项目的治理框架，明确治理委员会、发起人、项目经理和关键干系人的角色与职责。
- **确保战略一致性**：将项目目标与组织战略、项目组合和项目集目标对齐，确保项目交付的成果真正支持组织的价值创造，防止“做正确的事”与“正确地做事”脱节。
- **制定决策并处理变更**：建立清晰的决策流程和变更控制机制，明确由谁在什么层级上批准何种变更。重大变更由治理委员会审批，日常调整授权给项目经理，实现授权与控制的平衡。
- **定义并沟通项目成功标准**：与发起人和关键干系人共同定义可测量的成功标准，并在项目全程持续沟通、跟踪和验证这些标准，避免项目结束时才去争论“什么才算成功”。
- **整合其他绩效域**：治理作为整合机制，统筹范围、进度、财务、资源、风险、利益相关方等绩效域的决策与活动，确保各绩效域相互协调而非各自为政。
- **监督与汇报**：通过定期评审、绩效报告和治理会议监督项目进展，及时发现偏差并推动纠正措施；向治理委员会和干系人透明汇报项目状态与决策依据。
- **反馈与持续改进**：在治理框架中建立反馈循环，定期开展经验教训总结，迭代调整治理流程与审批权限，使治理与项目实际需要保持匹配。`,
      "🔗 与其他绩效域的相互作用": `治理绩效域与所有其他绩效域紧密互动，是连接各绩效域的整合纽带：

- **与范围绩效域的互动**：构成最重要的互动关系，因为项目范围是核心价值所在。治理决定范围控制的松紧程度——采用正式的控制（如严格的变更控制委员会）还是非正式的治理（如产品负责人直接决策），这一决策直接影响项目价值的实现。
- **与进度绩效域的互动**：涉及价值主张的时间敏感性。治理框架设定里程碑审批和进度汇报节奏，进度偏差达到阈值时触发治理层面的干预。
- **与财务绩效域的互动**：通过预算分配和财务控制实现。治理机构审批预算、监督资金使用，财务决策（如动用应急储备）需要治理授权。
- **与利益相关方绩效域的互动**：通过透明的决策制定实现。治理确保关键干系人参与决策、获得充分信息，从而建立信任并管理期望。
- **与资源绩效域的互动**：涉及资源在组织内的分配方式。治理决定项目可获得的人员、设备与预算规模，以及跨项目的资源优先级。
- **与风险绩效域的互动**：所有项目都属于具有内在风险的投资，减轻风险或把握机会的措施应与战略目标保持一致，治理负责审批风险应对所需的储备动用与决策授权。`,
      "✂️ 裁剪考虑": `治理需要根据项目情况灵活裁剪，避免“一刀切”：

- **适应型项目**：采用轻量级治理，减少文档和审批流程，依赖团队自我管理、产品负责人决策和迭代评审，治理重点放在价值验证与增量交付上。
- **混合型项目**：可采用适度或组合式治理，在不同阶段使用不同治理强度，例如预测型阶段采用正式审批，适应型阶段放权给团队。
- **大型预测型项目**：采用全面治理，包括正式的上报机制、投资控制、阶段关卡评审和多层级审批。
- **治理过度的风险**：治理过度会造成资源浪费，增加决策延迟和官僚成本，降低团队积极性。
- **治理不足的风险**：治理不足可能导致战略一致性缺失、合规问题和项目绩效失控，缺乏监督将增大失败概率。
- **平衡原则**：最佳治理应在战略一致性、合规性与价值实现之间实现适当平衡。
- **反馈循环**：无论采用何种治理强度，都应引入反馈循环，支持定期评审和经验教训总结，使治理随项目演化而持续优化。
- **规模与风险适配**：项目规模越大、风险越高、合规要求越严，治理的正式程度通常也越高。`,
      "📊 测量指标": `治理绩效域的测量指标用于评估治理的有效性和项目对组织价值的贡献：

- **领先指标（Leading Indicators）**：用于指示即将发生的变更或揭示项目中的趋势，能够在绩效偏差超出公差临界值之前将其识别，从而降低项目的绩效风险。在可能的情况下应优先使用，因为可以预防未来可能需要返工的问题。
- **滞后指标（Lagging Indicators）**：用于衡量项目可交付物或事件，提供“事后”信息，反映过去的绩效或状况，比领先指标更易于测量，例如已完成的可交付物数量、进度或成本偏差、消耗的资源量。
- **目标质量指标**：运用 SMART 准则评估所设目标的清晰性与可达成性，衡量项目成功标准是否可测量、是否设置了明确的时间框架。
- **决策时效与质量**：评估变更请求的处理周期、治理会议的决策效率以及决策被后续推翻的频率。
- **合规与审计结果**：衡量项目对治理要求、组织政策和外部法规的遵循程度。
- **战略一致性评估**：定期核对项目成果与组织战略目标、项目组合优先级的匹配程度。
- **干系人信任度**：通过干系人反馈评估治理的透明度与决策的公信力。`,
      "💼 实践案例": `某大型制造企业启动一项 ERP 系统升级改造项目，采用预测型生命周期，预算 2 亿元，周期 24 个月。由于项目涉及财务、供应链、生产等多个业务部门，组织建立了三层治理结构：最高层为项目治理委员会（由分管副总裁、CFO 和关键业务负责人组成），中间层为项目管理办公室，负责制定治理流程和提供决策支持，最下层为项目经理和核心团队，负责日常执行。

治理委员会在项目启动阶段即明确了战略一致性与成功标准：系统上线后三年内实现库存周转率提升 15%、财务关账时间缩短 50%。委员会每月召开治理评审会议，重点审查进度、成本、风险三大指标的领先/滞后状态。当领先指标显示核心模块开发速度连续两周低于计划 10% 时，委员会提前介入，追加外包开发资源并对关键路径赶工，避免了里程碑延误。

项目发生 1200 万元的需求变更申请，项目经理按授权仅批准 300 万元以内的变更，其余提交治理委员会评审。委员会结合战略优先级拒绝了与核心目标关联度低的需求，控制住范围蔓延。项目收尾时，组织将本次治理框架中的审批时限、汇报模板和评审节奏沉淀为组织过程资产，供后续项目复用。`,
    },
    keyConcepts: `有效项目治理的关键概念包括：

- **领先指标（Leading Indicators）**：用于指示即将发生的变更或揭示项目中的趋势，能够在绩效偏差超出公差临界值之前将其识别，以降低项目的绩效风险。应优先使用，因为它们可以预防未来可能需要返工的问题。
- **滞后指标（Lagging Indicators）**：用于衡量项目可交付物或事件，提供“事后”信息，反映过去的绩效或状况，比领先指标更易于测量。示例包括已完成的可交付物数量、进度或成本偏差、消耗的资源量等。
- **SMART准则**：一套指导方针，用于设定清晰的（Specific）、可测量的（Measurable）、可实现的（Achievable）、现实的（Realistic）和有时间限制的（Time-bound）目标。
- **资源获取策略**：项目资源可以从内部获取，也可以从外部获取，或者同时从内部和外部获取。决定项目的哪些部分应采用何种获取方式，这涉及一系列的治理决策。
- **项目治理框架**：由框架、职能和过程组成，用于指导项目管理的决策和活动，以优化项目的价值交付。
- **治理委员会**：由关键干系人组成的治理机构，负责审批重大决策与变更、监督项目绩效。
- **授权与责任体系**：明确谁有权在何种范围内做出何种决策，并对决策结果负责的机制。`,
    examTips: `- **治理是整合各绩效域的纽带**：治理绩效域与所有其他绩效域互动，其中与范围绩效域的互动最为重要，因为项目范围是核心价值所在。
- **领先指标 vs 滞后指标**：领先指标是“前瞻性”的，能在偏差超出临界值前预警；滞后指标是“事后”信息，更易测量但只能反映过去绩效。注意区分并优先使用领先指标。
- **SMART准则**：用于设定有效的项目目标，分别对应清晰、可测量、可实现、现实、有时间限制五个维度。
- **治理贯穿全生命周期**：治理不是一次性活动，从启动到收尾持续进行，需引入反馈循环实现持续改进。
- **结构化治理 vs 自我治理**：预测型项目通常使用结构化治理（正式流程、审批层级），适应型项目通常使用自我治理（团队自主决策、轻量级管控）。
- **治理过度与治理不足**：治理过度造成资源浪费，治理不足导致战略一致性和项目绩效问题；最佳治理应在战略一致性、合规性与价值实现之间取得平衡。
- **资源获取策略**：内部获取、外部获取或混合获取是重要的治理决策。
- **治理受多重因素影响**：执行组织的治理模型、客户与监管机构等利益相关方共同影响项目治理。`
  },
  "domain-scope": {
    overview: `范围在项目管理中具有独特且核心的地位，因为项目的价值来自与其范围相符的交付成果。范围绩效域包括确保项目涵盖成功完成项目所需的全部工作，并且仅规划必要工作而不执行不必要工作所需的过程，从而有助于优化成本和进度，实现项目价值的最大化。

除了定义和管理范围，范围绩效域还关注项目质量。质量的定义是满足利益相关方期望并实现项目和产品的需求。该绩效域有助于确保可交付物符合规定的验收标准，并且用于生成这些可交付物的过程既有效又高效。该绩效域强调持续的流程改进，这有助于确保范围与质量保持一致，能够持续满足项目目标与标准。

范围绩效域既适用于预测型项目（通过范围说明书、WBS 和变更控制来管理），也适用于适应型项目（通过产品待办事项列表、迭代评审和完成的定义来管理），并可在混合型项目中结合使用。该绩效域的核心目标只有一个：在规定的范围边界内，交付高质量、有价值的产品、服务或结果。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `范围绩效域中的项目管理工作涵盖定义、规划、确认与控制范围的全过程：

- **定义项目范围与产品范围**：项目范围涵盖为交付具有指定特性和功能的产品、服务或结果而开展的工作；产品范围描述产品、服务或结果的特性、功能和特征，二者需同步管理。
- **收集并确认需求**：通过访谈、研讨会、标杆对照等工具收集干系人需求，明确必须满足的条件或能力，并通过需求跟踪矩阵将需求与业务目标、可交付物和测试用例关联。
- **创建工作分解结构（WBS）**：将全部可交付物和项目工作按层级分解，遵循 100% 原则，确保所有必要工作都被覆盖且无冗余，并以 WBS 字典说明每项工作的细节。
- **制定范围基准**：在预测型环境中，经正式批准的范围说明书、WBS 和 WBS 字典构成范围基准，后续变更须通过正式变更控制程序。范围说明书应清晰描述项目范围与产品范围、可交付物清单、验收标准以及除外事项，为后续确认与控制范围提供依据。
- **管理范围变更**：所有范围变更须先评估其对进度、成本、质量与风险的影响，再经变更控制程序批准，确保范围基准的完整性与可追溯性。
- **确认范围（客户验收）**：在阶段或交付节点由客户或干系人检查可交付物，确认其符合验收标准并正式接受，为验收提供客观依据。
- **控制范围（防止蔓延）**：持续监控范围状态，管理对范围基准的变更，识别并遏制范围蔓延（未走变更流程的无序扩张）。
- **敏捷与混合场景的范围管理**：通过产品待办事项列表维护动态的、按优先级排序的需求池，每次迭代前进行范围细化，用完成的定义（DoD）明确验收标准，并通过迭代评审验证交付价值。
- **质量与范围集成**：将质量作为范围的内在属性，通过持续流程改进确保可交付物既符合验收标准，生成可交付物的过程又有效且高效。`,
      "🔗 与其他绩效域的相互作用": `项目的范围并非孤立存在，它与其他绩效域深度互联：

- **与进度、财务绩效域的互动**：最直接相关，任何范围变更都会直接影响进度计划和成本预算——增加范围往往导致工期延长与成本上升。
- **与风险绩效域的互动**：范围定义中的不确定性本身就是风险来源，范围扩大可能引入新的技术、接口和合规风险。
- **与利益相关方绩效域的互动**：需求来源于干系人，干系人的变化会引发需求变化，从而影响范围。
- **与治理绩效域的互动**：范围—治理方法可以包括大量的正式控制（严格的变更控制委员会），也可以包括非正式控制（敏捷中的产品负责人决策）。这类治理决策至关重要，因为项目的期望价值来自于对其范围的交付。
- **与资源绩效域的互动**：范围大小直接决定所需资源的种类与数量，范围变更将引起资源需求的调整。`,
      "✂️ 裁剪考虑": `范围管理需要根据项目特征进行裁剪：

- **与外部合作伙伴的依赖关系**：在涉及外部合作伙伴的项目中，如何管理将范围整合至合同协议的决策至关重要，例如固定总价合同下范围冻结早、变更成本高，而工料合同中范围管理更具弹性。
- **环境的动态性**：在高度动态的环境中（如技术快速迭代的软件项目），范围管理应特别灵活，引入迭代反馈机制，避免前期过度细化导致后期大量返工。
- **设计阶段投入**：某些行业（如建筑工程）必须在范围定义的早期阶段投入大量精力，以避免后期产生高昂的变更成本。
- **适应型和混合型生命周期**：适应型工作方式基于项目范围的持续细化（渐进明细），需求在迭代中不断演进；混合型方法需要根据多种工作方式组合进行裁剪，为预测型部分严格控范围、为适应型部分保留灵活性。
- **规模与复杂度**：项目越大、干系人越多，范围管理的正式程度越高；小型项目可采用简化的需求清单。
- **质量期望**：干系人对质量的期望决定了验收标准与范围定义的严格程度。`,
      "📊 测量指标": `范围绩效域的关键测量指标包括：

- **范围蔓延（Scope Creep）**：未通过正式变更控制就增加的需求或功能，是范围管理失控的核心信号。
- **范围流失（Scope Erosion）**：可交付物、功能或需求在未获批准的情况下被删减或降级，导致交付价值低于承诺。
- **验收的可交付物数量**：通过正式验收、满足验收标准的可交付物数量及其比例，反映范围完成与质量达标情况。
- **需求跟踪矩阵的覆盖率**：每项需求是否都有对应的可交付物、测试用例与验收记录的完整程度。
- **变更请求数量与处置率**：范围内变更的频繁程度和审批效率，过高可能预示范围定义不充分。
- **WBS 完整性**：通过 100% 原则核查 WBS 是否涵盖全部必要工作且无重复。
- **产品待办事项列表健康度（敏捷）**：条目是否按优先级排序、描述清晰、规模适中且可持续被迭代消化。
- **每迭代交付的功能数量与价值（敏捷）**：通过交付速率和商业价值评估范围交付效率。`,
      "💼 实践案例": `某银行上线一款移动端个人理财应用，项目初期由业务部门整理出 60 项需求，涉及存款、贷款、基金等多个业务条线。项目经理牵头组织需求研讨会，将需求归并、去重并评定优先级，最终将 60 项需求细化为 42 项进入范围说明书的首批范围。

项目采用预测型生命周期管理核心功能，同时预留敏捷空间迭代优化界面体验。团队创建 WBS，将项目分解为需求分析、系统设计、开发、测试、上线五大包和 35 个工作包，覆盖全部必须完成的工作。范围基准批准后，销售部门陆续提出 8 项新增需求，项目经理通过变更控制流程逐一评估，仅批准了其中与监管合规直接相关的 2 项进入范围，其余 6 项被推迟到二期，有效遏制了范围蔓延。

每个功能交付时，测试团队依据需求跟踪矩阵核对验收标准，确认后才向业务方申请正式验收。其中基金开户功能因未完全满足“双录”（录音录像）合规要求被退回，开发团队重新设计后通过验收。项目上线后，团队复盘发现，早期范围定义中过度细化的部分功能在交付时需求已变化，组织由此调整流程，在后续项目中引入迭代范围细化，减少前期过度设计的浪费。`,
    },
    keyConcepts: `范围绩效域的关键术语包括：

- **业务论证**：一份书面的经济可行性研究，用于确定项目所交付收益的有效性，是启动项目的重要依据。
- **项目范围**：涵盖为交付具有指定特性和功能的产品、服务或结果而开展的工作。
- **需求**：产品、服务或结果为满足业务需要而必须具备的条件或能力，通常可分为业务、干系人、解决方案、过渡和项目需求等类别，需在确认前收集完整并达成共识。
- **需求跟踪矩阵**：将每一项需求与业务目标、可交付物、测试用例和验收记录关联起来的表格，是需求可追溯性与变更影响分析的重要工具。
- **范围基准**：在预测型环境中，正式批准的范围文件（范围说明书、WBS、WBS 字典），可通过正式的变更控制程序进行修改。
- **工作分解结构（WBS）**：项目团队为实现项目目标并创建所需可交付物而需完成的全部工作范围的层级化分解，遵循 100% 原则。
- **将质量作为特性**：质量是范围的内在属性，交付物不仅要“存在”，还要满足验收标准与干系人期望。
- **产品范围**：对项目拟交付的产品、服务或结果的特性、功能和特征的描述。
- **价值分解结构（VBS）**：将项目范围及其预期价值与产品范围连接起来的层级化结构。
- **产品待办事项列表**：动态的、按优先级排序的工作条目和特性列表，随项目演进持续细化。
- **完成的定义（DoD）**：列出所有必须满足的验收标准的核对单，是敏捷中判定“完成”的客观依据。`,
    examTips: `- **范围说明书 vs 项目章程**：范围说明书详细描述可交付物和验收标准（“做什么”），项目章程更侧重于授权（批准项目、授权项目经理），二者不要混淆。
- **WBS 的 100% 原则**：WBS 必须包含全部必要工作，既不多也不少；只有 WBS 最底层（工作包）才可进行成本与历时估算。
- **确认范围 vs 控制范围**：确认范围是客户验收（检查可交付物是否符合验收标准），控制范围是防止蔓延（管理对范围基准的变更），前者核对“质量达标”，后者防范“范围失控”。
- **DoD（完成的定义）**：敏捷范围管理的关键概念，是团队判定用户故事或迭代是否真正完成的客观核对单。
- **范围蔓延 vs 范围流失**：蔓延是未受控地加功能，流失是未获批准地减功能，两者都损害价值交付。
- **渐进明细**：适应型项目基于范围的持续细化展开，需求随迭代演进，这是与预测型最大的差别。
- **需求分类**：业务、干系人、解决方案、过渡与项目需求是常见的需求分类，出题常要求识别题干所描述的需求属于哪一类。
- **业务论证**：是范围管理的前提，范围必须始终服务于论证过的业务价值。`
  },
  "domain-schedule": {
    overview: `项目进度规划为项目提供了一个计划，说明项目将如何及何时交付项目范围中定义的产品、服务和结果。作为一种协调和管理利益相关方期望的工具，进度计划为绩效报告提供基础，使团队能够监控项目进展、识别偏差。项目进度计划还有助于主动识别潜在的延误和风险，从而能够及时采取纠正措施，使项目保持在正轨上。

详细的项目进度计划应在整个项目过程中保持灵活性，以便根据获取的知识、对风险和外部影响的深入理解，以及增值活动对其进行调整。在整个项目期间，应持续修订和维护项目进度，以维持一个现实可行的进度计划。

可以在不同层级创建和定义进度计划。即使是采用预测型方法的项目，也可能无法预先制订详细的项目进度计划，因此，越来越多的项目管理从业者在项目推进过程中逐步制订详细的进度计划——一种辅助该方法的著名技术是滚动式规划。进度绩效域的目标，是确保项目在承诺的时间框架内高效交付价值，同时为应对不确定性和变化保留必要的灵活性。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `进度绩效域中的项目管理工作围绕“规划—估算—排程—控制”展开：

- **规划进度管理**：确定进度管理的方针与工具，规定进度计划如何制订、更新与汇报，为后续工作设定规则。
- **定义活动**：将工作包进一步分解为具体的进度活动，确定完成可交付物所需开展的动作，得到活动清单与活动属性。
- **排列活动顺序**：识别活动之间的逻辑关系（完成到开始、开始到开始、完成到完成、开始到完成），建立项目进度网络图，这是关键路径分析的基础。
- **估算活动持续时间**：利用专家判断、类比估算、参数估算、三点估算等方法，估算完成每项活动所需的时间，为排程提供输入。
- **制订进度计划**：综合活动、逻辑关系、持续时间与资源，通过关键路径法（CPM）、关键链法、资源优化等方法生成进度模型，输出进度基准与项目日历。
- **控制进度**：持续监控进度状态，计算进度偏差，分析趋势，采取纠正或预防措施，如进度压缩（赶工、快速跟进），并对进度基准的变更走变更控制流程。
- **维护进度模型**：随着项目推进不断更新进度计划，通过滚动式规划仅对近期工作详细规划、远期工作保持概要层级，确保进度计划始终现实可行。
- **进度报告与沟通**：定期向干系人汇报进度状态、里程碑达成与进度预测，运用进度网络图、甘特图和里程碑图等可视化工具支撑汇报与沟通。
- **多方法与场景适配**：根据项目特点选用关键路径法、关键链法、基于位置的进度规划（如施工中的流水线）、精益进度规划（拉动式生产与看板）等方法。
- **迭代计划与时间盒（适应型）**：适应型项目采用迭代计划、时间盒和节奏管理，在每次迭代开始前细化计划。`,
      "🔗 与其他绩效域的相互作用": `进度绩效域与治理、范围、财务、利益相关方、资源和风险绩效域紧密相互作用：

- **与范围、财务绩效域的互动**：范围、进度和财务绩效域彼此密切关联，其中任何一个绩效域的变更都可能影响其他绩效域——范围增加通常延长工期并推高成本，进度延迟往往导致成本上升。
- **与利益相关方绩效域的互动**：进度计划是管理干系人期望的重要工具，干系人对里程碑和交付时间的预期直接影响进度的压力。
- **与资源绩效域的互动**：进度与资源相互制约，资源不足会拉长工期，进度紧张则需要调配更多资源（如赶工）。
- **与风险绩效域的互动**：进度本身既承受风险（延误风险）也产生风险（时间约束），风险应对可能调整活动顺序或缓冲设置。
- **与治理绩效域的互动**：进度基准的变更需通过治理层面的变更控制，治理设定的里程碑评审与汇报节奏决定了进度的监控粒度。
- **总体平衡**：项目的持续时间取决于其范围、成本、资源和质量，各绩效域并行运作并在治理绩效域的框架下保持平衡。`,
      "✂️ 裁剪考虑": `进度规划需根据项目特征进行裁剪：

- **生命周期与开发方法选择**：预测型生命周期中，进度计划预先定义，变更通过正式程序；适应型生命周期中，进度计划更为灵活，采用时间盒式进度计划（迭代固定时长，范围可伸缩）；混合型生命周期结合了适应型方法的灵活性和预测型方法的结构化。
- **产品与可交付物属性**：关键性高的项目（如涉及安全的系统）需要更详细的进度更新与更严格的控制；新的或创新性技术可能需要更具迭代性的进度规划，因为不确定性高、需求不明确。
- **项目团队属性**：团队规模和地理分布影响进度计划的沟通与维护方式——分布式团队需要更精细的同步点；团队经验水平影响估算的详细程度和进度缓冲的设置。
- **规划深度**：即使预测型项目也可能无法提前制订详细进度，宜采用滚动式规划逐层细化。
- **方法选择**：常见进度规划方法包括关键路径法、关键链法（关注缓冲与瓶颈）、基于位置的进度规划（空间导向）、精益进度规划（面向流动与拉动）等，应根据项目类型选用或组合。
- **法规与合同约束**：合同中约定的里程碑、罚款条款等外部约束也决定了进度管理的严格程度。`,
      "📊 测量指标": `进度绩效域的关键测量指标包括：

- **进度偏差（SV）**：SV = EV − PV，反映项目提前或滞后于计划的进度金额差。
- **进度绩效指数（SPI）**：SPI = EV / PV，大于 1 表示进度提前，小于 1 表示进度落后，是衡量进度效率的核心指标。
- **关键路径长度与总浮动时间**：关键路径决定项目最短工期，关键路径上活动的总浮动通常为零；总浮动为负说明进度已落后于承诺交付日期。
- **里程碑达成率**：按期完成的里程碑数量占里程碑总数的比例。
- **挣值进度（Earned Schedule, ES）**：用挣值理论将进度偏差转化为时间单位，弥补 SV 以金额计量的局限。
- **迭代交付速率（适应型）**：每个迭代完成的用户故事或功能数量，用于预测后续交付能力。
- **周期时间与吞吐量**：工作项从开始到完成的时长以及单位时间内完成的工作项数量，反映流程效率。
- **进度预测**：基于当前绩效对完工时间的预测，是向干系人汇报的核心信息。`,
      "💼 实践案例": `某城市轨道交通信号系统改造项目，网络图显示关键路径为 26 个月。项目在启动第 4 个月时，业主因配合既有线路运营窗口限制，要求压缩工期至 22 个月。

项目经理组织进度团队进行进度压缩分析：赶工方案是在信号联调阶段增加测试工程师，将关键路径上的联调活动从 5 个月压缩到 3 个月，但需追加 800 万元人力成本；快速跟进方案是将部分子系统的室内测试与轨旁安装并行开展，风险是返工概率上升。团队测算后选择“快速跟进 + 选择性赶工”组合，将关键路径压缩至 23 个月，并评估了并行作业带来的 15% 返工风险，通过加强接口测试管理予以缓解。

项目采用滚动式规划管理进度：对近 3 个月的联调排程精确到周，对更远期工作仅保留里程碑级计划，随项目推进逐步细化。每月治理评审会上，项目经理汇报 SPI 与里程碑达成情况。在第 15 个月时，SPI 一度降至 0.92，团队识别出室外设备安装受雨季影响，提前调整作业顺序并增派现场人员，使 SPI 在两个月内恢复至 1.02。最终项目在 23 个月内完成动态验收，比原计划提前 3 个月，为后续线路运营赢得了缓冲时间。`,
    },
    keyConcepts: `进度绩效域的关键术语包括：

- **项目进度计划**：进度模型的输出，展示与计划日期、持续时间、里程碑和资源相关联的活动，是沟通与管理期望的工具。
- **估算**：对变量的可能数值或成果的定量评估，如项目工作量或持续时间。
- **进度基准**：进度模型的已批准版本，可通过正式的变更控制程序进行变更。
- **进度灵活性**：进度计划适应变化、管理风险和优化资源分配的能力。
- **进度预测**：基于编制进度时可用的信息和知识，对项目未来状况和事件的估算或预判。
- **实际持续时间**：以日历单位计量的活动实际用时。
- **项目进度网络图**：项目进度活动之间逻辑关系（依赖关系）的图形化表示，是路径分析的基础。
- **关键路径法（CPM）**：通过确定网络图中的最长路径来计算项目最短工期的排程方法。
- **关键链法（CCM）**：考虑资源约束并在关键链末尾集中设置缓冲的方法。
- **滚动式规划**：渐进明细式的规划技术，对近期工作详细规划、远期工作概要规划。
- **时间盒**：适应型项目中为迭代设定的固定时间长度，范围可在盒内伸缩。`,
    examTips: `- **关键路径法（CPM）是必考内容**：关键路径是项目网络图中最长的路径，决定项目最短工期；关键路径上的活动总浮动时间通常为零，关键路径可以有多条。
- **浮动时间计算**：总浮动 = 最晚开始 − 最早开始（LS − ES）= 最晚完成 − 最早完成（LF − EF）。
- **进度压缩两大方法**：赶工（Crashing，增加资源以压缩工期，常伴随成本增加）和快速跟进（Fast Tracking，将原本串行的活动并行执行，常增加返工风险）。注意赶工通常只针对关键路径活动。
- **SPI 公式**：SPI = EV / PV，是衡量进度效率的核心公式，大于 1 表示进度提前，小于 1 表示进度落后。
- **PERT 三点估算**：(O + 4M + P) / 6，用于估算活动持续时间，其中 O 为乐观、M 为最可能、P 为悲观。
- **滚动式规划**：重要的进度规划技术，适用于无法预先详细计划的预测型项目，体现渐进明细思想。
- **适应型项目的特点**：采用时间盒式计划、迭代计划和优先级驱动的范围伸缩，不预先锁定全部细节。
- **甘特图 vs 进度网络图**：甘特图以条形直观展示活动与时间跨度，进度网络图以节点和箭头展示活动间的逻辑依赖，前者便于汇报、后者用于路径分析，注意区分二者用途。
- **资源优化**：资源平衡（平抑资源高峰）与资源平滑（不改变关键路径的前提下调整）是常见考点，注意区分。`
  },
  "domain-finance": {
    overview: `财务绩效域涉及与执行组织内部和外部货币资源的使用和分配相关的过程与工具。财务绩效与项目的成本、资金相关，并在某些情况下也与项目的价值主张相关。该绩效域所描述的过程包括规划、估算、预算制定、融资、筹资、管理、测量和成本控制，以便项目能够为组织优化价值。

及时且准确地获取项目工作信息和绩效信息，能够使项目团队了解并确定应对当前或预期的绩效偏差所需的适当行动。使用财务指标的原因多种多样，主要包括：对照计划评估绩效、跟踪资源的利用、展示担当意识、向利益相关方提供信息、预测未来趋势、评估投资回报率和长期价值、加强风险管理。

财务测量的价值不在于数据的收集与分发，而在于围绕如何利用这些数据来做出增值且明智的决策并采取适当行动的互动。财务绩效域的根本目标，是确保项目在预算约束内高效交付，同时为组织创造可衡量的经济价值。此外，该绩效域还关注资金的时间价值与全生命周期成本，要求团队在成本决策中兼顾项目交付后的运营与维护支出，从而全面衡量项目对组织的经济贡献。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `财务绩效域中的项目管理工作覆盖成本与资金的完整生命周期：

- **规划成本管理**：确定成本估算、预算和控制的方法与方针，规定成本管理的精度、单位、报告规则与偏差阈值。
- **估算成本**：利用类比估算、参数估算、自下而上估算、三点估算等工具，对完成项目活动所需资源进行定量评估，输出各活动及工作包的成本估算。
- **制定预算**：汇总各项估算，形成按时间段分配的批准预算——成本基准，并在成本基准之上增设管理储备，共同构成项目预算。
- **获取资金与融资**：通过组织内部预算、客户合同、拨款或众筹等方式为项目筹措资金，并根据资金到位节奏安排项目支出。
- **控制成本**：持续监控成本绩效，计算成本偏差与绩效指数，分析趋势，识别超支根因，对储备动用与预算变更实施变更控制。
- **挣值管理（EVM）**：整合范围、进度与成本数据，计算 PV、EV、AC、SV、CV、SPI、CPI、EAC、ETC、TCPI 等指标，全面评估项目健康度并支持预测。
- **财务测量与报告**：按既定频率向利益相关方汇报成本绩效，对照计划评估绩效、跟踪资源利用、展示担当意识。
- **财务决策与价值分析**：评估投资回报率（ROI）、内部收益率（IRR）、回收期、净现值（NPV）等，支持融资决策与长期价值评估，并考虑全生命周期成本。
- **风险相关的财务储备**：管理应急储备（应对已知—未知风险）与管理储备（应对未知—未知风险），并跟踪其使用情况。
- **财务预测与纠偏**：基于当前成本绩效预测完工成本，识别成本趋势中的异常信号，及时采取调整资源结构、重新谈判供应商价格、削减非增值活动等纠偏行动，并向治理层面透明汇报财务风险。`,
      "🔗 与其他绩效域的相互作用": `财务绩效域与多个绩效域密切关联：

- **与范围、进度绩效域的互动**：财务绩效域与范围、进度绩效域密切关联。范围变更直接影响成本，进度延期通常导致成本增加；成本、时间、范围三项约束相互依赖。
- **与治理绩效域的互动**：治理绩效域通过预算审批和财务控制来影响财务决策，预算与储备的动用需要治理授权。
- **与利益相关方绩效域的互动**：利益相关方通常协助制定预算、做出资金决策并监督财务控制，其期望直接影响资金安排的优先级。
- **与风险绩效域的互动**：风险绩效域的应对措施可能需要动用应急储备或管理储备，财务数据也是风险识别的输入。
- **与资源绩效域的互动**：资源获取决策直接影响项目成本——内部资源、外购资源或租赁的财务成本不同，资源结构决定了成本结构。
- **与团队绩效域的间接互动**：财务绩效通过激励机制与资源投入影响团队士气，而团队效率的波动又会反过来反映到成本绩效上。`,
      "✂️ 裁剪考虑": `财务管理需根据项目特征进行裁剪：

- **项目规模和复杂性**：大型复杂项目需要更精细的估算、多级预算审批和严格的成本控制；小型项目可简化汇报频率与审批层级。
- **组织财务管理实践**：遵循组织的过程资产、政策与治理规则，预算编制方式与会计核算口径因组织而异。
- **行业特定要求**：如建筑、航空航天、制药等行业对成本估算精度、审计与合规有更高要求。
- **合同类型**：固定总价、成本加酬金、工料等合同类型决定了成本风险由谁承担，进而影响估算与控制的严格程度。
- **资金来源和限制**：内部预算、外部融资或客户合同拨款等资金来源不同，资金到位的时序与灵活性不同，影响支出安排。
- **报告要求和频率**：根据干系人需求设定成本报告的详略与频率。
- **成本估算方法和工具**：预测型项目需要详细的成本估算和严格的变更控制；适应型项目可能采用更灵活的预算方式，如按迭代或按季度分配和修订预算。
- **全生命周期视角**：除项目执行成本外，还应考虑运营和维护等生命周期成本。`,
      "📊 测量指标": `财务绩效域的关键测量指标包括：

- **成本偏差（CV）**：CV = EV − AC，反映成本是超支（负值）还是节余（正值）。
- **成本绩效指数（CPI）**：CPI = EV / AC，大于 1 表示成本效率良好，小于 1 表示成本超支。
- **完工估算（EAC）**：基于当前绩效对项目最终成本的预测，常用公式 EAC = BAC / CPI 等。
- **完工尚需估算（ETC）**：完成剩余工作所需的成本估算。
- **完工尚需绩效指数（TCPI）**：TCPI = (BAC − EV) / (BAC − AC)，表示要达成既定目标，剩余工作必须达到的成本绩效水平。
- **资金需求曲线**：按时间段分配的资金需求（预算与储备），用于融资安排。
- **投资评估指标**：ROI（投资回报率）、IRR（内部收益率）、回收期、NPV（净现值）等，用于评估项目价值主张。
- **储备使用情况**：应急储备与管理储备的动用比例，反映风险应对的资金压力。
- **现金流**：项目现金的流入与流出节奏，直接影响组织的融资需求。
- **成本绩效趋势**：连续数期的 CV、CPI 走势，用于判断成本问题是暂时波动还是持续恶化，支持早期纠偏决策。`,
      "💼 实践案例": `某市政府采购的智慧政务系统集成项目，合同总价 5000 万元，采用固定总价合同。项目经理带领团队估算后形成成本基准 4800 万元，另设管理储备 200 万元，项目预算合计 5000 万元。

项目进行到第 8 个月时，挣值分析显示：计划价值 PV = 2400 万元，挣值 EV = 2040 万元，实际成本 AC = 2400 万元，由此 CPI = 0.85，成本绩效明显落后。团队分析根因发现，核心中间件供应商报价上涨 15%，且部分开发人员经验不足导致返工。

项目经理启动变更控制：申请动用 150 万元应急储备（该供应商涨价属于可预见的“已知—未知”风险，此前已列入风险登记册），同时要求供应商更换实施团队并通过验收测试规范减少返工。委员会批准动用应急储备后，团队重新计算 EAC = BAC / CPI，意识到若不干预将大幅超支。随后项目更换了部分中间件服务并优化开发流程，CPI 回升至 0.95。

季度财务评审会上，项目团队用 EVM 图表向政务业主透明展示了成本趋势与纠偏效果，业主认可其担当意识。项目最终以 4950 万元收尾，仅略高于成本基准，管理储备未动用，组织也从本次供应商涨价案例中更新了中间件类风险的储备评估基线。`,
    },
    keyConcepts: `财务绩效域的关键术语包括：

- **价值定义**：组织采用多种策略来定义价值，通常基于财务回报使用 ROI、IRR、回收期或 ROA 等度量指标。
- **价值最大化**：财务绩效域不仅关注成本管理，还致力于确保项目能为组织交付最大价值。
- **资金筹措**：可通过组织内部预算、客户合同、拨款或众筹等方式获得资金。
- **财务制约因素**：预算通常是主要财务制约因素，资金类型可能包括资本性支出（CapEx）和运营性支出（OpEx）。
- **项目预算**：构成取决于组织内部的组织过程资产、政策、治理和财务管理实践，等于成本基准加上管理储备。
- **成本基准**：已批准的按时间段分配的项目预算版本，不包括管理储备。
- **储备**：应急储备（应对已知—未知风险）和管理储备（应对未知—未知风险）。
- **成本估算方法**：类比估算（参照历史相似项目）、参数估算（基于历史数据与统计关系）、自下而上估算（逐层汇总工作包估算）、三点估算（综合乐观、悲观与最可能值）等，是形成成本基准的基础。
- **现金流管理**：跟踪项目资金的流入与流出节奏，确保项目在关键节点拥有可用资金，避免因资金短缺导致工作停滞。
- **成本管理**：需考虑全生命周期成本和维护费用。
- **挣值管理（EVM）**：整合范围、进度、成本衡量项目绩效的方法，核心要素为计划价值（PV）、挣值（EV）与实际成本（AC）。`,
    examTips: `- **挣值管理（EVM）公式必背**：SV = EV − PV、CV = EV − AC、SPI = EV / PV、CPI = EV / AC、TCPI = (BAC − EV) / (BAC − AC)。要能根据数据判断项目状态并计算预测值。
- **应急储备 vs 管理储备**：应急储备应对“已知—未知”风险，计入成本基准，由项目经理掌握；管理储备应对“未知—未知”风险，不计入成本基准，动用需高级管理层批准。成本基准 = 项目预算 − 管理储备。
- **EAC 的多种算法**：EAC = BAC / CPI（典型偏差）、EAC = AC + (BAC − EV)（非典型偏差）等，注意题干提示的偏差类型。
- **CapEx vs OpEx**：资本性支出是形成长期资产的支出，运营性支出是维持日常运营的支出，注意区分。
- **全生命周期成本**：不仅要考虑项目执行成本，还要考虑运营和维护成本。
- **EVM 三项基本要素**：PV（计划价值）、EV（挣值，已完成工作的计划价值）、AC（实际成本），所有挣值公式都建立在三项要素的基础上。
- **财务测量的价值在于决策**：财务数据本身不是目的，围绕数据做出明智决策并采取行动才是价值所在。
- **合同类型与风险**：固定总价合同将成本风险转嫁给供应商，成本加酬金合同则将风险保留在买方，这影响估算与控制的取向。`
  },
  "domain-stakeholder": {
    overview: `【绩效域概述】利益相关方绩效域（Stakeholder Performance Domain）聚焦于与利益相关方的有效互动，涵盖从识别利益相关方、分析其需要与期望，到在整个项目生命周期中争取其参与并持续监督其参与情况的全过程。利益相关方是能影响项目决策、活动或成果的个人、群体或组织，也包括受项目影响或自认为会受项目影响的各方，例如项目发起人、客户、团队成员、供应商、政府机构、监管者、竞争对手、社区等。利益相关方可以是组织内部的，也可以是外部的；一个项目可能仅有几名利益相关方，也可能有多达数百万名利益相关方。在项目的不同阶段会有不同的利益相关方，随着项目推进，利益相关方的影响力、权力或利益都可能发生变化，因此有效的识别、分析和争取必须贯穿整个生命周期，不能一劳永逸。

该绩效域的核心目标是建立并维持与利益相关方之间富有成效的工作关系，确保利益相关方对项目方向的支持，从而提高项目成功的可能性。它涵盖组织内部和外部的各方——既有支持项目者、保持中立态度者，也有反对项目者——需要对各类群体分别施策。该绩效域与沟通管理密切相关，沟通是争取利益相关方参与的主要手段。在该绩效域中需要培养的关键技能包括谈判和冲突管理。虽然掌握相关的技术项目管理技能是成功交付项目的重要方面，但具备与利益相关方有效协作的人际关系技能和领导力也同样重要，甚至更为重要。积极的发起人是项目取得良好成果的关键成功因素，项目经理应主动争取其支持；利益相关方满意度应作为优先事项纳入项目目标。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `- **识别利益相关方**：项目启动阶段即着手识别所有能影响项目或受项目影响的个人、群体和组织，记录其角色、部门、期望、联系信息等，形成干系人登记册（Stakeholder Register），并在整个生命周期中持续更新——新干系人会随项目推进不断出现，识别不是一次性活动。
- **分析利益相关方并确定优先级**：运用权力/利益方格、影响/作用方格、凸显模型（Salience Model，依据权力、紧急性、合法性三个维度）以及影响方向等分析模型，评估各干系人的权力、利益、影响力和当前态度，确定管理优先级，明确“重点管理谁、令谁满意、随时告知谁、只需监督谁”。
- **争取利益相关方参与**：根据干系人需要裁剪沟通方式，通过会议、报告、演示、定期反馈等渠道主动沟通，借助干系人参与度评估矩阵（Stakeholder Engagement Assessment Matrix）对比“当前参与度”与“期望参与度”在不知晓、抵制、中立、支持、领导五级上的差距，制定针对性的争取策略。
- **监督利益相关方参与**：在项目执行中持续监控干系人参与情况与满意度变化，及时调整沟通计划与参与策略；当干系人态度、权力或利益发生变化时，更新登记册与参与度矩阵。
- **管理冲突与谈判**：干系人之间往往存在利益分歧，项目经理需要运用谈判、协调与冲突管理技能，在各方诉求之间寻找平衡，避免冲突升级影响项目推进。
- **争取发起人的积极支持**：发起人为项目提供资金、资源与决策授权，项目经理应主动汇报进展、及时请求决策，使发起人始终了解项目状态并保持支持。
- **管理供应商与采购关系**：供应商和供方是重要的外部利益相关方，项目经理应具备供应商管理技能，确保合同履行与交付质量。`,
      "🔗 与其他绩效域的相互作用": `利益相关方贯穿于项目的各个方面，大部分项目工作都围绕着与利益相关方互动和沟通展开，因此本绩效域与所有其他绩效域都发生相互作用：
- **与团队/资源绩效域**：项目团队成员本身就是最重要的内部利益相关方，应予以同等对待；干系人的需求与期望是团队工作方向与动力的来源，干系人满意度直接影响团队士气。
- **与治理绩效域**：两个绩效域紧密相互作用，特别体现在争取项目治理机构和组织领导层（发起人、治理委员会、PMO）主动参与项目决策所需的技能上，高层支持需要专门的关系维护。
- **与财务绩效域**：利益相关方通常协助制定预算、做出资金决策并监督财务控制，财务信息的透明沟通有助于建立干系人信任，两个绩效域保持一致。
- **与规划绩效域**：利益相关方为项目团队定义需求和范围并排序其优先级，参与并影响项目规划，其期望直接转化为范围、进度与成本目标。
- **与交付绩效域**：利益相关方确定项目可交付物和成果的验收标准与质量标准，交付结果必须得到关键干系人的认可才能被接受。
- **与风险绩效域**：利益相关方是风险和不确定性信息的重要来源，其风险偏好决定项目整体风险承受水平；干系人态度变化本身也可能引发新的风险。
- **与测量绩效域**：干系人满意度与参与度是重要的绩效指标，测量结果又反过来驱动干系人管理策略的调整。`,
      "✂️ 裁剪考虑": `- **组织文化**：扁平化组织倾向于开放式沟通和非正式渠道，干系人管理可更灵活；层级化组织需要采用更正式、按层级展开的沟通与审批流程。
- **项目规模与干系人数量**：拥有众多干系人的复杂项目需要更精细的沟通管理计划，沟通渠道数量按 n(n-1)/2 计算；干系人数量有限的小型项目沟通渠道有限，可采用更轻量的做法。
- **产品与开发方法**：支持交互式、增量式方法的产品通常提供特定的干系人互动框架，如产品负责人代表客户利益、每日站会与迭代评审会创造频繁反馈机会；预测型项目则通过里程碑评审、正式变更控制委员会等机制与干系人互动。
- **行业与监管环境**：医药、金融、政府等受监管行业需满足合规沟通要求，会引入监管机构、审计方等额外干系人。
- **干系人地域分布**：跨时区、跨地域的干系人需要借助视频会议、协作平台等虚拟沟通工具，并注意时差与文化差异。
- **大语言模型与人工智能**：评估AI的使用情况，利用AI生成用于沟通的工件（会议纪要、状态报告、演示材料等），同时考虑安全和伦理措施，避免敏感信息泄露。
- **干系人文化与语言**：多元文化背景要求适配语言、沟通风格与礼仪，尊重不同文化偏好。`,
      "📊 测量指标": `- **干系人满意度**：通过满意度调查问卷、焦点小组访谈、一对一沟通等方式定期测量，将结果与项目目标对照，确保干系人诉求得到满足。
- **干系人参与度**：使用干系人参与度评估矩阵比较当前与期望参与度级别（不知晓/抵制/中立/支持/领导），量化参与度提升幅度；差距较大时及时调整争取策略。
- **干系人识别及时性与完整性**：考察干系人是否在项目早期被识别，是否有干系人在后期才被遗漏补充，反映识别过程的成熟度。
- **干系人变化率**：统计干系人登记册的增删与属性变更频率，变化频繁说明项目环境波动大，需要加强监控。
- **积极支持比例**：追踪处于“支持”与“领导”级干系人的占比，支持者越多，项目推进阻力越小。
- **沟通效果指标**：衡量信息传递的及时性与准确性，如会议决议落实率、误解与返工次数、干系人提出异议的频率。
- **沟通渠道有效性**：评估不同沟通方式（正式/非正式、书面/口头、虚拟/面对面）的覆盖面与反馈效率。`,
      "💼 实践案例": `某商业银行实施核心系统升级项目，涉及内部干系人（发起人、信息技术部、业务部、风控合规部、分支行一线员工）与外部干系人（软件供应商、监管机构、客户）。项目启动时，项目经理通过头脑风暴与访谈识别出全部干系人并建立登记册；用权力/利益方格分类——发起人与监管机构高权力高利益，纳入重点管理，定期一对一汇报；业务部门高权力低利益，令其满意并及时通报关键决策；一线员工低权力高利益，随时告知并收集反馈；供应商按合同管理。同时使用参与度评估矩阵发现风控合规部起初“抵制”，于是安排合规顾问参与每日站会并共同设计审批流程，将其提升为“支持”。项目中期监管新规发布引入新干系人，团队及时更新登记册并调整沟通计划。收尾阶段通过满意度调查，干系人满意度达到90%以上，系统平稳上线。该案例体现了“识别—分析—争取—监督”闭环与沟通管理的价值。`,
    },
    keyConcepts: `- **干系人登记册**：记录干系人识别、评估与分类结果的文档，是干系人管理的基础工件，需在整个生命周期持续更新。
- **争取利益相关方参与**：包括识别和分析利益相关方的需要，管理期望与沟通，以促进利益相关方对项目的支持。
- **利益相关方满意度**：应将其视为优先事项并纳入项目目标，是衡量本绩效域成果的核心维度。
- **积极的项目发起人**：项目取得良好成果的关键成功因素，为项目提供资金、资源、决策与政治支持。
- **项目团队的主动参与**：项目团队成员也是关键的利益相关方，应当予以同等对待和尊重。
- **沟通管理**：保持利益相关方参与的关键概念，应根据利益相关方的需要裁剪沟通方式（正式/非正式、口头/书面、虚拟/面对面）。
- **数据驱动的决策制定**：利用AI工具高效地收集、分析和解释数据，为干系人管理决策提供依据。
- **供应商和供方管理/采购**：项目经理应具备与供应商管理相关的重要技能，供应商是重要的外部利益相关方。`,
    examTips: `- **权力/利益方格**：识别和分析干系人的核心工具，横轴利益、纵轴权力，四象限对应不同策略——高权力高利益“重点管理”、高权力低利益“令其满意”、低权力高利益“随时告知”、低权力低利益“监督”。
- **沟通渠道数=n(n-1)/2**：高频计算题，注意陷阱——题干说“增加/减少了几名干系人”时需要重新计算总数。
- **干系人参与度评估矩阵**：五级（不知晓/抵制/中立/支持/领导），考察“当前”与“期望”参与度的差距，差距为负（抵制或不知晓）时需采取行动。
- **People板块占考试42%**：干系人、团队相关题目比重最大，必须吃透。
- **发起人的角色和职责是高频考点**：发起人提供资金与决策支持，不管理日常项目活动；“识别发起人”是启动阶段的关键动作。
- **利益相关方识别不是一次性活动**：需要在整个项目生命周期中持续更新，出现新干系人（如新法规、新官员、新部门）时及时识别并登记。
- **常见陷阱**：遇到干系人问题，首选动作是“与干系人沟通/更新干系人登记册与参与度矩阵”，而非直接修改项目计划；不要忽视低权力干系人（如领域专家）；干系人支持度下降时先分析原因再调整沟通策略。`
  },
  "domain-resource": {
    overview: `【绩效域概述】资源绩效域（Resource Performance Domain）聚焦于项目团队如何有效且高效地规划和利用可用资源。这里的资源既包括人力资源（项目团队成员），也包括实物或虚拟资源（如设备、材料、用品、设施、基础设施、软件、测试环境、许可证、服务、信息或文件）。资源绩效域还涉及资源的可用性、利用率和维护工作，目标是让有限的资源在正确的时间、以正确的数量和质量投入项目。

管理团队资源与管理实物或虚拟资源所需的技能和能力有所不同：实物资源的管理更多依赖计划、采购、库存与维护等流程性技能；团队资源的管理则依赖领导力、人际关系与激励技巧。项目经理作为项目团队的领导者，负责团队的组建和高效运作，应在获取、管理、激励和赋能项目团队方面投入适当的精力。此外，项目经理还应了解影响团队的各种因素，如团队环境、团队成员的地理位置、利益相关方之间的沟通、组织变革管理、内部与外部政治、文化问题与组织独特性。项目经理还常与资源经理（对一个或多个资源拥有管理职权的个人）协作，通过协商获取资源并解决资源竞争。

资源绩效域的预期成果包括：在交付项目结果的同时高效利用资源；建立一支高绩效、能适应变化并交付价值的团队；为团队成员提供能发挥其潜力、富有吸引力和专业发展机会的工作环境。资源规划必须与进度和成本规划协调进行，因为资源是进度与成本估算的基础，也是项目能否按承诺交付的根本保障。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `- **规划资源管理**：识别完成项目所需的人力与实物资源类别、数量、技能要求与时间安排，制定资源管理计划，明确资源获取方式、角色职责与资源日历；运用RACI矩阵（责任分配矩阵）界定每项活动的角色——A为Accountable（负责，每项活动有且只有一个）、R为Responsible（执行）、C为Consulted（咨询）、I为Informed（知会）。
- **获取资源**：与职能经理、资源经理协商获取团队成员，评估并选择供应商获取实物资源；关注资源的可用性、技能匹配度与到位时间，避免因资源未及时到位造成进度延误。
- **组建团队**：招募合适人员，通过团队章程明确目标、角色、职责与基本规则，营造共同目标感；评估成员技能差距，安排必要的培训与发展。
- **建设团队**：运用Tuckman团队发展阶段模型（形成→震荡→规范→成熟→解散）识别团队所处阶段并采取相应领导行为；通过激励、认可、团建与授权提升协作效率，培养高绩效团队文化。
- **管理团队**：跟踪成员绩效与满意度，运用冲突管理（合作、妥协、缓和、强制、回避）解决团队分歧，妥善处理人员更替；关注员工福祉，识别职业倦怠与“隐性离职”迹象并及时干预。
- **管理实物与虚拟资源**：跟踪资源利用率，处理资源冲突，安排资源的维护、升级与释放；利用资源日历协调共享资源的使用时间。
- **管理虚拟团队**：对异地分散的团队，借助视频会议、协作软件等技术手段提高沟通效率，强化信任建设与文化融合。`,
      "🔗 与其他绩效域的相互作用": `资源绩效域与所有其他绩效域相互作用，其中利益相关方、资源和风险三大绩效域对项目成果具有显著影响，而项目成果由进度、成本和范围参数定义：
- **与利益相关方绩效域**：干系人（尤其是职能经理与发起人）掌握资源分配权，直接影响资源可得性；干系人期望也决定资源的投入方向。
- **与风险绩效域**：资源短缺、关键人员依赖是常见风险来源，资源可用性变化会触发风险应对；风险管理中的人员配置计划与资源绩效域相互衔接。
- **与规划绩效域**：估算资源过程与估算成本等其他过程紧密协同，资源需求驱动进度与成本估算，进度计划又反向约束资源的时间安排，确保项目规划与执行的全面性。
- **与进度绩效域**：资源日历与进度计划相互约束，关键路径上资源到位与否直接决定工期；资源冲突导致延误时需调整资源分配或进度安排。
- **与交付绩效域**：团队是交付可交付物的主体，资源质量与团队能力直接决定交付物质量与价值实现。
- **与测量绩效域**：资源利用率、团队绩效等指标是测量绩效域的重要输入。
- **与治理绩效域**：组织治理结构决定资源获取的职权与流程，项目经理需在组织授权范围内获取和使用资源。
- 此外，其他项目可能在同一时间、同一地点争夺相同的可用资源，这种资源竞争可能对项目成本、进度、风险、范围、质量和其他项目领域产生重大影响，需要主动协调。`,
      "✂️ 裁剪考虑": `- **选择开发方法**：预测型项目需要提前规划资源管理，明确角色与资源需求并提前获取；适应型（敏捷）项目适合由通才型专家组成的自组织团队，角色更灵活，资源可随迭代动态调整。
- **项目团队的文化成熟度**：跨组织、跨部门组建的团队可能更正式化，需要更明确的章程与协议；成熟团队可减少行政管控。
- **行业背景**：制造业等可应用精益管理、准时制（JIT）、持续改进（Kaizen）等方法优化资源利用；IT、服务等行业侧重知识型团队的激励与协作。
- **组织治理结构**：影响职权与职责的集中化或分散化程度，矩阵型组织中资源双重汇报关系需要特别协调。
- **决策中的可持续性考量**：资源获取与消耗应兼顾环境、社会与经济可持续性，例如减少浪费、绿色采购。
- **项目团队成员的成熟度**：经验丰富的高年级成员可承担更多自主决策，新成员需要更多指导与培训。
- **虚拟项目团队**：需要借助技术手段提高沟通效率，制定明确的工作时间与协作规范。
- **重视员工福祉**：关注职业倦怠和“隐性离职”问题，通过合理负荷、灵活安排与心理支持保障团队健康与可持续产出。`,
      "📊 测量指标": `- **资源利用率**：计算资源实际用于项目的时间占总可用时间的比例，识别过度分配或闲置资源——利用率过高易引发倦怠，过低则造成成本浪费。
- **资源可用性**：评估按计划时间获得所需资源的达成率，反映资源获取过程的有效性。
- **团队人员更替率**：统计团队成员离职、调入调出情况，高更替率往往提示团队建设或工作环境问题，且会增加成本与进度风险。
- **团队士气与满意度**：通过定期员工调查、一对一沟通评估团队满意度，与干系人满意度调查配合使用。
- **技能差距**：识别团队成员现有技能与任务所需技能的差距，衡量培训投入的必要性。
- **团队效能**：衡量目标达成率、协作质量、决策速度与创新产出，例如敏捷团队的速率（Velocity）与燃尽图进度。
- **员工福祉指标**：监测加班时长、缺勤率、参与度下降等倦怠信号，预防“隐性离职”。
- **实物资源状态**：记录设备故障率、维护成本、闲置比例等，保障实物资源正常可用。`,
      "💼 实践案例": `某互联网公司启动一款移动应用开发项目，采用混合型（前端敏捷、后端预测）开发方式。项目经理与资源经理协商，获取了5名开发人员、2名测试人员和1名产品设计师组成的跨职能团队，并利用RACI矩阵明确了每个迭代任务的唯一负责人（A），避免职责不清。项目启动初期团队处于“形成”阶段，成员彼此陌生、沟通较少；项目经理组织团队建设活动并共同制定团队章程，约两周后团队进入“震荡”阶段，前后端对接口规范产生分歧，项目经理运用“合作”式冲突解决组织专题会议统一了方案，推动团队进入“规范”与“成熟”阶段，开放沟通与共同担当成为常态。项目中段，一名核心开发人员表现出隐性离职迹象，项目经理及时一对一沟通、调整工作负荷并安排知识传递，将人员更替的影响降到最低。实物资源方面，项目组通过资源日历提前预约测试环境，避免了与另一项目的环境冲突。最终项目按计划交付，团队士气调查得分高于公司平均水平。`,
    },
    keyConcepts: `- **项目经理**：作为项目团队的领导者，负责团队的组建和高效运作，统筹资源的获取、利用与维护。
- **资源经理**：对一个或多个资源拥有管理职权的个人（如职能经理、部门经理），项目经理需与其协商获取资源。
- **人力资源（项目团队成员）**：在项目团队中被分配特定角色和职责的个人，是项目价值创造的主体。
- **实物、材料或虚拟资源**：除人力资源外的所有资源，包括设备、材料、用品、设施、基础设施、软件、测试环境、许可证、服务、信息或文件。
- **高绩效项目团队的特征**：开放沟通、共同理解、共同担当、信任、协作、适应性、韧性、赋能/授权与自主性、认可。
- **Tuckman团队发展阶段模型**：形成（Forming）→震荡（Storming）→规范（Norming）→成熟（Performing）→解散（Adjourning），用于识别团队所处阶段并调整领导方式。
- **资源管理计划**：描述如何获取、分配、监控与释放资源的文档，含资源日历、角色职责与获取策略。
- **资源日历**：记录资源可用时间与占用情况的工具，用于资源排程与进度协调。`,
    examTips: `- **Tuckman团队发展阶段模型**：形成/震荡/规范/成熟/解散，考试常给出团队行为让你判断所处阶段——刚组建彼此拘谨是“形成”，出现分歧冲突是“震荡”。
- **冲突解决5种方式**：合作（Collaborate，双赢，最佳）、妥协（Compromise）、缓和/迁就（Smooth，求同存异）、强制（Force，职权压制）、回避（Withdraw）。优先选择合作，紧急或安全类问题可用强制。
- **RACI矩阵**：每个活动只有一个A（Accountable负责人）；陷阱——多个A或多个R不代表可以共享责任，遇到职责不清题先看RACI。
- **虚拟团队**：需要更多沟通和信任建设，考试中虚拟团队出现冲突时，首选“面对面视频会议”等加强沟通的选项。
- **仆人式领导、情商、T型人才**：敏捷资源管理的关键概念——仆人式领导服务团队、扫清障碍；T型人才既有专业深度又有广度，适合自组织团队。
- **资源冲突处理顺序**：先与资源经理/职能经理协商，再考虑替代资源、外包或调整进度。
- **常见陷阱**：把“资源”只理解为人员而忽视实物/虚拟资源；忽视职能经理在资源获取中的作用；团队成员是干系人，需同等对待。`
  },
  "domain-risk": {
    overview: `【绩效域概述】风险绩效域（Risk Performance Domain）代表了一种通过风险管理实践来管理风险、构建项目韧性的综合方法。项目充满不确定性，风险绩效域强调项目团队对各类风险及干扰因素的预判、防范、应对和适应能力，这有助于在不确定性环境下确保项目的连续性并实现成功交付。该绩效域提倡对已识别的项目风险及干扰因素采取主动规划的态度，同时建立适应性强、灵活可控的应对机制以应对突发状况。

风险是一种不确定的事件或条件，一旦发生，会对一个或多个项目目标产生正面或负面影响。潜在有害的风险通常被称为威胁，可能通过项目延期、成本超支或声誉受损等方式造成负面影响；正面风险通常被称为机会，可能包括潜在的市场份额提升、成本节约或积极的环境影响。风险可按认知程度分为“已知—已知”“未知—已知”“已知—未知”“未知—未知”四类：已知—已知是已识别并了解其影响的事件，可为其分配储备；已知—未知是已识别但发生概率或影响不确定的风险，是风险管理的主要对象；未知—未知是无法预见的事件，只能依靠整体储备与项目韧性应对。整体风险是指不确定性对项目组合、项目集或项目整体产生的影响，如果项目的整体风险过高，组织可能选择取消项目。

风险管理不是孤立的文档编制活动，而是与各绩效域紧密整合的动态过程，贯穿项目始终；项目韧性——项目吸收冲击并能够从挫折或失败中快速恢复的能力——是衡量本绩效域成果的重要维度。`,
    details: {
      "🏗️ 该绩效域中的项目管理工作": `- **规划风险管理**：确定风险管理的方法、角色职责、预算与时间安排，设定风险分类框架、风险偏好与临界值，明确风险登记册与报告机制的维护方式。
- **识别风险**：通过头脑风暴、德尔菲技术、访谈、SWOT分析、检查表、根本原因分析、假设条件分析等方式识别项目的威胁与机会，记录到风险登记册，并为每个风险指定风险责任人。
- **实施定性风险分析**：运用概率影响矩阵评估风险的概率与影响，结合紧迫性、可探测性、关联性等因素对风险排序，聚焦高优先级风险；该过程相对主观、快速，适合初步筛选。
- **实施定量风险分析**：对重要风险运用蒙特卡洛模拟、决策树分析、敏感性分析（龙卷风图）、期望货币价值（EMV）等技术量化整体风险敞口，评估实现项目目标的概率，为储备与应对决策提供数据支撑。
- **规划风险应对**：为威胁选择上报、规避、转移、减轻、接受五种策略；为机会选择上报、利用、分享、增强、接受五种策略；制定应急应对计划与弹回计划，预留应急储备和管理储备。
- **实施风险应对**：按计划执行风险应对措施，确保风险责任人到位、资源到位，并在应对效果不佳时及时调整策略。
- **监督风险**：持续跟踪已识别风险、识别新风险、评估应对措施的有效性，监控残余风险与次生风险，监督储备使用情况。
- **管理问题**：区分风险与问题——问题是当前已存在的状态或情况；将已发生且无法按风险管理的状况记入问题日志并推动解决。
- **构建韧性**：通过场景规划、应急演练、备份机制、冗余安排等方式提升项目吸收冲击与快速恢复的能力。`,
      "🔗 与其他绩效域的相互作用": `风险绩效域与范围、进度、财务和利益相关方绩效域紧密相互作用：
- **与范围绩效域**：风险可能影响项目范围（或增或减），范围变更又可能引入新的风险；在需求不断变化的适应性项目中，团队应调整计划以应对新的风险和不确定性。
- **与进度绩效域**：在范围稳定的预测性项目中，进度储备有助于管理已识别的风险；进度延误本身也会放大风险的影响。
- **与财务绩效域**：财务绩效域直接受风险管理的影响——风险应对需要预算支撑，成本超支风险影响财务控制，应急储备的计提与使用直接反映在财务计划中。
- **与利益相关方绩效域**：利益相关方是风险和不确定性的重要信息来源，其风险偏好与临界值决定了组织的风险承受水平；风险沟通需与干系人争取工作协同进行。
- **与资源绩效域**：资源短缺、关键人员依赖是典型风险源；风险应对措施往往需要额外的资源支持。
- **与测量绩效域**：风险指标（风险敞口、储备使用率、风险应对有效性）是测量绩效域的重要输入，测量结果又反馈调整风险管理策略。
- 有效的风险管理需要整合范围管理、进度规划、财务考量、利益相关方争取和沟通工作，确保各绩效域在不确定性面前保持一致应对。`,
      "✂️ 裁剪考虑": `- **项目规模和复杂性**：判断是否需要更详尽的风险管理方法——大型复杂项目需要系统的定性加定量分析，小型项目可采用轻量级的识别与应对。
- **风险偏好与临界值**：结合组织历史经验和风险厌恶程度设定风险临界值；高风险厌恶组织对威胁零容忍，机会导向型组织更愿意接受不确定性以换取收益。
- **项目风险管理的整体视角**：确保在各个绩效域之间统筹审视风险，避免部门化、孤岛式的风险管理。
- **战略重要性**：评价项目的战略重要性及其风险等级，战略关键项目需要更严谨的风险治理与上报机制。
- **开发方法**：明确预测型、适应型还是混合型——预测型侧重计划与储备，适应型强调频繁反馈、小步快跑、快速适应变化。
- **灵活规划并实施风险应对措施**：应对计划应保持弹性，可随情况变化调整，而非机械照搬。
- **探索风险识别和分析中的互补技术**：利用生成式AI和数据分析强化风险识别（挖掘历史数据、识别模式）与分析（自动化模拟），同时关注数据质量与伦理。
- **韧性规划的必要性**：通过场景规划为重大干扰事件做好准备，如关键供应商破产、自然灾害、监管突变，确保组织在冲击下仍能恢复。`,
      "📊 测量指标": `- **已识别风险数量与未识别风险比例**：反映风险识别过程的充分性，未识别风险可通过“已知—未知”与“未知—未知”的占比间接估计。
- **整体风险敞口**：所有已识别风险的潜在影响与概率的综合度量，可通过定量分析量化，并监测其随应对措施实施而下降的趋势。
- **风险应对的有效性**：对比应对措施实施前后的风险评分（概率×影响），评估优先级是否下降、敞口是否收敛。
- **威胁与机会的比例及偏差**：监测威胁与机会的分布及其对目标的净影响，避免只关注威胁而忽视机会。
- **风险发生频率与实际影响**：统计已发生风险的数量、频率及其实际影响与预估的偏差，用于校准分析质量。
- **储备使用情况**：跟踪应急储备与管理储备的使用进度，储备消耗过快说明应对不力或分析偏差。
- **韧性指标**：衡量项目在干扰后的恢复时间（Time to Recover）与中断持续时间，评估韧性建设成效。
- **问题解决及时率**：问题日志中问题的解决周期与关闭率，反映问题管理效率。`,
      "💼 实践案例": `某基础设施工程公司承建一座跨江大桥，工期24个月、预算8亿元。项目启动阶段，项目经理组织干系人头脑风暴识别出30余项风险并记入风险登记册，例如极端天气导致停工、钢材价格波动、地质勘察偏差、关键分包商违约等。定性分析用概率影响矩阵将“钢材价格大幅上涨”评为高优先级；定量分析用蒙特卡洛模拟得出项目在预算内完工的概率仅为62%，据此为进度和成本分别计提了应急储备。应对规划中，对钢材涨价采用“转移”策略签订远期固定价格合同，对极端天气采用“减轻”策略配置备用设备与应急预案，对地质偏差采用“规避”策略追加钻探勘察。实施过程中，一次罕见洪灾威胁临建设施，由于事前制定了弹回计划，团队在3天内恢复施工，体现了项目韧性。项目后期一家供应商破产（未知—未知事件），项目经理启用管理储备并快速更换分包商，将延误控制在计划范围内。最终项目按时交付，风险绩效域的主动规划与韧性建设成效显著。`,
    },
    keyConcepts: `- **风险**：不确定的事件或条件，一旦发生会对一个或多个项目目标产生正面或负面影响。
- **问题**：当前已存在的状态或情况，可能对项目目标产生影响；风险面向未来，问题发生在当下。
- **整体风险**：不确定性对项目组合、项目集或项目整体产生的影响。
- **风险偏好**：组织或利益相关方为获得回报而愿意接受的不确定性程度。
- **风险承受力**：组织或利益相关方能够承受的整体风险敞口的程度。
- **风险临界值**：对围绕某一目标的可接受偏差的度量。
- **风险敞口**：项目中所有风险的潜在影响的总体度量。
- **风险应对**：为应对特定威胁和机会而规划或实施的行动。
- **项目韧性**：项目吸收冲击并能够从挫折或失败中快速恢复的能力。
- **模糊性和不确定性**：模糊性是指不清晰的状态，不确定性涉及概率判断，两者都需要管理。
- **触发条件（Triggers）**：表明风险即将或已经发生的征兆或信号，是风险识别与监控的重要依据。`,
    examTips: `- **威胁5策略**：上报（Escalate）、规避（Avoid）、转移（Transfer）、减轻（Mitigate）、接受（Accept）——规避是消除风险本身（改变计划），转移是转嫁他人（保险、外包、固定价合同），减轻是降低概率或影响。
- **机会5策略**：上报、利用（Exploit）、分享（Share）、增强（Enhance）、接受——利用是确保机会发生，增强是提高机会发生的概率或影响。
- **定性分析vs定量分析**：定性用概率影响矩阵快速排序（较主观）；定量用蒙特卡洛模拟、决策树、敏感性分析量化（较客观），定量通常在定性之后针对高优先级风险进行。
- **EMV=P×I**：期望货币价值=概率×影响，用于决策树计算——机会取正、威胁取负，多条路径按期望值求和比较。
- **次生风险vs残余风险**：次生风险是实施应对措施引发的新风险；残余风险是采取应对后仍残留的风险，两者都需监督。
- **风险偏好vs风险承受力vs风险临界值**：偏好是“愿意接受不确定性的程度”；承受力是“能够承受的整体敞口”；临界值是“对某一目标可接受偏差的度量”，三者要区分清楚。
- **触发条件**：表明风险即将或已经发生的信号，是最早的预警。
- **常见陷阱**：风险≠问题（已发生的事件不是风险）；风险超出临界值时应上报决策而非私自接受；风险应对失效后需重新分析并调整策略，而不是照旧执行。`
  },
  "focus-initiating": {
    overview: `启动关注领域包含定义一个新项目或现有项目的一个新阶段，并授权开始该项目或阶段的一组过程。它的核心目的是为项目「立名分、定边界、拉队伍」——通过正式的授权文件，在项目与组织的商业目标之间建立明确联系，让各方对项目存在的理由、预期价值和大致边界达成共识。成功的项目始于对预期最终状态的清晰描述：清晰的商业论证能够让干系人在优先级和制约因素上达成一致，也为团队成员提供指导其工作的更广阔背景。本关注领域包含2个核心过程：启动项目或阶段、识别利益相关方。

启动过程的关键收益包括：正式授权项目或阶段，使其合法动用组织资源；在项目与业务目标之间建立价值联系；识别关键干系人并了解其期望、影响力与相互依赖关系；为后续规划提供输入。执行频率上，启动仅在项目开始时执行一次，并在每个新阶段开始时重复——对于大型多阶段项目，每个阶段都需重新确认授权。这一「阶段关口」机制确保项目在进入下一阶段前始终符合组织战略，避免资源投入偏离价值方向。

在启动阶段，项目章程在执行组织与请求组织之间建立合作关系。经批准的商业论证或类似文件，证明了启动项目的原因及其预期价值。项目章程可由发起人制定，也可由发起人委托项目经理参与起草——越早确定并指派项目经理，项目经理就越能理解项目的目的、目标和预期收益，从而更好地推动后续工作。经批准的项目章程正式启动项目。在适应型方法中，章程通常更轻量（如影响最小的工作表或简明的愿景陈述），聚焦回答关键问题：为何要实施项目？谁将参与？项目的内容是什么？项目将在何处开展？项目何时开始和结束？如何执行项目？谁是客户？`,
    details: {
      "📋 涵盖的过程": `- **启动项目或阶段（Start Project or Phase）**：制定并获批项目章程的过程，是启动领域的主过程。项目章程是一份正式文件，明确项目目的、高层级需求、总体预算、关键干系人与项目经理职权，将项目与业务目标绑定。核心输入为商业论证、协议、事业环境因素与组织过程资产；主要输出为项目章程和假设日志。章程获批即标志项目正式启动，也意味着批准动用组织资源。
- **识别利益相关方（Identify Stakeholders）**：定期识别项目干系人，分析并记录其兴趣、参与度、相互依赖关系、影响力与潜在影响。核心工具包括专家判断、数据收集（访谈、问卷）、干系人映射（权力/利益方格、凸显模型）与会议。主要输出为干系人登记册。该过程在启动阶段首次执行，并在整个项目期间随情况变化持续重复——新干系人出现或既有干系人地位改变时都要重新识别。`,
      "🔁 工作流程": `- **发起与授权**：发起人基于商业论证与组织战略发起项目，制定并签署项目章程，正式授权项目动用资源。章程获批是启动关口的核心里程碑，也是项目进入规划的前置条件。
- **尽早指派项目经理**：项目经理应在章程制定阶段或章程获批后尽早任命，以便理解项目背景并参与起草，为后续规划与执行奠定基础。
- **识别干系人**：以章程为输入，识别内外部干系人，用权力/利益方格、凸显模型等工具分析其影响力与参与度，录入干系人登记册，并据此确定优先争取的对象。
- **先后顺序**：启动内部遵循「章程→识别干系人」的先后，章程是识别干系人的输入；而「识别干系人→定义范围」的衔接把启动与规划连成一体——先明确授权与干系人，再谈范围与计划。
- **移交规划**：启动输出（项目章程、干系人登记册、假设日志）作为规划关注领域的输入。任何影响项目「存在理由」的重大变化（如商业论证失效、战略转向）都应回溯触发新一轮启动评估。
- **阶段循环**：在多阶段项目中，每个阶段开始都要重复启动动作——重新确认章程、更新干系人登记册，形成「启动→规划→执行→监控→收尾→再启动」的阶段关口循环。`,
      "⚖️ 预测型 vs 敏捷形态": `- **章程详略**：预测型项目章程通常较为详细，包含完整的高层级范围、总体预算与里程碑；敏捷项目章程则常为1-2页的轻量文档（愿景、使命、成功标准），聚焦回答「为什么做、做什么、如何算成功」，具体细节交给产品待办事项列表渐进细化。
- **授权方式**：预测型通过正式签字与阶段关口严格授权，强调控制与审批；敏捷更强调团队参与共创章程，授权基于信任而非控制，发起人提供背书与资源。
- **干系人识别时机**：预测型在启动阶段集中识别一次，之后定期审查更新；敏捷将干系人识别与争取嵌入每个迭代（迭代评审会、每日站会），随产品方向调整持续更新干系人登记册。
- **角色分工**：两者都需要发起人背书；敏捷中产品负责人承担部分「业务代言人」职责，与发起人共同定义愿景，而项目经理更多扮演仆人式领导者。
- **成功标准与验证**：预测型以章程中的里程碑与高层级验收为准，进入下一阶段需通过阶段关口；敏捷以持续交付可用增量获取早期反馈，启动的成功与否在早期迭代中即可验证并调整方向。`,
      "💼 实践案例": `某商业银行启动「移动支付APP升级」项目。商业论证测算出三年投资回报率并获董事会批准后，发起人起草项目章程：明确项目目的是提升支付体验与交易安全，高层级预算800万元，任命资深项目经理小李，授权其组建团队并动用相应资源。章程获批当日项目正式启动，项目同时创建假设日志，记录「现有核心系统接口可复用」「监管新规年内落地」等早期假设。紧接着，小李组织识别干系人：用权力/利益方格将合规部门（高权力、高利益）列为重点争取对象，将客服中心（低权力、高利益）纳入定期沟通，将技术外包商（高权力、低利益）纳入关注清单，形成干系人登记册。若改为敏捷形态，章程会压缩为1-2页的愿景与成功标准，由团队共创、发起人背书。项目随后携带章程、假设日志与登记册进入规划阶段——启动过程就此完成「立名分、拉队伍、定边界」的使命，为后续所有过程提供了授权依据与干系人全景图。`,
      "📝 启动的输入与输出": `- **主要输入**：商业论证（证明项目价值与启动理由）、协议（约定双方关系）、事业环境因素（组织文化、市场条件等）、组织过程资产（历史信息、模板、经验教训）。
- **主要工具**：专家判断（评估章程内容与干系人影响）、数据收集（头脑风暴、访谈、问卷）、人际关系与团队技能（冲突管理、引导、会议管理）、会议（章程制定会、干系人识别会）。
- **主要输出**：项目章程（授权文件）、假设日志（记录早期假设及状态）、干系人登记册（干系人信息库）。`,
    },
    keyConcepts: `- **项目章程**：正式授权项目启动的文件，在项目与商业目标之间建立联系。核心要素包括：项目目的、高层级需求、总体预算、关键干系人、项目经理职权。章程由发起人签发，项目经理可参与起草但不可越权签发。
- **商业论证**：证明启动项目的原因及其预期价值的文件，通常包含成本效益分析、投资回报率与可行性评估，是价值导向决策的依据。
- **假设日志**：记录项目早期阶段做出的假设及其状态的文件，在启动阶段创建，在整个项目期间持续更新。
- **干系人登记册**：记录已识别干系人及其分类、需求、期望、影响力与相互依赖关系等信息，是启动阶段的核心产出之一。
- **干系人分析**：系统收集干系人信息并评估其利益、期望与影响力的方法，常用权力/利益方格、凸显模型（从权力、合法性与紧迫性三维度分析）。
- **发起人**：为项目提供资金与高层支持的干系人，负责签署章程、提供资源、解决超出项目经理权限的问题，对项目的最终成功负责。`,
    examTips: `- **必考：项目章程由发起人签发**，不是项目经理签发的——但项目经理可以参与起草。情景题中凡「项目经理签发章程」均为错误选项。
- **章程的核心要素**：项目目的、高层级需求、总体预算、关键干系人、项目经理职权。考题常以「章程包含哪项」或「哪项不属于章程内容」出现——注意章程是高层级信息，不包含详细 WBS 或具体活动。
- **启动阶段核心产出**是项目章程和干系人登记册。特别注意区分：干系人登记册在启动阶段产出，干系人参与计划在规划阶段产出，两者不能混为一谈。
- **假设日志**在启动阶段创建、整个项目期间持续更新，不是一次性文件。
- **识别干系人是「定期」进行的**，不是只做一次——新干系人出现、干系人影响力变化、项目进入新阶段时都要重新识别。
- **发起人 vs 项目经理职权**：发起人负责章程、资金与高层协调；项目经理负责日常管理与执行。题目常考「超出项目经理权限的问题应上报发起人」。
- **敏捷章程考法**：轻量、团队共创、回答「为何/什么/如何算成功」，且不等于产品待办事项列表。混合型项目中可用轻量章程满足高层治理需求。`
  },
  "focus-planning": {
    overview: `规划关注领域包含明确项目范围、优化目标、为实现目标制定行动方案的过程。它是五个关注领域中过程数量最多、涉及面最广的一个，涵盖从范围、进度、成本到资源、风险、采购、沟通、干系人争取的完整规划版图，本关注领域约含20个过程。规划的目的在于把「为什么做」转化为「做什么、怎么做、何时做、花多少钱、防什么风险」，为执行阶段提供可遵循的路线图。

项目管理的每一项规划都应以项目目标为导向：应识别出实现目标所需的显性可交付物与活动，并保持它们之间的一致性——这正是「整合与对齐项目计划」过程的职责。这种一致性体现在将各绩效域的规划组件整合为统一的项目管理计划中。规划的关键收益包括：为执行提供明确指引、提前识别并规划风险应对、在干系人之间建立共识、为监控提供可对照的基准。

规划并非一次性活动。项目管理计划的内容会根据应用环境与复杂性裁剪：可以是高层级，也可以是详细级，并应具备足够适应性以应对动态环境——理想情况下通过渐进明细实现，随着项目进展获得更准确的信息。规划所需时间也应按实际情况确定，无论集中在前端还是贯穿全程；关键在于信息详细程度「足以推进项目，但不过度」。团队使用规划工件来确认干系人期望，并为他们提供决策与行动所需的信息。执行频率上，预测型项目在前期集中规划，敏捷项目通过滚动式规划在发布、迭代、每日等多个层面持续细化，并在每个迭代开始时重新规划。`,
    details: {
      "📋 涵盖的过程": `- **整合与对齐项目计划**：将各绩效域的规划组件整合为统一的项目管理计划，确保各子计划之间的一致性与连贯性。
- **规划资源获取策略**：基于战略重要性、成本、风险等确定项目组件使用内部还是外部资源，做出自制或外购决策。
- **规划范围管理**：编制范围管理计划与需求管理计划，明确如何定义、验证和控制项目范围与产品范围。
- **启发并分析需求**：通过访谈、焦点小组、问卷、原型法等识别、记录并分析干系人的需求与期望，输出需求文件与需求跟踪矩阵。
- **定义范围**：制定项目与产品的详细描述，输出范围说明书，明确可交付物、验收标准与项目除外责任。
- **制定范围结构**：将项目可交付物与工作分解为更小、更易管理的组件（WBS），形成范围基准。
- **规划进度管理**：建立设计、制定、管理、执行和维护进度计划的政策、程序与文档，输出进度管理计划。
- **制订进度计划**：应用关键路径法、资源优化、进度压缩等创建项目进度计划，输出进度基准与项目进度计划。
- **规划财务管理**：定义如何估算、预算、管理与监控项目财务，确定资金需求与财务控制方法，输出财务管理计划。
- **估算成本**：采用类比、参数、自下而上、三点估算等方法对完成项目工作所需资源成本进行近似估算。
- **制定预算**：汇总活动或工作包的估算成本，形成经批准的成本基准，并确定项目资金需求（含管理储备）。
- **规划利益相关方争取**：依据干系人的需求、期望、兴趣与潜在影响，制定争取其参与的策略，输出干系人参与计划。
- **规划沟通管理**：确定干系人的沟通需求、沟通方法与沟通模型，编制沟通管理计划。
- **规划资源管理**：定义如何估算、获取、领导与利用资源，用 RACI 矩阵明确职责，输出资源管理计划与团队章程。
- **估算资源**：估算所需团队资源及实物/虚拟资源的类型与数量，输出资源需求与资源分解结构（RBS）。
- **规划风险管理**：定义风险管理活动如何开展，编制风险管理计划，确定风险类别与概率影响标度。
- **识别风险**：识别项目的威胁与机会，使用头脑风暴、SWOT、德尔菲等记录于风险登记册与风险报告。
- **实施风险分析**：结合定性分析（概率影响矩阵）与定量分析（蒙特卡洛、决策树）评估风险对项目目标的影响。
- **规划风险应对**：为每个重要风险制定应对策略与责任人，威胁与机会各有五种应对策略。
- **规划采购管理**：记录采购决策、明确采购方法、识别潜在卖方，输出采购管理计划、招标文件与自制或外购决策。`,
      "🔁 工作流程": `- **以启动输出为起点**：项目章程、干系人登记册与假设日志是规划的输入。章程提供高层级目标与边界，干系人登记册提示需要平衡的期望。
- **先整合后细化**：整合与对齐项目计划过程统筹全局，确定各子计划如何拼接；随后各绩效域过程细化各自的子计划。
- **范围先行**：规划范围管理→启发并分析需求→定义范围→制定范围结构（WBS），形成范围基准，这是进度、成本与风险规划的基础。
- **进度与成本联动**：制订进度计划依赖范围与资源估算；估算成本与制定预算则汇总范围、进度与资源信息，形成进度基准与成本基准。
- **风险贯穿**：规划风险管理→识别风险→实施风险分析→规划风险应对，识别出的风险会反馈到进度、成本与资源规划（预留应急储备）。
- **资源与采购协调**：规划资源管理与估算资源确定内部需求，规划资源获取策略与规划采购管理决定自制/外购并筛选卖方。
- **输出与移交**：所有子计划与三大基准（范围、进度、成本）整合为项目管理计划，作为执行与监控的依据。规划过程中发现的新信息通过变更控制反馈，使计划渐进明细、持续更新。`,
      "⚖️ 预测型 vs 敏捷形态": `- **规划时机与粒度**：预测型在启动后集中进行详细前期规划，计划在前端一次性制定；敏捷采用滚动式规划，近期工作详细、远期工作粗略，仅在发布与迭代层面保持必要细节。
- **基准刚性**：预测型中范围、进度、成本基准一旦获批即冻结，变更须走正式 CCB 流程；敏捷中产品待办事项列表可灵活重排优先级，进度与成本通常是相对刚性的约束。
- **规划主体**：预测型由项目经理主导规划，专家判断与团队辅助；敏捷由自组织团队共同参与（迭代规划会、每日站会即时细化），产品负责人定义「做什么」，团队决定「怎么做」。
- **计划文档形态**：预测型输出详细的项目管理计划与子计划；敏捷以产品待办事项列表、发布计划、迭代待办事项列表为轻量载体，文档更精简。
- **混合形态**：大型混合项目往往先做高层级整体规划，再对不确定性高的组件（如软件模块）采用迭代规划，实现治理需求与敏捷性的平衡。`,
      "💼 实践案例": `某城市「智慧交通信号系统」项目（预测型）完成启动后进入规划。项目组先制定范围管理计划，通过访谈与问卷启发交警与市民需求，定义范围为「核心城区30个路口的智能信号改造」，并构建 WBS 分解为路口改造、中心平台、数据迁移等工作包，形成范围基准。进度规划用关键路径法排出8个月进度计划；成本规划以自下而上估算汇总出1200万元预算，形成成本基准；风险规划通过头脑风暴识别出「老旧设备兼容性」高风险，制定备选方案并预留应急储备。所有子计划整合为项目管理计划，经批准后作为执行阶段的行动纲领——规划阶段就此为「做什么、何时做、花多少、防什么」给出了完整答案。`,
      "📝 规划的输入输出": `- **主要输入**：项目章程、干系人登记册、假设日志、各绩效域的规划组件、事业环境因素与组织过程资产。
- **主要工具**：专家判断、数据收集与数据分析、分解、关键路径法、估算技术、备选方案分析、供方选择分析、会议。
- **主要输出**：项目管理计划（含各子管理计划与三大基准）、需求文件与跟踪矩阵、WBS 与范围基准、进度基准、成本基准、风险登记册、干系人参与计划、沟通管理计划、采购管理计划等。`,
    },
    keyConcepts: `- **项目管理计划**：整合所有子计划的统一文件，包含范围基准、进度基准、成本基准及各子管理计划，指导项目执行、监控与收尾。
- **渐进明细**：随着项目进展和更多信息的获取，逐步细化计划与估算的方法，是应对动态环境的核心理念。
- **滚动式规划**：渐进明细的具体技术——近期工作详细规划、远期工作粗略规划，随时间推移持续细化，敏捷中称为待办事项细化。
- **子管理计划**：范围、进度、成本、质量、资源、沟通、风险、采购、干系人参与等管理计划的统称，共同构成项目管理计划。
- **三大基准**：范围基准（范围说明书+WBS+WBS词典）、进度基准、成本基准——一旦建立，只能通过正式变更控制程序修改。
- **待办事项列表**：敏捷中的产品待办事项列表与迭代待办事项列表，是敏捷形态的「计划载体」，按价值与优先级排序。
- **发布计划**：敏捷中按功能组安排交付节奏的高层级计划，介于产品愿景与迭代计划之间。`,
    examTips: `- **规划不是一次性活动**：预测型中通过滚动式规划渐进明细，敏捷中每个迭代开始时重新规划——情景题常以「计划已冻结，无需再规划」为错误选项。
- **项目管理计划是「所有子计划的集合体」**，不是一份单一文件。题目常考「项目管理计划包含哪项」——子管理计划与三大基准均属，而工作绩效报告、干系人登记册不属。
- **基准只经正式变更控制修改**：情景题中「未经批准直接修改基准」必错。范围、进度、成本三大基准的修改权在 CCB。
- **规划信息「足够但不冗余」**：规划不是越详细越好，应以推进项目所需详细程度为度，避免过度规划。
- **三大基准与过程的对应关系**：范围基准在「制定范围结构」建立、进度基准在「制订进度计划」建立、成本基准在「制定预算」建立——过程与基准一一对应是高频考点。
- **渐进明细 vs 滚动式规划**：前者是原则，后者是具体技术；敏捷中的待办事项细化是滚动式规划的典型应用。
- **敏捷层级规划**：产品愿景→发布计划→迭代计划→每日细化，题目常考「敏捷中何时、在哪一层级规划」。`
  },
  "focus-executing": {
    overview: `执行关注领域包含完成项目管理计划中确定的工作，以满足项目要求的过程。它是将「计划」转化为「实际成果」的主战场：项目执行过程领导并实施计划中定义的工作，执行已批准的变更，以实现项目目标。项目工作可受益于对其更宏观目标的共同理解——例如为技术决策提供依据或激励团队成员，因此执行并非机械照搬计划，而是持续用目标校准行动。

执行过程的关键收益包括：产出可交付物、实现可衡量的项目绩效、推动干系人与沟通管理、建设并激励团队、落实风险应对与采购安排。项目经理在执行阶段的角色发生转变——从规划者变为协调者与问题解决者：协调技术、职能与管理活动，清除障碍，赋能团队。本关注领域约含9个过程，横跨治理、质量、知识、干系人、沟通、资源、风险与采购等多个绩效域。

执行过程贯穿整个项目期间，持续进行。过程中会收集工作绩效数据（原始观察与测量），并传递给相关监控过程进行分析；该分析提供了可交付物完成状态及项目绩效其他细节的信息。工作绩效数据还可用作监控关注领域的输入，并可作为经验教训的反馈，以改进未来工作包的绩效。执行还包括审查所有项目变更的影响，并落实批准的变更（纠正措施、预防措施与缺陷修复）。项目经理与项目团队共同管理并推动已规划活动的执行，协调项目生态系统内技术与职能活动的各个方面。`,
    details: {
      "📋 涵盖的过程": `- **管理项目执行**：指导并执行项目管理计划中定义的工作，管理资源、问题、风险与批准的变更，产出可交付物、工作绩效数据与问题日志，是执行领域的枢纽过程。
- **管理质量保证**：通过计划、系统化的质量活动确保过程按照干系人期望执行，关注过程质量而非事后检验，产出质量报告与测试评估文件。
- **管理项目知识**：利用现有知识（经验教训）并创造新知识以实现项目目标，显性知识可编码、隐性知识靠互动分享，维护经验教训登记册。
- **管理利益相关方争取**：与干系人沟通和协作，满足其需求、解决问题、促进适当参与，积极应对其顾虑与期望，输出问题日志与变更请求。
- **管理沟通**：按沟通管理计划确保及时、适当地收集、创建、分发、存储、检索项目信息，输出项目沟通记录。
- **获取资源**：通过预分派、谈判、多标准决策分析获取团队与实物/虚拟资源，输出项目团队派工单与资源日历。
- **领导团队**：通过反馈、协作、冲突解决或上报来指导、建设和管理团队，应用 Tuckman 团队发展阶段模型，输出团队绩效评价。
- **实施风险应对**：执行风险应对计划以应对项目风险，最小化威胁并最大化机会，持续跟踪应对措施的实施效果。
- **实施采购**：获取卖方响应、选择卖方并授予合同，包括投标人会议、建议书评价与谈判，输出选定的卖方与协议/合同。`,
      "🔁 工作流程": `- **以计划与批准变更为输入**：执行依据项目管理计划、项目文件与批准的变更请求展开，批准的变更在此阶段落地实施。
- **管理项目执行**：作为枢纽过程指挥工作执行，管理资源、问题与风险，收集工作绩效数据，产出可交付物。
- **质量与知识并进**：管理质量保证确保过程符合期望，管理项目知识将经验教训沉淀进登记册并反馈改善后续工作。
- **团队与干系人**：获取资源到位后，领导团队建设（Tuckman 模型）推动协作；管理干系人争取与管理沟通确保持续对齐。
- **风险与采购落实**：实施风险应对执行应对计划，实施采购完成卖方选择与合同签订，外包工作随之纳入执行。
- **数据流向监控**：工作绩效数据作为监控关注领域的输入，监控分析后形成工作绩效信息与报告；偏差触发变更请求，经批准后回传执行实施——形成「执行→监控→变更→再执行」的闭环。
- **经验教训回流**：执行中产生的经验教训持续更新登记册，作为未来工作包绩效改进的依据。`,
      "⚖️ 预测型 vs 敏捷形态": `- **领导方式**：预测型中项目经理按计划指挥与控制，风格偏指令性、以里程碑驱动；敏捷中采用仆人式领导，通过提问、赋能与清除障碍驱动自组织团队。
- **节奏与反馈**：预测型按阶段推进，以里程碑与正式状态报告为节拍；敏捷以短周期冲刺（如1-4周）为节拍，每日站会同步进度、迭代评审获取干系人反馈、迭代回顾改进过程。
- **质量实现**：预测型通过质量保证审计与阶段关口把关过程质量；敏捷将质量融入完成定义（DoD），通过测试驱动开发、持续集成、配对编程等实践内置质量。
- **变更响应**：预测型变更须走 CCB 审批后实施；敏捷在迭代内保持稳定、迭代间灵活重排待办事项，拥抱变更。
- **团队决策**：预测型决策集中于项目经理；敏捷授权团队自组织决策，充分利用团队集体知识。
- **工作流可视化**：预测型以正式进度报告与挣值分析呈现执行状态；敏捷用看板面板、燃尽图等信息发射源让执行状态一目了然，并借助 WIP 限制暴露瓶颈、保障流动。`,
      "💼 实践案例": `某互联网公司「会员积分商城」项目进入执行。团队通过预分派与谈判获取5名开发、2名测试与1名 UI 设计师，形成跨职能团队。执行中项目经理小李应用 Tuckman 模型：初期团队经历震荡（技术选型分歧），通过合作式冲突解决达成一致进入规范期。每日站会同步进度并暴露障碍（如测试环境不稳定），小李立即协调运维清除；迭代评审向产品负责人展示可运行增量，回顾会沉淀「环境配置流程」经验教训。质量上团队以 DoD 把关，采纳持续集成保证代码质量。期间第三方支付接口风险发生，团队立即实施应对预案切换备用通道。整个执行过程持续产出可交付物与工作绩效数据，数据实时流向监控过程评估绩效并驱动调整；经验教训登记册持续充实，为后续工作包改进提供依据。`,
      "📝 执行的输入输出": `- **主要输入**：项目管理计划、项目文件、批准的变更请求、事业环境因素与组织过程资产——其中批准的变更请求是执行阶段区别于其他阶段的独特输入。
- **主要工具**：专家判断、项目管理信息系统（进度/财务/问题追踪软件）、会议（站会/周会）、沟通技能、人际关系与团队技能、冲突管理、决策——每个工具都服务于「把计划落地」这一目的。
- **主要输出**：可交付物、工作绩效数据、问题日志、变更请求、项目沟通记录、团队绩效评价、经验教训登记册、项目文件与项目管理计划更新——其中工作绩效数据是连接执行与监控的关键纽带，经验教训登记册则在收尾时归档为组织过程资产。`,
    },
    keyConcepts: `- **工作绩效数据**：在执行项目活动过程中收集的原始观察与测量值（如实际完成百分比、实际成本、实际持续时间），是监控过程的输入。
- **可交付物**：根据项目管理计划执行活动所产生的输出，包括产品、服务或成果，是项目价值的物质载体。
- **变更请求**：对项目管理计划或项目文件提出的修改建议，类型包括纠正措施、预防措施、缺陷修复与更新——批准的变更在执行阶段落实。
- **问题日志**：记录执行中出现的阻碍或问题及其责任人、解决状态的工具，帮助团队跟踪并消除障碍。
- **经验教训登记册**：沉淀项目执行中知识、指导未来工作的载体，持续更新并在收尾时归档为组织过程资产。
- **授权与赋能**：授予团队在其职责范围内决策与行动权力，是敏捷执行的核心机制，能提升响应速度与成员积极性。
- **自组织团队**：由成员自行决定如何完成工作的跨职能团队，需要信任、清晰目标与仆人式领导的支持。
- **完成定义（DoD）**：敏捷中衡量一个条目「完成」的共同标准，是质量内建、避免返工的关键实践。`,
    examTips: `- **必考：数据流转链**——执行阶段产出「工作绩效数据」，监控阶段将其转化为「工作绩效信息」，再汇总为「工作绩效报告」。三者的层次区分是高频考点，注意顺序不可颠倒。
- **项目经理角色转变**：执行阶段从规划者变为协调者与问题解决者。情景题中「项目经理亲自下场做技术工作」通常不是最佳答案——清除障碍、赋能团队才是。
- **批准的变更请求在执行阶段实施**：未批准的变更不得实施，「先实施后补批」必错。已批准的纠正、预防与缺陷修复都要落实。
- **团队集体知识高于个体**：充分利用团队知识、鼓励协作与分享，而非依赖单点英雄——这是「构建赋能型文化」原则在执行的体现。
- **质量保证（QA）vs 质量控制（QC）**：管理质量保证关注过程、面向未来；控制质量关注产品、面向结果。执行阶段做的是 QA。
- **Tuckman 团队发展阶段**：形成→震荡→规范→成熟→解散。震荡期冲突增多属正常，需要积极管理而非回避。
- **敏捷执行考点**：仆人式领导、每日站会、迭代评审/回顾、DoD、自组织团队、WIP 限制——情景题中「项目经理直接下指令」「无视障碍」均为错误选项。`
  },
  "focus-monitoring": {
    overview: `【领域概述】监控关注领域是贯穿项目生命周期的一组过程，包含跟踪、审查和调整项目进展与绩效，识别必要的计划变更并启动相应变更的过程。随着项目的推进，外部环境与内部条件不断变化，偏差和变更在所难免，有效的项目管理需要对这些变更做出适当的调整。监控项目绩效过程为实现价值创造而进行的有效变更提供了治理之道，确保变更不是随意的，而是经过评估、审批并受控实施的。

- **监督（Monitoring）**：项目管理中持续开展的活动，贯穿项目全过程。监督包括收集、测量和评估数据及趋势，以推动项目实现更优的成果，维持项目健康，并识别需要重点关注的领域。监督回答的是“我们做得有多好、趋势如何”的问题。
- **控制（Controlling）**：在监督发现问题后采取行动，包括确定纠正或预防措施、重新进行规划，并跟进行动计划，以确保绩效问题得到解决。控制回答的是“如何纠正、如何回到正轨”的问题。
- **监控与测量的关系**：监控项目绩效过程与测量紧密相关，因为该过程需要持续跟踪、审查和报告项目度量指标。有效的测量能够为项目进展、资源利用和项目状态的评估提供所需的必要数据。通过收集并分析领先指标和滞后指标，项目从业者能够及早识别潜在问题、做出明智决策，并采取纠正或预防措施。
- **过程数量**：监控关注领域包含约10个过程，覆盖整体项目绩效与变更控制，以及范围、进度、成本、资源、沟通、风险、采购和干系人参与等多个绩效域的监督与控制活动。`,
    details: {
      "📋 涵盖的过程": `监控关注领域在本学习机中覆盖约10个过程，按绩效域归纳如下，每个过程都各司其职地支撑“跟踪—审查—调整”的监控闭环：

- **监控项目绩效**（整体/治理域）：跟踪、审查和报告整体项目进展，对照范围、进度、成本等绩效目标进行评估，综合运用挣值管理（EVM）、偏差分析和趋势分析，产出工作绩效报告与变更请求。
- **评估与实施变更**（整体/治理域）：即实施整体变更控制，管理影响项目各个方面的变更请求——纠正措施、预防措施、缺陷修复或更新建议——由变更控制委员会（CCB）评估与审批，批准后更新项目管理计划和项目文件。
- **监控范围**（范围域）：即控制范围，监督项目和产品范围的状态，管理范围基准的变更，确保可交付物满足既定标准，防止范围蔓延（Scope Creep）和镀金（Gold Plating）。
- **确认范围**（范围域）：由客户或发起人对已完成并经内部核实（控制质量）的可交付物进行正式验收，是客户接受可交付物并形成验收证据的关键关口。
- **监控进度**（进度域）：即控制进度，监控项目进度状态，管理进度基准变更，运用挣值进度指标（SV、SPI）、关键路径法、迭代燃尽图等手段确保项目按时完成。
- **监控财务**（财务域）：即控制成本，监控项目财务状态，管理成本基准变更，核心工具是挣值管理（EVM），通过CPI、CV等指标确保项目持续的财务可行性。
- **监督干系人参与**（干系人域）：持续评估干系人的参与程度与期望变化，必要时调整参与策略和计划，确保干系人维持在适当的参与水平。
- **监督沟通**（干系人域）：收集沟通活动数据，评估沟通效果，确保项目及其干系人的信息需求持续得到满足，必要时调整沟通管理计划。
- **监控资源**（资源域）：即控制资源，确保分配给项目的实物或虚拟资源按计划可用，对比资源计划与实际使用情况，及时调整资源分配。
- **监督风险**（风险域）：在整个项目生命周期中持续跟踪和分析风险，实施风险应对计划，评估应对措施的有效性，关注新风险和次生风险，运用风险审计、储备分析等方法。
- **控制采购**（治理/采购域）：管理采购关系和合同绩效，监督供应商履约情况，处理合同变更与索赔，并在合同结束时执行合同收尾。`,
      "🔁 工作流程": `监控工作遵循“测量—比较—分析—决策—行动—验证”的闭环，其典型流程如下：

- **步骤1 收集数据**：在执行过程开展工作时，持续收集工作绩效数据，如实际进度、实际成本、已完成工作量、质量指标等原始观察与测量值。
- **步骤2 对照基准比较**：将实际数据与项目管理计划中的范围基准、进度基准和成本基准进行对比，运用偏差分析确定计划与实际之间的差距。
- **步骤3 分析与整合**：运用挣值管理、趋势分析、储备分析、因果分析等方法对数据进行分析和整合，将原始的工作绩效数据转化为有决策意义的工作绩效信息，并汇编为工作绩效报告。
- **步骤4 评估影响与预测**：评估偏差对项目目标（范围、进度、成本、质量）的影响，形成进度预测和成本预测，判断偏差是否处于可接受的临界值范围内。
- **步骤5 决定应对措施**：根据分析结果确定纠正措施（使项目回到计划轨道）、预防措施（防止问题发生）或缺陷修复，并评估其对其他方面的影响。
- **步骤6 提交与审批变更**：将应对措施以变更请求形式提交，经评估与实施变更过程评估，由变更控制委员会（CCB）或其他授权人审批。
- **步骤7 更新计划与基准**：批准的变更更新项目管理计划及相应基准；未批准则维持原计划，并向相关干系人沟通决策结果。
- **步骤8 实施与验证**：批准后的变更回到执行过程实施，监控过程持续跟踪变更后的绩效，验证纠正或预防措施是否有效、问题是否真正解决。
- **步骤9 沟通与报告**：通过状态报告、绩效报告向干系人通报项目状态，将经验教训反馈到后续规划与执行中，形成持续改进。`,
      "⚖️ 预测型 vs 敏捷形态": `- **预测型（瀑布）监控**：强调“对照基准、正式变更、关口评审”。团队按既定的三大基准（范围、进度、成本基准）持续比较实际绩效，偏差超出临界值时触发正式变更请求；变更须经整体变更控制过程和CCB审批，审批后更新基准；以里程碑和阶段关口（Phase Gate）作为评审节点，依赖挣值管理等量化指标。
- **适应型（敏捷）监控**：强调“检视—调整”的经验主义循环，监控内嵌于每个迭代。团队通过每日站会检视当日进展与障碍，在迭代评审会议（Sprint Review）中演示已完成的工作并收集反馈，通过迭代回顾（Retrospective）识别流程改进点；进度主要用燃尽图或燃起图跟踪剩余工作量，范围通过待办事项列表（Product Backlog）的重新排序动态吸收变更，无需正式的CCB和纸质变更请求。
- **关键差异**：预测型把变更当作需要治理的“例外”并通过正式流程控制；适应型把变更当作常态，通过优先级重排即时吸收。预测型依赖事后量化测量，适应型强调短周期内频繁检视与即时调整。
- **混合型**：在高层级（合同、阶段、里程碑）沿用预测型监控与关口评审，在交付层采用适应型迭代监控，二者通过分层治理相衔接。`,
      "💼 实践案例": `某软件开发项目按预测型方法管理，预算500万元，工期12个月。项目进行到第6个月时，监控过程发现异常：

- **挣值分析**：PV（计划价值）=250万元，EV（挣值）=220万元，AC（实际成本）=280万元。由此计算得出CV=-60万元、CPI≈0.79（成本超支），SV=-30万元、SPI=0.88（进度滞后）。
- **趋势与储备分析**：趋势分析显示偏差仍在扩大，储备分析发现应急储备已消耗过半，若不干预预计将严重超支。
- **根因与应对**：分析发现主要原因是关键架构人员离职导致返工、外包人力成本上升。团队据此提出两项变更请求：一是调整资源计划、引入有经验的签约专家（纠正措施）；二是精简非核心功能并重新排定优先级（范围变更）。两项变更经CCB评估批准后，更新了进度基准与成本基准。
- **后续监督**：以SPI/CPI每周跟踪，确认偏差逐步收敛；同时在每日站会和月度评审中持续监督风险与新需求，防止范围蔓延。到第12个月，项目以成本超支约8%的代价按时交付核心功能，避免了更大损失。
- **关键启示**：监控的价值在于“尽早发现、量化评估、受控调整”——及时通过挣值指标识别问题，用正式变更流程治理调整，而非等到项目失败才亡羊补牢。`,
    },
    keyConcepts: `- **工作绩效数据**：在执行过程中收集的原始观察与测量值，如实际进度、实际成本、已完成百分比，未经分析整合。
- **工作绩效信息**：通过对工作绩效数据进行分析和整合而获得的绩效信息，如CV、SPI、CPI等，具有决策意义。
- **工作绩效报告**：对工作绩效信息进行汇编形成的文档，用于制定决策和沟通，如状态报告、里程碑报告、仪表盘。
- **变更请求**：监控过程中识别出的纠正措施、预防措施、缺陷修复或更新建议，是监控过程的关键输出。
- **变更控制委员会（CCB）**：由干系人组成的正式机构，负责审查、评估、批准或拒绝变更请求，批准后形成批准的变更请求。
- **基准（Baseline）**：经批准的范围、进度、成本版本，是偏差比较的参照标准，变更审批通过后方可更新。
- **偏差分析**：比较计划与实际之间的差距，用于识别范围、进度、成本等方面的偏差。
- **趋势分析**：根据历史数据预测未来走向，判断偏差是收敛还是扩大。
- **挣值管理（EVM）**：整合范围、进度、成本的量化绩效方法，核心指标包括PV、EV、AC、SV、CV、SPI、CPI、TCPI。
- **领先指标**：用于指示即将发生的变更或揭示趋势，具有预测性，如缺陷趋势、燃尽速度。
- **滞后指标**：反映过去的绩效或状况，具有回顾性，如已完成工作的实际成本。
- **测量陷阱**：常见包括霍桑效应（测量本身影响行为）、虚荣指标（好看但无用的数据）、士气低落（过度监视打击团队）、误用度量指标、确认偏见，以及将相关性误认为因果关系。`,
    examTips: `- **监控贯穿整个项目生命周期**：监控不是某个阶段的活动，而是从项目开始持续到收尾，考试中“监控只在最后阶段”是错误选项。
- **变更请求是监控阶段的关键输出**：监控过程识别出的纠正措施、预防措施、缺陷修复都要以变更请求形式提出，不能跳过变更流程直接实施。
- **变更处理顺序必考**：识别变更→评估影响→提交变更请求→CCB审批→更新计划与基准→实施→验证。CCB是审批机构，项目经理通常负责分析与推荐，无权擅自批准超出其职权的基准变更。
- **先控制质量，再确认范围**：内部质量控制核查无误后，才交由客户确认范围（正式验收），顺序不可颠倒。
- **范围蔓延 vs 镀金**：范围蔓延是未经控制的变更（多由干系人需求引起），镀金是主动添加超出需求的功能（多由团队成员引起），两者都应避免。
- **领先指标（预测）vs 滞后指标（回顾）**：要能分辨——预示未来问题的信号是领先指标，反映已发生绩效的是滞后指标。
- **测量陷阱**：霍桑效应（被测量改变行为）、虚荣指标（无用数据）、士气低落、误用度量指标、确认偏见、相关性不等于因果，都是选择题常客。
- **监控形态差异**：预测型强调基准对比和正式变更控制；适应型强调迭代评审、燃尽图和待办事项列表优先级重排，没有正式CCB。
- **EVM公式**：SV=EV-PV、CV=EV-AC、SPI=EV/PV、CPI=EV/AC、TCPI=(BAC-EV)/(BAC-AC)；CPI大于1表示节约，小于1表示超支。
- **识别问题后先找根因**：先分析根本原因再采取纠正措施，而不是急于把指标“做漂亮”掩盖问题。`
  },
  "focus-closing": {
    overview: `【领域概述】收尾关注领域包含正式完成或结束项目、阶段或合同所执行的过程。所有项目和项目阶段最终都会结束——它们可能按原计划实现预期影响，也可能因正面原因（如价值提前实现）或负面原因（如目标不再可行）比预期提前或延迟结束。结束项目或阶段过程旨在对所有与项目、阶段、发布、迭代或合同（无论成败）相关的活动进行最终结项。

- **关键收益**：归档项目信息或阶段信息，完成规划工作，并释放组织资源以用于新项目；该过程还包括确认价值或交付价值的能力在多大程度上已经实现。
- **收尾涵盖的活动**：确认所有项目活动已完成；获得客户或发起人对可交付物的正式验收；确保所有财务结算已完成；归档项目文件和经验教训；释放项目资源；将最终产品/服务/结果移交给运营团队。
- **收尾的时机**：在适应型方法中，收尾可能发生在每个迭代或发布结束时，而不仅仅在项目结束时。团队在每次迭代回顾中总结经验教训，并在后续迭代中应用；在项目最终收尾时，需要汇总所有迭代的经验教训，确保知识的完整传递。
- **收尾与监控的联系**：收尾往往是监控发现“项目已完成既定目标”或“目标已不再可实现”之后的自然终点；确认范围过程输出的验收的可交付物，正是收尾过程的关键输入。`,
    details: {
      "📋 涵盖的过程": `收尾关注领域在过程层面包含1个正式过程，另有与之配套的收尾性活动：

- **结束项目或阶段**（Close Project or Phase，治理域）：对项目、阶段、发布、迭代或合同（无论成败）的所有活动进行最终结项。其核心工作包括：确认所有项目活动与可交付物均已完成并获得正式验收；完成财务结算；汇编并归档经验教训；发布最终报告；更新组织过程资产；释放项目资源；将最终产品、服务或结果移交给客户或运营团队，并评估价值实现程度。
- **配套的合同收尾活动**：采购合同的收尾活动（确认供应商履约完毕、处理最终付款、完成索赔与争议处理）在本学习机中由监控关注领域的控制采购过程执行——合同收尾应在行政收尾（结束项目或阶段）之前完成，二者不可混淆。
- **阶段级收尾**：在多阶段项目中，每个阶段结束时也应执行收尾活动（阶段关口评审），只有通过关口才能进入下一阶段。`,
      "🔁 工作流程": `收尾工作通常遵循以下流程（按顺序执行）：

- **步骤1 确认活动完成**：对照范围基准和验收的可交付物，确认所有项目工作已完成，没有未了结的活动或悬而未决的工作项。
- **步骤2 获得正式验收**：基于确认范围过程的结果，取得客户或发起人对最终可交付物的正式签署和验收，形成验收的可交付物。
- **步骤3 完成财务结算**：结清项目账户，支付所有供应商款项和内部费用，处理与成本相关的未决事项，确保财务记录完整。
- **步骤4 完成合同收尾**：对采购合同确认供应商已按合同履约，完成最终付款，处理索赔与争议，正式关闭合同。
- **步骤5 汇编经验教训**：组织经验教训研讨会（回顾会议），收集成功经验与失败教训，记录到经验教训登记册，供未来项目借鉴。
- **步骤6 发布最终报告**：编制并发布最终报告，总结项目绩效（范围、进度、成本、质量）、成果、偏差及原因、经验教训与价值实现情况。
- **步骤7 归档项目文件**：将所有项目文件、记录、报告归档到组织过程资产，形成可复用的组织知识库。
- **步骤8 释放项目资源**：解散项目团队，归还或调配人员、设备、设施等资源，释放组织资源用于新项目。
- **步骤9 移交与庆祝**：将最终产品、服务或结果正式移交给客户或运营团队，举行收尾会议或庆祝活动，宣布项目或阶段正式结束。`,
      "⚖️ 预测型 vs 敏捷形态": `- **预测型收尾**：一次性、集中式收尾，通常发生在项目或阶段结束的关口。遵循正式流程：确认交付→正式验收→财务结算→合同收尾→行政收尾→移交资源；强调文档完整性与正式归档，经验教训在项目结束时统一收集。
- **适应型（敏捷）收尾**：收尾分散且持续。每个迭代结束时通过迭代回顾总结经验教训，并在下一迭代立即应用；每个发布（Release）结束时执行发布级收尾，交付可工作的增量价值；项目最终结束时再汇总所有迭代的经验教训，形成完整的知识传递。
- **关键差异**：预测型把经验教训的积累推迟到项目末期，适应型把学习内嵌到每个短周期中，实现“边做边改进”；预测型强调正式验收与文档归档的完整性，适应型强调持续交付与反馈闭环。
- **共同要求**：无论采用哪种形态，正式验收、资源释放、知识归档与最终移交都是收尾不可或缺的环节。`,
      "💼 实践案例": `某企业部署一套新的客户关系管理系统（CRM），采用预测型方法，历时10个月。进入收尾阶段后，项目经理执行了以下活动：

- **验收与移交**：经确认范围过程，客户签署验收报告，正式接受系统及操作手册；随后IT运营团队接管系统运维，项目团队向运营团队完成知识转移（架构文档、配置清单、运维流程）。
- **财务与合同结算**：财务部门结清项目账户，与外包开发供应商完成最终付款并关闭合同，处理了中途两次范围变更产生的追加费用。
- **经验教训与归档**：召开经验教训研讨会，总结出“需求变更频繁导致进度压力大，应尽早建立变更评审机制”等6条经验，连同全部文档归档到组织知识库；发布最终报告，报告显示项目在进度基准内完成、成本超支3%，并评估系统上线后预计每年可提升销售转化率约10%。
- **资源释放**：将5名项目成员释放，其中3人转入新启动的移动端项目，2人回归业务部门。
- **提前终止的另一案例**：同期另一个数据分析项目因主要业务假设被证伪（负面原因）而提前终止，项目经理仍执行收尾：归档已完成的调研成果、记录终止原因与经验教训、结清供应商合同、释放资源，避免更多投入。
- **关键启示**：收尾不仅关乎“做完”，更关乎“做好善后”——无论项目成败，正式验收、财务结算、知识归档、资源释放都必须完整执行。`,
    },
    keyConcepts: `- **最终产品/服务/结果移交**：将项目可交付物正式移交给客户或运营团队，是收尾的标志性活动。
- **最终报告**：总结项目绩效、成果和经验教训的文件，向发起人和干系人正式通报项目结局。
- **组织过程资产更新**：将项目经验和知识归档到组织知识库中，供未来项目复用。
- **正式验收**：由客户或发起人签署的对可交付物的正式接受，通常来源于确认范围过程的输出。
- **验收的可交付物**：经客户确认且被接受的可交付物，是收尾过程的关键输入。
- **行政收尾**：确保所有项目管理活动完成，包括文件归档、经验教训汇编、最终报告发布等。
- **合同收尾**：完成所有合同义务并结清合同，包括最终付款、索赔处理、合同关闭；合同收尾通常先于行政收尾完成。
- **经验教训**：项目过程中获得的知识与洞见，记录于经验教训登记册，用于改进后续项目。
- **收益/价值实现**：收尾时需评估预期价值与收益的实现程度，通常与商业论证中的目标进行对照。
- **提前终止**：项目因正面或负面原因提前结束时，仍须执行完整的收尾过程。`,
    examTips: `- **收尾不是只发生在项目结束时**：每个阶段结束、每次迭代或发布结束时也需要收尾，这是高频考点。
- **必须归档经验教训**：经验教训应持续记录并在收尾时汇总归档；考试中“经验教训到项目结束再做”的说法并不准确，应边做边积累。
- **行政收尾和合同收尾都要完成**：二者不同——行政收尾针对项目管理活动（文件、报告、经验教训），合同收尾针对采购合同（最终付款、关闭合同）；合同收尾通常先于行政收尾。
- **收尾时要逐项确认**：所有采购合同已结清、所有资源已释放、所有文件已归档、所有财务已结算、可交付物已获得正式验收并移交。
- **提前终止也要收尾**：无论因正面还是负面原因提前终止，都要执行收尾过程并归档经验教训，不能草草了事。
- **正式验收不等于项目结束**：验收（确认范围）发生在收尾之前，是收尾的输入，不能把两者等同。
- **释放资源**：收尾必须释放项目资源以便组织用于新项目，考试中“收尾后团队原地待命”是错误选项。
- **最终报告与价值评估**：收尾要发布最终报告，并对照商业论证评估价值实现程度。
- **经验教训“三不”**：不惩罚性追责、不流于形式、不只记成功——要记录真实的失败与改进建议，并确保未来项目可访问。`
  },
  "proc-start-project": {
    overview: `启动项目或阶段过程通过创建项目章程或类似文件，正式授权项目启动，并赋予项目经理分配组织资源用于项目活动的职权。这种授权可在项目、业务论证和组织战略目标之间建立直接联系，形成项目的正式记录，并体现组织对项目的承诺。该过程通常只进行一次，或者在项目生命周期的某些节点（如每个阶段开始时）执行，属于“启动”关注领域的核心过程。

项目章程在执行组织与请求组织之间建立了一种合作关系。经批准的业务论证证明了启动项目的原因及其预期价值。对于涉及两个或两个以上组织的跨企业项目，合同或协议用于在这些组织间建立合作关系。经批准的项目章程可正式启动项目，应尽早（务必在规划开始之前）确定和指派项目经理。项目章程可由发起人或项目经理与启动方协作制定，使项目经理能够更好地理解项目的目的、目标和预期收益。

在适应型方法中，通常可更为灵活地设计项目章程。适应型项目章程通常侧重于回答关键问题：为何要实施项目？谁将参与？项目的内容是什么？项目将在何处开展？项目何时开始和结束？如何执行项目？谁是客户？通过强调清晰性和灵活性，适应型项目章程能够确保利益相关方之间保持一致，同时在项目生命周期中具备应对变更的能力。

本过程的关键收益包括三点：其一，正式授权并确立项目经理职权，使项目团队有权使用组织资源开展活动；其二，将项目与业务论证、组织战略目标建立直接联系，为后续决策和投资评审提供依据；其三，尽早识别高层级假设、制约条件与关键干系人，为后续规划划定边界。本过程的输出项目章程与假设日志将贯穿整个项目生命周期，持续影响执行、监控与变更管理活动。`,
    details: {
      "📥 输入 Inputs": `- **商业论证**：用于证明项目经济可行性的文件，说明启动项目的原因及其预期价值。编制章程时可从中提取项目目的、预期收益、财务可行性分析等信息，作为章程的基础依据；项目获批后，商业论证仍作为评估项目价值的参照，若项目价值不再成立，可能触发项目终止或范围变更。
- **协议**：定义各方权利和义务的合同、谅解备忘录或服务协议等，用于在跨企业项目或涉及外部组织的项目中建立合作框架。协议中约定的目标、范围、验收条件与付款安排会直接体现到项目章程中，确保各方对项目预期保持一致，并明确组织间的责任边界。
- **事业环境因素**：项目团队无法直接控制但会影响项目成败的组织内部或外部条件。内部因素包括组织文化、治理结构、组织可用资源、干系人风险承受力；外部因素包括行业标准、法律法规、市场与政治环境等。这些因素界定了章程编制时的约束边界与合规要求，例如法务要求会直接影响章程的表述与审批流程。
- **组织过程资产**：组织积累的可供项目借鉴的流程、政策与知识，如项目章程模板、组织标准流程、历史项目信息、经验教训知识库、批准与授权政策等。使用标准化模板可提高编制效率并减少遗漏，参考历史项目可避免重复踩坑，确保章程与组织惯例和治理要求保持一致。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助拥有特定知识或专业训练的个人或团体（如发起人、职能经理、主题专家、行业顾问）的判断，评估项目范围、确定高层级预算与里程碑、识别关键干系人，并判断章程内容的完整性与可行性，弥补单一信息来源的不足。
- **数据收集**：通过头脑风暴（邀请干系人群策群力，收集对项目目标与范围的期望）、焦点小组（邀请有代表性的干系人集中讨论项目需求与风险）、访谈（与关键干系人一对一深入交流，获取书面资料中缺失的隐性信息）等方式，为章程编制收集充分输入，确保章程真实反映各方诉求。
- **人际关系与团队技能**：包括冲突管理（化解干系人之间在项目目标、优先级上的分歧）、引导（推动会议形成共识并聚焦议题）、会议管理（高效组织评审并控制时间）与谈判（在预算、范围、资源等议题上与干系人达成一致），用于促成利益相关方对章程内容的一致认可。
- **会议**：组织项目启动会议、章程评审会议、干系人共识会议等，用于讨论项目目标与成功标准、评审章程草案、收集修改意见，并最终推动发起人正式批准与发布项目章程，宣告项目正式启动。`,
      "📤 输出 Outputs": `- **项目章程**：由项目发起人发布的正式授权文件，授权项目启动，并赋予项目经理分配组织资源用于项目活动的职权。章程通常记录：项目目的、可测量的项目目标与成功标准、高层级需求、高层级项目描述与边界、总体风险、总体里程碑、总体预算、关键干系人名单、项目经理及其职权级别、发起人与其他指定干系人名单、假设与制约因素等核心信息。章程是项目管理计划及后续所有规划、执行、监控过程的顶层输入，也是项目变更与收尾时对照的依据。
- **假设日志**：记录项目在制定章程和规划期间识别的所有假设条件与制约因素。假设是认为真实但尚未得到证实的信息（如“关键设备将在三个月内到货”），制约因素则是限制项目团队选择的因素（如预算上限、法规要求、技术约束）。假设日志会随项目推进不断更新与核验，也是识别风险、评估变更、规划应急储备和监控项目健康度的重要输入。`,
      "🔗 与其他过程的相互作用": `启动项目或阶段过程是项目生命周期的起点，其输出的项目章程与假设日志将传递给后续所有规划类过程。项目章程是整合与对齐项目计划、规划范围、进度、成本、资源、采购、风险、沟通、利益相关方参与等过程的核心输入，为规划工作提供授权、目标与边界，确保各专项计划不偏离章程。假设日志则在识别风险、估算资源与成本、编制进度、评估变更等过程中被持续更新和引用。对于多阶段项目，每个阶段开始时都可能再次执行本过程（发布阶段授权文件或更新章程），与阶段门评审和阶段退出标准相互衔接；当项目早期章程内容过时或发生重大范围变更时，也可重新启动本过程以更新章程，使项目始终与最新业务现实保持一致。
此外，章程与假设日志也是项目组合和项目集管理的衔接点——组合层面依据商业论证与章程进行项目优选与优先级排序，项目集则以章程作为统一目标对齐各子项目的基准。`,
      "✂️ 裁剪考虑": `在预测型项目中，项目章程通常正式、详尽，在项目启动时一次性编制并批准，章程的任何变更须走正式变更程序。在适应型（敏捷）项目中，章程通常简洁、灵活，聚焦回答“为何做、谁参与、做什么、在哪做、何时做、如何做、客户是谁”等关键问题，强调对变化的响应能力，甚至允许在项目推进中迭代更新。混合型项目则对确定性高的部分采用正式章程，对探索性部分采用轻量授权。小型项目可精简章程要素并采用快速审批流程；大型复杂项目则需要多层级批准并配套完整的商业论证与治理安排。组织内部项目可能无需协议输入，而跨企业项目必须依托合同或谅解备忘录；受监管行业（如金融、医疗）的章程还需额外满足合规审查要求。
同时应裁剪章程的批准层级：低风险小项目可由职能经理批准，战略级项目须由高管层或董事会批准，以匹配治理要求与风险等级。`,
      "💼 实践案例": `某大型商业银行决定启动新一代核心银行系统建设项目。高级管理层基于商业论证确认项目具备经济与技术可行性后，任命一位资深项目经理，并授权其与发起人协作完成章程编制。项目经理通过焦点小组和一对一访谈收集业务、运营、风控、合规等部门干系人的期望，梳理出项目目的（替换老旧系统、满足监管要求）、高层级需求、总体预算约2亿元、总体里程碑（30个月内上线）等要点，并列明关键干系人与项目经理职权。章程经发起人批准后正式发布，同时在假设日志中记录“监管政策一年内无重大调整”“现有数据迁移方案可行”等假设。随后项目经理依据章程组建团队并启动规划工作，使项目与组织战略目标建立了清晰的联系，为后续获批的预算和资源投入提供了依据。
这一案例说明：一份高质量且获批准的章程，是项目取得资源与干系人承诺的前提，也是项目顺利进入规划阶段的通行证。`,
    },
    keyConcepts: `- **项目章程**：由发起人发布的正式授权文件，是项目的“出生证明”，正式授予项目经理职权并确立项目与组织战略目标的联系。
- **商业论证**：论证项目经济可行性的文件，回答“为什么要做”，是章程的重要输入，也是衡量项目价值的持续参照。
- **假设日志**：记录假设与制约条件的动态文件，随项目推进持续更新与核验。
- **发起人**：签署章程、为项目提供资金与资源支持、对项目成功负责的关键干系人。
- **协议**：合同、谅解备忘录等，在跨组织项目中界定各方权利与义务，是跨企业项目章程的前提。
- **高层级范围与总体预算**：章程中的宏观描述，区别于后续过程逐步细化的详细范围与精确预算。
- **项目目标与成功标准**：章程中可测量的目标描述，是后续绩效测量与验收的顶层依据。
- **渐进明细**：章程作为早期文件，其内容会在后续规划中逐步细化，而非一次到位。
- **阶段门（Stage Gate）**：多阶段项目中，阶段开始时的章程或授权文件是进入下一阶段的门槛，确保项目在获批后才投入资源。`,
    examTips: `- 必考！项目章程由发起人签发；项目经理不签发章程，但可以参与起草。
- 区分“商业论证”与“项目章程”：业务论证证明项目经济可行性，章程正式授权项目启动。
- 章程的核心要素要背熟：项目目的、高层级需求、总体预算、关键干系人、项目经理职权、成功标准。
- 章程应尽早发布（务必在规划开始之前），且项目经理应在章程制定阶段即被任命，而非规划完成后。
- 记住项目章程发布后项目才算正式启动；在章程批准前的工作（如可行性研究、立项调研）不属于项目执行。
- 适应型项目章程更灵活，聚焦关键问题并支持变更，而非事无巨细地固化细节。
- 常见陷阱：把总体预算误当成精确预算；把章程误认为由项目经理签发；把章程与合同混为一谈——内部项目用章程，跨企业项目还需要协议。
- 补充要点：跨企业项目启动时，合同/协议先于或与章程并行；多阶段项目中，每个阶段重新授权，而非一次性授权全部阶段。`
  },
  "proc-integrate-plan": {
    overview: `整合与对齐项目计划过程包括整合、对齐并协调所有计划组件，将其合并为统一的项目管理计划。该过程的关键收益是，创建一份全面的文件，详细说明所有项目活动各个方面的基础，以及这些活动将如何被执行。该过程通常在项目期间执行一次或在特定时间间隔执行，并在计划发生变更时随之更新，属于“规划”关注领域的枢纽过程。

项目管理计划明确规定了项目将如何被执行、监控和收尾。其内容会根据项目的应用环境和复杂性而有所不同。该计划可以是高层级的，也可以是详细的，应根据项目的具体需要对其进行裁剪。该计划还应具有足够的适应性，以应对动态的项目环境——理想情况下可通过渐进明细的方法来实现，从而确保随着项目的进展，能够获得更为准确的信息。

在项目开始阶段，应明确总体的裁剪考虑因素，并确定开发方法和项目生命周期。该信息应作为项目管理计划的一部分，并作为所有绩效域的输入，指导其规划工作。随后，应将各绩效域的所有管理计划和基准整合至项目管理计划，并对其一致性进行验证，识别并消除各计划之间的冲突。

本过程集中体现了项目管理的整合属性：项目经理最重要的职责之一，就是对各项子计划进行整合，识别子计划之间的矛盾与冲突并加以协调，使整体计划保持一致、可行且可执行。整合视角贯穿项目始终——任何单一领域计划的更新，都可能需要在整体层面重新评估其对其他计划的影响，因此本过程也是项目经理整合领导力与全局视野的直接体现。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：作为顶层授权文件，章程中的项目目的、高层级范围、总体预算、总体里程碑与关键干系人等为制定项目管理计划提供方向与约束，确保各子计划与项目目标保持一致，也是计划中对项目边界进行裁剪的依据。
- **其他过程的输出**：本过程最重要的输入，包括范围管理计划、进度管理计划、成本管理计划、质量管理计划、资源管理计划、沟通管理计划、风险管理计划、采购管理计划、利益相关方参与计划等全部子计划，以及范围基准（经批准的范围说明书、WBS与WBS词典）、进度基准和成本基准三大基准。本过程的任务就是将这批分散的计划组件整合、对齐为一份统一协调的文件，并检查它们之间的相容性。
例如，范围管理计划规定范围如何定义与验证，进度管理计划规定进度如何编制与控制，风险管理计划规定风险的应对策略与资源安排，采购管理计划规定采购决策与合同管理方式——这些计划从不同维度规定项目如何运作，只有整合起来才能形成完整的执行蓝图。
- **事业环境因素**：组织文化、行业标准、法律法规、市场条件等，决定计划的格式要求、详细程度与合规约束，例如监管行业要求特定的审计与记录条款。
- **组织过程资产**：组织标准的计划模板、以往项目的计划范例、经验教训知识库与审批程序等，帮助项目团队高效编制符合组织惯例的集成计划，并减少重复工作。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助具备项目管理、组织运营、行业专业知识的人员经验，判断各子计划之间是否存在冲突、计划是否完整可行，并确定计划的裁剪深度与整合策略，例如判断预算与进度的冲突是否可通过调整资源解决，必要时还可引入独立第三方评审以增加整合的客观性。
- **数据收集**：通过头脑风暴、访谈、标杆对照等方式，收集干系人对各计划草案的反馈与意见，并参考行业最佳实践，确保整合后的计划全面反映各方需求与约束。
- **人际关系与团队技能**：利用引导（主持计划整合会议并推动达成共识）、冲突管理（协调各绩效域负责人对资源、时间、成本安排的分歧）、会议管理与谈判，促使各专项负责人就统一计划达成一致，避免各自为政导致计划碎片化。
- **会议**：组织计划整合评审会议、干系人计划评审会议等，逐项核对各子计划与三大基准的相容性，讨论冲突解决方案，并最终确认整合后的项目管理计划，为计划的批准与发布奠定基础。`,
      "📤 输出 Outputs": `- **项目管理计划**：规定项目如何被执行、监控和收尾的综合文件。它不是一份单一文件，而是所有子计划与基准的集合体：通常包含九份管理计划（范围、进度、成本、质量、资源、沟通、风险、采购、利益相关方参与），三大基准（范围、进度、成本），以及项目生命周期描述、开发方法（预测型/适应型/混合型）、变更管理程序、配置管理程序、绩效测量基准等辅助内容。项目管理计划是执行、监控与变更控制的基础文件，其任何变更都必须遵循变更控制程序，经评估批准后方可更新，以保证计划与实际执行始终保持一致。
其中，配置管理程序用于管理计划的版本与组成部分状态，确保干系人使用的始终是最新有效版本；绩效测量基准通常由三大基准组合而成，作为挣值分析等绩效测量方法的对照基线。项目经理应确保计划既是行动的指南，也是控制的手段——既要足够详细以指导执行，又要足够灵活以吸纳新信息。`,
      "🔗 与其他过程的相互作用": `整合与对齐项目计划过程是规划类过程的汇聚点与枢纽。各绩效域规划过程（规划范围、编制进度、估算成本、规划资源、识别风险、规划采购、规划沟通、规划利益相关方参与等）先分别产出各自的子计划与基准，本过程再将这些输出整合为统一的项目管理计划并验证一致性。整合后的项目管理计划又作为“管理项目执行”、“监控项目绩效”和“评估变更请求”等过程的核心输入，指导实际工作并作为绩效测量的基线。当任何一个子计划或基准发生变更时，项目经理都需从整合视角评估变更对整体的连锁影响，并同步更新项目管理计划；因此本过程在项目生命周期中往往与变更评估过程交替运行，持续到项目收尾，体现了整合管理贯穿始终的特点。
值得注意，本过程并不取代各专项规划过程——它是在各专项规划基础上进行的二次整合与校验，专项规划越扎实，整合越顺利。`,
      "✂️ 裁剪考虑": `在预测型项目中，项目管理计划在规划阶段一次性编制完成、内容详尽，三大基准一经批准即受严格变更控制，变更需经变更控制委员会评审。在适应型项目中，计划保持轻量并采用滚动式规划：长期计划相对宏观（对应产品愿景与发布计划的整合），短期细节通过迭代/冲刺规划在临近实施时才细化，以应对频繁变化，避免大量前置的详细计划被浪费。混合型项目则对确定性高的部分采用正式基准，对探索性部分采用渐进明细。大型复杂项目可能需要数百页的分层计划体系，并配套子计划单独审批；小型项目则可使用简洁的一页式计划。无论规模如何，都应避免计划过度详细导致僵化，同时保证足够详细以切实指导工作与监控。
此外，可视项目复杂度决定是否将项目管理计划拆分为多卷文档，并在组织层面规定计划的格式与审批模板，以支持复用与合规审查。`,
      "💼 实践案例": `某市政基础设施项目团队先后完成了范围、进度、成本、风险、沟通、资源等子计划的编制。项目经理召开计划整合评审会议，发现进度管理计划中关键路径上的土建工期安排与资源管理计划中重型机械的到场时间存在冲突：若机械晚到一周，关键路径将延误并引发成本超支。经与各负责人协商，通过提前租用外部机械调整了资源调配方案，化解了矛盾。随后团队将九份子计划与三大基准整合为统一的项目管理计划，并在核对中发现按当前方案计算的总体预算超出立项上限，遂通过范围裁剪与设计优化将成本控制在批准范围内。最终计划经发起人批准，作为项目执行、监控与变更控制的统一依据，为后续各项活动提供了清晰的基准。
该案例展示了整合过程的典型价值：单看各子计划都合理，但整合时才暴露资源与工期、成本与范围的系统性冲突，这正是整合与对齐过程存在的意义。`,
    },
    keyConcepts: `- **项目管理计划**：所有子计划与基准的集合体，而非一份单一文件，是项目如何被执行、监控和收尾的总纲。
- **三大基准**：范围基准、进度基准、成本基准，是变更控制与绩效测量的基准线，任何基准变更须经正式批准。
- **整合属性**：项目经理的核心职责，协调各计划组件保持一致与连贯，识别并消除冲突。
- **渐进明细**：计划随项目推进逐步细化，在准确性与灵活性之间取得平衡，是应对动态环境的机制。
- **开发方法**：预测型、适应型或混合型的选择是项目管理计划的顶层组成部分，决定后续规划与执行的基调。
- **变更控制程序**：项目管理计划及其基准的变更必须遵循的正式流程，包含评估、批准与更新环节。
- **项目管理计划 vs 项目文件**：计划需经批准并受变更控制；项目文件（如假设日志、风险登记册）不纳入基准变更。
- **配置管理程序**：管理计划及其组成部分的版本与状态，保证干系人始终使用最新有效版本。
- **绩效测量基准**：由三大基准整合而成，是挣值分析等绩效测量方法的基础。`,
    examTips: `- 必记：项目管理计划是“所有子计划的集合体”，不是一份单一文件，也不是“项目文件”。
- 区分“项目管理计划”与“项目文件”：计划受正式变更控制，项目文件可随时更新、无需严格审批。
- 三大基准分别是范围、进度、成本；质量没有独立基准，质量问题通常引发范围与成本基准变更。
- 计划整合由项目经理牵头负责，而非某一专项负责人或计划专员。
- 渐进明细是核心概念——计划随项目进展逐步细化，反对一次到位、过度僵化。
- 在敏捷环境中，计划整合对应产品愿景与发布计划的整合，而非一次性编制全套文档。
- 常见陷阱：把子计划误当整体计划；把基准变更与普通计划更新混淆——基准变更必须走变更控制程序。
- 注意：项目管理计划批准后，任何涉及基准的变更都必须评估对进度、成本、范围的整体影响。
- 补充：管理计划可以相对容易更新，但基准变更必须经正式审批；答题时先判断变更是否触及基准，再判断应走哪条流程。
- 综合题提示：出现“子计划冲突”时，先整合协调再执行；执行中遇到计划与实况不符，先走变更评估而非擅自改计划。`
  },
  "proc-plan-resource-acquisition": {
    overview: `规划资源获取策略过程包括记录项目资源获取决策，明确资源选择方法，确定外部资源获取的工作范围，并选择合适的合同和资源以交付工作。该过程为获取项目可交付物建立了清晰的框架——无论是从组织内部还是从组织外部获取资源，并定义了需要获取的内容、获取的方式和获取的时间。

该过程用于确定工作或可交付物是使用内部资源完成更好，还是应使用外部资源。在进行自制或外购决策时，应考虑多项因素：内部资源获取的优势包括充分利用内部专业能力、通常成本较低（尤其在需要大量创新的场景下，内部团队沟通与协调成本更低）、与战略优势更紧密整合、增强对可交付物的控制与监管；外部资源获取的优势包括借助外部专业能力、释放产能和资本聚焦竞争优势、将交付风险转移给供应商。

该过程的一个关键部分是建立供方选择标准，并对供应商的评估与选择提供指导。这些标准可能包括成本、技术能力、过往绩效、财务稳定性、需求的合规性，以及与组织价值观或可持续性目标的契合度。本过程与采购管理紧密相关，其决策结果为后续采购规划、合同签订与供应商管理奠定基础，属于“规划”关注领域中衔接资源与采购的桥梁过程。
与规划资源管理过程（侧重内部资源的规划）不同，本过程聚焦于资源获取决策本身——确定需要什么、由谁提供、以何种安排获取；其结论直接决定后续采购活动的边界与合同策略。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：其中规定的项目目的、高层级需求、总体预算与关键干系人等，约束了资源获取策略的范围与投入上限，例如预算限制会直接影响自制或外购的选择，高层级里程碑则决定资源到位的时限要求。
- **项目管理计划**：包括范围基准、进度基准、成本基准以及资源管理计划、采购管理计划等相关子计划，界定了需要获取哪些资源、何时需要、可用预算、质量标准与外部依赖等约束，是制定获取策略的基础依据。
- **项目文件**：包括假设日志（假设与制约条件影响自制外购判断）、风险登记册（提示外包可能引入的供应商风险、合同风险）、需求文件（明确待交付工作包的内容与验收标准）与干系人登记册（识别采购决策相关的干系人及其期望）等，为决策提供情境信息。
当自制或外购决策涉及已识别的风险或待解决问题时，还应结合风险登记册与问题日志判断是否需要调整资源获取的安排。
- **事业环境因素**：组织内部资源的可用性与产能、市场供应商的供给状况、行业惯例、法律法规（如采购合规、数据保护要求）、组织文化与战略方向等，直接影响内部还是外部资源的判断。
- **组织过程资产**：组织既定的合格供应商清单、标准合同模板、采购政策与程序、历史供应商绩效数据、经验教训知识库等，为供方选择与合同类型确定提供参考，帮助团队复用已验证的做法。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助具有采购、合同、财务、法务与专业技术经验的人员的判断，评估自制或外购的利弊，推荐合适的资源获取方式、供方选择方法与合同类型，尤其适用于缺乏历史数据的首次采购场景。
- **数据分析**：对成本数据、供应商报价、内部产能、风险敞口等进行分析与比较，为决策提供定量依据；常用方法包括成本效益分析（比较内外方案的总拥有成本）、备选方案分析（比较多种获取路径）、假设情景分析（评估不同情景下的成本与进度影响）等。
- **自制或外购分析**：本过程的核心决策工具，通过系统比较内部自行生产或提供服务与向外部采购两种方式在成本、能力、风险、战略价值与工期上的差异，判断哪种方式更优；分析结论应记录决策理由，便于追溯。
- **供方选择分析**：评估适合具体采购情形的供方选择方法，如加权标准打分（对多家候选按多准则综合评分）、独立估算（以第三方估算校验报价的合理性）、筛选系统（按硬性门槛进行资格初筛）与多源分析（评估多家供方组合的可行性），确保选择过程公平、客观且与项目需求匹配。
- **会议**：组织与干系人、采购部门、法务及潜在供应商代表等的会议，讨论自制外购决策、评审供方选择标准、澄清需求边界与交付要求，并就资源获取时间表形成共识。`,
      "📤 输出 Outputs": `- **资源获取策略计划**：记录项目资源获取决策与方法的结构化文件，说明哪些工作由内部完成、哪些外购，获取的时间与方式，以及获取过程中遵循的原则、程序与审批要求，为后续采购与资源管理提供统一指导，并作为审计与追溯的依据，同时它也是干系人对获取安排达成共识的记录，可有效减少执行阶段因分工不清引发的纠纷。
- **供方选择标准**：一套用于评估和选择供应商的准则，可能包括成本、技术能力、过往绩效、财务稳定性、需求合规性，以及与组织价值观或可持续性目标的契合度等；各项标准可按重要性加权，作为供应商评估、打分与最终选定的客观依据。
- **自制或外购决策**：针对每项工作或可交付物作出的明确结论，判定由内部资源完成还是外购，并记录决策的理由、所考虑的替代方案与后续获取路径，供后续采购规划、合同签订与资源管理过程引用与追溯。`,
      "🔗 与其他过程的相互作用": `规划资源获取策略过程是资源管理与采购管理之间的桥梁。其上游输入来自启动与规划过程（项目章程、项目管理计划、项目文件）；其输出的资源获取策略计划、供方选择标准与自制或外购决策，为后续“规划采购管理”（确定采购策略、合同类型与采购文件）和“获取资源”（招募团队成员、获取团队与实物资源）等过程提供决策基础。项目执行期间，若内部资源发生重大变动、供应商出现问题或外部市场环境变化，本过程的决策结论会被重新审视，相应更新策略文件，并可能触发采购计划的变更与重新评估。
同时，供方选择标准与自制外购决策还会影响风险登记册的更新——外购引入的供应商风险、合同风险需要同步纳入风险管理范围，形成决策与风险的联动。`,
      "✂️ 裁剪考虑": `在预测型项目中，自制或外购决策通常在规划阶段通过正式分析一次性确定，并配套签订详细合同，变更较少。在适应型项目中，资源获取策略更强调灵活与渐进：可先以小范围外购验证供应商能力，再逐步扩大外包范围，合同多采用灵活的供应商协议或工料合同，以适应需求变化。混合型项目则对核心能力倾向自建、非核心业务倾向外包。分析深度应按风险与重要性裁剪：高风险核心部件需严格的多准则评估与独立估算；低风险通用件可简化处理，直接采购即可。对组织战略敏感或涉及核心技术秘密的组件应优先自制，以防范知识产权流失；对短周期、非关键的辅助工作则可直接外包。
在跨国或多地区项目中，还需考虑本地化采购政策、汇率风险与供应商地理分布，策略分析相应增加对应的评估维度与权重。`,
      "💼 实践案例": `某新能源企业启动储能系统研发项目，需对电池管理系统（BMS）的软件模块进行自制或外购分析。财务团队对比了自建研发（成本约1800万元、周期16个月、需招聘40名工程师，但可长期积累核心能力）与外包给成熟供应商（成本约1400万元、周期10个月，交付更快但需支付许可费）两种方案，同时评估技术风险：BMS是企业的核心竞争力且需长期迭代，外包存在知识产权与战略风险。最终决定核心算法模块自制、通用测试框架外购。供方选择标准侧重技术能力、过往项目绩效与财务稳定性，经加权打分从五家候选供应商中选定两家入围，并签订固定总价合同，将测试框架的交付风险与成本波动转移给供应商，确保质量与工期受控。
该决策平衡了成本、能力与战略三要素：短期外包节省成本与时间，长期自制沉淀核心能力，体现了资源获取策略在项目整体目标下的综合权衡。`,
    },
    keyConcepts: `- **自制或外购分析（Make-or-Buy Analysis）**：本过程的核心决策工具，比较内部完成与外部采购在成本、能力、风险与战略价值上的差异。
- **供方选择标准**：评估与选择供应商的准则，包括成本、技术能力、过往绩效、财务稳定性、合规性与可持续性契合度等，可按权重综合评分。
- **资源获取策略计划**：记录资源获取决策与方法的结构化文件，指导后续采购与资源管理。
- **合同类型**：固定总价、成本补偿与工料合同，需依据风险敞口与范围确定性选择：范围明确用固定总价，范围模糊用成本补偿。
- **组织价值观与可持续性**：日益重要的供应商选择维度，体现组织对ESG的承诺。
- **内部资源 vs 外部资源**：内部侧重控制、能力沉淀与整合；外部侧重专业能力、产能释放与风险转移。
- **谈判与合同管理**：获取策略落地的执行环节，策略计划为谈判范围、合同条款与供应商绩效管理提供依据。`,
    examTips: `- 与采购管理紧密相关，核心决策是 make-or-buy（自制或外购）分析。
- 自制或外购的考虑因素：战略重要性、成本、风险、时间与内部能力。
- 必区分：规划资源获取策略过程（涉及外包/自制决策）不同于规划资源管理过程（涉及内部资源管理）。
- 供方选择标准是本过程的重要输出，注意与执行阶段的“建议书评估技术”区分——前者先定标准，后者才做评估。
- 考试常见场景：给定项目背景判断自制还是外购——核心技术敏感、长期战略价值高倾向自制；工期紧张、能力不足倾向外购。
- 对供应商的评估不是一次性行为，可结合加权打分、独立估算等方法多维度校验报价的合理性。
- 常见陷阱：把自制或外购决策误当成只比较成本的决策——战略价值、风险与可持续性同等重要；把合同类型选择孤立看待——它取决于范围确定性与风险分配。
- 补充：预算不足或内部产能受限时往往转向外购，但核心能力与知识产权敏感部件即使成本较高也倾向自制；答题时抓住“战略价值”这一核心权衡。`
  },
  "proc-manage-execution": {
    overview: `【过程概述】指导和管理项目执行（Direct and Manage Project Work）是执行过程组中最核心的过程，旨在领导和实施项目管理计划中所定义的工作，并执行已批准的变更，以实现项目目标。该过程的关键收益是，在全面管理项目工作和可交付物的基础上，提高项目成功的概率。本过程从项目启动后开始，持续到项目收尾，贯穿整个执行阶段。

要点概览：
- **目的**：将项目管理计划转化为实际行动和成果，通过执行已规划的项目活动产出可交付物，并落实已批准的变更请求（含纠正措施、预防措施和缺陷补救）。
- **关键收益**：在全面管理项目工作和可交付物的基础上，提升项目整体成功的概率。
- **执行频率**：在整个项目期间持续执行，与监控项目工作、实施整体变更控制等过程形成“执行—监控—调整”的闭环。
- **角色转变**：执行阶段，项目经理的角色从规划者转变为协调者和问题解决者，需要同时统筹资源分配、问题、风险和变更等多个方面。
- **知识对齐**：在领导团队时，团队成员的集体知识水平通常高于任何单个成员，本过程能使所有团队成员的知识与技能与项目目标保持一致。
- **数据产出**：执行过程中持续收集工作绩效数据（原始数据），并将其传递给相关控制过程进行分析，从而驱动绩效监控与计划调整。
- **生态系统协调**：项目经理与项目团队共同管理并推动已规划活动的执行，协调项目生态系统内技术与职能活动的各个方面，并审查所有项目变更的影响。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：指导项目执行的总体依据，包含范围、进度、成本、质量、资源、沟通、风险、采购、干系人参与等子管理计划，以及范围、进度、成本三大基准。执行中所有活动都必须依据计划开展，计划既是“做什么”的来源，也是判断偏差、评估变更的参照标准。
- **项目文件**：执行过程中需要的各类辅助文件，如需求文件、风险登记册、干系人登记册、假设日志、里程碑清单、问题日志等。它们为执行活动提供背景与细节信息，并随执行推进被持续更新，使计划与实际执行保持一致。
- **批准的变更请求**：已经实施整体变更控制过程正式审批并签字确认的变更请求，是本过程执行“已批准变更”的直接依据。批准内容通常包括纠正措施（使工作恢复与计划一致）、预防措施（降低潜在负面影响的概率）和缺陷补救（修复缺陷或不符合项），执行时须逐一落实并记录结果。
- **事业环境因素**：项目团队无法直接控制的客观条件，如组织文化、基础设施、资源可用性、市场条件、行业标准等。它们约束执行的方式与效率，例如组织制度决定变更如何被处理、汇报采用何种模板和频度。
- **组织过程资产**：组织积累的可复用流程、政策、程序、模板与历史经验，如标准操作规程、经验教训库、配置管理数据库、历史项目档案等。执行时优先复用这些资产，可提高效率、统一口径并减少重复犯错。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助具备专业知识或接受过专门培训的个人或团队的意见来指导执行，例如在技术细节、资源配置、变更影响评估、冲突处理等方面咨询内部专家、主题专家或外部顾问。使用时需注意甄别专家背景、结合其他信息综合判断，避免单一意见带来的偏差。
- **项目管理信息系统（PMIS）**：由组织基础设施中的硬件、软件和工具构成的信息系统，用于收集、存储和分发工作绩效数据与信息，典型如进度计划软件（MS Project、P6）、工作授权系统、配置管理系统、工时与费用管理系统等。项目经理通过PMIS编制进度、分配任务、记录工时、跟踪问题与发布状态，使执行过程数字化、自动化、可追溯。
- **会议**：通过召开各类会议来沟通、决策和推动执行，包括项目启动会、每日站会、进度例会、问题解决会、技术评审会等。会议应有明确议程、合适的干系人参与并做好会议纪要（行动项、负责人、截止时间），确保会议结论转化为后续可执行的动作。`,
      "📤 输出 Outputs": `- **可交付物**：在某个过程、阶段或项目完成时必须产出的独特、可验证的产品、结果或服务能力，是执行已规划活动的直接产物。可交付物须经过核实与验收，作为控制质量、确认范围以及干系人验收的对象。
- **工作绩效数据**：执行过程中直接观察到的原始观测值与测量值，如实际开始/完成日期、已完成百分比、实际成本、实际持续时间等。它未经任何分析，是生成工作绩效信息和绩效报告的基础素材，须传递给控制过程进行偏差分析。
- **问题日志**：记录和监控项目问题的正式登记册，包含问题描述、类型、责任人、优先级、状态与解决日期等信息。执行中发现的任何妨碍工作推进的问题都应录入日志并跟踪直至关闭，防止问题被遗忘或扩散。
- **变更请求**：针对任何偏离计划的正式变更提议，可能源于执行中发现的偏差、干系人新需求、风险应对或质量缺陷。变更请求须提交实施整体变更控制过程评估并批准，批准的变更再回到本过程执行，形成“提出—审批—执行”的闭环。
- **项目文件更新**：执行过程对相关项目文件的修订，如更新需求文件、风险登记册、干系人登记册、里程碑清单等，使文件如实反映最新状态，保持信息一致性与可追溯性。
- **组织过程资产更新**：执行过程产生的可复用经验与资产的更新，如经验教训登记册新增内容、流程模板的改进、配置项记录等，为组织后续项目积累知识。`,
      "🔗 与其他过程的相互作用": `本过程是执行过程组的核心枢纽，与多个过程紧密衔接：它以项目管理计划和规划过程组产出的项目文件、批准的变更请求为执行依据；执行中产生的工作绩效数据流向监控项目工作过程，用于生成工作绩效信息与绩效报告；发现偏差或出现新需求时转化为变更请求，提交实施整体变更控制过程审批，已批准的变更又回到本过程执行；控制进度、控制成本、控制质量、确认范围等控制过程则对本过程的执行结果进行跟踪与验证。本过程还与管理项目知识（沉淀经验教训）、管理团队与资源（保障团队高效运转）、实施风险应对（执行已批准的应对计划）等过程协同，共同保障项目执行顺畅。可以说，本过程是项目执行的“发动机”，把计划持续转化为成果，并驱动监控与变更闭环的运转。`,
      "✂️ 裁剪考虑": `- **预测型项目**：执行按既定顺序和里程碑推进，变更受正式流程严格约束，较多使用PMIS、正式会议和审批流程，可交付物在阶段末集中交付与验收，强调过程的规范性。
- **适应型（敏捷）项目**：执行以迭代/冲刺为单位，计划随反馈持续细化，变更被鼓励并快速吸纳；执行中更多采用每日站会、冲刺评审、冲刺回顾等短周期互动，可交付物增量交付。裁剪时弱化正式审批，强化快速反馈与持续调整机制。
- **混合型项目**：关键接口、里程碑和合同类工作走预测式执行与正式变更，产品功能开发走敏捷式迭代执行；裁剪时应明确哪些活动适用正式流程、哪些允许灵活调整。
- **项目规模与复杂度**：大型、复杂项目需要更正式的工作授权、PMIS与汇报机制；小型项目可简化为轻量工具和每日沟通，减少文书负担。
- **行业与合规要求**：建筑、制药、医疗等受监管行业，执行须严格遵守法规和强制性程序，裁剪空间小；内部工具类项目可大幅简化流程。
- **组织文化**：鼓励授权的组织可赋予团队更多执行自主权；控制严格的组织的执行活动需更多审批节点。`,
      "💼 实践案例": `某市政道路建设项目进入执行阶段后，项目经理依据项目管理计划下达施工任务。验槽过程中，施工方发现地下存在图纸未标注的燃气管道，存在安全隐患。项目经理立即召集专家现场勘察确认，将问题录入问题日志并指定安全负责人跟踪；评估后提出变更请求——调整施工方案并增设防护措施，经实施整体变更控制批准后，在本过程中组织团队按新方案执行，并通过PMIS更新进度基准、重新调配资源。执行全程，团队持续记录实际工期与成本等工作绩效数据，提交监控过程分析偏差。最终变更顺利落地，避免了一起安全事故，项目按修订后的基准如期推进。`,
    },
    keyConcepts: `- **指导和管理项目执行**：执行项目管理计划中定义的工作并落实已批准变更的过程，是项目执行的核心驱动，贯穿执行阶段始终。
- **批准的变更请求**：已经正式批准、必须在本过程执行的变更，包括纠正措施、预防措施和缺陷补救三类。
- **工作绩效数据 vs 工作绩效信息**：前者是执行中直接收集的原始数据（未经分析）；后者是经分析加工后的信息。本过程只产出工作绩效数据。
- **可交付物**：完成活动后必须产出的独特、可验证的产品、结果或服务能力，是执行的直接输出。
- **问题日志**：登记、跟踪并关闭项目问题的正式工具，执行中发现的问题必须记录并跟踪至解决。
- **项目管理信息系统（PMIS）**：支撑计划、执行、监控的软硬件集成系统，使执行过程可追溯、可度量。
- **执行—监控—变更闭环**：执行产出数据→监控分析→提出/批准变更→回到执行落实，是本过程相互作用的核心逻辑。`,
    examTips: `- 高频考点：执行阶段项目经理的角色从“规划者”转变为“协调者和问题解决者”，需同时统筹资源、问题、风险和变更。
- 易混淆点：本过程产出的是工作绩效数据（原始数据），而非工作绩效信息（分析后的数据）或工作绩效报告（汇总后的报告）。
- 批准的变更请求是本过程的重要输入，只有经实施整体变更控制正式批准的变更才能被执行；未经批准的变更坚决不执行，这是防止范围蔓延的关键。
- 输出常考：可交付物、工作绩效数据、问题日志、变更请求；注意变更请求既出现在输入又出现在输出，构成变更闭环。
- 项目管理信息系统（PMIS）属于工具而非输出，常与配置管理系统、工作授权系统一起考查，注意其用于收集、存储和分发信息。
- 会议工具覆盖启动会、站会、进度会、评审会等，注意区分不同会议的应用场景与目的。
- 常见陷阱：把“实施已批准的变更”误认为“自主决策变更”；把问题日志与经验教训登记册混为一谈（前者记问题，后者记知识）。`
  },
  "proc-manage-quality": {
    overview: `【过程概述】管理质量（Manage Quality）是执行过程组中的质量管理过程，旨在确保项目过程按照干系人期望的方式执行。它通过将项目管理计划转化为可执行的活动，并把组织的标准、法规和政策纳入其中，系统性地保障“做事的质量”。该过程的关键收益是提高实现项目目标的概率，并识别出低效流程及项目绩效不佳的原因。本过程在整个项目期间持续执行，从项目启动一直贯穿到收尾。

要点概览：
- **管理质量 = 质量保证（QA）**：关注“过程”，致力于有效运用项目的过程、遵循并满足标准，从而向干系人保证项目最终结果能够满足其需要、期望和需求。
- **与控制质量（QC）的区别**：控制质量关注“产品”，旨在创建符合既定规范和临界值的可交付物，涉及定义价值属性并确保可交付物具备这些属性；两者是质量管理的两条不同战线，一个管“过程对”，一个管“产品好”。
- **计划性与系统性**：本过程实施质量管理计划中定义的一系列计划性和系统性措施与流程，目标包括：借助质量审计和失效分析建立信心；提升过程与活动的效率和效果；确保项目得到妥善治理。
- **敏捷情境的灵活性**：在敏捷项目中，质量保证可以依据具体情境以正式或非正式的方式进行，如通过完成的定义（DoD）、自动化测试、持续集成和评审等活动将质量内建到每个迭代中。
- **质量是“融入”的**：本过程的深层理念是“预防胜于检查”，质量应通过设计、培训和过程改进被融入产品与过程，而不是靠事后的检验“检查出来”。`,
    details: {
      "📥 输入 Inputs": `- **质量管理计划**：项目管理计划的组成部分，规定项目质量政策、质量目标、质量角色与职责、需要遵守的标准、质量工具与方法、质量审计安排等，是本过程开展质量保证活动的总纲领与执行依据。
- **质量度量指标**：定义质量要求如何被验证的量化指标，如缺陷密度、按时交付率、返工率、客户满意度分数、周期时间等。它们用于评估过程与结果是否符合质量目标，并支撑质量报告中的度量分析。
- **质量控制测量结果**：控制质量过程输出的、记录实际质量测量结果的记录。管理质量过程借助这些结果分析过程是否存在系统性问题、评估过程能力，并识别改进机会，实现“过程—产品”双向反馈。
- **项目文件**：执行中与质量相关的辅助文件，如质量核对单、问题日志、经验教训登记册、风险登记册、干系人登记册等，为质量审计、过程分析和根因定位提供证据与上下文。`,
      "🔧 工具与技术 Tools": `- **数据收集**：以结构化方式获取质量相关信息，主要工具是核对单（核对表）——基于历史经验与组织标准编制的逐项检查清单，用于在执行中核查过程步骤是否满足既定要求，避免遗漏关键环节。
- **数据分析**：对质量数据进行分析以识别问题与改进机会，典型方法包括：
  - **过程分析**：检查过程运行情况，识别非增值活动、瓶颈与浪费，判断过程是否稳定高效，为过程改进指明方向；
  - **根本原因分析**：系统定位问题的深层根源，常借助“5个为什么”、因果图等手段层层追问，确保改进措施直击要害而非停留在表面症状。
- **决策**：在质量方案与改进措施之间作出选择，常用**多标准决策分析**——依据成本、效益、可行性、风险、干系人接受度等多个标准对备选方案加权打分，客观选出最优方案。
- **数据表现**：将质量数据可视化以辅助分析与沟通，常用图形包括：
  - **亲和图**：对大量意见、问题或想法按相似性归类聚类，帮助梳理主题与结构；
  - **因果图（鱼骨图/石川图）**：按人、机、料、法、环、测等类别系统追溯问题根因；
  - **流程图**：展示过程的步骤与流转路径，识别环节衔接与改进点；
  - **直方图**：以条形图呈现数据分布形态，识别集中趋势、离散程度与异常；
  - **矩阵图**：展示多组变量之间的关联强度，帮助找出关键影响因素；
  - **散点图**：考察两个变量之间的相关性，判断关系方向与强弱。
- **审计（质量审计）**：独立、结构化的评审，用于确定项目活动是否遵循组织和项目的政策、过程与程序。质量审计可识别良好实践（可推广至组织其他项目）与差距（触发纠正措施），并可用于干系人绩效认可，其定位是“帮助团队变好”而非“惩罚团队”。
- **面向X的设计（Design for X）**：在设计阶段就针对特定目标优化产品设计，如面向可制造性、可维护性、可装配性、可测试性的设计，从源头降低过程缺陷与产品成本。
- **问题解决**：结构化地发现并解决质量问题的方法，通常遵循“定义问题—识别根本原因—生成备选方案—选择并实施—验证有效性”的步骤，必要时结合根本原因分析工具展开。
- **质量改进方法**：运用PDCA循环（计划—执行—检查—处理）或六西格玛DMAIC（定义—测量—分析—改进—控制）等系统方法，持续提升过程能力与产品质量，使改进活动有章可循、可量化验证。`,
      "📤 输出 Outputs": `- **质量报告**：汇总质量活动执行情况、质量度量结果、过程改进建议与质量审计结论的正式文件，向干系人清晰传达质量状态，并为质量决策与改进行动提供依据。
- **测试与评估文件**：记录质量测试与评估活动的计划、方法与结果的文件，用于评估过程是否达到质量目标，也可在批准变更前评估变更对质量目标的影响，支撑决策。
- **变更请求**：质量审计、过程分析发现的改进机会或质量缺陷，可能转化为变更请求提交实施整体变更控制过程审批，批准后通过更新计划、文件或调整过程来落实改进。`,
      "🔗 与其他过程的相互作用": `管理质量与质量管理过程组内其他过程紧密衔接：它从制定项目管理计划/规划质量管理过程接收质量管理计划和质量度量指标；从控制质量过程接收质量控制测量结果作为过程分析的输入；产出的质量报告交付干系人沟通并支持监控项目工作；测试与评估文件及改进建议可触发变更请求，进入实施整体变更控制过程审批，批准后回流到指导和管理项目执行过程落实。管理质量向控制质量提供质量保证框架（保证“过程做对了”），控制质量向管理质量反馈“产品测得准不准”的数据，二者形成“过程质量—产品检验”的互补闭环。此外，管理质量还与管理项目知识过程交互，将质量经验与良好实践沉淀为组织过程资产，支撑组织级质量改进。`,
      "✂️ 裁剪考虑": `- **预测型项目**：质量保证较为正式，依赖计划中安排的独立质量审计、检查点、符合性报告和阶段性质量门禁，QA角色通常独立于开发团队，强调可追溯的书面证据。
- **适应型（敏捷）项目**：质量在每个迭代中被“内建”，通过完成的定义（DoD）、测试驱动开发（TDD）、持续集成、结对编程、代码评审与冲刺回顾保证质量；质量审计更轻量、非正式，注重快速反馈与即时改进。
- **混合型项目**：对关键接口、合规要求高的部分采用正式审计，对灵活开发部分采用敏捷实践内建质量，需明确质量保证的边界与责任人。
- **行业与监管要求**：制药、医疗、航天、核电等受监管行业必须满足强制法规与认证要求，质量管理活动的裁剪空间小、证据要求严；内部工具类项目可大幅简化。
- **组织成熟度**：质量管理体系成熟度高的组织可复用既有过程标准与质量体系，项目只需适配；成熟度低时项目需自建质量流程与审计机制。
- **项目规模**：大型项目需要专职QA、分层审计与系统性质量度量；小型项目可由团队兼职、轻量核对与回顾替代。`,
      "💼 实践案例": `某企业ERP软件项目在连续两次迭代中出现缺陷密度偏高、返工成本上升的问题。项目经理与QA团队启动管理质量过程：先用核对单核查开发过程是否遵循编码规范与评审流程，再用过程分析定位“测试环境与生产环境配置不一致”这一低效环节，随后用因果图和“5个为什么”追溯根因——配置变更缺乏版本控制。团队对“引入统一配置管理工具”与“加强人工核查”两个方案开展多标准决策分析，依据成本、见效速度与长期收益选出前者。改进落地后，通过质量审计确认过程符合新规范，缺陷率明显下降。QA团队将经验写入经验教训登记册，并向干系人提交质量报告说明质量提升情况，整个项目“关注过程而非单点检查”，质量稳步改善。`,
    },
    keyConcepts: `- **管理质量（质量保证 QA）**：确保项目过程按照干系人期望执行，关注“过程”，是向干系人提供信心的系统性活动。
- **控制质量（质量控制 QC）**：确保可交付物符合既定规范与临界值，关注“产品”，与管理质量形成互补。
- **质量审计**：独立、结构化的评审，确认项目活动是否遵循政策、过程与程序，识别良好实践与差距。
- **过程分析**：检查过程运行、识别非增值活动与改进机会的分析方法。
- **根本原因分析**：系统定位问题深层根源的技术（“5个为什么”、因果图等）。
- **质量成本（COQ）**：一致性成本（预防、评估）与不一致性成本（内部失败、外部失败）之和，用于权衡质量投入与质量水平。
- **预防胜于检查**：质量应通过设计与过程改进“融入”，而非靠事后检验“查出”。
- **面向X的设计、PDCA、DMAIC**：从源头设计与系统流程层面持续改进质量的方法论。`,
    examTips: `- 高频辨析：管理质量=质量保证（QA），关注过程；控制质量=质量控制（QC），关注产品。题干说“审查过程是否遵循标准”→管理质量；“检验可交付物是否达标”→控制质量。
- 质量审计是管理质量的标志性工具：评估质量管理过程的有效性，识别良好实践与差距，定位是“帮助而非惩罚”团队，审计结果可能触发变更请求。
- 核心理念“预防胜于检查”：质量是“融入/内建”出来的，不是“检查出来”的；符合性（符合规范）与适用性（满足使用）的区分也是常考点。
- 工具归属要分清：成本效益分析、质量成本（COQ）属于规划质量管理过程；管理质量过程常用过程分析、根本原因分析、多标准决策分析、质量审计、面向X的设计与质量改进方法。
- 输出辨析：质量报告与测试与评估文件是管理质量的输出；控制质量的输出是质量控制测量结果、核实的可交付物等，两者勿混淆。
- 图形工具速记：找根因→因果图/根本原因分析；梳理大量意见归类→亲和图；多组变量关联强度→矩阵图；两变量相关性→散点图；数据分布形态→直方图；识别过程瓶颈与浪费→过程分析。
- 敏捷视角：完成的定义（DoD）、测试驱动开发、持续集成、结对编程是“质量内建”的敏捷体现，常与“预防胜于检查”理念联合考查。`
  },
  "proc-manage-knowledge": {
    overview: `【过程概述】管理项目知识（Manage Project Knowledge）旨在运用现有知识和创造新知识，以实现项目目标并促进组织学习。该过程的关键收益包括：利用以往的组织知识以产出或改进项目成果；收集项目产生的新知识，以支持组织运营和未来的项目或阶段。本过程贯穿整个项目生命周期持续执行，并在知识共享的关键节点（如里程碑评审、迭代回顾、项目收尾）集中开展。

要点概览：
- **两类知识**：知识管理同时管理显性知识与隐性知识。显性知识正式、系统化，可通过文字、图片或数字方便地编码（如手册、程序、记录在案的流程），能够通过数据库、登记册、网络搜索等信息管理工具轻松传播与共享；隐性知识嵌入个人大脑、极具个性化，难以表达（如技术技能、经验、洞察、实践知识），通常通过人与人之间的对话和互动来共享。
- **核心目标**：在可能的情况下将隐性知识转化为显性知识，使其可被记录、复用与传承。
- **时机安排**：确定如何及何时在整个项目过程中进行经验教训总结和回顾会议，是支持知识管理的重要实践——既要有过程性的及时沉淀，也要有收尾时的集中复盘。
- **共享机制**：有效的知识管理依赖实践社区、工作见习、故事讲述、头脑风暴等人际互动机制，以及鼓励分享、宽容失败的组织文化。
- **AI的机遇与风险**：最新人工智能技术（如访谈机器人）为获取和共享隐性知识与显性知识增添了新的强大能力，但也存在重大风险——可能无意间泄露敏感信息，以及遭遇AI幻觉，使用时应谨慎并设置防护与复核机制。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：为知识管理提供上下文与约束，包括范围、进度、沟通管理计划等组件以及项目如何记录、分享和应用知识的相关安排，界定知识管理的边界与方式。
- **项目文件**：承载项目当前知识与状态的各类文件，如风险登记册、干系人登记册、问题日志、假设日志等。它们既是知识的载体，也是知识更新与经验沉淀的对象。
- **可交付物**：执行过程中产出的产品、结果或服务能力，其开发过程本身蕴含大量隐性知识、技术经验与改进机会，是获取新知识的重要来源。
- **事业环境因素**：组织支持知识管理的环境条件，如知识库系统、内部社区平台、组织学习文化、工作授权流程等，决定知识共享的便利程度与工具选择。
- **组织过程资产**：组织积累的经验教训库、历史项目信息、标准、模板与知识库，为本过程提供“拿来用”的既有知识，也接收本过程沉淀的新知识，形成组织级知识循环。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助掌握专业知识或拥有相关经验的人员（如主题专家、资深项目经理、组织知识库负责人）指导知识管理活动的设计，帮助判断哪些知识值得沉淀、采用何种共享方式最有效。
- **知识管理**：聚焦“人”的方法，通过人际互动促进隐性知识的获取、共享与转化，常用机制包括：
  - **实践社区（CoP）**：由具有共同关注点或相似专业的人员组成的非正式社群，定期交流实践、分享经验与最佳做法，是隐性知识流动的重要载体；
  - **工作见习/影子学习**：让新人跟随资深成员工作，在“干中学”中直接吸收难以言传的操作技能与判断经验；
  - **故事讲述**：通过叙事方式传递经验教训，使隐性知识在具体情境中被理解和记忆，比抽象文档更容易内化；
  - **头脑风暴会议**：激发集体创意与讨论，在思想碰撞中产生并共享新知识；
  - **引导与工作坊**：由引导者组织结构化讨论，凝聚团队分散知识、形成共识并产出结论；
  - **配对/师徒制**：通过一对一的互动与指导，实现技能与经验的高效传承。
- **信息管理**：聚焦“内容”的方法，对显性知识进行编码、存储与检索，常用机制包括：
  - **文件系统与数据库**：集中存储、检索文档、数据与记录，是显性知识的基本载体；
  - **网页/网络搜索**：快速定位组织内外部可用的信息与资源；
  - **组织社交媒体与内部百科/维基**：以低门槛方式发布、评论、修订与检索知识，形成持续演进的组织级知识资产；
  - **登记册（如经验教训登记册）**：结构化记录项目过程中获得的知识与经验，供当前及未来项目复用。`,
      "📤 输出 Outputs": `- **经验教训登记册**：记录项目过程中获得的知识与经验教训的正式文件，通常随项目推进持续更新，内容包括发生的情境、原因、影响、应对措施与改进建议，供当前和未来项目复用，是知识管理最重要的载体。
- **项目文件更新**：知识管理活动引发的对现有项目文件的修订，如将新的经验、决策依据与洞察补充到风险登记册、干系人登记册、里程碑清单等文件中，保持项目知识的一致性与可追溯性。`,
      "🔗 与其他过程的相互作用": `管理项目知识过程贯穿项目整个生命周期：启动与规划阶段，它调用组织过程资产中的既有知识（历史经验教训、标准模板）辅助计划制定；执行与监控阶段，它通过会议、回顾、质量审计等从各过程获取新知识并即时沉淀；收尾阶段，它把项目产生的知识最终固化到组织过程资产，供未来项目使用。它与指导和管理项目执行、监控项目工作、控制质量、管理质量等过程均发生知识输入与输出，并往往通过经验教训登记册把知识从当前项目流向组织，形成“项目成功→组织学习→未来项目更成功”的价值闭环。同时，知识共享高度依赖干系人参与与沟通管理所营造的互动氛围，因此本过程与干系人参与、沟通管理过程协同运作，共同保障知识的有效流动。`,
      "✂️ 裁剪考虑": `- **预测型项目**：知识管理偏正式，通常在阶段门评审、里程碑审查和项目收尾时集中总结经验教训，强调文档化、合规性与知识归档。
- **适应型（敏捷）项目**：知识管理非正式而频繁，主要通过每个冲刺末的回顾会议快速总结经验并立即应用，强调口头分享与即时行动，文档保持轻量化。
- **混合型项目**：重大里程碑采用正式复盘与归档，日常迭代采用轻量回顾与持续改进。
- **组织规模与团队分布**：分布式团队需更多依赖信息管理工具、线上互动平台与异步协作，以弥补面对面交流不足；集中办公团队可充分使用人际互动机制。
- **知识敏感度**：涉及保密或专有信息的项目，在知识共享时须设置权限、脱敏与审计机制，避免敏感信息泄露；使用AI工具时尤其要加设防护。
- **组织文化**：鼓励分享、宽容失败的组织文化可更多依赖人际机制；反之，需用正式流程与激励制度强制沉淀知识。
- **行业特点**：研发、工程等知识密集行业应重点投资知识管理；标准化流程行业可侧重显性知识的固化与复用。`,
      "💼 实践案例": `某跨国软件开发项目在首个里程碑后，项目经理组织了一场“故事讲述”式的经验分享会，邀请核心架构师讲述一次隐蔽性能瓶颈的排查过程——这类判断经验难以写成文档，属于典型隐性知识。同时，团队将可编码内容（配置方案、优化清单）补充进经验教训登记册，并在公司内部维基发布“性能优化速查”，沉淀为组织过程资产；随后组建“性能优化实践社区”，供后续项目成员随时咨询。临近收尾，团队又用访谈机器人对资深成员进行结构化访谈，把多年部署经验转化为显性知识入库，同时对AI生成内容逐条复核，防止“AI幻觉”混入知识库。这些做法使后续同类项目启动即可复用，显著缩短了问题排查时间。`,
    },
    keyConcepts: `- **显性知识**：正式、系统化、可编码的知识，如手册、程序、记录在案的流程与文档，通过数据库、登记册、网络搜索等信息管理工具传播与共享。
- **隐性知识**：嵌入个人大脑、极具个性化的知识，如技术技能、经验、洞察与实践知识，难以表达，通常通过人与人之间的对话与互动共享。
- **知识管理的核心目标**：在可能的情况下将隐性知识转化为显性知识，使其可记录、可复用、可传承。
- **经验教训登记册**：记录项目过程中获得的知识与经验的核心载体，随项目持续更新并沉淀为组织过程资产。
- **知识共享机制**：实践社区（CoP）、工作见习、故事讲述、头脑风暴、引导工作坊、师徒制等人际互动方式。
- **知识管理的两条路径**：知识管理（聚焦“人”，人际互动）与信息管理（聚焦“内容”，编码与存储），两者互补。
- **AI的机遇与风险**：访谈机器人等增强知识获取与共享能力；但也存在无意泄露敏感信息与AI幻觉的风险，需防护与复核。`,
    examTips: `- 核心考点：隐性知识通过“人与人互动”传递（对话、实践社区、工作见习、故事讲述、头脑风暴、师徒制）；显性知识通过“文档与信息工具”传递（数据库、登记册、内部维基、网络搜索）。
- 常考表述：“将隐性知识转化为显性知识是知识管理的核心目标”；题干出现这一导向时，优先选择促进人际互动的机制。
- 典型陷阱：问“下列哪项最有助于共享隐性知识”时，选实践社区/工作见习/故事讲述等互动方式，而非建数据库、写文档（后者适合显性知识）。
- 经验教训登记册是贯穿项目全程的工件，不是收尾时才一次性创建；“何时总结、如何总结”的时机安排也是考点。
- 收尾过程组会把经验教训登记册沉淀为组织过程资产，供未来项目使用，注意“从当前项目流向组织”的方向。
- 常见混淆：经验教训登记册（记录知识与经验）vs 问题日志（记录问题及解决状态）；管理项目知识（过程）vs 知识管理（该过程中的一类工具）。
- AI考点：使用AI获取知识可能无意间泄露敏感信息，也可能遭遇AI幻觉（生成不实内容），需设置防护与复核机制，切勿直接采用未经核实的AI输出。`
  },
  "proc-monitor-performance": {
    overview: `监控项目绩效过程用于跟踪、审查和报告整体项目进展，对照项目管理计划中所定义的绩效目标进行评估。该过程的关键收益是使干系人能够了解项目的当前状态，确认为解决任何绩效问题所采取的措施，并通过成本与进度预测掌握项目的未来状态。本过程属于监控过程组，贯穿执行阶段的始终，核心动作包括：对照计划评价实际绩效、跟踪资源利用和已完成的工作、展现担当意识、向干系人提供信息、评估项目可交付物是否按计划实现预期收益、就权衡与选项进行沟通、评估当前风险并识别新风险。

本过程与测量紧密相关。项目团队应聚焦测量那些具有相关性的事物，并确保所选度量指标具有可操作性。只有符合SMART准则——具体（Specific）、可衡量（Measurable）、可达成（Achievable）、相关（Relevant）、有时限（Time-bound）——度量指标才能发挥效用。同时必须警惕测量陷阱：霍桑效应（测量行为本身改变了被测量的行为）、虚荣指标（数据好看但无决策价值）、士气低落、误用度量指标、确认偏见、把相关性与因果关系混为一谈。监控的最终目的是把测量、分析和决策连成闭环，驱动价值交付，而不是为测量而测量。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：包含范围、进度、成本、质量、资源、沟通、风险、采购、干系人参与等子管理计划，以及范围基准、进度基准、成本基准三类基准，是绩效测量的标尺，用于将实际执行结果与计划逐项对比，判断偏差的大小与是否处于可接受范围。
- **项目文件**：包括进度计划、成本估算、风险登记册、假设日志、里程碑清单、需求文件、预测等，提供过程级的细节数据，帮助定位偏差产生的根源、波及的范围以及需要调整的计划组件。
- **工作绩效数据**：在执行过程中直接采集的原始观测结果与测量值，如已完成百分比、实际成本、实际开始/完成日期、缺陷数量、变更次数等，是测量和分析的基础原材料，未经任何加工整理，也是工作绩效信息与报告的数据来源。
- **协议**：包括合同中约定的履约指标、里程碑、付款条件、验收标准，以及服务水平协议，是衡量供应商或承包商绩效、监控合同执行情况的重要依据，常用于外包与采购项目的绩效衡量。
- **事业环境因素**：组织的工作授权系统、财务控制程序、项目管理信息系统、绩效测量数据库等，决定绩效数据如何采集、存储、分析与报告，也约束监控的方式、工具和频度。
- **组织过程资产**：历史信息与经验教训库、绩效测量数据库、报告模板与政策、偏差处理政策、控制政策等，为对比分析、趋势预测和报告格式提供参考基准，使监控结果可横向比较。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具备该领域专长的发起人、干系人、主题专家等对绩效数据进行专业解读，判断偏差的严重性、预测的可信度以及应采取的措施，弥补量化数据本身的信息局限，尤其在数据异常或信息不完整时尤为关键。
- **数据分析**：监控绩效的核心工具组合，具体包括：
  - **挣值分析**：利用EV、PV、AC计算SV、CV、SPI、CPI，综合评估进度与成本绩效，是挣值管理的落地应用；
  - **趋势分析**：基于历史绩效数据外推未来表现，判断绩效是改善还是恶化，用于早期预警；
  - **偏差分析**：将实际结果与基准逐项对比，找出偏差的大小、方向与原因；
  - **储备分析**：评估应急储备的充足性与剩余风险，判断是否动用或增加储备；
  - **根本原因分析**：定位偏差的深层根因，为制定纠正措施提供依据；
  - **备选方案分析**：比较不同纠正措施方案的优劣后再做决策。
- **决策**：包括一致同意、大多数原则等群体决策技术，当出现绩效问题需要选择应对方案时，帮助团队快速、公平地达成一致并形成行动决定。
- **会议**：包括状态审查会议、迭代评审与回顾会、每周例会等，用于同步绩效信息、审查偏差、讨论应对选项并做出调整决策，是监控闭环中信息流通的关键载体。`,
      "📤 输出 Outputs": `- **工作绩效报告**：将工作绩效数据加工为工作绩效信息后汇总成面向干系人的可读报告（状态报告、进展报告、备忘录、仪表盘等），以图表、数据表或文字形式呈现当前进展、已解决与待解决问题、风险状态和预测结果，供干系人按需索取或定期推送，支撑其做出知情决策。
- **变更请求**：当监控发现偏差需要纠正时，提出纠正措施、预防措施、缺陷补救或范围/进度/成本调整请求，并附上影响分析，交由整体变更控制过程（评估与实施变更）统一评估与处理。`,
      "🔗 与其他过程的相互作用": `- **与管理项目工作**：管理项目工作过程持续产生工作绩效数据，监控项目绩效过程将其转化为工作绩效信息并输出工作绩效报告；预测结果又用于管理项目工作过程的后续规划与资源调整。
- **与评估与实施变更**：监控发现偏差后提出的变更请求进入评估与实施变更过程，走整体变更控制流程，批准的变更更新基准后回流到相应子计划，重新指导执行，形成闭环。
- **与各控制子过程**：控制范围、控制进度、控制成本、控制质量、监控风险、控制采购等过程分别聚焦各领域监控，本过程则在整体层面汇总各领域信息，形成项目全景视图并做出综合判断，避免只见树木不见森林。`,
      "✂️ 裁剪考虑": `- **预测型项目**：定期（如每周或每月）生成正式状态报告，严格对照三大基准测量偏差，变更需走正式审批流程，监控频度高、文档规范，绩效测量基准与报告模板高度标准化。
- **适应型项目**：以每日站会、迭代评审、回顾会和看板度量（燃尽图、累积流图、吞吐量、周期时间）持续监控，减少繁琐的正式报告，通过待办事项列表的持续调整实现快速反馈，重点指标如迭代速率、缺陷逃逸率。
- **混合型项目**：关键接口与里程碑采用预测式监控，内部开发工作采用敏捷式监控。
- **通用裁剪原则**：监控频率、指标颗粒度、报告形式与审批层级均应根据组织文化、项目规模、复杂度、监管要求和干系人信息需求进行裁剪。`,
      "💼 实践案例": `某软件开发项目在第6周结束时，计划完成40%的工作（PV=40万元），实际完成35%（EV=35万元），已支出成本44万元（AC=44万元）。经挣值分析：SV=-5万元、SPI=0.875，说明进度滞后；CV=-9万元、CPI=0.795，说明成本严重超支。项目经理解读数据后召开状态会议，通过根本原因分析确认根因是需求频繁变更和工作量低估，随即向评估与实施变更过程提出纠正措施请求，并调整下阶段的资源投入与任务安排，同时更新成本预测提请干系人知悉。会后项目经理在周报中说明储备使用情况，建议通过变更流程追加预算，最终项目在压缩部分非关键功能后重新回到可控轨道。`,
    },
    keyConcepts: `- **挣值管理（EVM）**：综合衡量范围、进度和成本的绩效测量方法，是监控绩效的核心工具。核心指标：SV=EV-PV、CV=EV-AC、SPI=EV/PV、CPI=EV/AC、TCPI=(BAC-EV)/(BAC-AC)。
- **工作绩效数据/信息/报告三层递进**：数据是执行中采集的原始观测值，信息是经过分析和加工的结果，报告是面向干系人的汇总文件。
- **测量陷阱**：霍桑效应（测量影响行为）、虚荣指标（数据好看但无决策价值）、士气低落、误用度量指标、确认偏见、相关性与因果关系混淆。
- **SMART准则**：度量指标应具体、可衡量、可达成、相关、有时限。
- **领先指标与滞后指标**：领先指标预示未来趋势（如缺陷密度、待办事项流动速率），滞后指标反映过去结果（如已完成百分比）。`,
    examTips: `- EVM必考！SV>0=提前、SV<0=滞后；CV>0=节约、CV<0=超支；SPI>1=提前、CPI>1=节约。四个公式与符号含义务必牢记，计算题常给出EV、PV、AC求SV/CV/SPI/CPI。
- TCPI用于计算剩余工作的成本效率要求：TCPI=(BAC-EV)/(BAC-AC)；当BAC不可用时改用EAC作分母，即TCPI=(BAC-EV)/(EAC-AC)。
- 注意区分工作绩效数据（原始）、工作绩效信息（分析后）和工作绩效报告（汇总后）三个层次，选择题常考其归属。
- 领先指标与滞后指标：判断一个指标是预示未来还是反映过去。
- 监控发现问题→提出变更请求→走整体变更控制流程，绝不直接修改计划或基准。
- 警惕虚荣指标与霍桑效应的干扰，考核哪个指标为真正的决策依据。`
  },
  "proc-evaluate-change": {
    overview: `评估与实施变更过程贯穿整个项目生命周期，因为变更可能在任何阶段、由任何干系人提出。变更请求可能影响项目范围、产品范围、项目管理计划组件和项目文件。在预测型方法中，基准建立前变更不受正式控制；然而一旦建立基准，所有变更都须通过正式流程进行评估与实施。变更虽可口头发起，但必须书面记录并录入变更或配置管理系统，通常附有估算的进度影响与成本影响信息。影响项目基准的变更应按正式流程采用整体变更控制措施评估并实施，由指定人员（如项目发起人或项目经理）批准、推迟或否决；重大变更通常交由正式成立的变更控制委员会（CCB）审批。

在适应型方法中，管理变更通常涉及待办事项列表管理，而非正式的变更请求流程。在整个迭代开发周期中会持续评估变更并进行优先级排序：干系人提出的变更被记录为产品待办事项，若被分配较低优先级，实质上意味着该变更被推迟处理。本过程的关键收益是确保项目基准受控、变更得到有序且可追溯的处理，防止范围蔓延（未经控制的增量变更累积）和质量下降。其核心是整体变更控制——对变更进行综合评估，不仅看变更本身，还要看它对所有约束条件、其他计划组件和相关风险的综合影响。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：包括范围、进度、成本等子管理计划和基准，是评估变更影响的对象与依据，用于判断变更会触碰哪些计划组件与基准，以及更新时需要修订哪些部分。
- **变更请求**：描述变更的内容、理由、影响范围、备选方案以及预计的进度影响和成本影响，是进入本过程的核心输入，可能来自干系人、监控过程或缺陷补救需求，任何干系人均可提出。
- **工作绩效数据**：提供当前执行状况的原始数据，用于评估变更对现状的增量影响，判断是否有必要、有能力实施该变更，并支撑影响分析的准确性。
- **组织过程资产**：变更控制政策、配置管理政策、变更请求模板与处理流程、审批层级规则、历史变更记录等，规范变更如何提交、评估、批准与记录，保证处理的一致性与可审计性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由发起人、主题专家、干系人等评估变更的技术可行性、进度与成本影响、风险影响和干系人影响，弥补纯量化分析的局限，确保评估覆盖技术、商业与治理多个维度。
- **变更控制工具**：配置管理系统与变更管理系统的具体载体，用于记录、跟踪变更请求、配置项及其审批状态，支持版本控制与审计追踪，保证变更全程可追溯、可回滚。
- **数据分析**：包括备选方案分析（比较不同变更方案的优劣）、成本效益分析（评估变更带来的收益与代价）、影响分析（定量或定性评估变更对范围、进度、成本、风险、质量的影响）、回归分析（判断变更对既有成果的波及）等，为决策提供量化依据。
- **决策**：包括投票（一致同意、大多数原则）、独裁决策（由授权人单独决定）、多标准决策分析（按多个标准评分选择方案），用于批准、推迟或否决变更请求。
- **会议**：变更控制委员会（CCB）会议是审查与决定变更请求的正式场合，会上对变更进行综合评估并形成正式决策，确保变更治理的严肃性与权威性。`,
      "📤 输出 Outputs": `- **批准的变更请求**：经过评估后获得批准（可能附带条件）、被推迟或被否决的变更请求，经批准的变更成为指导项目执行、更新计划与基准的正式依据，被否决的变更须记录原因供干系人知悉。
- **项目管理计划更新**：批准的变更使相应子计划或基准得到更新——涉及基准的变更须经CCB批准后重新发布基准并记录变更，涉及子计划的变更则更新相应计划组件，确保计划始终反映最新决策。
- **项目文件更新**：如范围说明书、需求文件、进度计划、风险登记册、问题日志等随批准的变更相应调整，确保项目文件与最新决策保持一致。`,
      "🔗 与其他过程的相互作用": `- **作为变更中枢**：监控项目绩效等监控过程发现偏差后提出的变更请求，以及管理项目工作过程中干系人直接提出的变更，都在本过程统一评估和处理，任何变更都不应绕过本过程直接实施。
- **回流执行**：批准的变更更新项目管理计划相应组件与基准后，重新指导管理项目工作过程和各控制过程，确保变更真正落地。
- **协同配置管理**：配置管理识别并管理配置项版本，与本过程协同，确保改什么、由谁批准、当前是哪个版本清晰可查。
- **联动其他过程**：变更评估同时驱动风险监控（评估变更引入的新风险）、质量控制（评估对质量目标的影响）和范围管理（防止范围蔓延），是项目治理的关键枢纽。`,
      "✂️ 裁剪考虑": `- **预测型项目**：设立正式的CCB，基准建立后所有变更都走完整审批流程——提交变更申请单、进行影响分析、召开审批会议、更新计划、实施与验证，变更日志完整记录每一步。
- **适应型项目**：不设正式CCB，变更直接进入产品待办事项列表，由产品负责人按价值与优先级持续排序，在迭代内灵活吸纳，重点防范范围蔓延，变更管理工具可简化为待办事项管理工具。
- **混合型项目**：合同接口类和里程碑类变更走正式流程，产品功能类变更走待办事项管理，两者并行。
- **通用裁剪原则**：审批层级（哪些变更由项目经理批准、哪些必须上报CCB）、变更控制工具的复杂度、评估深度均应按项目规模、组织治理结构和干系人期望裁剪。`,
      "💼 实践案例": `某基建项目在施工阶段，业主提出增加一座人行天桥的重大变更。项目经理收到书面变更请求后，组织专家完成影响分析：预计增加成本800万元、延长工期45天，并影响既有地下管线方案，同时评估了三种备选方案。该变更提交CCB会议评审，CCB结合预算可用性与战略价值有条件批准（要求压缩其他分项的工期弥补部分延误）。项目经理随即更新成本基准与进度基准、修订相关计划文件和风险登记册，将批准记录存档，并指导团队按新基准实施。整个过程从评估、审批到实施与验证均可追溯、可审计，未出现擅自变更。`,
    },
    keyConcepts: `- **整体变更控制（Integrated Change Control）**：贯穿项目始终的综合变更管理机制，对所有变更请求进行综合评估并决定批准、推迟或否决，防止范围蔓延与基准失控。
- **变更控制委员会（CCB）**：正式成立的组织，负责审查、评估、批准、推迟或否决变更请求，其成员构成与审批权限在变更管理计划中定义，重大变更必须由其决策。
- **变更控制流程**：识别变更→评估影响→提交变更请求→CCB审批→更新计划→实施→验证，顺序不可颠倒。
- **配置管理**：识别并管理配置项及其版本，确保变更可追溯、可回滚，是变更控制的基础设施。
- **变更日志**：按时间顺序记录所有变更请求及其评估与审批状态的日志文件，是变更管理可审计性的直接体现。
- **范围蔓延**：未经批准或控制的增量变更累积，导致项目范围不受控扩张，是变更管理不力最典型的后果。`,
    examTips: `- 最常考！变更控制流程必须完整：识别变更→评估影响→提交变更请求→CCB审批→更新计划→实施→验证。永远不能跳过流程直接实施变更！
- 基准建立前变更不受正式控制，基准建立后所有变更必须走正式流程——这一分界点是高频考点。
- 口头提出的变更也要书面记录并录入变更/配置管理系统；先评估影响再决策，绝不能先实施后补手续。
- 只有批准变更后才更新计划与基准；被否决的变更要记录并继续跟踪，而非搁置遗忘。
- 敏捷项目中变更被记录为产品待办事项，由产品负责人排序，低优先级意味着推迟处理。
- 重大变更通常由CCB审批；项目经理权限不足时不能擅自批准，干系人（包括客户）也无权直接要求团队改范围。
- 区分纠正措施、预防措施、缺陷补救与范围/进度/成本调整四类变更请求及其用途。
- 在敏捷场景中范围蔓延同样是风险，产品负责人在接受新变更时须权衡其对迭代目标与价值交付的影响。`
  },
  "proc-close-project": {
    overview: `结束项目或阶段过程旨在对所有与项目、阶段、发布、迭代或合同（无论成败）相关的活动进行最终结项。该过程的关键收益是归档项目信息或阶段信息、完成规划工作、并释放组织资源以用于新项目，同时确认价值或交付价值的能力在多大程度上已经实现。收尾工作包括：获得客户或发起人对可交付物的正式验收、确保所有财务结算已完成并结清所有合同、归档项目文件（包括经验教训）、将最终产品/服务/结果移交给运营团队或客户、释放所有项目资源（团队成员、设备等）、发布最终报告。其中，行政收尾（完成所有项目管理活动并归档）与合同收尾（完成所有合同义务并结清合同）须同时完成。

本过程通常在项目或阶段的所有目标达成后触发，也可能因优先级变化、资金终止、需求不再存在等原因提前触发。在适应型方法中，收尾不仅发生在项目终点，还发生在每个迭代或发布结束时——团队在每次迭代回顾中总结经验教训并在后续迭代中应用。即使项目提前终止（无论成败），仍须执行收尾过程，确保项目文件和知识的完整归档。收尾过程是项目生命周期的最后一环，也是组织知识传承与资源循环的关键接口。同时，收尾还涉及对干系人与团队成员的正式告别与感谢，确保以积极、完整的方式为项目画上句号。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：包含收尾政策、验收标准以及范围/进度/成本等基准的完成情况，用于核对所有项目活动是否按计划完成、是否满足收尾条件，是收尾工作启动的清单依据。
- **项目文件**：包括经验教训登记册、问题日志、风险登记册、变更日志、里程碑清单、范围说明书等，为最终归档和经验总结提供素材，也是验收与移交时的参考。
- **可交付物**：经确认范围过程正式验收的、已完成的可交付物，是最终移交和正式接受的对象，须确保其完整性并随附验收记录，成为编制移交协议的基础。
- **事业环境因素**：组织的收尾程序、归档要求、审计要求、法律与合规要求、财务结算规定等，决定收尾活动的执行方式与文件保存规范。
- **组织过程资产**：历史项目档案、收尾报告模板、经验教训模板、组织政策与流程，为规范收尾动作和沉淀组织知识提供依据，使收尾工作有章可循，并支撑收尾质量的一致性与可比性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由发起人、干系人、主题专家等确认可交付物的完整性、评估收尾条件是否满足、审查经验教训的有效性，确保收尾结论可靠且符合组织与干系人期望，在验收争议时还能提供专业仲裁依据。
- **知识管理工具**：将团队隐性经验显性化，如组织知识分享会、导师制、故事讲述、复盘工作坊等方式，并把经验教训结构化地录入组织知识库，供未来项目复用，是组织学习文化落地的重要抓手。
- **信息管理工具**：项目档案管理系统、文档管理系统、企业内容管理系统等，用于存储、检索和归档项目记录，保证项目信息可追溯、可审计、可长期保存，满足合规与审计要求。
- **人际关系与团队技能**：包括沟通、会议主持、团队协作等软技能，用于组织收尾会议、向干系人传达结项结果、引导经验教训的坦诚分享，并妥善处理成员释放时的情绪与过渡。`,
      "📤 输出 Outputs": `- **经验教训登记册**：沉淀项目全过程的经验教训（成功的做法与改进点），归档至组织过程资产，供未来项目直接参考，是组织学习与知识传承的核心载体，通常按主题分类以便检索复用。
- **项目管理计划更新**：记录计划与实际执行的差异说明以及收尾过程中发生的相关变更，作为项目最终档案的组成部分，供审计、复盘与后续项目借鉴。
- **组织过程资产更新**：包括项目档案（最终报告、可交付物记录、验收文件）、经验教训知识库、绩效评估与历史信息，丰富组织资产供后续项目使用，形成组织持续改进的基础。
（另：本过程通常还产生最终产品/服务/结果的移交与最终报告等输出，具体以组织收尾要求为准。）`,
      "🔗 与其他过程的相互作用": `- **承接确认范围**：收尾过程处于项目生命周期的末端，先由确认范围过程获得干系人对可交付物的正式验收，再进行行政收尾，顺序不可颠倒。
- **衔接控制采购**：合同收尾与控制采购过程衔接，需结清所有合同义务并对供应商绩效做出最终评估，完成合同款项结算与供应商绩效评价。
- **传承组织知识**：本过程输出的经验教训与组织过程资产更新，又成为未来项目的重要输入，形成组织知识的传承闭环，提升组织的整体项目管理成熟度。
- **处理遗留问题**：收尾中若发现遗留问题，通常以记录并移交后续运营或支持团队处理为主，不再改变既有基准。`,
      "✂️ 裁剪考虑": `- **预测型项目**：收尾集中在项目结束时进行，包含完整的正式验收、财务结算、合同收尾、文件归档与最终报告发布，收尾检查单逐项确认。
- **适应型项目**：在每个迭代或发布结束时进行轻量收尾（迭代回顾、发布说明、增量归档），项目级收尾依然完整执行，经验教训持续积累。
- **合同型项目**：行政收尾与合同收尾并重，特别注重供应商绩效评估与合同结清，验收与付款紧密挂钩。
- **提前终止的项目**：即使项目未按预期完成，仍须完整执行收尾，并重点记录终止原因与未完成工作，避免未来项目重蹈覆辙。`,
      "💼 实践案例": `某信息化改造项目完工后，项目经理组织干系人召开验收评审会，客户对系统进行最终测试验收并签字确认。随后开展行政收尾：完成财务结算、编制最终绩效报告、将全套文档（验收单、变更记录、测试报告、操作手册）归档，组织召开经验教训总结会并更新组织知识库，最后释放团队成员与设备，并将系统运维正式移交给运营团队。在收尾会议上，客户提出的新功能需求被记录为后续项目的机会，而非并入本项目。项目经理还在最终报告中客观总结了工期、成本与质量的达成情况，并为团队成员的后续安排提供建议。整个收尾过程在计划时间内有序完成，组织资产得到充实。`,
    },
    keyConcepts: `- **行政收尾**：确保所有项目管理活动完成、项目文件归档、经验教训沉淀、项目资源释放。
- **合同收尾**：完成所有合同义务、结清所有合同款项、对供应商绩效进行最终评估，确保无遗留法律义务。
- **确认范围 vs 收尾**：确认范围是对可交付物的正式验收（发生在前），结束项目或阶段是归档与资源释放（发生在后），顺序要清楚。
- **提前终止**：即使项目未按预期完成，也必须执行收尾过程以保证知识与文件完整归档，并记录终止原因。
- **可交付物移交**：将最终产品、服务或结果正式移交给客户或运营团队，并明确后续支持与运维责任，是收尾的关键动作之一。
- **最终报告**：总结项目成果、绩效对比（范围、进度、成本、质量达成情况）与收尾结论的正式文件，是干系人了解项目最终结果的核心依据。
- **经验教训**：贯穿项目全程，在迭代回顾和项目收尾中持续总结，回灌组织过程资产供未来项目复用。`,
    examTips: `- 收尾不等于项目结束——每个阶段、迭代或发布结束时也需要执行收尾。
- 必须发布最终报告并归档经验教训；行政收尾和合同收尾都要完成，缺一不可。
- 顺序要清楚：确认范围（客户验收可交付物）→ 结束项目或阶段（归档和释放资源）。
- 如果项目提前终止（无论成败），仍然需要执行收尾过程。
- 收尾时必须释放所有项目资源，团队成员会被重新分配。
- 经验教训要沉淀为组织过程资产，供未来项目参考复用。
- 常见陷阱：收尾不能草率跳过合同结清与财务结算；收尾阶段客户提出的新需求应记录为后续项目，而非悄悄并入本项目导致范围蔓延。
- 收尾阶段的验收文件、移交记录与最终报告要完整归档，作为后续审计、维护与争议处理的依据。`
  },
  "proc-plan-scope-mgmt": {
    overview: `【过程概述】规划范围管理过程是规划过程组中范围领域的第一个过程，其目标是创建范围管理计划，并同时制定需求管理计划。该过程通过明确完成项目所需的全部工作，排除或移除不会为项目增加价值的不必要工作，来定义项目将如何交付。

- **过程目的**：回答"本项目将如何规划和管理范围"，为后续定义范围、制定范围结构（WBS）、确认范围和监控范围等所有范围管理活动提供指导框架。
- **关键收益**：为范围管理提供指导，确保向利益相关方（干系人）交付价值。范围管理的目标（确保价值交付）始终不变，但方式因开发方法而异。
- **执行频率**：在规划阶段执行一次，但应根据项目生命周期持续定义、制订、监督、确认和控制范围管理计划，必要时予以更新。
- **预测型方法**：范围管理计划更详细、更正式，范围在项目早期被完整定义，变更受正式变更控制流程约束。
- **适应型方法**：规划范围管理过程更具迭代性和协作性，范围管理计划更精简灵活，范围通过产品待办事项列表逐步细化，优先聚焦于价值交付。
- **与其他计划的关系**：范围管理计划和需求管理计划都是项目管理计划的子计划，与进度管理计划、成本管理计划等相互衔接，共同构成项目管理计划的整体框架。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：记录项目目的、高层级描述、高层级风险、总体可交付物和主要干系人等信息，是项目启动的授权文件。本过程用它确定范围规划的基本方向和边界，明确项目的合法性来源。
- **项目管理计划**：已被批准的项目管理计划（含已有的质量管理计划、项目生命周期描述、开发方法等子组件）为本过程提供组织协调依据，确保范围管理计划与整体项目管理计划保持一致。
- **事业环境因素**：指项目团队无法控制的组织内外部条件，如组织文化、行业标准、监管要求、市场条件、基础设施和人事管理制度等。它们影响范围管理计划的裁剪方式，例如某些行业（医疗、金融）对范围文档有强制性规范。
- **组织过程资产**：指组织积累的可复用资产，如范围管理的政策、程序、指南、模板（WBS模板、范围说明书模板）、历史信息和经验教训数据库。利用它们可提高范围规划的效率和一致性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：请教具有项目或范围管理经验的项目经理、干系人、行业领域专家和咨询顾问，用于确定范围管理计划的形式与详细程度、做出开发方法裁剪决策、评估范围管理方案的适用性。专家判断贯穿整个过程，是制定高质量计划的关键输入。
- **数据分析**：本过程主要使用**备选方案分析**，评估不同的范围管理方法、开发方法（预测型、适应型、混合型）和工具组合的利弊，选择最适合本项目特点的方案，作为裁剪决策的依据。
- **会议**：通常召开规划范围管理会议，由项目经理、项目团队和关键干系人共同参加，讨论并达成对范围管理计划的一致意见。会议讨论内容包括范围说明书如何制定、WBS如何创建、范围如何验证和控制，以及需求如何分析和管理。`,
      "📤 输出 Outputs": `- **范围管理计划**：项目管理计划的子计划，描述如何定义、验证和控制项目和产品范围。其典型组件包括：
  - **如何制定项目范围说明书**：明确项目范围说明书应包含的内容（产品范围描述、可交付物、验收标准、项目除外责任）及其制定责任人和审批流程。
  - **如何创建WBS**：规定WBS的分解层级、工作包粒度、WBS词典的编制要求以及编码方式，为制定范围结构过程提供指引。
  - **如何制定范围基准**：明确范围基准（经批准的项目范围说明书+WBS+WBS词典）的审批方式和维护责任。
  - **如何验证和验收可交付物**：规定确认范围过程的验收方式、验收标准来源和干系人参与方式。
  - **如何控制范围变更**：定义范围变更的处理流程、范围蔓延的应对方式，以及范围与整体变更控制流程的衔接关系。范围管理计划可以是正式或非正式的、详细或概要的，取决于项目需求和裁剪决定。
- **需求管理计划**：项目管理计划的子计划，记录如何分析、记录和管理项目和产品需求。其典型组件包括：
  - **如何规划、跟踪和报告需求活动**：规定需求活动的开展方式、责任人、跟踪频次与报告形式。
  - **配置管理活动**：定义需求变更如何发起、评审和批准，以及需求版本的管理方式。
  - **需求优先级排序过程**：规定需求优先级排序的方法（如MoSCoW、Kano模型、多标准决策分析）和参与人员。
  - **产品度量指标**：定义用于跟踪和度量需求价值的指标（如功能点数、缺陷密度）。
  - **需求跟踪结构**：规定需求跟踪矩阵如何建立、跟踪哪些属性（如来源、可交付物、优先级、状态），确保每个需求可追溯。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：本过程的输入来自启动过程组（项目章程）和已制定的项目管理计划，是范围领域规划链条的起点。
- **下游衔接**：范围管理计划指导定义范围（如何制定范围说明书）、制定范围结构（如何创建WBS和范围基准）；需求管理计划指导启发并分析需求（如何分析、记录和管理需求）以及后续的需求跟踪与变更。
- **与整体变更控制**：范围管理计划定义了范围变更如何进入整体变更控制流程（评估与实施变更过程），确保范围变更经过正式评估和批准。
- **与监控过程**：监控范围过程依据范围基准评估偏差；范围管理计划中规定的控制临界值和绩效测量规则是监控范围的依据。`,
      "✂️ 裁剪考虑": `- **预测型项目**：范围管理计划详细而正式，范围在项目早期完整定义，范围变更须走严格的形式化变更控制流程。
- **适应型项目**：范围管理计划更精简灵活，范围通过产品待办事项列表逐步细化，需求以用户故事表达并持续排序，范围管理聚焦于价值交付而非一次性完整定义。
- **混合型项目**：对确定性高的部分采用预测型范围管理，对不确定性高的部分采用适应型范围管理，两者在计划中明确划分边界。
- **其他裁剪维度**：项目规模（大型项目需更详细的范围治理）、行业（监管严格的行业需更正式的范围文档）、项目复杂度、干系人分布和期望都会影响范围管理计划的详细程度与形式。`,
      "💼 实践案例": `某银行实施核心业务系统升级项目。项目经理在规划范围管理时，考虑到需求不确定性和监管合规要求，选择了混合型方法：将监管必须满足的硬性需求采用预测型管理并写入详细范围说明书，将客户体验优化类需求采用适应型管理，以用户故事形式纳入待办事项列表。在范围管理计划中明确规定了WBS的分解层级（不超过5层）、范围变更须经变更控制委员会（CCB）审批、范围蔓延须立即上报；在需求管理计划中规定了需求跟踪矩阵的建立方式（跟踪需求来源、优先级、验收标准和对应可交付物）以及需求优先级排序采用MoSCoW方法。该计划使后续范围管理活动有章可循，有效防止了范围蔓延。

另一个例子：某创业公司开发移动端点餐App，采用适应型方法。其范围管理计划十分精简，仅包含：每次迭代开始时由产品负责人与团队共同细化产品待办事项列表；需求以用户故事表达并按其商业价值排序；范围变更直接表现为待办事项列表的增删与重排，无需填写正式变更申请单。这种裁剪大大加快了价值交付节奏，体现了适应型方法中范围管理的协作性与迭代性。`,
    },
    keyConcepts: `关键术语——
- **范围管理计划**：项目管理计划的子计划，记录如何定义、验证和控制项目和产品范围，是范围管理的"指导手册"。
- **需求管理计划**：项目管理计划的子计划，记录如何分析、记录和管理项目和产品需求，并规定需求优先级排序、配置管理、需求跟踪等机制。
- **项目范围 vs 产品范围**：项目范围指为交付可交付物而必须完成的工作；产品范围指产品、服务或结果所具有的特性和功能。两者由不同的度量标准衡量（项目范围看项目工作是否全部完成，产品范围看产品功能是否满足要求）。
- **规划范围管理的关键输出**：范围管理计划+需求管理计划，两者都是规划过程中创建的基础性指导文件。
- **裁剪**：根据项目特点（方法、规模、行业、复杂度）调整范围管理计划的详细程度和正式程度，是项目管理者的重要职责。`,
    examTips: `考试重点/常见陷阱——
- **高频考点：范围管理计划的组成**——包括如何制定范围说明书、如何创建WBS、如何制定范围基准、如何验证和验收可交付物、如何控制范围变更，考试常以"以下哪项属于范围管理计划的内容"形式出现。
- **高频考点：需求管理计划的组成**——包括如何分析、记录和管理需求，以及需求优先级排序、配置管理、产品度量指标、需求跟踪结构，注意与范围管理计划内容区分。
- **易混淆**：范围管理计划（如何管理的计划）≠项目范围说明书（具体范围描述）≠WBS（范围分解）≠范围基准（经批准的范围说明书+WBS+WBS词典）。
- **适用范围**：规划范围管理既适用于预测型也适用于适应型项目，区别在于详细程度与迭代性，而非"敏捷不需要范围管理计划"。
- **收益关键词**："确保向利益相关方交付价值""提供范围管理指导"，考试若问该过程关键收益，选"指导范围管理以确保交付价值"。`
  },
  "proc-elicit-requirements": {
    overview: `【过程概述】启发并分析需求过程是规划过程组中范围领域的第二个过程，其目标是定义并记录利益相关方（干系人）对于产品、服务或结果所需特性和功能的需求，以确保向干系人交付的成果兼具质量和价值。

- **需求的定义**：需求是指产品、服务或结果为满足业务需要而必须具备的条件或能力。它是范围定义的基础输入。
- **需求类型**：
  - **业务需求**：组织的高层级需要，回答了"组织为什么开展此项目"。
  - **干系人需求**：干系人的需要和期望，回答了"干系人需要什么"。
  - **解决方案需求**：产品或解决方案需满足的功能性需求（系统应具备的功能）和非功能性需求（性能、安全、可用性等约束条件）。
  - **过渡需求**：从当前状态过渡到目标状态所需的临时能力，如数据迁移、人员培训、系统切换。
- **适应型环境**：需求以用户故事的形式被收集（"作为[角色]，我希望[功能]，以便[收益]"），然后在待办事项列表（产品待办事项列表）中进行优先级排序。
- **关键收益**：为定义能够为干系人增加价值的产品、服务或结果提供方向和起点。
- **主要活动**：通过访谈、焦点小组、引导式研讨会、问卷和调查、观察法、原型法、标杆对照等数据收集方法启发需求，再经分析和确认形成需求文件和需求跟踪矩阵。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目目的、高层级需求、高层级产品描述和主要干系人信息，是需求的原始来源和收集方向的起点。
- **项目管理计划**：其中**需求管理计划**规定了需求活动如何开展（分析、记录、管理、排序、跟踪），**干系人参与计划**帮助识别应访谈的干系人，**范围管理计划**界定需求与范围的关系，共同指导本过程执行。
- **项目文件**：包括假设日志（记录影响需求的假设条件）、干系人登记册（识别需咨询的干系人）以及商业文件（商业论证、效益管理计划，明确需求背后的商业动机和预期效益）。
- **协议**：合同或协议中的条款、交付物描述和验收约定，尤其是对外采购部分的需求必须与合同一致，是本过程重要的需求来源。
- **事业环境因素**：组织文化、市场条件、法律法规、行业标准等，影响需求收集的范围、方式与合规要求。
- **组织过程资产**：历史项目需求、需求模板、政策程序、经验教训数据库等，可复用以往需求信息以提高收集效率。`,
      "🔧 工具与技术 Tools": `- **专家判断**：邀请具有需求分析经验的领域专家、业务分析师或干系人代表，协助确定需求收集方法、解释复杂需求并验证需求完整性。
- **数据收集**：
  - **访谈**：与干系人一对一的直接对话，通过提问和倾听获取需求，适用于深入了解特定干系人的期望，应提前准备问题清单。
  - **焦点小组**：由主持人引导约6-12位干系人代表集中讨论，围绕特定议题收集多方期望，比一对一访谈效率更高。
  - **问卷和调查**：以书面形式向大量干系人收集信息，适合干系人数量大、地理位置分散的场景，统计分析后得出需求倾向。
  - **标杆对照**：将本项目与可比组织或类似项目进行对比，识别最佳实践并作为改进依据，常用于确定性能类需求的目标值。
- **数据分析**：主要使用**文件分析**，通过研究现有文档（商业计划、协议、市场文献、法规条文、历史项目文件）提取与项目相关的需求，是低成本高价值的需求来源。
- **决策**：包括**投票**（一致同意、大多数同意、相对多数三种方式）和**多标准决策分析**（按收益、成本、风险、复杂度等多个标准对需求方案打分排序），用于对需求进行优先级排序和方案选择。
- **人际关系与团队技能**：
  - **头脑风暴**：团队发散式提出大量想法，再集中讨论筛选，用于激发创造性需求。
  - **引导式研讨会**：跨职能干系人在同一场合共同定义需求，能快速消除误解、加速达成一致，是需求收集的高效工具。
  - **名义小组技术**：先让参与者独立思考记录想法，再逐一分享并投票排序，兼顾个体贡献与群体决策。
  - **观察和交谈**：通过实地观察干系人的工作方式或流程（或旁观使用者操作），获取难以言表的隐性需求。
  - **人际关系技能**：如积极倾听、冲突管理、建立信任等，支撑上述方法的有效开展。
- **原型法**：制作可演示的原型（草图、模型、可点击页面）供干系人体验和反馈，通过反复迭代澄清需求，在产品不确定性高、需求难以描述时尤为有效。`,
      "📤 输出 Outputs": `- **需求文件**：记录已识别需求的正式文件，描述每个需求及其属性（如唯一标识、需求类型、优先级、来源、验收标准、相关干系人）。需求文件是定义范围、制定范围结构（WBS）和后续确认/监控范围的重要输入。
- **需求跟踪矩阵**：将产品需求与来源（干系人、业务需要、协议）和对应可交付物连接起来的表格，记录需求标识、需求描述、来源、状态、优先级、所属可交付物等属性。其核心作用是确保每个需求都能追溯到其来源和对应的可交付物，防止需求遗漏和范围蔓延，并作为需求变更和监控的依据。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：输入来自启动过程组（项目章程）和已制定的计划/文件（需求管理计划、干系人登记册、商业论证等）。
- **下游衔接**：需求文件和需求跟踪矩阵输出给**定义范围**过程（据此编写项目范围说明书）；需求文件还输入**制定范围结构（WBS）** 和**制订进度/成本计划**等过程。
- **与监控过程**：需求跟踪矩阵在监控需求变化时发挥作用——当需求被批准变更时，其状态和对应可交付物在矩阵中被同步更新，需求变更须通过整体变更控制流程（评估与实施变更）处理。
- **与干系人管理**：需求收集与干系人识别、干系人参与紧密联动，需求来源即干系人。`,
      "✂️ 裁剪考虑": `- **预测型项目**：在规划早期一次性完成较完整的需求收集，以正式需求文件记录，需求变更须走正式变更流程。
- **适应型项目**：需求以用户故事形式持续收集，存入产品待办事项列表并随每次迭代重新排序，不追求一次性完整；优先级排序常采用MoSCoW（必须有/应该有/可以有/不会有）、Kano模型或相对权重方法。
- **混合型项目**：对稳定、明确的需求采用正式需求文件管理，对探索性需求采用用户故事和原型法逐步细化。
- **裁剪维度**：干系人数量（数量大时多用问卷和调查）、需求不确定性（不确定性高时多用原型法和引导式研讨会）、项目行业（监管行业需求收集须覆盖合规要求）。`,
      "💼 实践案例": `某银行开发手机银行App。项目经理通过多种方法组合收集需求：对高管层进行访谈以明确业务需求（如"三年内将线上交易占比提升到60%"）；邀请6位不同客户群体代表参加焦点小组讨论界面偏好；面向5000名活跃客户发放问卷和调查收集功能偏好；同时制作高保真原型让目标用户体验，根据反馈反复迭代界面交互；并与竞品银行App进行标杆对照，确定指纹登录、实时到账提醒等性能类需求的基准目标。最终将所有需求按类型分类记录在需求文件中，并建立需求跟踪矩阵，将每条需求追溯到其来源客户群体和对应的App模块，有效防止了需求遗漏与范围蔓延。

另一案例：某电商平台开发智能客服系统。由于需求高度不确定，团队采用适应型方法，将需求全部以用户故事表达（如"作为顾客，我希望机器人能识别我的订单状态，以便快速查询物流"），放入产品待办事项列表并按商业价值排序。每个迭代末通过观察客服人员的实际工作方式（观察法）发现新需求并补充进待办事项列表，实现了需求的持续演进与价值优先交付。`,
    },
    keyConcepts: `关键术语——
- **需求文件**：记录已识别需求及其属性（类型、优先级、来源、验收标准）的文件，是范围定义的基础。
- **需求跟踪矩阵**：连接需求与来源、可交付物的表格，确保每个需求可追溯、可覆盖，防止范围蔓延。
- **需求类型**：业务需求、干系人需求、解决方案需求（功能性+非功能性）、过渡需求。
- **需求（Requirement） vs 期望（Expectation）**：需求是必须满足的条件或能力，期望是希望达到的状态；满足需求是底线，超越期望是加分。
- **用户故事**：适应型方法中标准的需求表达方式："作为[角色]，我希望[功能]，以便[收益]"，强调从用户视角描述价值。
- **功能性需求 vs 非功能性需求**：功能性需求描述系统"做什么"（功能），非功能性需求描述系统"做得怎么样"（性能、安全、可用性、可维护性等约束）。
- **数据收集方法**：访谈、焦点小组、引导式研讨会、问卷和调查、观察法、原型法、标杆对照。`,
    examTips: `考试重点/常见陷阱——
- **高频考点**：需求管理计划+需求文件+需求跟踪矩阵是本过程的输出链条，考试常问"收集需求的关键输出是什么"——答案选需求文件和需求跟踪矩阵。
- **高频考点：需求跟踪矩阵的作用**——把需求与来源和可交付物连接，确保可追溯、防止遗漏，而不是直接管理变更。
- **易混淆**：需求（Requirement，必须满足）与期望（Expectation，希望达到）必须区分；功能性需求（做什么）与非功能性需求（做到什么标准）也必须区分。
- **方法选择**：访谈=一对一深度了解；焦点小组=6-12人小组讨论；问卷=大范围收集；原型法=不确定性高时澄清需求；观察法=获取隐性需求。考试常给出场景让选择最合适的方法。
- **收益关键词**："为定义能够为干系人增加价值的产品/服务/结果提供方向和起点"。
- **常见陷阱**：需求收集不是一次性的——适应型项目中需求持续演进；需求文件不是可交付物本身，而是需求信息的记录。`
  },
  "proc-define-scope": {
    overview: `【过程概述】定义范围过程是规划过程组中范围领域的第三个过程，其目标是对项目、产品及预期交付的价值进行详细或高层级的描述。

- **过程目的**：明确"项目要交付什么"以及"什么不在项目范围内"，形成项目范围说明书，为后续制定WBS和范围基准奠定基础。
- **执行时机**：该描述可以在项目开始时进行（适用于预测型方法），也可以在每次迭代开始时进行（适用于适应型和混合型方法），按项目生命周期分层细化。
- **结构化方式**：在预测型方法中，可交付物应通过WBS进行结构化（结构化、层级化的分解）；在适应型方法中，可交付物则通过待办事项列表（产品待办事项列表）逐步细化，以用户故事等形式演进。
- **关键收益**：确保利益相关方（干系人）和项目团队理解将通过产品、服务或结果交付的价值，从而减少误解和返工。
- **核心输出——项目范围说明书**：详细描述了项目可交付物、验收标准和项目除外责任，是WBS和范围基准的基础。项目范围说明书与项目章程有本质区别：章程侧重于授权和高层级信息，范围说明书则提供详细的范围描述。
- **项目范围说明书的内容**：产品范围描述、可交付物、验收标准、项目除外责任（明确指出项目不包含的内容，有助于管理干系人期望）。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目目的、高层级范围描述、高层级可交付物和关键干系人期望，是定义范围最上层的权威依据。
- **其他过程的输出**：指范围管理计划（规定范围说明书如何制定）、质量管理计划、项目生命周期描述、开发方法等项目管理计划组件，以及需求文件、假设日志、风险登记册、干系人登记册等项目文件——它们共同提供细化范围所需的全部信息。
- **事业环境因素**：组织文化、行业法规、技术标准等外部条件约束范围的边界，例如合规要求决定了范围必须覆盖哪些内容。
- **组织过程资产**：历史项目范围说明书、WBS模板、范围模板和经验教训数据库，为编写范围说明书提供参考和最佳实践。`,
      "🔧 工具与技术 Tools": `- **专家判断**：邀请领域专家、业务分析师和资深项目经理，协助界定产品范围、确定验收标准和判断除外责任的合理性，弥补团队对业务理解的不足。
- **数据收集**：主要使用**备选方案分析**（从多种产品/方案中评估选择）和**产品分析**（以需求文件为依据，通过产品分解、系统分析、价值工程等方法逐步细化产品范围描述）。
- **人际关系与团队技能**：
  - **引导式研讨会**：组织跨职能干系人共同讨论确定范围，促进对范围边界的一致理解，降低后续需求变更概率。
  - **演示**：向干系人演示产品方案或原型，帮助其理解和确认范围。
  - **观察**：观察干系人工作方式以辅助界定范围（尤其适用于适应型项目）。
- **会议**：召开范围定义会议，与干系人、团队一起评审并确认项目范围说明书的初稿，收集反馈后定稿。`,
      "📤 输出 Outputs": `- **项目管理计划（更新）**：定义范围过程产出的**项目范围说明书**被纳入项目管理计划，作为范围基准的核心组件之一，为制定范围结构（WBS）、确认范围和监控范围提供依据。同时，假设日志、需求文件、干系人登记册等**项目文件**也会被更新（如记录新识别的假设条件、需求细化结果、干系人对范围的确认意见）。
- **项目范围说明书的内容**：
  - **产品范围描述**：逐步细化项目章程和需求文件中所述的产品、服务或结果特征，回答"要交付什么样的东西"。
  - **可交付物**：项目必须产出的有形的（如系统、报告）和无形的（如培训、服务）成果清单。
  - **验收标准**：可交付物必须满足的一系列条件或准则，只有满足后才被客户或发起人接受，是确认范围过程的依据。
  - **项目除外责任**：明确指出项目边界之外的内容，即"本项目不做什么"，有助于管理干系人期望、防止范围蔓延。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：启发并分析需求过程的输出（需求文件、需求跟踪矩阵）是本过程的主要输入，需求定义了范围的内容基础。
- **下游衔接**：项目范围说明书输出给**制定范围结构（WBS）** 过程，范围说明书+WBS+WBS词典共同构成范围基准；范围基准是**监控范围**（评估偏差）和**确认范围**（验收可交付物）的依据。
- **与整体变更控制**：范围一旦纳入基准，任何范围变更必须通过评估与实施变更（整体变更控制）过程处理，防止范围蔓延。
- **与质量与风险**：范围说明书中的验收标准为质量管理提供依据；明确的边界有助于风险评估（识别范围相关的风险）。`,
      "✂️ 裁剪考虑": `- **预测型项目**：在项目规划早期一次性完成详细、正式的项目范围说明书，随后冻结为基准，变更须走正式变更流程。
- **适应型项目**：仅定义高层级范围描述（项目目的、目标、价值主张），具体功能在每次迭代开始时通过待办事项列表逐步细化，范围说明书以轻量形式存在。
- **混合型项目**：核心架构和稳定需求采用详细范围说明书管理，探索性部分以用户故事细化。
- **裁剪维度**：项目大小和复杂度（大型项目范围说明书更详尽）、需求确定性（不确定性高时先用高层级描述再逐步细化）、行业合规（监管行业须在范围说明书中明确合规边界）。`,
      "💼 实践案例": `某连锁酒店集团开发酒店管理系统。在定义范围时，项目经理组织业务部门、IT团队和供应商召开引导式研讨会，共同起草项目范围说明书：产品范围描述明确了系统需覆盖客房预订、入住登记、房态管理、账务结算四大模块；可交付物清单包括系统软件、操作手册、上线后的48小时驻场支持；验收标准规定预订响应时间不超过1秒、支持500间房并发操作等量化条件；项目除外责任明确写出"本系统不包含硬件采购与机房建设、不包含与第三方OTA平台的对接"。由于范围边界清晰，后续施工中当销售部门提出"增加OTA对接"时，团队依据除外责任条款将其作为新需求走正式变更流程评估，有效防止了范围蔓延。

另一案例：某互联网公司用适应型方法开发内部数据分析平台。团队仅在项目启动时编写了一页纸的高层级范围描述（目标、价值主张、不包含项），之后每个迭代开始时由产品负责人与团队共同从产品待办事项列表中选取最优先的用户故事细化范围。平台上线后再根据业务反馈通过待办事项列表持续增删功能，体现了适应型方法中范围随迭代逐步细化的特点。`,
    },
    keyConcepts: `关键术语——
- **项目范围说明书**：详细描述项目可交付物、验收标准和项目除外责任的正式文件，是WBS和范围基准的基础。
- **项目范围说明书 vs 项目章程**：章程侧重于授权和高层级信息，由发起人发布；范围说明书提供详细的范围描述，由项目经理和团队制定，两者不能混为一谈。
- **产品范围描述**：逐步细化项目章程和需求文件中所述的产品、服务或结果特征，回答"交付什么样的东西"。
- **验收标准**：可交付物必须满足的一系列条件才能被接受，是确认范围（正式验收）和监控质量的依据。
- **项目除外责任**：明确指出项目边界之外的内容（"本项目不做什么"），有助于管理干系人期望、防止范围蔓延。
- **范围基准**：经批准的项目范围说明书+WBS+WBS词典，是监控范围、控制变更的对照基准。
- **产品范围 vs 项目范围**：产品范围关注产品特性与功能；项目范围关注为交付产品而必须完成的工作。`,
    examTips: `考试重点/常见陷阱——
- **最高频考点**：项目范围说明书≠项目章程！范围说明书更详细，包含产品范围描述、可交付物、验收标准、项目除外责任四要素；章程侧重于授权和高层级信息。考试常给一个文件内容让判断"是章程还是范围说明书"。
- **高频考点：项目除外责任**——明确说明"本项目不做什么"，可以防止范围蔓延（Scope Creep）并管理干系人期望，属于范围说明书的必备内容而非可选内容。
- **验收标准的作用**——验收标准是确认范围过程（客户正式验收）的判断依据，考试常考验收标准写在哪里（答：项目范围说明书）。
- **执行时机差异**：预测型在项目开始时一次性定义详细范围；适应型在每次迭代开始时细化，考试注意"适应型范围更灵活、逐步细化"。
- **常见陷阱**：定义范围产出的范围说明书+WBS+WBS词典构成范围基准；不要把它与"定义活动"（进度域过程）混淆。
- **收益关键词**："确保干系人和项目团队理解将交付的价值"。`
  },
  "proc-develop-scope-structure": {
    overview: `在采用预测型方法的项目中，制定范围结构过程的目的是明确项目目标，并定义完成目标所需的全部可交付物。该过程以工作分解结构（WBS）为核心工具，将项目全部工作范围进行结构化、层级化的分解，形成更小、更易于管理的工作包，以便于分配、跟踪和测量，从而确保所有利益相关方对项目可交付物有清晰且一致的理解。在涉及复杂或相互依赖的可交付物的项目中，可编制WBS词典，为每个WBS组件提供更详细的信息。WBS词典通过详细说明范围描述、里程碑、责任方、资源需求和验收标准等要素，为WBS提供支持。在敏捷项目中，WBS的角色由产品待办事项列表承接，其中的工作项可以分解为史诗和用户故事。产品待办事项列表是一份优先级排序的清单，列出了已知特性和项目团队将执行的工作，并在迭代过程中持续细化。该过程的关键收益是，为项目范围和价值提供战略视角，使团队既能看到项目全貌，又能聚焦于具体的工作单元，是后续估算、进度计划编制、风险识别、资源分配和范围监控的共同基础。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：为制定范围结构提供顶层框架和授权来源。章程中包含项目目的、高层级需求、高层级项目描述、总体里程碑、总体预算和发起人信息，制定范围结构时必须确保分解出的范围与章程的高层级意图一致，不越出章程的授权范围。
- **项目管理计划**：主要提供范围管理计划（定义如何制定、验证和控制范围）、需求管理计划、项目生命周期描述和开发方法（预测型、适应型或混合型）。开发方法决定范围结构采用WBS还是产品待办事项列表，是选择分解形式的关键依据。
- **项目文件**：提供补充信息，常见包括假设日志（记录范围相关的假设条件）、风险登记册、干系人登记册、需求跟踪矩阵等，帮助团队识别分解时需要特别关注的制约因素、风险和干系人关注点。
- **需求文件**：详细记录已识别的需求和功能特性，是WBS分解的直接依据。分解时必须确保每个需求都能在WBS中找到对应的组件，避免遗漏；WBS词典中的验收标准往往直接取自需求文件。
- **事业环境因素**：包括组织文化、行业标准、项目管理信息系统（PMIS）、治理框架和授权体系等。例如某些行业有强制性的WBS标准或合同规定的报告分解层级，这些因素会限制或引导分解方式。
- **组织过程资产**：包括历史项目的WBS模板、WBS词典样例、范围分解与变更的政策程序、过往经验教训。复用经过验证的模板可以显著提高分解质量与速度，同时保持与组织内其他项目的可比性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：邀请具有WBS分解、产品架构或相关行业经验的主题专家参与，确保分解层级合理、术语一致、工作包粒度适当。专家还负责审查分解结果是否覆盖全部范围、是否符合行业惯例，避免新手团队漏项或过度分解。
- **产品分析**：将高层级的产品描述转化为有形的可交付物和功能集合，适用于以产品为导向的范围分解。常用技术包括产品分解、系统分析、系统工程、价值工程和价值分析，帮助团队回答要交付什么以及每一项的价值何在。
- **备选方案分析**：用于评估满足相同需求和范围的不同分解方式或交付方案，如模块化拆解与整体交付、外包与自建、不同的WBS层级设计等，通过比较成本、风险、可控性与价值，选择最优方案。
- **引导**：通过引导式研讨会（如联合应用设计JAD、范围分解工作坊）召集关键干系人共同完成分解。引导者保持会议中立、聚焦目标，促成不同部门、不同背景的干系人对分解结构和范围边界达成共识，尤其适用于跨职能、多干系人的项目。`,
      "📤 输出 Outputs": `- **项目范围说明书**：对项目范围的详细描述，是干系人之间关于做什么、不做什么的书面共识。内容包括产品范围描述、可交付物清单、验收标准、项目除外责任（明确不在范围内的工作）、制约条件和假设条件。它是制定WBS和后续范围验收的基础，也是范围基准的重要组成部分。
- **项目文件更新**：主要包括工作分解结构（WBS）和WBS词典——WBS将项目可交付物和工作细分为更小、更易管理的组件的层级化分解，其最低层是工作包；WBS词典为每个WBS组件提供范围描述、可交付物、验收标准、里程碑、责任方和资源需求等详细信息，两者与项目范围说明书共同构成范围基准。此外还更新假设日志、需求文件、干系人登记册和经验教训登记册，记录分解过程中的新信息与决策依据。`,
      "🔗 与其他过程的相互作用": `本过程位于规划工作流的中间环节，向上承接制定项目章程（提供授权与高层级意图）、收集需求和定义范围（提供详细需求与范围高层级描述），向下为后续几乎所有规划过程奠定基础。工作包是估算成本、制定进度计划（将工作包进一步分解为活动）、识别风险、分配资源和确定里程碑的依据；WBS与控制账户的设置是挣值管理的基础，使绩效测量成为可能。在预测型项目中，批准后的项目范围说明书、WBS和WBS词典构成范围基准，作为监控范围和确认范围时进行偏差分析与验收对照的基线。在适应型项目中，本过程对应的产品待办事项列表持续被整理、细化并重新排序，与规划迭代、指导工作和交付价值等过程相互交织。此外，WBS词典中的验收标准直接服务于后续的确认范围过程，实现分解时定义验收标准、交付时据此验收的闭环。`,
      "✂️ 裁剪考虑": `- **预测型项目**：通常一次性建立完整的WBS和WBS词典，层级清晰、工作包粒度一致，范围说明书详尽，范围基准严格控制。
- **适应型（敏捷）项目**：以产品待办事项列表替代WBS，工作项按史诗、特性、用户故事逐层细化，采用滚动式规划，仅在即将开始的迭代前细化到故事级，不追求一次性完整分解。
- **混合型项目**：对需求稳定、可预测的部分建立正式WBS，对不确定的部分采用待办事项列表并随迭代推进逐步明确。
- **项目规模与复杂度**：小项目可用一页纸的简单WBS甚至直接列出工作包清单；大型复杂项目需要增加层级、编制详细WBS词典并设置控制账户。WBS的分解深度也受预算、报告层级和合同要求的影响。
- **不确定性**：高度创新或需求易变时，避免过度分解，采用滚动式规划保留弹性，防止因需求变化而频繁返工。`,
      "💼 实践案例": `某银行实施新一代核心系统升级项目。收集需求并定义范围后，团队召开引导式工作坊，邀请业务、开发、运维和数据迁移专家，将范围按可交付物分解为需求评审、系统设计、核心模块开发（账户、支付、风控）、系统集成、测试（单元、集成、用户验收）、数据迁移、部署上线、培训与文档等若干控制账户。每个控制账户下再分解为工作包，例如数据迁移控制账户下包括源数据分析、迁移脚本开发、影子验证、正式迁移等工作包，每个工作包规模控制在8-80小时。对于数据迁移这一相互依赖的复杂可交付物，单独编制WBS词典，逐项说明范围描述、验收标准（如数据一致性达到99.99%）、责任方和里程碑。项目执行阶段，团队依据WBS跟踪各工作包完成情况，挣值分析得以顺利开展；上线前，按WBS词典中的验收标准对可交付物逐项确认。在敏捷变体中，则按支付、账户、报表等功能将待办事项列表划分为史诗，再拆分为用户故事并排序，随迭代逐步交付。`,
    },
    keyConcepts: `关键术语——
- **工作分解结构（WBS）**：将项目可交付物和项目工作细分为更小、更易管理的组件的层级化分解，是可交付物导向的（用名词描述），而非活动导向。
- **WBS词典**：为每个WBS组件提供详细信息的文件，包括范围描述、可交付物、验收标准、里程碑、责任方和资源需求等。
- **工作包（Work Package）**：WBS最低层级的工作单元，是可以可靠估算进度、成本并分配责任的最小单元；工作包还需进一步分解为活动，才能编制进度计划。
- **控制账户（Control Account）**：位于工作包之上、WBS中间的管控点，用于整合成本、进度和范围绩效以进行挣值管理；一个控制账户可包含多个工作包，而每个工作包只属于一个控制账户。
- **8-80规则**：经验法则，建议工作包的规模（所需工时）在8小时至80小时（约1-2周）之间，过小则过细、过大则难以管理。
- **100%原则**：WBS必须包含完成项目所需的全部工作，且下层组件的总和必须等于上层组件的100%，不得遗漏也不得多余。
- **滚动式规划**：详细规划近期工作，远期工作在更接近时再细化，适合需求不确定的环境。
- **产品待办事项列表（Product Backlog）**：适应型方法中按优先级排序的工作项清单，其中的史诗可进一步拆分为用户故事，与WBS的分解思路对应。
- **范围基准（Scope Baseline）**：由批准的项目范围说明书、WBS和WBS词典构成，是监控范围与确认范围的对照基线。`,
    examTips: `考试重点/常见陷阱——
- WBS的最底层是工作包（Work Package），不是活动；活动是制定进度计划时将工作包进一步分解的产物。
- 100%原则是高频考点：WBS下层之和必须等于上层的100%，既不能遗漏，也不能包含范围外的工作。
- 控制账户与工作包的区别常考：控制账户是管理控制点，位于工作包之上；每个工作包只属于一个控制账户，一个控制账户可含多个工作包。
- 8-80规则：工作包规模约8-80小时；类似表述还有按两周分解。
- WBS是可交付物导向（名词），不是活动导向（动词），也不是按组织结构划分——不要用WBS描述流程顺序。
- 制定范围结构不仅输出范围说明书，还产出WBS与WBS词典，三者共同构成范围基准。
- 敏捷场景中，产品待办事项列表对应WBS的角色，史诗和用户故事对应分解层级。
- 常见陷阱：把WBS画成组织机构图或流程图；遗漏某个可交付物而违反100%原则；把活动写进WBS。`
  },
  "proc-monitor-scope": {
    overview: `监控范围是一个持续进行的过程，用于监督和管理项目范围的变更，并测量可交付物的质量和价值，以确保其满足质量标准。该过程负责控制对详细项目范围说明书的变更请求的处理方式，同时确保可交付物满足规定的质量要求，以及范围和质量均与范围基准保持一致。管理和控制范围的主要目标是，确保产品、服务或结果与利益相关方相关，能为利益相关方交付价值，并满足利益相关方规定的需求。该过程涉及对导致范围变更的因素施加影响，确保所有变更请求都通过评估与实施变更过程（整体变更控制）进行处理，并在实际变更发生时进行管理。范围蔓延是指未经控制的项目或产品范围扩大，而未对时间、成本和资源进行相应调整；镀金是指主动添加超出需求的额外功能或特性。这两种现象都会消耗资源、延长工期且不增加经批准的价值，都应通过有效的范围监控加以防止。该过程的关键收益是，使范围变更得到正式控制，确保范围绩效始终透明、与基准一致，为后续的确认范围和结束项目阶段提供可靠的范围状态依据。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：提供监控所需的基准与规则，主要是范围管理计划（规定如何监控范围、设定控制临界值）和范围基准（项目范围说明书、WBS、WBS词典），作为偏差分析的比较对象；变更管理计划和配置管理计划则规定变更如何被评估、批准与记录。
- **项目文件**：包括需求文件、需求跟踪矩阵、里程碑清单、假设日志、干系人登记册等，帮助团队判断变更对需求、里程碑和干系人的影响，追踪每项需求是否被交付。
- **工作绩效数据**：来自执行过程的原始观测数据，如已完成的工作百分比、已开始与未开始的工作项、完成的可交付物数量、实际里程碑达成情况等。它是偏差分析、趋势分析的原料，本身未经整合处理。
- **组织过程资产**：包括范围变更控制政策与程序、变更控制委员会章程、监控报告模板、历史项目的范围绩效数据与经验教训，用于规范监控动作并使报告口径与组织惯例一致。`,
      "🔧 工具与技术 Tools": `- **偏差分析**：将实际范围绩效（已完成工作、实际交付的百分比等）与范围基准逐项比较，计算偏差的大小并分析其成因。偏差分析回答当前范围与计划差多少、为什么差，其结果将决定是否需要提交变更请求或采取纠正、预防措施；它还可用于评估变更请求对范围的影响。
- **趋势分析**：按时间序列检查范围绩效数据的变化模式，如连续数周的完成百分比偏差是否在扩大，据此预测未来可能出现的偏差，从而提前采取措施。趋势分析强调方向，比单点偏差更具前瞻性，常用于早期预警范围蔓延。若数据显示偏差持续扩大而基准不变，通常意味着发生了范围蔓延或绩效劣化，需立即调查并介入。`,
      "📤 输出 Outputs": `- **工作绩效信息**：将原始绩效数据与范围基准比较后得到的整合信息，如各项可交付物的完成状态、与基准的偏差量及原因、变更请求的影响评估结果，是编制绩效报告和供管理层决策的基础。
- **变更请求**：当偏差超出临界值、范围基准需要调整或发现缺陷时提出，类型包括纠正措施、预防措施、缺陷补救和计划内变更。所有变更请求都必须提交评估与实施变更过程（整体变更控制）处理，经批准后才能影响范围基准。
- **项目管理计划更新**：主要是范围基准的更新——只有经整体变更控制批准的变更才能修订范围基准（更新WBS、WBS词典或范围说明书），同时可能更新范围管理计划以调整监控方式、控制临界值等。
- **项目文件更新**：包括需求文件、需求跟踪矩阵（标记新增、删除或变更的需求及交付状态）、假设日志、经验教训登记册等，记录监控过程中获得的新信息和教训。`,
      "🔗 与其他过程的相互作用": `监控范围处于执行与监控交界的环节。它从制定范围结构等规划过程获得范围基准，从指导项目工作和交付价值等执行过程获得工作绩效数据，再通过偏差分析和趋势分析将数据转化为工作绩效信息，供监控项目绩效等过程汇总为绩效报告。当发现偏差需要调整范围时，监控范围提出变更请求，交由评估与实施变更过程（整体变更控制）统一审批；只有经批准的变更才能更新范围基准，形成新的比较基线。监控范围关注范围是否按基准受控、变更是否被正式管理，而确认范围关注可交付物是否被客户或发起人正式验收，两者一个控制变更、一个验证成果，分工互补。控制质量保证做对了（正确性），监控范围保证按需做（范围受控），两者都服务于交付价值的目标。监控范围还为结束项目或阶段提供范围状态信息。`,
      "✂️ 裁剪考虑": `- **预测型项目**：范围基准正式且严格控制，变更必须走完整变更控制流程，偏差分析通常在里程碑或定期（如每周或每月）进行，控制临界值在范围管理计划中明确设定。
- **适应型（敏捷）项目**：范围通过产品待办事项列表持续演化和重新排序，变更多表现为优先级调整而非正式基准修订；监控以价值交付和完工指标（如燃尽图、已完成用户故事数）为主，减少流程化文书。
- **混合型项目**：对稳定部分采用正式基准与变更控制，对敏捷部分允许待办事项的持续调整，并定义两者的交接规则。
- **项目规模与风险**：高风险、高合规要求项目收紧临界值和变更审批层级；低风险内部项目可简化审批环节，但仍需保留范围变更的记录与追溯。`,
      "💼 实践案例": `某市政道路建设项目的范围基准为5公里道路、3座桥梁和附属绿化。执行中，监控范围发现第2座桥梁实际完成进度较基准超出20%，经偏差分析确认，原因是现场技术员应施工方口头要求增加了引道拓宽内容，未提交任何变更请求——典型的范围蔓延。团队立即将该变更正式化，提交整体变更控制评估，确认增加预算与工期后批准，并更新范围基准。同时，趋势分析显示过去三周范围偏差持续扩大，团队判断现有审批流程存在漏洞，随即采取预防措施：加强变更请求培训、在周例会上强调超出合同范围的工作一律先走变更；并将施工方未经授权自行采购高档装饰材料的镀金行为及时纠正，避免成本虚增。经过整改，范围偏差回落至临界值以内，项目按基准恢复受控状态。`,
    },
    keyConcepts: `关键术语——
- **范围蔓延（Scope Creep）**：未经控制的项目或产品范围逐渐扩大，往往是许多小的、未获批准的变更累积而成，却未相应调整时间、成本和资源。
- **镀金（Gold Plating）**：团队主动添加超出需求的额外功能或特性，未经过变更控制；通常源于想做得更好的心态，但违背只做被批准工作的原则。
- **偏差分析（Variance Analysis）**：将实际绩效与范围基准比较，确定偏差大小与原因。
- **趋势分析（Trend Analysis）**：分析绩效数据随时间的变化模式，预测未来偏差，实现早期预警。
- **范围基准（Scope Baseline）**：批准的WBS、WBS词典与项目范围说明书的集合，是偏差分析、绩效测量的基线。
- **工作绩效数据 vs 工作绩效信息**：数据是执行过程的原始观测值；信息是将数据与基准比较、整合后的结果。
- **整体变更控制 / 变更控制委员会（CCB）**：评估并决定变更请求是否获批的机制与组织；范围基准变更必须经过此环节。`,
    examTips: `考试重点/常见陷阱——
- 范围蔓延＝未经控制的变更（多为外部需求悄悄累积）；镀金＝主动添加超出需求的功能（团队内部行为）。两者均违背聚焦于价值的原则，是高频辨析点。
- 只有经整体变更控制批准的变更，才能更新范围基准；未经批准的变更不得改变基准，这正是监控的意义。
- 偏差分析＝与基准对比找差距；趋势分析＝随时间走势做预测。二者工具归属常考。
- 工作绩效数据是原始数据，工作绩效信息是比较后的信息，注意措辞区分。
- 变更请求的类型常考：纠正措施（修正已出现的偏差）、预防措施（防止偏差发生）、缺陷补救（修复不合格交付物）、计划内变更（调整基准或计划的正式变更）。
- 监控范围与确认范围的区别：监控范围管变更控制，确认范围管正式验收。
- 监控范围是持续进行的过程，而非阶段性的单次活动。
- 常见陷阱：把镀金当成干系人要求的额外功能；把范围蔓延等同于已批准的变更；混淆偏差分析与趋势分析的作用。`
  },
  "proc-validate-scope": {
    overview: `确认范围过程有两个主要目标：一是检查用于达成质量标准的过程，二是正式验收可交付物。该过程有助于确保可交付物符合既定的质量标准，并获得利益相关方的正式验收。该过程的关键收益是，通过客观的过程来确认范围，以保障所交付产品、服务或结果的价值和质量，同时提高所交付产品、服务或结果被接受的概率。确认范围通常由客户或发起人代表项目团队之外的利益相关方执行，他们在对照项目范围说明书和验收标准、检查实际可交付物后，作出接受或拒绝的正式决定。确认范围与控制质量的过程顺序非常重要：通常先执行控制质量（内部检查可交付物是否正确、是否符合质量要求），再执行确认范围（由客户或发起人正式验收可交付物）。因此，确认范围的输入包括核实的可交付物——即已经过控制质量过程验证的可交付物。该过程的输出包括验收的可交付物，即由客户或发起人正式签署接受的可交付物，它也是结束项目或阶段过程的关键输入。在适应型方法中，确认范围通常在每个迭代或冲刺末的评审中反复进行，干系人基于增量交付物持续反馈并确认。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：提供验收的依据与程序，主要是范围管理计划（定义如何验证和确认范围、由谁验收、验收标准如何建立）、需求管理计划以及范围基准（项目范围说明书中的可交付物清单与验收标准、WBS、WBS词典）。
- **项目文件**：包括需求文件、需求跟踪矩阵（用于逐项核对每项需求是否被交付并验收）、里程碑清单、假设日志等，帮助验收人员判断可交付物是否完整覆盖需求。
- **核实的可交付物**：已经过控制质量过程验证、确认符合质量要求与验收标准的可交付物，是确认范围的直接审查对象；它体现先控制质量、再确认范围的顺序。
- **工作绩效数据**：可交付物完成情况、验收测试结果等原始观测数据，用于支持验收过程中的核对与判断。`,
      "🔧 工具与技术 Tools": `- **检查（Inspection）**：对可交付物进行审查、测量和测试，以确认其符合验收标准。常用形式包括评审、同行评审、审计和走查，可结合检查表逐项核对。检查可用于早期发现偏差和预防缺陷，是确认范围的核心手段；它也可以叫作审查、产品评审或测试，具体名称随行业和项目而异。
- **决策（Decision Making）**：由干系人基于检查结果决定可交付物是否被接受。决策技术包括投票（一致同意、大多数同意或相对多数同意）和独裁决策（由单一权威干系人作最终判断）。确认范围中的决策通常体现为客户或发起人正式签署验收，或提出需要返工的意见。`,
      "📤 输出 Outputs": `- **验收的可交付物（Accepted Deliverables）**：由客户或发起人正式签署接受的可交付物，是确认范围的标志性输出，也是结束项目或阶段过程的关键输入；只有验收的可交付物才能交付给客户并进入收尾。
- **工作绩效信息**：反映可交付物验收状态的信息，如哪些可交付物已验收、哪些未通过验收、验收过程中发现的偏差与返工需求，供绩效报告和后续决策使用。
- **变更请求**：当可交付物未通过验收时，通常提出缺陷补救型变更请求（返工），也可能因验收过程中发现范围偏差而提出纠正措施或计划内变更，所有变更请求都需经整体变更控制处理。
- **项目管理计划更新**：如验收过程中发现验收标准或范围基准描述不清晰而需要澄清时，可能更新范围管理计划、需求管理计划等子计划，但此类更新须经变更控制。
- **项目文件更新**：主要是需求跟踪矩阵（将验收的可交付物对应的需求标记为已验收）、经验教训登记册（记录验收中的经验教训）、干系人登记册等。`,
      "🔗 与其他过程的相互作用": `确认范围处于做与收的关键衔接点。其上游是控制质量——控制质量先从内部验证可交付物的正确性，输出核实的可交付物，确认范围再据此对外正式验收，两者顺序不可颠倒；若未经内部验证便交给客户验收，往往导致返工和信任损失。制定范围结构提供了验收标准与范围基准，是验收的对照依据。确认范围的输出——验收的可交付物——直接输入结束项目或阶段过程，是项目能否正式收尾的前提；未验收的可交付物则触发变更请求，回到整体变更控制流程。确认范围与监控范围分工互补：监控范围管理范围变更并维持范围与基准一致，确认范围则验证最终成果是否满足需求。此外，确认范围产生的验收反馈（如需求变更、验收标准澄清）会回传至收集需求、定义范围和制定范围结构等规划过程，推动范围与需求的迭代完善。在采购场景中，对供应商交付物的确认范围与控制采购过程紧密配合。`,
      "✂️ 裁剪考虑": `- **预测型项目**：通常在阶段末或项目全部完成时进行正式验收，由客户或发起人对照合同和验收标准逐项检查并签署验收文件，验收活动正式、程序化。
- **适应型（敏捷）项目**：在每个冲刺末的评审（Sprint Review）中确认范围，干系人观看增量演示、给出反馈并确认已完成的功能；验收标准内嵌于用户故事，验收频繁、反馈即时，几乎不产生正式基准变更。
- **混合型项目**：迭代内频繁确认可交付物，阶段末进行正式验收，两者并存。
- **项目规模与干系人**：大规模、多干系人项目可分层验收（如模块级、系统级、整体验收）；关键设备、合规类项目需邀请独立第三方或监管机构参与验收。验收频率和正式程度需与风险、合同要求和干系人期望相平衡。`,
      "💼 实践案例": `某软件公司为制造企业开发一套ERP系统，合同约定项目范围覆盖财务、采购、库存与生产四大模块。开发团队完成财务模块后，先由内部测试团队执行控制质量：单元测试、代码评审和系统集成测试全部通过，确认无误后，将核实的可交付物连同需求跟踪矩阵提交给客户进行用户验收测试（UAT）。客户在确认范围阶段执行检查，逐项核对验收标准，发现供应商对账单自动对账功能未按需求实现，随即拒绝签署该可交付物。团队据此提出缺陷补救变更请求，经批准后返工重新开发，再次通过内部质量验证后，客户重新检查并最终在验收单上签字，形成验收的可交付物。所有模块验收通过后，项目进入结束项目或阶段过程，验收的可交付物与移交文档一并交付客户。整个过程中，先控制质量、再确认范围的顺序有效避免了把质量问题推到客户验收环节而造成的返工浪费。`,
    },
    keyConcepts: `关键术语——
- **确认范围（Validate Scope）**：由客户或发起人正式验收已完成的可交付物的过程，重点是验收。
- **控制质量（Control Quality）**：内部检查可交付物是否符合质量要求的工程性活动，重点是正确性。
- **核实的可交付物（Verified Deliverables）**：已通过控制质量验证的可交付物，是确认范围的输入。
- **验收的可交付物（Accepted Deliverables）**：经客户或发起人正式签署接受的可交付物，是确认范围的输出、结束项目或阶段过程的输入。
- **检查（Inspection）**：通过审查、测量、测试确认可交付物符合验收标准的工具，形式包括评审、同行评审、审计、走查等。
- **决策（Decision Making）**：用投票（一致同意、多数同意、相对多数同意）或独裁方式决定可交付物是否被接受。
- **用户验收测试（UAT）**：客户在交付前对系统功能进行核实的常见验收形式。
- **冲刺评审（Sprint Review）**：敏捷方法中在每个冲刺末确认范围、获取干系人反馈的环节。`,
    examTips: `考试重点/常见陷阱——
- 顺序高频考点：先控制质量（内部验证正确性），再确认范围（客户正式验收），两者不可颠倒。
- 输入输出对应关系常考：核实的可交付物＝控制质量的输出＝确认范围的输入；验收的可交付物＝确认范围的输出＝结束项目或阶段过程的输入。
- 工具常考：确认范围用检查＋决策，而不是偏差分析；注意与监控范围（偏差分析＋趋势分析）区分。
- 确认范围可由客户、发起人或其授权的干系人执行；未经正式验收不得结束项目或阶段。
- 验收不通过时，输出缺陷补救型变更请求（返工），而非直接修改基准。
- 敏捷中冲刺评审相当于确认范围，验收标准通常写在用户故事中。
- 常见陷阱：混淆确认范围与控制质量；误把验收当作团队内部自检；忽略验收的可交付物在收尾环节的关键作用。`
  },
  "proc-plan-schedule-mgmt": {
    overview: `【过程概述】规划进度管理是项目进度管理领域的第一个过程，旨在为设计、制订、管理、执行和维护项目进度计划而建立政策、程序和文档。该过程的关键收益是：在整个项目期间，为如何管理项目进度提供明确的指导和方向，避免"凭感觉排进度、排完就失控"的混乱状态。

本过程的执行频率通常是：在项目早期开展一次，当项目发生重大变更（如开发方法切换、范围重大调整、关键约束变化）时，可在项目预定义的时间点按需重新开展。需要特别强调的是，本过程并不负责"排出具体日期"，而是先"定规矩"：它决定后续用哪种进度模型方法（关键路径法 CPM、关键链法 CCM，还是敏捷迭代方法）、以什么计量单位与精度等级计量时间、允许进度偏差大到什么程度才触发处理（控制临界值）、用什么规则测量绩效、如何维护和更新进度计划、以什么格式向谁报告进度。

该过程的具体输出是进度管理计划。该计划通常包括：项目进度计划的制订、发布与迭代的时长、精度等级、计量单位、与组织程序的关联、项目进度计划的维护要求、控制临界值、绩效测量规则、报告格式等信息；同时定义了使用哪些进度规划方法与工具（如 CPM、CCM 或敏捷方法），以及进度模型的建立与迭代方式。

进度管理计划是项目管理计划的子计划之一，为"制订进度计划"和"监控进度"两个后续过程提供指导和框架。应根据项目的特点（规模、复杂度、行业）、组织文化和所选开发方法（预测型、适应型、混合型）对本过程及其产出进行裁剪。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：由发起人发布、正式授权项目的文件，其中包含高层级的总体里程碑和约束期限（如"18 个月内上线"）。它是确定时间单位、精度等级和进度模型方法的顶层约束来源；章程中的假设与制约因素（如固定完工日期、法定交付窗口）会直接写入进度管理计划或假设日志。
- **项目管理计划**：主要使用其中的范围管理计划（界定范围如何定义与控制）和开发方法（预测型、适应型、混合型的选择），据此确定进度模型方法。例如：选择预测型时，进度管理计划要求完整定义活动并建立关键路径；选择适应型时，则按迭代与待办事项列表组织进度，进度管理计划相应简化。
- **事业环境因素（EEF）**：包括组织文化、组织结构、组织可用的进度规划软件与工具（如 Microsoft Project、Jira、看板工具）、行业标准、组织与财务日历（可工作时段、财政年度）、资源可用性与能力等。这些是"外部客观存在"的条件，直接限制进度管理计划的可行方案，例如工具不支持某方法就只能调整。
- **组织过程资产（OPA）**：包括历史进度信息与项目档案、进度规划方法模板与政策、进度管理计划模板、控制临界值标准、进度报告格式、组织的正式与非正式程序（如发布流程、变更审批惯例）等，供本过程参考与复用，避免从零摸索。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助具备进度规划专长的人——有经验的项目经理、进度计划编制专员、行业顾问、相关干系人——针对进度管理计划的各要素（方法选择、计量单位、精度等级、临界值设定、报告频率）提供专业判断和权衡建议，减少个人拍板的偏差。例如请资深工程师判断某类设备安装的合理时间单位与精度。
- **数据分析**：本过程主要使用"备选方案分析"，即系统比较不同进度规划方法的优劣。在预测型（关键路径法/关键链法）、适应型（Scrum 迭代、看板）和混合型之间权衡，评估各自对项目性质、干系人期望和组织能力的适配度，选出最合适的方法并写入计划。例如：客户要求固定交付日期且需求明确，宜选预测型并配关键路径法；需求模糊且快速迭代的环境，则宜选适应型并以迭代时长组织进度。
- **会议**：召开规划会议，把编制进度管理计划所需的关键干系人召集起来（如项目经理、发起人、主要团队成员、进度专员、职能经理代表），共同确定方法、工具、计量单位、精度、临界值和报告格式，形成各方一致认可、后续可执行的进度管理框架。会议通常在项目启动阶段、整体项目管理计划编制期间举行，必要时分多次完成，并在会后将决议正式记录进计划。`,
      "📤 输出 Outputs": `- **进度管理计划**：项目管理计划的子计划，是"管理进度的总纲"。通常包含：进度模型制定的方法（用 CPM、CCM 还是迭代方法，以及用什么软件建模与迭代频率）；时间单位（小时、天、周等）；精度等级（如建筑项目按天、高复杂度研发按小时或按迭代）；发布与迭代的时长；与控制账户、组织程序的关联；进度计划的维护规则（何时、由谁更新）；控制临界值（如允许偏差 ±5%）；绩效测量规则（用挣值 SV/SPI，还是其他指标及其计算口径）；报告格式（频率、受众、粒度）。该计划本身不包含具体日期，它只规定"怎么管进度"。`,
      "🔗 与其他过程的相互作用": `本过程是进度管理知识领域的起点，向下游两个过程提供"操作手册"：它为"制订进度计划"确定方法与工具（用什么算关键路径、用什么软件建模、精度到何种程度），为"监控进度"确定控制临界值、绩效测量规则与报告格式。向上游，它依赖"制定项目章程"给出的总体工期约束，以及"制定项目管理计划"中对范围与开发方法的决定；项目范围的界定与 WBS 的完成会反过来影响进度管理计划的细节。当项目在开发方法或重大约束上发生变化时，本过程需要重新开展，对进度管理计划的更新须经由整体变更控制批准。此外，进度管理计划中定义的绩效测量规则与成本管理计划中的挣值规则应保持计量口径一致（如都按挣值法并采用相同的报告周期），二者共同支撑后续对进度与成本的一体化监控。`,
      "✂️ 裁剪考虑": `- **预测型项目**：进度管理计划应强调完整的活动网络、关键路径法/关键链法、明确的里程碑精度与较严格的临界值；报告频率可以较低，但数据要求完整、可追溯。
- **适应型（敏捷）项目**：进度管理计划大幅简化，重点定义迭代时长、发布节奏、待办事项列表的管理方式，以及燃尽图/看板等可视化工具的使用，几乎不定义关键路径。
- **混合型项目**：通常分层处理——交付层按敏捷迭代管理，整体里程碑层按预测型关键里程碑管理，进度管理计划需同时规定两套规则及其衔接。
- **行业与规模因素**：大型建筑工程精度到"天"、资源约束强、需考虑天气日历；小型软件项目可能以"周"或"迭代"为单位。组织既有的报告制度、工具与治理结构决定了格式裁剪的方向。`,
      "💼 实践案例": `某银行核心系统升级项目（预测型，合同约定 12 个月内上线，逾期有罚金）。项目经理在规划阶段召开进度规划会议，与发起人、IT 架构师和采购专员共同决定：采用关键路径法并以 Microsoft Project 建模；时间单位精确到"天"，精度等级为"天"，里程碑精度为"周"；控制临界值设为 ±5%（关键路径活动延误超过 5% 须启动变更）；绩效测量采用挣值 SV/SPI 并按周报告给管理层。该计划为后续制订与监控进度提供了明确标尺。三个月后，关键路径上的"接口开发"延误达到 6%，触发了临界值并启动变更评估，团队及时调整资源并压缩后续活动，避免了逾期罚金风险。若没有预先设定的临界值，这次延误很可能被拖到无法挽回时才被发现。`,
    },
    keyConcepts: `- **进度管理计划**：定义进度模型的开发方法（CPM/CCM/敏捷）、时间单位、精度等级、控制临界值、绩效测量规则、报告格式的"管理进度总纲"，是制订进度计划和监控进度的依据，本身不含具体日期。
- **时间单位**：进度中用于计量活动持续时间的粒度（小时、天、周、迭代），其选择受项目类型、精度等级与报告粒度影响。
- **精度等级**：活动持续时间估算允许的舍入程度，如"到天"或"±10%"，影响数据采集与报告的可信度。
- **控制临界值**：进度偏差超过该阈值即需采取行动的界限，如 SPI < 0.95 或关键活动延误超 5% 时触发偏差分析与变更。
- **绩效测量规则**：定义用哪种挣值法、哪些指标（SV/SPI 等）以及如何计算和汇总进度绩效。
- **控制账户**：范围基准中的管理控制点，进度与成本在该层面汇总测量，进度管理计划需说明与控制账户的关联方式。
- **进度模型**：结合活动、依赖关系、持续时间和资源等信息来生成项目进度计划的工具/方法，如关键路径法、关键链法等。
- **开发方法**：预测型、适应型或混合型，决定进度模型的形态（完整活动网络 vs 迭代待办列表）。`,
    examTips: `- **区分三个易混概念**：进度管理计划（"怎么管进度"的规矩，不含日期）、项目进度计划（具体的日期安排）、进度基准（经批准的进度计划，是监控的比较基线）。考试常考这三者的区分。
- **进度管理计划的内容清单**：时间单位、精度等级、控制临界值、绩效测量规则、报告格式、发布与迭代时长是高频考点；注意"进度管理计划不含具体日期"。
- **执行频率**：规划进度管理通常在项目早期执行一次，可在预定义时间点按需更新——不是每天/每周都做，也不要在每次进度评审时重写。
- **数据流向链条**：章程给总约束 → 规划进度管理出进度管理计划 → 制订进度计划按其方法与工具产出进度/基准 → 监控进度按临界值与规则衡量偏差并触发变更。理清这条链，场景题才能选对过程。
- **裁剪差异**：敏捷项目的进度管理计划强调迭代时长、发布节奏与可视化工具，不强调关键路径；不要用预测型套路的完整网络去套敏捷场景。
- **EEF vs OPA**：两者都是本过程输入，注意区分——事业环境因素是"外部客观条件"（工具、日历、组织文化、财政年度），组织过程资产是"组织历史积累"（模板、政策、历史数据、报告格式）。`
  },
  "proc-develop-schedule": {
    overview: `【过程概述】制订进度计划是进度管理的核心过程，旨在分析活动顺序、持续时间、资源需求和进度制约因素，以创建用于项目执行和监控的进度模型。制订可接受的项目进度计划是一个迭代过程——随着数据更准确、细节更深入，计划会被反复调整直至可接受。进度模型用于根据现有的最佳信息，确定项目活动和里程碑的计划开始与完成日期。

制订进度计划通常包括四个步骤：步骤1——定义活动：识别并记录为产出项目可交付物而需执行的具体行动，将工作包分解为进度活动。步骤2——确定顺序：确定进度要素之间的依赖关系和关联（完成到开始、开始到开始、完成到完成、开始到完成四种逻辑关系），定义能够实现最高效率的工作逻辑顺序。步骤3——估算投入和持续时间：确定使用已估算的资源来完成单项活动所需的工作周期数，可以使用专家判断、类比估算、参数估算、三点估算（PERT）、自下而上估算、计划扑克、故事点等技术。步骤4——调整：根据前几步确定的活动顺序、估算和资源审查进度计划草案，必要时进行资源平衡和资源优化，使计划既可行又符合目标。

在估算持续时间和编排进度时，需要特别考虑：边际收益递减规律（加倍资源不会使工期减半）、资源数量增加不一定等比减少时间（协调成本上升）、技术进步的影响（新工具可能缩短时间）、认知偏差（乐观偏差、锚定效应会扭曲估算）等因素。本过程是考试的重中之重，其中关键路径法（CPM）、关键链法（CCM）、进度压缩、提前量/滞后量等是必考核心。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：主要使用"进度管理计划"（提供方法、工具、精度、临界值等规则）和"范围基准"（范围说明书、WBS、WBS 词典），界定需要排进进度的活动边界与工作包，防止范围外工作混入进度。
- **项目文件**：本过程使用大量项目文件，逐个理解：
  - **活动清单**：列出全部进度活动及其唯一标识，是排程的基本单元来源。
  - **活动属性**：描述每项活动的时间约束、前置条件、负责人、资源、允许浮动等信息。
  - **里程碑清单**：里程碑是持续时间为零的时点活动，常作为进度计划的锚点与对外承诺点。
  - **项目进度网络图**：以 PDM 形式展示活动之间逻辑关系的图形，是执行网络分析的基础。
  - **活动资源需求**：每项活动所需资源的种类与数量，决定活动能否按期开始。
  - **资源分解结构（RBS）**：按类别与层级汇总资源需求，便于识别资源负荷与缺口。
  - **活动持续时间估算**：来自"估算活动持续时间"过程，是排程的基本输入。
  - **估算依据**：支撑估算的假设、数据来源与说明，排程冲突时用于追溯。
  - **假设日志**：记录影响进度的假设与制约因素（资源到位时间、外部交付、验收窗口）。
  - **风险登记册**：识别出的进度风险及其应对策略，影响缓冲的预留。
  - **经验教训登记册**：以往项目的进度经验，帮助避免重蹈覆辙。
  - **项目团队派工单**：明确活动责任人，排程时确保人员能力与可用时间匹配。
  - **资源日历**：资源何时可用、可用多少，直接决定活动能否按最早日期排入。
- **协议（Agreements）**：合同或采购协议中规定的交付里程碑、交货期限与供应商义务，约束分包活动的排期；供应商能力与承诺直接影响外购活动（如设备到货）的持续时间。
- **事业环境因素（EEF）**：组织日历（公司可工作时段、节假日）、资源可用性、发布/交付平台节奏（如固定的月度软件发布窗口）、组织可用的进度管理信息系统等。
- **组织过程资产（OPA）**：进度规划方法政策、进度模板、历史项目进度数据与绩效、进度工具的既有配置等。`,
      "🔧 工具与技术 Tools": `- **进度网络分析（Schedule Network Analysis）**：一项综合技术，把活动顺序、依赖关系、持续时间与资源综合起来，通过前推/后推法计算每项活动的最早开始/结束、最晚开始/结束和浮动时间，是所有网络技术的"总调度台"，也是 CPM 计算的载体。
- **关键路径法（CPM, Critical Path Method）**：本过程最核心的工具，需彻底掌握。**前推法（Forward Pass）**：从网络起点开始向终点推进，每项活动 ES 取全部紧前活动 EF 的最大值，EF = ES + 持续时间（DU），最后一个活动的 EF 即项目最短工期。**后推法（Backward Pass）**：从网络终点向起点推进，每项活动 LF 取全部紧后活动 LS 的最小值，LS = LF - DU。**总浮动（Total Float）= LS - ES = LF - EF**，衡量"不影响项目完工日期"的机动时间；**自由浮动（Free Float）= 紧后活动 ES 的最小值 - 本活动 EF**，衡量"不影响紧后活动最早开始"的机动时间，自由浮动永远不大于总浮动。总浮动最小（通常为 0）的活动构成关键路径，其长度决定项目最短工期。注意：关键路径可能不止一条（多条关键路径时，任一关键活动延误都会推后整个项目）；关键路径可能漂移（非关键活动延误超过其总浮动后，会升级为关键活动）。
- **关键链法（CCM, Critical Chain Method）**：基于约束理论的进度方法，把资源约束与依赖关系同时纳入网络。其核心理念是：各活动按"50% 概率完工"的激进估算（而非悲观保险估算）排程，将省出的时间集中起来形成缓冲，整体保护完工日期。三种缓冲：**项目缓冲（Project Buffer）**放在整条关键链末端，吸收关键链上活动的综合延误，保护项目完工日期；**汇入缓冲（Feeding Buffer）**放在非关键链汇入关键链的交汇处，保护关键链不被非关键链的延误侵蚀；**资源缓冲（Resource Buffer）**不是时间储备，而是"预警信号"，提醒资源在关键链活动开始前做好切换准备，避免关键链因资源未就位而中断。CCM 通过监控缓冲消耗率来判断项目健康状况并决定干预时机。
- **资源优化（Resource Optimization）**：当资源超负荷或受限时调整活动排期。**资源平衡（Resource Leveling）**：在资源可用量或数量约束下调整活动开始时间，可能改变关键路径、延长项目工期，用于资源不足/超负荷的场景。**资源平滑（Resource Smoothing）**：只在活动的总浮动时间窗内平移活动，不改变关键路径与完工日期，用于满足资源数量约束。辨析要点：平衡可能动关键路径、延长工期；平滑不会。
- **数据分析**：包括**假设情景分析（What-if Scenario Analysis）**——评估"如果关键资源推迟两周到位""如果测试环境不可用"等情景对完工日期的影响，支持备选方案制定；以及**模拟（Simulation）**——主要是蒙特卡洛模拟，对活动持续时间的不确定性做上千次随机试算，输出项目在给定日期前完工的概率分布，为设定完工目标与储备提供量化依据。
- **提前量与滞后量（Leads and Lags）**：**滞后量（Lag）**是强制等待时间，使紧后活动推迟开始或完成，如混凝土浇筑后养护 7 天才能继续施工，用 FS+7（完成到开始加 7 天滞后）表示；**提前量（Lead）**允许紧后活动提前开始，如土方开挖结束前 3 天即可开始铺设管道，用 FS-3（负值表示提前量）表示。PMBOK 约定：负值表示提前量、正值表示滞后量。注意提前量不能跨越里程碑随意应用，滥用提前量会增加返工风险。
- **进度压缩（Schedule Compression）**：在不改变范围的前提下缩短工期，两种基本手段。**赶工（Crashing）**：通过加班、增加资源或额外支付来缩短关键路径活动，以成本换时间；只对关键路径活动有效，且存在边际收益递减。**快速跟进（Fast Tracking）**：把原本顺序执行的活动改为并行（压缩其逻辑关系），如边设计边施工，不直接增加成本但增加返工与风险。辨析：赶工增加成本，快速跟进增加风险。
- **项目管理信息系统（PMIS）**：进度软件（如 Microsoft Project、Primavera P6）自动完成前推/后推计算、资源加载与平衡、模拟运算，并输出甘特图、资源直方图与各类进度报告，降低手工计算错误。
- **敏捷发布规划（Agile Release Planning）**：适应型项目用于确定发布与迭代节奏：把待办事项映射到迭代/发布周期，设定迭代时长与发布目标，采用滚动式规划逐层细化，产出发布计划与迭代计划，替代传统一次性排定全部活动的做法。`,
      "📤 输出 Outputs": `- **进度基准（Schedule Baseline）**：经批准的项目进度计划版本，是绩效测量基准的组成部分，也是"监控进度"过程中比较实际进度的"标尺"；对它的任何变更都必须通过整体变更控制。
- **项目进度计划（Project Schedule）**：进度模型的输出，常见表现形态有三种：**横道图/甘特图**——最常用，直观显示活动起止与重叠；**里程碑图**——只显示主要交付物与关键外部接口的起止日期，便于高层汇报与合同履约；**进度网络图**——显示依赖关系与浮动时间，技术性强，通常配合甘特图使用。
- **进度数据（Schedule Data）**：支撑进度计划的详细数据，包括活动及其属性、假设与约束、浮动时间、备选路径（次关键路径）、资源负荷直方图、赶工/快速跟进所需资源等，供后续分析与报告使用。
- **项目日历（Project Calendars）**：定义可进行进度活动的日历（工作日、班次、节假日、非工作时段），决定活动能够排入的实际日期；它和资源日历、组织日历共同约束排程。
- **变更请求**：当建模结果显示需要调整范围、基准或方案（如调整里程碑、追加资源）时，提出变更请求，经整体变更控制批准后更新相应基准与计划。
- **项目管理计划更新**：进度管理计划、范围基准等可能随建模结果调整而更新。
- **项目文件更新**：假设日志、估算依据、活动属性、资源日历、风险登记册、经验教训登记册等随新发现与决策不断更新。`,
      "🔗 与其他过程的相互作用": `制订进度计划是进度管理领域的"装配车间"：它汇聚"定义活动→排列活动顺序→估算活动资源→估算活动持续时间"四个过程的成果，把活动清单、网络图、资源需求、持续时间估算"装配"成完整、可执行的进度模型。它向上承接"规划进度管理"确定的规则，向下为"监控进度"提供进度基准与项目日历，基准又进入绩效测量基准以支撑进度与成本的一体化监控。当需要压缩工期或资源不足时，可能要求调整范围（触发范围变更）、调整采购安排（外购资源到位时间）或追加成本（赶工资金），因此本过程会产生变更请求并走上整体变更控制流程。在适应型项目中，本过程体现为发布/迭代规划，迭代评审的反馈会回注到待办事项列表并调整后续迭代，形成持续规划的闭环，而非一次性排定全部。`,
      "✂️ 裁剪考虑": `- **预测型项目**：完整展开活动网络与 CPM 计算，重视资源平衡与进度压缩，强调确定性日期与正式的进度基准。
- **适应型（敏捷）项目**：不做完整网络，改用待办事项列表 + 迭代节奏组织进度，用计划扑克/故事点估算，靠燃尽图/看板跟踪，用滚动式规划替代一次性排定全部。
- **混合型项目**：整体里程碑层按预测式锁定，工作层按敏捷迭代排期，两条线的衔接规则需提前定义。
- **规模与风险**：大型、高风险、高不确定性的项目应加大模拟（蒙特卡洛）与缓冲（关键链）的投入；小型简单项目用类比估算即可，不必过度建模。
- **组织环境**：组织既有的进度工具与报告制度决定了模型的载体与细化程度。`,
      "💼 实践案例": `一个 8 个月的楼宇机电安装项目：项目经理用 CPM 建立网络，识别出关键路径为"结构验收→设备到货→安装→调试→联动测试"，初始计算工期 260 天，超出合同 240 天。她分三步处理：首先做**进度压缩**——对关键路径上的"设备安装"赶工（增加一个夜班班组，成本约 +8%），对"调试"与"联动测试"快速跟进（并行启动，用额外测试轮次缓解风险）；其次做**资源平衡**，解决电工班组在安装高峰期的超负荷问题；最后引入**关键链法**，在链条末端设置 15 天项目缓冲、在非关键链汇入处设 8 天汇入缓冲，把计划工期压回 255 天并留有余量。执行阶段她持续监控缓冲消耗率，当项目缓冲消耗超过三分之一时及时增援资源，最终提前 5 天交付，避免了合同罚金。`,
    },
    keyConcepts: `- **关键路径法（CPM）**：确定项目最长路径与最短工期的技术；前推求 ES/EF，后推求 LS/LF，总浮动 = LS-ES = LF-EF，总浮动最小（通常为 0）的路径为关键路径。
- **总浮动 vs 自由浮动**：总浮动衡量"不影响项目完工日期"的机动时间；自由浮动衡量"不影响紧后活动最早开始"的机动时间；自由浮动 ≤ 总浮动。
- **多条关键路径**：当网络中有多条关键路径时，任一关键活动延误都会推后整个项目，监控难度加大。
- **关键路径漂移**：非关键活动延误超过其总浮动后升级为关键活动，关键路径随之改变，需重新计算。
- **关键链法（CCM）**：约束理论的进度应用，采用 50% 概率激进估算 + 项目缓冲/汇入缓冲/资源缓冲，通过缓冲消耗监控健康度。
- **PDM 前导图法**：用节点表示活动、箭线表示逻辑关系的绘图法，四种关系为完成到开始（FS）、开始到开始（SS）、完成到完成（FF）、开始到完成（SF），FS 最常见。
- **提前量与滞后量**：滞后量（正数）是强制等待；提前量（负数）允许紧后活动提前，如 FS-3。
- **进度压缩**：赶工（加资源/加班，增成本）与快速跟进（并行，增风险）。
- **PERT 三点估算**：期望时间 = (乐观值 + 4×最可能值 + 悲观值)/6；标准差 = (悲观值 - 乐观值)/6。
- **里程碑清单**：持续时间为零的时点活动，作为进度锚点与承诺点。
- **项目日历**：定义可工作时段；组织日历、资源日历、项目日历的关系是高频辨析点。
- **边际收益递减**：加倍资源不一定减半时间，协调成本上升使收益递减。`,
    examTips: `- **核心公式串必背**：ES/EF 前推、LS/LF 后推、总浮动 = LS-ES = LF-EF。考试给出网络图或表格让你算关键路径长度、某活动的总浮动/自由浮动，是最经典题型，务必多练。
- **关键路径判断逻辑**：加长关键路径 = 项目变长；缩短非关键路径不缩短项目（除非它因此变成关键路径）；关键路径上的延误直接推后完工日期。
- **赶工 vs 快速跟进辨析**：题干出现"增加成本/加班/加资源"选赶工（Crashing），且对关键路径活动有效；出现"并行执行/接受风险/可能返工"选快速跟进（Fast Tracking）。
- **提前量/滞后量方向**：滞后是等待（FS+7），提前是并行（FS-3）；PMBOK 中负值代表提前量。题目问"让活动提前开始"要意识到这是提前量。
- **三点估算公式**：β 分布 (O+4M+P)/6 用于 PERT；三角分布 (O+M+P)/3 别混淆。题目说 PERT 通常指 β 分布。
- **资源平衡 vs 平滑**：平衡可能改变关键路径、延长工期；平滑不改变关键路径。题干出现"不能延长项目工期"的约束时选平滑。
- **总浮动 vs 自由浮动**：总浮动影响项目完工日期，自由浮动影响紧后活动最早开始；自由浮动不可能大于总浮动，这是常见判断点。
- **关键链缓冲**：项目缓冲保护完工日期、汇入缓冲保护关键链、资源缓冲只是"通知"不是时间——别把资源缓冲当成时间储备。
- **边际收益递减**：题干"要求更快"时警惕承诺加资源必能减半时间——协调成本上升使收益递减。`
  },
  "proc-monitor-schedule": {
    overview: `【过程概述】监控进度过程旨在监督项目状态，以更新项目进度计划并管理对既定进度计划的变更。更新进度计划需要了解截至目前的实际绩效或预测绩效。该过程的关键收益是：在整个项目期间维持一个现实可行的进度计划——既不能脱离实际空谈理想计划，也不能放任偏差失控。

监控进度涉及五项主要活动：确定项目进度的当前状态（实际开始/结束、完成百分比、剩余工作）；对导致进度变更的因素施加影响（推动有利变更、化解不利变更）；重新评估必要的进度储备（缓冲是否够用）；确定整体项目进度是否已发生变更；在实际变更发生时进行管理。

当使用预测型方法时，对进度基准的任何变更都只能通过"评估与实施变更"过程并遵循整体变更控制才能获得批准——项目经理不能擅自修改基准。当使用适应型或敏捷方法时，监控进度的方式显著不同：通过比较已交付工作总量与已完成工作的估算值来确定进度状态（如燃尽图/燃起图）；召开回顾会议以纠正和改进过程；重新确定剩余工作（待办事项列表）的优先级；确定可交付物的产出和验收速率（团队速率 Velocity）。本过程贯穿整个项目生命周期，持续进行，频率依项目风险与不确定性而定。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：包括**进度管理计划**（规定控制临界值、报告规则与测量方法）、**进度基准**（比较实际进度的对象）、**范围基准**与**绩效测量基准**（与成本联动监控的基线）。
- **项目文件**：包括**资源日历**（资源可用性变化，判断延误是否会延续）、**项目进度计划**（当前最新版本）、**进度数据**（实际日期、浮动、储备消耗等）、**项目日历**（工作日/班次变化）、**经验教训登记册**（历史进度教训）、**风险登记册**（进度风险是否已变现）、**假设日志**（假设是否仍然成立）。
- **工作绩效数据**：本过程的"燃料"，指在实施过程中收集到的原始观测数据，如实际开始/结束日期、完成百分比、剩余工期、里程碑完成情况、已投入工时等，尚未经过加工分析。
- **事业环境因素（EEF）**：行业进度标准、组织的报告系统与信息工具、组织日历、财务约束等。
- **组织过程资产（OPA）**：进度报告模板、控制临界值的历史标准、历史偏差数据、纠正措施与预防措施的政策程序。`,
      "🔧 工具与技术 Tools": `- **数据分析——挣值分析（Earned Value Analysis）**：用挣值体系量化进度偏差。**SV = EV - PV**（进度偏差，货币值），SV>0 表示提前，SV<0 表示滞后，SV=0 表示恰好符合；**SPI = EV / PV**（进度绩效指数），SPI>1 提前，SPI<1 滞后，SPI=1 符合。关键局限：SPI 只反映"量"的完成程度，不反映关键路径状态——非关键活动大量提前可能让 SPI>1，而关键路径实际已落后，因此必须与关键路径法结合使用。同时可用 SPI 推导完工日期预测，如简单法预计完工时间 = 计划工期 / SPI。
- **数据分析——迭代燃尽图（Iteration Burndown Chart）**：适应型项目监控进度的主要工具。横轴为迭代天数，纵轴为剩余工作量（故事点或任务数），同时绘制"计划燃尽线"与"实际燃尽线"。实际线位于计划线之上表示剩余工作多于计划、进度落后；位于之下表示提前。与之对应的是**燃起图（Burnup Chart）**，显示已完成工作量的累计上升曲线，并与范围线对比，直观反映"完成多少"与"范围是否扩张"；**累积流图（Cumulative Flow Diagram, CFD）**则以面积图展示各状态（待办/进行中/已完成）的在制品（WIP）数量随时间的变化，帮助识别瓶颈、拥堵与工作流稳定性。
- **数据分析——绩效审查（Performance Reviews）**：把实际绩效与进度基准系统对比，审查已完成工作、里程碑达成情况、预留时间的使用等，是偏差分析之前的总览动作。
- **数据分析——趋势分析（Trend Analysis）**：观察进度偏差随时间的变化方向与速率，判断项目是趋于恶化、好转还是平稳，常用 S 曲线或移动平均线辅助判断。
- **数据分析——偏差分析（Variance Analysis）**：分解进度偏差（SV/SPI、里程碑延误、活动延误）找出根本原因并评估影响。核心判断逻辑：**关键路径上的延误**直接推后完工日期，必须立即干预；**非关键路径的延误**若未超出其总浮动，不影响完工日期，可暂缓处理；一旦非关键活动延误超过总浮动，它就升级为关键活动，问题变得严重。
- **数据分析——假设情景分析（What-if Scenario Analysis）**：对"如果关键资源缺勤两周""如果测试环境延迟交付"等情景推演对完工的影响，辅助决定是否赶工、快速跟进或动用储备。
- **关键路径法（CPM）**：监控中再次运用——跟踪关键路径上活动的实际绩效，识别关键路径延误；当活动延误超过总浮动导致关键路径变化时，需要重新计算关键路径。若采用关键链方法，则重点监控各缓冲（项目缓冲/汇入缓冲）的消耗率。
- **项目管理信息系统（PMIS）**：电子表格、进度软件、看板工具自动汇总实际数据、更新进度模型并生成偏差报告，降低手工计算的滞后与错误。
- **会议**：**每日站会**（对齐进展、识别障碍）、**进度评审会**（对照基准评审偏差）、**迭代评审与回顾会**（敏捷中验证增量、纠正过程）。配合使用的**人际与团队技能**包括引导（主持有效的评审）、谈判（协商资源与排期）与团队建设（维持士气）。`,
      "📤 输出 Outputs": `- **工作绩效信息**：对工作绩效数据加工、分析后的信息，包括计算得出的 SV/SPI、进度偏差及其原因、关键路径状态、缓冲消耗情况等，汇入工作绩效报告供干系人决策。
- **进度预测（Schedule Forecasts）**：基于截至目前的实际绩效对未来完工日期或剩余工期的估算（如基于 SPI 推导的预计完工时间，或"尚需时间 ETS"），随项目进展不断刷新，是滚动规划的重要输入。
- **变更请求**：监控发现偏差后提出的正式请求，类型包括纠正措施（纠偏）、预防措施（防止再发）、缺陷补救与计划更新；预测型项目中的任何基准变更都必须走整体变更控制并经 CCB 批准。
- **项目管理计划更新**：进度基准、进度管理计划、成本基准、绩效测量基准等经批准后更新，确保基准确立后不再随意漂移。
- **项目文件更新**：进度数据、项目日历、经验教训登记册、风险登记册、假设日志等随新的观察与决策更新。`,
      "🔗 与其他过程的相互作用": `监控进度依赖"制订进度计划"产出的进度基准与项目日历作为比较对象，也持续接收实施过程中产生的工作绩效数据。它与"监控成本"共享绩效数据——SPI 与 CPI 联合分析可更全面地判断项目健康度，进度预测也作为滚动式"估算成本"的输入。发现偏差后，本过程产生变更请求交给"评估与实施变更"及整体变更控制处理；批准的变更会回流更新进度基准、绩效测量基准，使监控对象始终反映最新批准状态。在敏捷场景中，每日站会、迭代评审与回顾会形成的观察结果反馈到待办事项列表与下一迭代规划，形成短周期闭环，几乎不需要正式的变更请求流程。整个监控过程与"指导和管理项目工作""评估与实施变更""监控风险"等过程相互联动，共同维护项目的计划一致性。`,
      "✂️ 裁剪考虑": `- **预测型项目**：以正式的偏差报告 + 变更控制为特点，按周/月开展进度评审，使用 SV/SPI 与关键路径状态作为主要指标，监控频率与临界值由进度管理计划规定。
- **适应型（敏捷）项目**：以每日站会、燃尽图/燃起图、看板与 CFD 进行持续跟踪，靠迭代回顾会持续改进，实时重新排定待办优先级，几乎不使用正式变更请求。
- **混合型项目**：整体里程碑层按预测型监控（报告、变更控制），迭代内按敏捷可视化跟踪，两条线各用各的度量。
- **不确定性与风险**：高风险、高不确定性项目应提高监控频率、收窄控制临界值、加大储备消耗监控力度；稳定低风险项目可放宽。
- **工具与组织**：组织的报告制度、看板/进度软件能力决定了监控载体与报告粒度。`,
      "💼 实践案例": `一个 6 个月的网站改版项目，第 4 个月末监控时：挣值分析显示 SPI=0.92、SV=-9 天，进度明显滞后。进一步做偏差分析：关键路径上的"支付模块集成"延误了 5 天——这是**关键路径延误**，直接推后完工日期；而非关键路径的"静态页面"延误 3 天，但仍在总浮动范围内，**不影响完工日期**。同时检查进度储备：原预留 20 天已消耗 12 天，消耗率偏高。项目经理据此提出变更请求：对关键路径的集成工作赶工（增派 2 名后端工程师两周），把非关键路径的"静态页面"在浮动窗内平滑调序，并重新评估储备。CCB 批准后进度基准更新，月底 SPI 回升至 0.99。期间团队通过每日站会和看板发现 CFD 中"进行中"列 WIP 过高、形成瓶颈，于是限制在制品数量，工作流恢复顺畅。这个案例说明：监控要区分关键路径与非关键路径的延误，结合储备消耗分析判断严重性，并通过正式变更程序实施纠偏。`,
    },
    keyConcepts: `- **SV（进度偏差）**：SV = EV - PV，货币值；SV>0 提前，SV<0 滞后，SV=0 符合计划。
- **SPI（进度绩效指数）**：SPI = EV / PV，比率值；SPI>1 提前，SPI<1 滞后，SPI=1 符合计划。
- **挣值（EV）**：已批准预算中已完成工作对应的价值；计划价值（PV）是计划中到期应完成工作的预算价值。
- **进度储备消耗分析**：监控预留时间缓冲的消耗速率，判断项目健康度；消耗过快说明风险正在变现、需干预或重估储备。
- **迭代燃尽图**：显示迭代内剩余工作量随时间下降的曲线，实际线高于计划线即落后。
- **燃起图**：显示已完成工作累计上升的曲线，与范围线对比可发现范围蔓延。
- **累积流图（CFD）**：展示各状态在制品数量的堆积面积图，识别瓶颈与工作流稳定性。
- **关键路径延误**：关键活动延误直接推后完工日期，必须立即处理；**非关键路径延误**：未超出总浮动则不影响完工，可暂缓。
- **进度预测**：基于当前绩效（SPI 等）对完工日期或剩余工期的估算，如预计完工时间 = 计划工期 / SPI，随监控不断刷新。
- **团队速率（Team Velocity）**：敏捷中团队平均每个迭代完成的故事点数，用于预测未来迭代产能与完工时间。`,
    examTips: `- **SV/SPI 必背**：SV>0 提前、SV<0 滞后；SPI>1 提前、SPI<1 滞后。SV 是差值、SPI 是比率，方向判断是送分题，务必拿稳。
- **SPI 的局限（高频陷阱）**：SPI 只反映"量"，不反映关键路径。题干出现"SPI>1 但关键路径延误"时，不要误判项目正常——需结合 CPM 看关键路径状态。
- **燃尽图方向判断**：实际燃尽线在计划线**之上** = 剩余工作多于计划 = 进度落后；之下 = 提前。注意与燃起图（已完成工作累计上升）方向相反。
- **关键路径延误 vs 非关键路径延误**：问"是否影响完工日期"→ 先判断延误活动是否在关键路径上、延误是否超过其总浮动；这是监控题最高频的判断逻辑。
- **预测型变更必须走整体变更控制**：进度基准任何修改都要通过 CCB，不能因"时间紧"直接改；敏捷项目则实时调整待办、无需 CCB。
- **储备消耗要重估**：进度储备消耗过快时要重新评估储备是否足够，并可通过变更申请追加；不要把储备随便用于非关键活动。
- **进度预测 ≠ 进度计划**：预测是基于现状对未来的估算（含预计完工时间），计划是既定安排，二者常被故意混设陷阱。
- **敏捷监控三件套**：迭代燃尽图 + 团队速率（Velocity）+ CFD 识别瓶颈，是适应型项目监控的核心考点。
- **CPI 与 SPI 联合**：题干同时给出成本与进度数据时，判断"整体健康度"要 CPI 与 SPI 一起看，单一指标会误导。`
  },
  "proc-plan-financial-mgmt": {
    overview: `【过程概述】规划财务管理过程（Plan Financial Management）旨在，定义如何对项目收入与支出进行估算、预算制定、管理和监控，以确保其与项目目标和组织战略保持一致。该过程的关键收益是，为如何在整个项目期间管理项目财务提供指导和方向，从而在项目开始前就为成本、收益与资金流管理建立统一框架。该过程通常在项目前期执行一次，或在项目的预定节点（如里程碑、预算周期、季度评审）重新执行，以便适应外部环境变化或组织战略调整。

财务管理计划是本过程的输出，也是项目管理计划的子计划之一，通常包括以下要素：
- **计量单位**：项目财务使用的货币类型（如人民币、美元）及度量单位（如人天、立方米、吨）。
- **精确度**：估算金额的四舍五入程度（如精确到千元）以及可接受的取整范围。
- **控制临界值**：在采取纠正行动前允许的最大偏差范围（如成本偏差允许±5%）。
- **绩效测量规则**：定义使用何种挣值管理（EVM）方法，如何计算PV、EV、AC等指标，以及采用何种完工百分比规则。
- **报告格式**：财务报告的频率、格式、分发对象与汇报层级。
- **组织程序链接**：工作分解结构（WBS）与组织会计科目（记账代码）之间的对应关系，便于成本核算、对账与审计。
- **资金限制**：组织或客户对项目资金支出的约束条件，是后续资金限制平衡的输入。

此外，规划财务管理还要考虑收入端（如合同款、客户预付款、融资流入）的规划，确保收入与支出的节奏相匹配，为现金流管理与项目财务可行性判断提供依据。该计划为估算成本、制定预算和监控财务三个后续过程提供指导框架，是财务域规划工作的纲领性文件。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目概算、总体资金规模、审批权限及主要干系人（如发起人）信息，章程中的财务约束是本过程的输入条件。
- **项目管理计划**：规划财务管理通常在规划阶段早期开展，其他子计划（如范围管理计划、资源管理计划、沟通管理计划、风险管理计划）中的假设与策略会影响财务计划要素的设定，也为财务管理计划的整合提供上下文。
- **事业环境因素**：包括组织文化、组织结构、市场条件、组织财务管理体系、汇率与通货膨胀水平、法律法规、行业规范等，这些因素影响计量单位、精确度、控制临界值、资金限制与报告格式等要素的确定。
- **组织过程资产**：包括组织的财务管理政策与程序、历史财务信息、成本估算模板、会计科目表、报告模板、以往项目沉淀的经验教训等，为制定财务管理计划提供参考基础与制度依据。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具备成本管理、财务管理、预算编制经验的人员或小组（如财务部门、项目经理、发起人、行业专家）提供意见，帮助确定计量单位、精确度、控制临界值、绩效测量规则等计划要素，并判断哪些历史信息适用于本项目。
- **数据分析**：在规划财务管理过程中，主要运用备选方案分析，比较不同的财务管理方案（如不同的预算分配方式、不同的挣值计算规则、不同的储备策略），评估其对本项目财务目标的影响，从而选择最合适的管理方法。在备选方案分析之外，还可运用现金流分析与模拟，评估不同预算分配与支付安排下项目的现金流入与流出，识别潜在的现金流缺口风险，并据此调整资金限制与付款安排。
- **会议**：召开财务管理规划会议，项目经理与团队成员、财务部门、干系人就财务管理计划的各项要素达成共识，统一对精确度、控制临界值、绩效测量规则、报告频率的理解，并将共识正式写入计划。`,
      "📤 输出 Outputs": `- **财务管理计划**：财务管理计划是项目管理计划的子计划，描述如何规划、安排和控制项目成本与收入，内容涵盖计量单位、精确度、控制临界值、绩效测量规则、报告格式、组织程序链接、资金限制等要素。该计划是估算成本、制定预算、监控财务三个过程的指导性框架，也是财务绩效评估、偏差分析与变更管理的依据。此外，该计划还应明确成本与收入的归集规则（如按WBS或控制账户归集）以及财务信息的沟通与审批路径，确保后续财务活动与组织治理保持一致。`,
      "🔗 与其他过程的相互作用": `本过程属于规划过程组，处于财务域的入口。它接收项目章程和项目管理计划的总体约束，产出财务管理计划，为后续的估算成本、制定预算、监控财务三个过程提供框架。在预测型生命周期中，本过程通常在规划阶段一次完成；在适应型（敏捷）生命周期中，可结合季度预算周期滚动修订。财务管理计划还与其他规划过程联动：范围基准决定估算对象，资源管理计划影响资源费率，风险管理计划影响储备策略与绩效测量规则。当项目发生重大变更（如范围、资金、组织战略调整）时，可能需要重新审视并更新财务管理计划。同时，财务管理计划需与收益管理计划衔接——收益实现节奏会影响收入预测与现金流规划；范围与进度的重大变更也会反过来触发对财务管理计划的审视与更新。`,
      "✂️ 裁剪考虑": `- **预测型项目**：财务管理计划通常在项目早期一次性制定，要素详尽，控制临界值较紧，报告周期较长。
- **适应型（敏捷）项目**：财务通常按迭代或季度滚动预算，预算可频繁修订，报告周期短，控制临界值较宽，更关注已交付功能的价值而非单纯的成本支出。
- **混合型项目**：核心阶段采用预测型财务控制，探索性阶段采用滚动预算与轻量测量。
- **组织规模**：小型组织可简化报告格式与会计链接；大型组织须遵循严格的财务制度、审计与披露要求。
- **行业特点**：受监管行业（如制药、金融、政府项目）需满足特定财务合规与披露要求。
- **合同类型**：固定总价合同下成本监控压力小、侧重收款与现金流；成本补偿型合同下成本监控更严格，财务管理计划需要更精细的成本归集与审批安排。`,
      "💼 实践案例": `某软件公司承接一个为期两年的政府信息化项目。项目经理在启动会后即召开财务管理规划会议，与财务部、发起人共同确定：计量单位为人民币万元；估算精确度为±10%；成本偏差控制临界值为±5%；绩效测量规则采用挣值管理的50/50完工百分比规则；每月向发起人提交财务报告；并将WBS与组织会计科目建立映射。该计划使项目团队在后续估算、预算与监控过程中有章可循，也便于财务部门月末对账与审计追溯。`,
    },
    keyConcepts: `- **财务管理计划**：定义如何估算、预算、管理和监控项目收入与支出的子计划，是财务域三个后续过程的框架。
- **计量单位**：项目财务使用的货币类型与度量单位。
- **精确度**：估算金额取整的程度，与估算类型和项目阶段相关。
- **控制临界值**：在采取纠正行动前允许的最大偏差，可设置为金额或百分比。
- **绩效测量规则**：定义使用何种EVM规则及完工百分比计算方法。
- **报告格式**：财务报告的频率、格式与分发对象。
- **组织程序链接**：WBS与组织会计科目之间的对应关系。
- **资金限制**：对项目资金支出的约束条件，驱动后续的资金限制平衡。`,
    examTips: `- 高频考点：财务管理计划的组成要素——计量单位、精确度、控制临界值、绩效测量规则、报告格式、组织程序链接、资金限制。
- 控制临界值指“在采取行动前允许的最大偏差范围”，不要与项目范围临界值混淆。
- 该计划是估算成本、制定预算、监控财务三个过程的框架性输入，考题常问“谁指导估算成本/制定预算”，答案应指向财务管理计划。
- 在敏捷项目中，预算可以按季度分配和修订，具有更大的灵活性——这是与预测型模式的典型差异，也是热门考点。
- 注意区分三个易混输出：财务管理计划（规划财务管理输出）、成本估算（估算成本输出）、成本基准（制定预算输出）。
- 规划财务管理不仅管成本，也管收入（合同款、融资、预付款），确保收入与支出节奏匹配、维持财务可行性，考试偶尔会强调“收入与支出双重管理”。`
  },
  "proc-estimate-costs": {
    overview: `【过程概述】估算成本过程（Estimate Costs）旨在，对完成项目工作所需的资源成本进行近似估算。该过程的关键收益是，确定完成项目工作所需的货币资源数量，为后续制定预算提供基础。在项目过程中，应随着更多信息的获取（范围细化、风险识别、市场变化、设计深入）而逐步细化成本估算，因此成本估算具有明显的迭代性，不同阶段对应不同的估算精度等级。

成本估算需要覆盖所有项目资源成本，包括：人力（工资、福利）、材料（消耗品与构成品）、设备（采购或租赁）、服务（外包、咨询、监理）、设施（办公场地、机房）以及其他特殊项目成本（如许可、保险）。此外，还应考虑通货膨胀、汇率波动、市场供求、间接成本分摊、质量成本（COQ）等因素对估算的影响。

估算方法由粗到精分为四种：类比估算（基于历史类似项目的实际成本，快速但精度较低）、参数估算（基于单位成本×数量的统计关系，需要可靠的参数数据）、自下而上估算（从WBS底层工作包开始逐层汇总，精度最高但耗时最长）、三点估算（考虑乐观、最可能、悲观三种情景，用统计公式降低不确定性）。此外，储备分析用于确定应急储备和管理储备的金额，质量成本分析用于评估质量投入与总成本之间的平衡。所有支持估算的数据与假设都应记录在案，形成估算依据。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：成本管理计划（提供估算方法、精确度、控制临界值等规则）、质量管理计划（影响质量成本水平）、范围基准（WBS与范围描述是估算的对象和基础）。
- **项目文件**：项目进度计划（明确活动时序与资源占用时间）、范围需求文件等，为估算提供上下文。
- **资源需求**：来自资源管理规划，规定所需资源的类型与数量，是自下而上估算与参数估算的基础数据。
- **假设日志**：记录成本估算所依赖的假设条件（如资源费率、汇率、通胀率、交付周期），假设一旦变化，估算须相应调整。
- **风险登记册**：提供已识别风险及其概率、影响的信息，用于评估风险应对成本与应急储备的金额。
- **经验教训登记册**：提供以往项目的成本估算经验与教训，避免重复以往的错误，提升估算准确性。
- **事业环境因素**：如市场行情、资源费率、汇率、利率、通胀率、组织成本数据库与定价体系。
- **组织过程资产**：历史信息、成本估算模板、定价清单、行业费率表、估算审批流程等。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具备成本估算经验的人员判断估算参数、识别偏差来源、处理异常情况，并对估算结果进行合理性审查。
- **类比估算**：又称自上而下估算，用历史类似项目的实际成本类比当前项目，成本低、速度快，但依赖历史项目的相似性与专家经验，精度较低，通常在项目早期、信息不足时使用。
- **参数估算**：基于统计关系，成本=单位成本×数量（如每平方米造价×建筑面积、每小时费率×工时），需要可靠的单位参数与历史数据，精度优于类比估算，可在范围较清晰时使用。
- **自下而上估算**：对WBS最底层的工作包或活动逐一进行估算，再逐层汇总到控制账户与项目总成本，精度最高，但工作量大、耗时长，适用于范围明确、WBS分解详细的项目。
- **三点估算**：考虑不确定性与风险，对每个活动给出乐观（O）、最可能（M）、悲观（P）三种估计，再以统计公式加权计算期望值：三角分布为(O+M+P)/3；贝塔分布（PERT加权平均）为(O+4M+P)/6，后者是PMI考试默认使用的公式。
- **数据分析**：包括储备分析（为已识别风险确定应急储备，为未识别风险确定管理储备）与质量成本（COQ）分析（权衡预防、评估、失败成本，寻求质量投入与总成本的最优平衡），必要时还可进行备选方案分析、模拟与敏感性分析。
- **项目管理信息系统**：如成本估算软件、电子表格工具，用于存储估算数据、维护参数模型、支持统计计算与蒙特卡洛模拟，提高估算效率与可追溯性。
- **决策**：在多方意见不一致或存在多个备选方案时，运用投票（如达成一致原则）或多准则决策分析，选出最终接受的估算值或估算方案。`,
      "📤 输出 Outputs": `- **成本估算**：项目活动或工作包的量化成本近似值，通常以货币金额表示（如人民币万元），可包含直接成本、间接成本分摊与税金，并标注对应的精度等级（如粗略量级-25%~+75%、预算估算-10%~+25%、确定性估算-5%~+10%）。
- **估算依据**：记录估算所依据的数据、假设、排除项、使用的估算方法、精度等级以及专家意见的文件，用于支持估算结果的可信度与可追溯性，也是后续变更审查与审计的依据。
- **项目文件更新**：通常更新经验教训登记册（记录本次估算的方法与经验）和假设日志（更新影响估算的假设条件），使项目文件保持一致。`,
      "🔗 与其他过程的相互作用": `估算成本位于规划过程组财务域，承接财务管理计划的框架性指导，以范围基准（WBS）为估算对象。它利用资源需求（来自资源管理规划）与风险信息（来自识别风险），输出成本估算与估算依据，供制定预算过程汇总为成本基准。估算过程中发现的新风险与假设变化会反馈到风险登记册与假设日志。在项目执行与监控阶段，监控财务过程将实际成本与估算对比，发现问题时通过变更控制程序更新估算。估算也是启动阶段商业论证中粗略量级估算的逐步细化，与项目财务可行性判断相衔接。`,
      "✂️ 裁剪考虑": `- **预测型项目**：规划阶段进行较精细的自下而上估算，WBS分解详细，估算精度高。
- **适应型（敏捷）项目**：估算粒度较粗，常按故事点或相对规模估算，随迭代持续滚动细化，不追求一次性精确，重点关注相对大小而非绝对金额。
- **项目规模**：小型项目可用类比或参数估算快速完成；大型复杂项目需要自下而上结合三点估算与储备分析。
- **市场波动大的环境**：估算中须加入通胀率与汇率敏感性分析，并适当放宽精度等级或加大储备。`,
      "💼 实践案例": `某建筑项目需要对一座10,000平方米的办公楼进行成本估算。立项阶段，项目经理使用类比估算，参考此前同类办公楼的实际造价，得到粗略量级估算（精度约-25%~+75%）；设计完成后，采用参数估算（每平方米单价×建筑面积）进行细化；招标图完成后，施工单位按WBS工作包自下而上汇总，并对关键路径上的不确定活动采用三点估算（三角分布与贝塔分布）计算期望值，同时通过储备分析为已识别风险留出应急储备，最终形成带有完整估算依据的确定性估算（精度约-5%~+10%），提交给制定预算过程。`,
    },
    keyConcepts: `- **类比估算**：基于历史类似项目，自上而下，粗略快速，精度较低。
- **参数估算**：单位成本×数量，依赖可靠的参数数据与统计关系。
- **自下而上估算**：WBS底层逐层汇总，最精确但最耗时。
- **三点估算**：三角分布(O+M+P)/3；贝塔分布/PERT加权平均(O+4M+P)/6，PMI考试默认。
- **估算精度等级**：粗略量级估算ROM为-25%~+75%（用于立项/启动）；预算估算为-10%~+25%；确定性估算为-5%~+10%。
- **储备分析**：确定应急储备（应对已知-未知，含于成本基准）与管理储备（应对未知-未知，不含于成本基准）。
- **质量成本（COQ）**：预防成本、评估成本、内部与外部失败成本之和，目标是质量与成本的平衡。
- **成本类型**：直接成本与间接成本、可变成本与固定成本、沉没成本（决策时应忽略沉没成本）。`,
    examTips: `- 类比 vs 参数 vs 自下而上对比是高频题：类比=历史项目类比、快速粗略；参数=统计关系（单位成本×数量）；自下而上=WBS底层汇总、最精确。
- 三点估算公式务必分清：贝塔分布（PERT）为(O+4M+P)/6，是考试默认；三角分布为(O+M+P)/3，题目会明确说明“用三角分布”。
- 精度等级必背：粗略量级-25%~+75%（启动阶段），预算估算-10%~+25%，确定性估算-5%~+10%。
- 应急储备包含在成本基准中；管理储备不包含在成本基准中，由管理层控制。
- 质量成本（COQ）的核心思想是“质量与成本的平衡”——过度提升质量会增加成本，质量不足则失败成本上升。
- 估算依据（Basis of Estimates）记录假设、方法与精度等级，常与“任何估算都应可追溯”的考点结合。
- 沉没成本不应影响当前决策，此点在决策类考题中反复出现。`
  },
  "proc-develop-budget": {
    overview: `【过程概述】制定预算过程（Develop Budget）旨在，汇总各项活动或工作包的估算成本，以建立经批准的成本基准。该过程的关键收益是，确定项目成本基准，并将其作为绩效测量与资金控制的依据。成本基准是已批准的按时间段分配的项目预算版本，不包括任何管理储备，只能通过正式的变更控制程序进行变更，并用作与实际结果（EVM测量）进行比较的基础。

项目预算的构成遵循清晰的“等式链”：
- **成本汇总**：将工作包成本估算按WBS自下而上逐层汇总；
- **成本汇总+应急储备=成本基准（Cost Baseline）=BAC（完工预算）**：应急储备用于应对已识别风险（已知-未知），包含在成本基准中，项目经理可直接使用；
- **成本基准+管理储备=项目资金需求（总预算）**：管理储备用于应对未识别风险（未知-未知），不包含在成本基准中，通常由管理层控制，项目经理需申请并经批准后才能使用。
- 项目资金需求又可分为总资金需求与分阶段资金需求，后者说明资金在各时间段的到位安排。

制定预算时还需考虑资金限制平衡（在资金有限的条件下调整工作安排，确保各期支出不超过资金限额）、历史信息审核（验证估算合理性）、融资（确定项目资金的来源和到位时间）等活动。预算一经批准即成为项目财务监控的基准，任何调整必须通过正式变更控制程序，未经批准不得更改。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：成本管理计划（提供汇总与绩效测量规则）、资源管理计划（提供资源费率与资源日历信息）、范围基准（提供WBS与工作包定义，是成本汇总的对象）。
- **项目文件**：包括成本估算（各工作包的成本估算值）、估算依据（支持估算的数据与假设）、项目进度计划（成本按时间段分配的基础）、资源日历（反映资源可用时间，影响按时间分段的成本）、风险登记册（支持储备分析）、协议（如采购合同中的价格与付款条件，影响资金需求）等。
- **成本估算**：来自估算成本过程的输出，是成本汇总的原料与基础。
- **估算依据**：提供估算的假设、方法与数据来源，供历史信息审核验证估算的合理性。
- **项目进度计划**：将成本分配到时间段，形成S曲线与分阶段资金需求计划。
- **资源日历**：反映各类资源的可用时间与数量，影响成本按时间段的分布。
- **风险登记册**：提供已识别风险的信息，用于确定应急储备的金额。
- **协议**：合同中的价格、付款节点与激励条款直接决定部分成本与资金需求安排。
- **商业文件**：商业论证（投入产出与投资回报分析）与收益管理计划，用于验证项目财务可行性，确保预算水平与预期收益相匹配。
- **事业环境因素**：汇率、通胀率、税率、融资条件、市场环境等。
- **组织过程资产**：预算模板、会计科目、历史预算数据、预算审批流程与限额规定等。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由财务、造价与行业专家判断成本估算的合理性、确定应急储备与管理储备的合适比例、选择适合组织的融资方式、处理资金约束与预算审批中的特殊问题。
- **数据收集**：运用标杆对照，将本项目的估算与行业基准、历史类似项目进行对比，验证成本基准的合理性。
- **数据分析**：主要是储备分析——评估已识别风险的应急储备与未识别风险的管理储备金额是否充足；也可进行生命周期成本分析、S曲线分析等。
- **成本汇总**：按WBS结构把工作包的成本估算逐层汇总到控制账户，再汇总到项目总成本，形成成本基准的基础数据。
- **资金限制平衡**：当成本基准与资金限额冲突时，通过调整工作包的进度安排（推迟或提前）使各期支出曲线不超出资金限额，必要时须重新协商范围或资金，而不是简单地削减成本。
- **融资**：确定项目资金的外部融资来源（如银行贷款、股权融资、客户预付款、信用证、政府拨款），明确资金到位的时间与方式，支持分阶段资金需求的规划。
- **会议**：召开预算审查会议，就成本基准、项目资金需求、储备分配达成共识，并取得发起人或管理层的正式批准。`,
      "📤 输出 Outputs": `- **成本基准**：已批准的按时间段分配的项目预算版本，通常以S曲线表示，包含应急储备但不包含管理储备，其数值等于BAC（完工预算），是EVM绩效测量与变更控制的基准。
- **项目资金需求**：包含总资金需求与分阶段资金需求，通常按年度或季度细分，说明资金何时到位；其数额等于成本基准加管理储备，往往高于成本基准，由发起人或融资机构批准。
- **项目文件更新**：如风险登记册（更新储备相关信息）、成本估算（如有调整）等，使项目文件与批准的基准保持一致。`,
      "🔗 与其他过程的相互作用": `制定预算承接估算成本过程输出的成本估算与估算依据，经成本汇总与储备分析形成成本基准；输出的成本基准是监控财务过程EVM测量的基准，输出的项目资金需求交由发起人或融资机构审批放款。成本基准在项目实施中受严格变更控制约束，任何调整都必须通过正式变更请求并经批准。制定预算还与范围、进度、资源、风险、采购规划联动：范围变更会改变成本汇总对象，进度压缩影响资金的时段分配，风险登记册决定应急储备额度，采购协议价格决定部分资金需求。此外，制定预算的批准层级与授权通常由组织财务制度规定，预算审查会议的结果（如调整后的储备或资金安排）会反馈到风险登记册与假设日志。`,
      "✂️ 裁剪考虑": `- **预测型项目**：一次性建立完整成本基准与资金需求，变更控制严格，S曲线固定。
- **适应型（敏捷）项目**：通常按季度滚动预算，成本基准分阶段批准，重点关注已交付价值的货币化，管理储备可按季度评审调整。
- **组织财务制度**：政府与国企项目资金需求须符合财政拨付节奏；私营项目可采用融资杠杆与分期付款。
- **项目规模**：大型项目按控制账户细分成本基准以加强管控；小型项目可简化成本汇总层级与报告。`,
      "💼 实践案例": `某制造企业新品开发项目，估算成本总计800万元。项目经理将各工作包成本自下而上汇总后，通过储备分析确定应急储备100万元，得到成本基准900万元（BAC）；加上管理层保留的管理储备150万元，项目资金需求总额为1,050万元。然而客户资金到位节奏为上、下半年各400万元，项目经理通过资金限制平衡，将部分工作包进度后移，使季度支出不超出资金限额，最终形成经批准的S曲线成本基准与分阶段资金需求，提交财务委员会审批放款。`,
    },
    keyConcepts: `- **成本基准**：已批准的按时间段分配的项目预算版本，不含管理储备、含应急储备，等于BAC，用于EVM测量与变更控制。
- **BAC（完工预算）**：=成本汇总+应急储备=成本基准，即经批准的总预算。
- **项目资金需求**：=成本基准+管理储备，分总资金需求与分阶段资金需求。
- **应急储备**：应对已知-未知风险，项目经理可直接使用，包含在成本基准中。
- **管理储备**：应对未知-未知风险，由管理层控制，不包含在成本基准中，项目经理需申请才能使用。
- **成本汇总**：WBS工作包→控制账户→项目总成本的逐层累加。
- **资金限制平衡**：在资金有限条件下调整工作安排的预算与进度协调。
- **融资**：确定项目资金来源（贷款、预付款、拨款等）与到位时间。`,
    examTips: `- 必考等式链：成本汇总+应急储备=成本基准=BAC；成本基准+管理储备=项目资金需求。
- 应急储备（已知-未知，项目经理直接使用）vs 管理储备（未知-未知，管理层控制，项目经理需申请）是高频对比题。
- 成本基准只允许通过正式变更控制程序修改，任何直接改动都是错误的做法。
- 资金限制平衡的做法是“调整工作安排（进度）使支出不超过资金限额”，优先调整进度而非削减范围。
- 成本基准用于EVM绩效测量；项目资金需求由管理层/发起人批准，二者数值不同，注意区分。
- 融资指确定资金来源（贷款、客户预付款、政府拨款等），与成本估算、储备分析是两个不同概念。`
  },
  "proc-monitor-finance": {
    overview: `【过程概述】监控财务过程（Monitor Finances）旨在，监督项目财务状况，更新项目财务信息，管理成本基准和收入预测的变更，并确保项目可交付物在整个项目生命周期内保持其财务可行性。该过程的关键收益是，使利益相关方能够了解项目的当前财务状态，并确认为解决任何财务绩效问题所采取的措施。

挣值管理（EVM）是监控财务的核心工具，它将范围、进度和成本整合在一起进行综合绩效测量。核心指标包括：PV（计划价值）、EV（挣值）、AC（实际成本），以及派生指标：SV=EV-PV（进度偏差）、CV=EV-AC（成本偏差）、SPI=EV/PV（进度绩效指数）、CPI=EV/AC（成本绩效指数）。当CV>0或CPI>1时，项目成本节约；当CV<0或CPI<1时，项目成本超支；当CV=0或CPI=1时，成本符合计划。

监控财务还包括：完工预测（EAC与ETC的多种计算）、趋势分析、储备分析（判断剩余应急储备是否充足）、TCPI（完工尚需绩效指数）以及完工百分比规则的应用，并评估各类变更请求对财务的影响，必要时批准或拒绝变更以维持项目的财务可行性。同时，监控财务也关注收入端（合同回款、预付款、融资流入）的实现情况，确保收入与支出节奏匹配，使项目自始至终保持财务可持续性。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：成本管理计划（提供控制临界值、测量规则与报告要求）、成本基准（EVM测量的基线）等。
- **项目文件**：如资源需求、假设日志、估算依据等，用于支持偏差解释与储备分析。
- **工作绩效数据**：项目执行中收集的原始数据，如实际成本、已花费工时、实际完成百分比、已收入款项，是财务测量的原始输入。
- **协议**：合同中的付款条款、成本约束、奖惩机制与成本补偿方式，直接影响财务监控与预测。
- **事业环境因素**：汇率、利率、通胀、市场行情等外部条件影响对财务状态与预测的判断。
- **组织过程资产**：财务报告模板、会计制度、历史绩效数据、行业基准与成本控制程序等。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具备成本与财务管理经验的人员解释偏差原因、评估预测合理性、选择纠正措施。
- **数据分析**：监控财务最核心的工具组，包括：
  - **挣值管理（EVM）**：计算PV、EV、AC及派生指标SV、CV、SPI、CPI，通过挣值、偏差、绩效指数、预测四类测量进行综合绩效测量；
  - **完工预测（EAC/ETC）**：基于当前绩效预测完工总成本与剩余工作成本；
  - **趋势分析**：用回归分析等方法预测未来偏差的走向，判断偏差是收窄还是扩大；
  - **储备分析**：比较剩余应急储备与剩余风险敞口，判断储备是否充足；
  - **TCPI**：计算剩余工作必须达到的绩效效率，用于判断剩余预算是否可行；
  - **完工百分比规则**：如50/50、0/100、20/80、100/100等，统一EV的计算口径，保证测量的一致性。其中50/50规则指任务开始即计入50%挣值、完成后再计入其余50%；0/100规则指任务完成后才计入全部挣值；该规则在无法准确判断中间完成度时，确保EV计算的客观与一致。
- **决策**：当偏差超出控制临界值时，选择纠正措施与预防措施，或形成正式变更请求。
- **会议**：召开状态审查会，向干系人汇报财务状态，评审偏差原因、纠正行动与预测结果。`,
      "📤 输出 Outputs": `- **工作绩效报告**：将财务测量结果（EVM指标、偏差、绩效指数、完工预测）按报告格式整理后分发给干系人，如成本绩效报告与完工预测报告，是干系人了解项目财务状态的主要载体。
- **变更请求**：当偏差超出控制临界值、需调整成本基准或资金安排时提出变更请求（纠正措施、预防措施、缺陷补救或计划更新），经CCB等批准后实施，形成闭环。`,
      "🔗 与其他过程的相互作用": `监控财务处于监控过程组财务域。它接收执行过程产生的工作绩效数据与协议信息，结合制定预算输出的成本基准进行EVM测量，输出工作绩效报告与变更请求。变更请求经批准后，触发成本基准、预算或计划的更新，形成“测量—分析—纠正—更新”的闭环。监控财务与监控进度过程联动：SPI影响EAC的第三种算法与TCPI判断；与监控收益衔接：收入预测与成本状态共同决定项目财务可行性；与监控风险联动：储备消耗、风险发生状态与财务预测相互影响。此外，监控财务与采购管理联动，采购付款节点与合同索赔会影响实际成本与现金流；与质量管理联动，返工与缺陷成本会直接影响CV与CPI。`,
      "✂️ 裁剪考虑": `- **预测型项目**：全面使用EVM四类测量（挣值、偏差、绩效指数、预测），控制临界值较紧，报告严格。
- **适应型（敏捷）项目**：以功能、故事点为基础的轻量挣值（如基于已完成故事点计算SPI/CPI），更关注价值交付与燃尽图、燃起图，而非细粒度的成本EVM。
- **混合型项目**：核心阶段用完整EVM，探索阶段用迭代速度与预算速率跟踪。
- **小型项目**：可简化为实际成本与预算的对比分析，不必部署完整EVM体系。`,
      "💼 实践案例": `某项目BAC为1,000万元，第6个月检查时：PV=500万元、EV=450万元、AC=540万元。计算得：SV=EV-PV=-50万元（进度落后）、CV=EV-AC=-90万元（成本超支）、SPI=0.90、CPI=0.833。项目经理分析认为成本超支由一次性的返工事件造成（非典型偏差），采用EAC=AC+(BAC-EV)=540+550=1,090万元预测完工成本，并计算剩余工作的必需效率TCPI=(BAC-EV)/(BAC-AC)=550/460≈1.196，即剩余工作必须以约120%的效率完成。据此提出纠正措施与变更请求，并更新成本预测报告上报发起人。`,
    },
    keyConcepts: `- **EVM核心公式**：PV（计划价值）、EV（挣值）、AC（实际成本）；SV=EV-PV、CV=EV-AC、SPI=EV/PV、CPI=EV/AC。
- **EAC四种算法**：①非典型（当前偏差不持续）EAC=AC+(BAC-EV)；②典型（偏差持续）EAC=BAC/CPI；③进度与成本同时受限EAC=AC+[(BAC-EV)/(CPI×SPI)]；④自下而上重新估算EAC=AC+ETC。
- **ETC两种**：基于非典型ETC=BAC-EV；基于典型ETC=(BAC-EV)/CPI；也可自下而上重新估算。
- **TCPI两种变体**：基于BAC的TCPI=(BAC-EV)/(BAC-AC)；基于EAC的TCPI=(BAC-EV)/(EAC-AC)。
- **完工百分比规则**：50/50、0/100、20/80、100/100等，用于统一EV的计算口径。
- **储备分析**：判断剩余应急储备是否足以应对剩余风险。
- **趋势分析**：用回归分析等方法预测偏差的未来走向。`,
    examTips: `- EVM核心公式必须背熟：SV=EV-PV、CV=EV-AC、SPI=EV/PV、CPI=EV/AC。
- CPI>1表示节约、CPI<1表示超支；SPI>1表示提前、SPI<1表示落后。注意CPI>1是“好”的，容易与直觉混淆。
- EAC四种算法要能根据情景选择：当前偏差不持续用非典型AC+(BAC-EV)；偏差持续用典型BAC/CPI；进度也受制约用AC+[(BAC-EV)/(CPI×SPI)]。
- ETC=EAC-AC；或ETC=(BAC-EV)/CPI（典型）、ETC=BAC-EV（非典型）。
- TCPI两种变体：当认为BAC可达成时用基于BAC的TCPI=(BAC-EV)/(BAC-AC)；当BAC已不可实现时用基于EAC的TCPI=(BAC-EV)/(EAC-AC)。
- 完工百分比规则（50/50、0/100等）决定EV的计算基础，题目常隐含默认规则。
- 管理储备不计入EVM测量，因为成本基准不含管理储备。
- TCPI与CPI的关系是经典考点：当TCPI>CPI时，剩余工作需要的效率高于当前效率，预算可能难以达成；当TCPI=1时，剩余工作按计划效率即可完成。
- 项目成本超支时，应首先识别偏差原因，再选择纠正措施或提出变更请求，不能未经变更控制就修订成本基准。`
  },
  "proc-identify-stakeholders": {
    overview: `【过程概述】
- **过程定位**：识别利益相关方（Identify Stakeholders）是启动过程组中的第二个过程，紧接在制定项目章程之后。本过程旨在识别能够影响项目决策、活动或结果，或会被项目所影响（包括正面与负面影响）的个人、群体或组织（统称"利益相关方"），并分析、记录其利益、参与程度、相互依赖性、影响力以及对项目成功的潜在影响。
- **关键收益**：本过程的核心收益是帮助项目团队建立清晰的干系人全景图，从而确定在争取每位或每类利益相关方时应关注的优先级和重点，避免"眉毛胡子一把抓"式地平均用力。
- **执行频率**：识别利益相关方"根据需要在整个项目期间定期实施"，它不是一次性的启动活动。随着项目环境演变、团队组成变化、新参与者出现，干系人清单需要持续刷新。持续的利益相关方识别本身就是一种风险管理策略——早识别、早分析、早应对，可显著降低项目后期因遗漏关键干系人而引发的冲突与返工。
- **干系人的构成**：利益相关方通常分为内部与外部两类。内部利益相关方包括发起人、项目经理、项目团队成员、职能经理、PMO等；外部利益相关方包括客户、最终用户、供应商、卖主、监管机构、政府、社区、行业组织等。其中发起人（Sponsor）是提供资源与支持、为项目背书的个人或团体，通常是最重要的内部干系人之一，其信息会写入项目章程。
- **核心工具**：本过程的核心工具包括权力/利益方格（Power/Interest Grid）——按权力与利益两个维度将干系人分成四类；凸显模型（Salience Model）——从权力、合法性与紧迫性三个维度评估干系人的重要性。这些分析工具的输出最终汇入利益相关方登记册，为后续规划干系人争取和规划沟通管理奠定事实基础。`,
    details: {
      "📥 输入 Inputs": `- **商业论证（Business Case）**：说明项目立项的经济合理性与价值理由，可据此判断哪些人或组织在项目成功中拥有既得利益，是识别干系人的起点文档。
- **项目章程（Project Charter）**：由发起人签发，授权项目经理并确立项目高层级需求与主要干系人信息，为识别干系人提供权威的项目背景与边界，识别活动须在章程批准后进行。
- **项目管理计划（Project Management Plan）**：具体指其中的沟通管理计划和干系人参与计划等组件，说明组织打算如何与干系人沟通和互动，帮助判断各类干系人在沟通与参与上的既有安排。
- **项目文件（Project Documents）**：包括变更日志（揭示谁提出过变更、影响谁）、问题日志（记录阻碍项目的问题及其相关方）、经验教训登记册（沉淀以往项目的干系人识别经验）、需求文件（列出需求提出方），都是干系人识别的信息源。
- **协议（Agreements）**：包括合同、谅解备忘录、服务协议等，其当事方（客户、卖主、分包商、合作方）都是天然的关键干系人，协议内容还规定了各方权责与沟通渠道。
- **事业环境因素（EEF）**：组织文化、治理结构、行业监管要求、市场条件等内外部环境因素，决定了干系人的行为动机与约束边界（例如受监管行业会强制将监管机构纳入干系人清单）。
- **组织过程资产（OPA）**：以往项目的干系人登记册、经验教训、组织政策、模板等，为快速识别同类项目的典型干系人提供参考。`,
      "🔧 工具与技术 Tools": `- **专家判断（Expert Judgment）**：由项目经理、发起人、高层管理人员、职能经理、主题专家等具备项目与行业经验的人，辅助识别干系人清单、评估干系人影响并选择分析维度。
- **数据收集（Data Collection）**：通过问卷调查（向大范围群体收集干系人态度与期望）和头脑风暴（召集团队与专家发散式列举潜在干系人）两类技术系统化汇集干系人信息。
- **数据分析（Data Analysis）**：核心是干系人分析（Stakeholder Analysis）——系统梳理干系人名单及其利益、期望、影响力和参与程度，为选择合适的管理策略提供依据。
- **数据表现（Data Representation）**：即干系人映射工具家族，将分析结果可视化，包括：
  - **权力/利益方格**：按"权力（对项目的影响力）"与"利益（对项目结果的关注度）"把干系人分为四象限（高权力高利益、高权力低利益、低权力高利益、低权力低利益），是最常用的分类工具。
  - **权力/影响方格**：用"权力"与"对项目的直接参与/影响程度"两个维度分类，适合评估干系人在具体决策中的权重。
  - **影响/利益方格**：用"影响（参与度）"与"利益"两个维度分类，适合了解干系人对项目的兴趣及行动参与。
  - **相关方立方体（Stakeholder Cube）**：把权力、影响、利益三个维度组合成立方体模型，形成更精细的三维分类。
  - **凸显模型（Salience Model）**：从权力（Power）、合法性（Legitimacy，与项目的合法关系或权责）与紧迫性（Urgency，需求的时间敏感性）三个维度评估干系人的"凸显度"，用多个区域（如支配型、危险型、依赖型等）刻画其在优先级阶梯上的位置，特别适合干系人众多、需快速收敛重点的场景。
  - **影响方向（Directions of Influence）**：按干系人影响力的作用方向分类——向上（对高层/发起人）、向下（对团队成员）、向外（对客户、供应商等外部相关方）、侧向（对同级人员如项目经理同伴），用于规划沟通与争取路径。
  - **优先级排序（Prioritization）**：结合权力、利益等维度对干系人排序，把有限的团队精力优先投向影响大、利益高的少数关键干系人。
- **人际关系与团队技能（Interpersonal and Team Skills）**：包括利益冲突管理（识别并处理团队/干系人之间彼此竞争或对立的利益，确保决策不被个人利益绑架）以及观察与交谈、政治意识等人际技巧，帮助团队更敏锐地理解干系人立场。
- **会议（Meetings）**：通过干系人识别研讨会、分组讨论、一对一访谈等会议形式，汇集跨部门观点，验证干系人清单并共同商定分析结果。`,
      "📤 输出 Outputs": `- **利益相关方登记册（Stakeholder Register）**：本过程的核心输出，记录所有已识别干系人的关键信息，通常包含三大要素——①身份信息（姓名、职位、部门、联系方式、角色）；②评估信息（期望、潜在影响、参与项目的阶段、对项目成功的兴趣强度）；③分类（内部/外部、支持者/中立者/抵制者等）。登记册是规划干系人争取和规划沟通管理的直接输入。
- **变更请求（Change Requests）**：当识别过程中发现项目范围、计划或章程需要调整（例如发现新的法规合规要求）时，提出变更请求走变更控制流程，经批准后更新相应计划。
- **项目管理计划更新（PM Plan Updates）**：若识别结果影响到既定的计划安排，可更新项目管理计划的相应组件（如干系人参与计划）。
- **项目文件更新（Project Documents Updates）**：包括假设日志（补充与干系人相关的假设）、问题日志（登记新发现的干系人相关问题）、风险登记册（把立场对立或期望未满足的干系人视为潜在风险）。`,
      "🔗 与其他过程的相互作用": `- 本过程位于启动过程组的"制定项目章程 → 识别利益相关方"链路上，需以已批准的项目章程为起点和边界，章程中记录的发起人与高层级干系人信息是识别的首批对象。
- 其输出利益相关方登记册直接作为规划干系人争取、规划沟通管理等规划过程的主要输入，使后续的参与策略与沟通计划建立在真实干系人画像之上。
- 在执行与监控阶段，干系人相关信息的变化会触发对干系人登记册、参与计划、沟通计划的更新，形成"识别→规划→执行→监督→再识别"的持续闭环。
- 反过来，监督干系人争取过程中发现的新干系人或参与度缺口，又会回到本过程补充识别。`,
      "✂️ 裁剪考虑": `- **预测型项目**：通常在项目启动和主要阶段开始时做一次系统性识别，并在里程碑节点定期复查，识别方式偏正式（研讨会、访谈、专家评审）。
- **适应型（敏捷）项目**：干系人识别贯穿每个迭代，依赖与产品负责人、客户代表的高频互动，识别方式轻量且持续；用户与业务干系人常在迭代评审中实时涌现。
- **混合型项目**：对核心阶段采用预测式完整识别，对迭代部分保持持续增量识别。
- **跨文化/跨国项目**：需额外考虑文化背景、时区、语言差异对干系人分类与沟通的影响，识别会议宜按时区错开安排。
- **监管严格的行业（医疗、金融、核电）**：监管机构几乎必为高凸显干系人，应提前纳入并倾斜资源。`,
      "💼 实践案例": `某制造企业实施ERP系统升级项目。项目启动后，项目经理组织识别研讨会，先用头脑风暴列出包括发起人（财务副总裁）、各部门负责人、一线操作员、供应商、工会、外部审计机构在内的约30名潜在干系人；再用权力/利益方格把他们分为四类：财务副总裁与运营总监为高权力高利益（重点管理），IT部门负责人为高权力低利益（令其满意），一线操作员为低权力高利益（随时告知、收集反馈），工会为低权力低利益（监督即可）。项目中期因新增数据合规要求，团队重新启用凸显模型，识别出外部审计机构具有高权力、高合法性、高紧迫性，属"支配型"干系人，随即将其登记入册并调整沟通频率，避免了一次潜在的合规事故。`,
    },
    keyConcepts: `- **利益相关方登记册**：记录已识别干系人的关键信息，含身份信息、评估信息（期望、影响、利益）与分类三大要素，是干系人管理的基础工件。
- **权力/利益方格**：按权力（影响力）与利益（关注度）两个维度把干系人划分为四类，指导差异化争取策略。
- **凸显模型**：从权力、合法性、紧迫性三个维度评估干系人重要性，适用于干系人数量庞大、需快速收敛重点的场景。
- **干系人映射工具家族**：包括权力/影响方格、影响/利益方格、相关方立方体、凸显模型、影响方向、优先级排序，统称数据表现技术。
- **内部/外部干系人**：内部含发起人、项目经理、团队成员、职能经理等；外部含客户、最终用户、供应商、监管机构、社区等。
- **沟通渠道数**：n个干系人之间的沟通渠道数为 n×(n-1)/2，用于评估干系人沟通复杂度。`,
    examTips: `- **权力/利益方格是高频考点**：记住四象限对应策略——高权力高利益=重点管理，高权力低利益=令其满意，低权力高利益=随时告知，低权力低利益=监督即可。
- **凸显模型三维度**：权力（Power）、合法性（Legitimacy）、紧迫性（Urgency），缺一不可；考题常给干系人场景让你判断其凸显度。
- **区分映射工具**：权力/利益方格（最常用）、权力/影响方格（决策影响）、影响/利益方格（参与度）、相关方立方体（三维）、凸显模型（加入合法性）、影响方向（向上/下/外/侧向）——注意每种工具的维度组合。
- **识别是持续过程**：干系人识别"贯穿整个项目生命周期"，不是启动阶段做一次就完事；选择"一次性即可"的选项是陷阱。
- **登记册三要素**：身份信息、评估信息、分类——缺一不可。
- **发起人是关键干系人**：提供资源与背书，通常出现在章程中。
- **沟通渠道数=n(n-1)/2**：干系人从n增加到n+1时，渠道数新增n条。`
  },
  "proc-plan-stakeholder-engagement": {
    overview: `【过程概述】
- **过程定位**：规划利益相关方争取（Plan Stakeholder Engagement）属于规划过程组，紧跟在识别利益相关方之后，是"干系人管理"链路上把"知道有哪些干系人"推进到"想好怎么争取他们"的关键一步。本过程基于已识别干系人的需要、期望、利益、需求和潜在影响，制定一套争取干系人有效参与的策略。
- **关键收益**：提供一份与干系人进行有效互动的可行计划（利益相关方参与计划），使团队明确"谁最需要关注、争取到什么程度、用什么方式争取"，避免凭感觉应对干系人。
- **执行频率**：根据需要在整个项目期间定期实施——干系人清单一变，参与计划就要跟着调整。
- **核心工具**：利益相关方参与度评估矩阵（Stakeholder Engagement Assessment Matrix）是本过程的标志性工具，将每位干系人的"当前参与度"与"期望参与度"进行逐行比对。
- **参与度五级**：不知晓（Unaware）→抵制（Resistant）→中立（Neutral）→支持（Supporting）→领导（Leading）。五级的含义分别为：不知晓——不了解项目及其潜在影响；抵制——了解项目但抵制变更；中立——了解项目但既不支持也不反对；支持——了解项目并支持变更；领导——积极参与以确保项目成功。
- **过程本质**：推动干系人从当前参与度向期望参与度移动，两者之间的差距就是需要填补的工作量；对高权力高利益的干系人要重点管理，对低权力低利益的干系人监控即可。
- **计划的内容**：利益相关方参与计划要回答"对每位干系人采取什么争取策略、行动由谁负责、资源与预算如何安排、何时评审更新"。它把干系人登记册中的静态画像转化为可执行的日常行动，并随参与度评估结果动态调整。
- **与沟通计划的配合**：参与计划定义"要争取到什么程度"（战略），沟通计划定义"如何传递信息"（战术）。参与计划中为某干系人设定的参与度目标，直接决定沟通计划为该干系人安排的信息类型、频率与渠道；两者需要同步制定、配套修订。
- **区分"参与计划"与"沟通计划"**：参与计划聚焦"战略与行动（凭什么、做什么、谁负责）"，沟通计划聚焦"信息传递（说什么、何时说、怎么说）"，两者互补但不等同——沟通计划只是参与计划的战术实现手段之一。`,
    details: {
      "📥 输入 Inputs": `- **项目章程（Project Charter）**：提供项目高层级描述、主要干系人与发起人信息，作为界定各干系人角色与参与策略的基准。
- **项目管理计划（Project Management Plan）**：主要读取其中的资源管理计划（团队构成与能力）、沟通管理计划（既定的沟通安排）和风险管理计划，确保参与策略与这些计划保持一致。
- **项目文件（Project Documents）**：其中干系人登记册是本过程最关键的输入（提供每位干系人的身份、评估与分类信息，直接决定参与策略的针对性）；另有假设日志（干系人相关假设）、变更日志、问题日志、需求文件、进度计划、风险登记册、干系人评估结果等，共同构成参与策略的事实基础。
- **协议（Agreements）**：合同与协议规定了关键干系人（客户、卖主）的参与义务与协作条款，参与计划须与之对齐，避免承诺超出合同约定的参与投入。
- **事业环境因素（EEF）**：组织文化、组织结构、政治氛围、干系人参与的政策与工具平台等，决定参与方式的可行边界；例如等级森严的组织中，正式汇报比开放式讨论更有效。
- **组织过程资产（OPA）**：以往项目的参与计划模板、经验教训、干系人参与的最佳实践，为设计策略提供参考，避免重复踩坑。`,
      "🔧 工具与技术 Tools": `- **专家判断（Expert Judgment）**：项目经理、干系人代表、组织高层、主题专家结合经验判断每位干系人应争取到何种参与度以及如何争取。
- **数据收集（Data Collection）**：包括标杆对照（Benchmarking，参考其他项目/组织在干系人参与上的做法）和问卷调查（了解干系人当前态度与期望），为参与度评估提供一手数据。
- **数据分析（Data Analysis）**：核心是假设与制约因素分析（Assumption and Constraint Analysis）——识别并验证影响干系人参与的假设与制约条件（如组织政策、资源限制），避免参与策略建立在错误前提上。
- **决策（Decision Making）**：包括优先级排序（Prioritization，把注意力投向最重要的干系人）和多标准决策分析（Multi-Criteria Decision Analysis，用多个标准——如权力、利益、影响、紧迫性——对干系人或策略方案加权评分排序），是科学排序的关键工具。
- **数据表现（Data Representation）**：包括思维导图（厘清干系人之间的关系网络）与干系人参与度评估矩阵——矩阵的行是干系人，列是五级参与度（不知晓/抵制/中立/支持/领导），在每位干系人的当前级与期望级处做标记，直观呈现差距；例如某干系人当前为"中立"而期望为"支持"，矩阵中这两个格子之间的空缺就是参与计划要安排行动填补的地方。
- **人际关系与团队技能（Interpersonal and Team Skills）**：包括冲突管理（处理干系人之间的利益冲突，避免项目陷入僵局）、谈判（就参与方式达成共识）、观察与交谈（洞察干系人真实立场）、沟通技巧（为不同风格干系人设计不同互动方式）。
- **会议（Meetings）**：通过干系人参与规划研讨会、头脑风暴会召集各方共同商定参与目标与行动，把干系人代表纳入规划过程，既提高计划的可执行性，也是一次天然的争取动作。`,
      "📤 输出 Outputs": `- **利益相关方参与计划（Stakeholder Engagement Plan）**：本过程的唯一主要输出，也是核心输出。它是项目管理计划的组件之一，详细描述针对每位或每类干系人的争取策略与行动，内容包括：争取策略（如推动某干系人从中立到支持）、当前参与度与期望参与度、计划采取的互动/沟通行动、关键干系人的管理重点（如对高权力高利益干系人重点管理）、预算与资源、更新时机等。它决定了团队"如何争取"干系人，是沟通管理计划的战略性上游。`,
      "🔗 与其他过程的相互作用": `- 上游衔接识别利益相关方——以干系人登记册为输入，把"认识干系人"转化为"争取干系人"。
- 下游输出利益相关方参与计划，作为规划沟通管理的输入之一：参与计划定战略（争取到哪一级），沟通计划定战术（如何传递信息），两者配合保证干系人信息与参与策略的一致。
- 在执行过程组中，干系人争取（Manage Stakeholder Engagement）按照参与计划开展互动；监督干系人争取（Monitor Stakeholder Engagement）用参与度评估矩阵比对实际与期望参与度，缺口反馈回来触发参与计划的修订，形成"规划→执行→监督→再规划"的闭环。
- 风险管理也与本过程相互影响：低参与度或立场对立的干系人往往被登记为项目风险，其风险应对措施也可能反过来要求调整参与策略（例如把关键干系人的负面态度转化为缓解措施）。
- 与资源管理相互配合：参与计划中安排的座谈会、培训、一对一汇报等行动需要人力与预算，须与资源管理计划协调排期，避免计划落不了地。`,
      "✂️ 裁剪考虑": `- **预测型项目**：参与计划较为正式、详尽，常一次性制定并在里程碑节点复查。
- **适应型（敏捷）项目**：干系人参与通过迭代评审、每日站会等高频接触自然展开，参与计划更轻量，随每次迭代动态调整。
- **混合型项目**：对关键干系人（发起人、客户）采用正式参与计划，对迭代内干系人保持轻量持续争取。
- **干系人规模差异**：干系人少时用简化参与计划；干系人众多时必须用优先级排序聚焦核心，避免资源稀释。
- **跨文化项目**：参与方式须适配文化差异（如等级观念、沟通偏好），避免"一刀切"策略。`,
      "💼 实践案例": `在上一例ERP升级项目中，干系人登记册显示一线操作员（低权力高利益）当前参与度为"不知晓"，期望为"支持"。项目经理在利益相关方参与计划中为该群体安排：每月一场操作员座谈会（交互式沟通）、上岗前针对性培训、设立意见反馈通道，推动他们从"不知晓"逐步走向"支持"。而对高权力高利益的财务副总裁，计划安排每周一次一对一汇报、关键决策邀请其参与评审，维持"领导"级参与。项目评审时用参与度评估矩阵比对，发现财务副总裁滑落到"支持"级，团队随即触发计划调整，增补月度经营分析会参与安排，将参与度拉回"领导"级。`,
    },
    keyConcepts: `- **利益相关方参与度评估矩阵**：把每位干系人的当前参与度与期望参与度逐行比对的可视化矩阵，五级为不知晓→抵制→中立→支持→领导，矩阵中的空缺就是参与计划的工作清单。
- **五级参与度**：不知晓（不了解项目及影响）、抵制（了解但抵制）、中立（了解但不支持也不反对）、支持（了解并支持）、领导（积极投身项目成功）。
- **参与度差距**：当前参与度与期望参与度之差，就是参与计划需要填补的工作量，是制定行动的依据。
- **多标准决策分析**：用多个标准对干系人或备选策略加权评分，辅助优先级排序，确保有限资源投向最关键干系人。
- **优先级排序**：结合权力、利益、影响等维度排出干系人的优先关注顺序，是"重点管理少数、监督多数"原则的操作化。
- **利益相关方参与计划**：描述每位干系人的参与策略与行动，是项目管理计划的组件之一，随项目进展动态修订。
- **参与计划≠沟通计划**：参与计划管"战略与行动"，沟通计划管"信息传递"，两者互补；沟通计划是参与计划目标达成的战术手段。`,
    examTips: `- **五级参与度是必背内容**：不知晓（Unaware）→抵制（Resistant）→中立（Neutral）→支持（Supporting）→领导（Leading），题目常考顺序或给定状态判断等级。
- **核心是填差距**：参与计划的目标是把干系人从当前参与度推到期望参与度，考题常问"某干系人当前中立、期望支持，应该怎么做"——答案指向针对性争取行动。
- **"参与计划=沟通计划"是陷阱**：两者不同，参与计划聚焦争取策略，沟通计划聚焦信息传递；沟通计划只是参与计划的战术实现之一。
- **多标准决策/优先级排序**：在干系人众多、资源有限时使用，考试常考其目的（聚焦关键干系人、科学排序）。
- **输出只有参与计划一个主要工件**：利益相关方参与计划是项目管理计划组件，不是独立文件。
- **监督干系人争取用同一矩阵**：监控阶段用参与度评估矩阵比对实际与期望参与度，发现缺口回到规划过程修订参与计划。`
  },
  "proc-plan-communications": {
    overview: `【过程概述】
- **过程定位**：规划沟通管理（Plan Communications Management）属于规划过程组，旨在规划如何与团队内外已识别的利益相关方进行沟通，即回答"谁需要什么信息、何时需要、通过什么渠道获取、由谁提供、多久一次"这五个核心问题。
- **与干系人管理的关系**：沟通规划与干系人识别、分析、优先级排序和争取存在重叠，并与利益相关方争取计划密切对应，有助于确保沟通策略的一致性——先定"要争取谁"，再定"怎么和他说话"。
- **关键收益**：提供一份既考虑干系人信息需求、又兼顾组织可用沟通技术与方法的可行性沟通计划，避免"信息过载"或"信息缺失"两个极端，让正确的人在正确的时间获得正确的信息。
- **执行频率**：根据需要在项目期间定期实施；干系人画像或组织环境发生变化时需重新规划。
- **核心内容**：沟通需求分析（判断谁需要什么信息）、沟通渠道数 n×(n-1)/2（评估沟通复杂度）、沟通技术（同步/异步）、沟通模型（发送方→编码→媒介→噪声→解码→接收方→反馈→回应）、沟通方法（交互式/推送式/拉取式）、5C沟通原则（Correct/Concise/Clear/Coherent/Controlling）。
- **有效沟通vs高效沟通**：有效沟通（Effective Communication）指信息被正确理解、内容本身正确；高效沟通（Efficient Communication）指用合适的方式、在合适的时间把合适的信息传递给合适的人，避免过度与冗余沟通。两者的目标可以兼得：规划阶段通过沟通需求分析和5C原则，既保证信息准确无歧义（有效），又按需定制渠道与频率（高效）。
- **信息维度**：沟通内容可按多个维度梳理——内部（团队内）与外部（客户、供应商、监管）；纵向（上下级）与横向（同级部门）；正式（报告、评审）与非正式（口头、即时消息）；书面与口头。规划时要为每个信息流指明归属，避免信息在错误的维度上流动。`,
    details: {
      "📥 输入 Inputs": `- **项目章程（Project Charter）**：提供项目目标与主要干系人信息，界定沟通要服务的项目目的。
- **项目管理计划（Project Management Plan）**：主要读取资源管理计划（团队规模、集中/虚拟办公）与干系人参与计划（希望干系人达到的参与度），沟通计划须与之协调。
- **项目文件（Project Documents）**：干系人登记册是本过程最关键的输入，确定沟通对象及他们的信息需求；需求文件帮助了解各类需求提出方的信息期望。
- **协议（Agreements）**：合同中的报告与沟通条款（如客户要求周报、里程碑报告、验收通知）必须纳入沟通计划，否则构成违约。
- **事业环境因素（EEF）**：组织的沟通工具（邮件、即时通讯、项目管理软件）、组织结构、时区、文化差异等，决定可用沟通手段与约束。
- **组织过程资产（OPA）**：组织沟通政策、模板、以往项目的沟通计划与经验教训，为制定计划提供参考。`,
      "🔧 工具与技术 Tools": `- **专家判断（Expert Judgment）**：项目经理、干系人代表、组织沟通专家根据经验确定沟通频率、形式与内容颗粒度。
- **沟通需求分析（Communication Requirements Analysis）**：系统确定各干系人的信息需求，常结合干系人登记册、干系人参与计划和沟通渠道数公式进行；"谁需要什么信息、何时需要、由谁提供"是分析的核心句式。分析的维度包括：信息类型（决策信息、状态信息、操作信息）、信息粒度（高层看结论、执行层看细节）、信息频率、信息敏感度，以及内部/外部、纵向/横向、正式/非正式、书面/口头等分类。沟通渠道数 n×(n-1)/2 用于评估沟通复杂度——干系人越多，越需要结构化地收敛沟通需求，防止渠道爆炸。
- **沟通技术（Communication Technology）**：选择信息传递的工具手段，分为同步技术（实时互动，如面对面会议、电话、视频会议、即时消息）与异步技术（非实时，如电子邮件、文档、项目管理工具留言板）。选择依据包括信息紧迫性、工具可用性与易用性、环境敏感性、团队分布（虚拟团队需更多远程异步手段）。
- **沟通模型（Communication Models）**：基本模型为"发送方→编码→传输媒介→解码→接收方→反馈→回应"，过程中存在噪声（Noise）干扰信息。沟通的最大障碍是噪声与缺乏反馈，规划时要设计降低噪声、鼓励反馈的机制。
- **沟通方法（Communication Methods）**：交互式沟通（面对面、电话、视频会议，双方或多方实时多向交换信息，反馈最快，适合复杂讨论）；推送式沟通（邮件、报告、备忘录，发送方向特定接收者单向推送，接收者被动接受，适合通知与状态报告）；拉取式沟通（内部网、知识库、电子公告板，接收者主动访问获取，适合大量受众和非紧急信息）。
- **人际关系与团队技能（Interpersonal and Team Skills）**：包括沟通风格评估（了解自己与他人的沟通风格并调整方式）、政治意识（理解组织权力格局对信息解读的影响）、文化意识（识别文化差异对沟通的干扰）。
- **数据收集（Data Collection）**：问卷调查——向干系人收集沟通偏好与信息需求，避免"拍脑袋"定沟通方式。
- **数据分析（Data Analysis）**：干系人分析——依据干系人登记册与参与度评估判断每位干系人需要什么层次的信息（高层要决策信息、执行层要操作信息）。
- **数据表现（Data Representation）**：沟通矩阵/干系人沟通需求表格——用矩阵直观呈现干系人与信息需求、频率、渠道、责任人的对应关系。
- **会议（Meetings）**：通过规划沟通研讨会确认沟通需求、频率与渠道，把干系人代表请进规划过程，提高计划可行性。`,
      "📤 输出 Outputs": `- **沟通管理计划（Communications Management Plan）**：本过程的核心输出，也是项目管理计划的组件之一。它记录：沟通对象（谁）、需要的信息（什么）、传递时间与频率（何时）、传递渠道（如何获取）、信息提供方（由谁提供）、发送技术（用什么技术）。计划须在详细程度、格式、范围上匹配项目需求。
- **项目管理计划更新（PM Plan Updates）**：如干系人参与计划等组件可能因沟通规划的结果而调整。
- **项目文件更新（Project Documents Updates）**：需求文件、干系人登记册等可能因沟通规划补充的信息而更新。`,
      "🔗 与其他过程的相互作用": `- 上游以干系人登记册与干系人参与计划为输入：先识别、分析、排序、争取干系人，再规划与他们沟通的渠道与节奏，保证"参与战略→沟通战术"的一致性。
- 输出沟通管理计划贯穿执行过程：干系人沟通（Manage Communications）按计划发布信息、执行沟通；监督沟通（Monitor Communications）检查沟通是否按计划进行、是否有效，发现偏差触发计划修订。
- 与风险、采购、范围等计划相互影响：风险沟通、合同报告要求都要在沟通计划中统一安排，避免各自为政；范围变更后的信息发布也依赖沟通计划定义的渠道。
- 沟通计划还与资源管理配合：安排会议与报告需要资源投入，虚拟团队的异步沟通要配套协作工具与培训，这些都要在计划中体现。
- 与质量管理的衔接：项目质量报告、质量审计结论同样经由沟通计划规定的渠道传递，保证质量信息不丢失、不迟到。`,
      "✂️ 裁剪考虑": `- **预测型项目**：沟通计划详尽，正式报告（周报、月报、状态报告、里程碑报告）频率明确，变更需走计划评审。
- **适应型（敏捷）项目**：沟通高频、轻量（每日站会、迭代评审、看板、演示），正式文档少，以面对面/白板/看板为主，沟通计划简化甚至隐性内嵌于工作节奏。
- **混合型项目**：正式报告用于高层与合同相关干系人，敏捷沟通用于开发团队内部。
- **虚拟团队**：多用异步技术与结构化会议，需额外规划时区与文化协调，并明确同步窗口（如约定每日重合时间）。
- **信息敏感性**：涉密或合规项目需限制沟通渠道与受众范围，必要时加密与审批，把安全要求写进沟通计划。
- **干系人规模**：干系人少时沟通计划可精简为一张沟通矩阵；干系人众多时需按优先级分级安排频率与渠道，避免信息过载。`,
      "💼 实践案例": `继续ERP项目。项目经理依据干系人参与计划，为不同干系人设计差异化沟通：对财务副总裁（高权力高利益）——每周一次一对一电话（交互式、同步，反馈最快）；对一线操作员——每月座谈会加内网知识库FAQ（拉取式，供随时查询）；对全体项目相关方——每周邮件周报（推送式，信息广播）。沟通管理计划中明确5C要求，并规定"周报中财务数据须经财务部复核后再发布"以保证Correct（正确）。项目中期发现操作员对系统上线日期存在误解，项目经理启动监督沟通，定位为FAQ更新不及时（信息滞后/噪声），随即修订沟通计划，将FAQ更新频率改为每周两次并追加一条视频演示链接，误解得以消除。`,
    },
    keyConcepts: `- **沟通需求分析**：系统确定各干系人信息需求的工具，核心回答"谁需要什么信息、何时需要、由谁提供"，并兼顾信息类型、粒度、频率与敏感度。
- **沟通方法**：交互式（面对面、电话、视频会议，多向实时、反馈最快）；推送式（邮件、报告、备忘录，单向发送、接收者被动）；拉取式（内部网、知识库、公告板，接收方主动获取）。
- **沟通模型**：发送方→编码→媒介→噪声→解码→接收方→反馈→回应；最大障碍是噪声与缺乏反馈。
- **5C沟通原则**：Correct（正确）——内容准确无误；Concise（简洁）——信息不冗余；Clear（清晰）——无歧义；Coherent（连贯）——前后一致、有逻辑；Controlling（控制）——通过提问等方式掌控沟通效果。
- **沟通渠道数**：n×(n-1)/2，用于评估沟通复杂度。
- **同步vs异步技术**：同步=实时互动（会议、电话、视频、即时消息）；异步=非实时（邮件、文档、知识库、留言板）。
- **有效vs高效沟通**：有效=信息被正确理解；高效=以合适方式、在合适时间把合适信息给到合适的人。
- **沟通矩阵**：用表格呈现干系人与信息需求、频率、渠道、责任人的对应关系，是沟通管理计划的直观载体。`,
    examTips: `- **三种沟通方法必考**：交互式（双向、反馈最快）、推送式（发送方控制、接收者被动）、拉取式（接收方主动获取）。题目问"哪种方式反馈最好/最适合复杂讨论"——选交互式。
- **5C原则是沟通质量标尺**：Correct/Concise/Clear/Coherent/Controlling 五个词常考，题目给一句话判断违反了哪个C。
- **沟通模型中的"噪声"**：是一切沟通障碍的总称（语言、文化、时区、技术问题都算），最大障碍是噪声和缺乏反馈。
- **沟通渠道数公式 n(n-1)/2**：注意算的是"渠道数"；团队从5人增加到6人，新增渠道5条。
- **同步vs异步**：同步=实时（面对面、电话、视频、即时消息），异步=非实时（邮件、文档、知识库）；虚拟团队常搭配使用。
- **信息维度考点**：内部/外部、纵向/横向、正式/非正式、书面/口头——题目常让判断某条信息应该走哪个渠道（如高层决策信息适合正式书面+交互式确认）。
- **规划沟通≠发布信息**：规划沟通管理是规划过程，执行沟通管理（Manage Communications）才实际发布信息，题目常混淆过程归属。
- **输出陷阱**：本过程核心输出是沟通管理计划；"利益相关方参与计划"属于规划干系人争取过程的输出，选项里出现要能辨别。`
  },
  "proc-manage-stakeholder-engagement": {
    overview: `【过程概述】管理干系人争取是执行过程组中的一个过程，贯穿项目始终。其核心目的是与干系人（包括发起人在内的所有相关方）进行沟通和协作，以满足他们的需要和期望，处理他们提出的任何问题，并促进干系人在项目中的适当参与。该过程的关键收益是：帮助项目经理赢得干系人的支持，并尽可能降低来自干系人的阻力。

- **主动管理期望**：不仅要被动回应干系人提出的要求，更要主动识别、引导并管理其合理与不合理的期望，避免期望落空演变为对项目的抵制。
- **处理问题与投诉**：干系人的顾虑、投诉、意见须及时记录到问题日志并跟踪到底，不能只做口头承诺。
- **前瞻预测**：预判干系人未来可能出现的不满和潜在问题，提前介入化解，而不是等问题爆发后再救火。
- **推动积极参与**：在适当的节点让关键干系人参与审查、决策和方案选择，增强其主人翁意识与支持度。
- **差异化参与**：干系人在利益、影响力、文化背景、参与意愿上各不相同，需要“千人千面”地调整沟通方式与参与策略（正式/非正式、高频率/低频率、一对一/群体会议）。
- **关键收益**：赢得支持、降低阻力，是后续所有工作顺利开展的软环境保障。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：本过程的行动蓝图。其中干系人参与计划规定了每个干系人的所需参与级别、当前参与级别以及缩小差距的具体行动；沟通管理计划规定了向谁、何时、以何种方式沟通；变更管理计划规定了干系人诉求引发变更时的处理流程；资源管理计划提供了团队协作与冲突处理的背景。
- **项目文件**：最核心的是干系人登记册，记录干系人的身份、利益、期望、影响程度、分类及当前参与级别，是制定与调整参与策略的直接依据；还包括变更日志、问题日志、需求文件等，帮助了解项目当前状态与干系人诉求的关联。
- **事业环境因素**：组织文化与政治氛围、干系人之间的既有关系与结盟情况、组织既有的沟通渠道与信息发布惯例等，都会影响沟通与参与方式的选择。
- **组织过程资产**：组织以往项目关于干系人沟通与参与的经验教训、干系人参与程序与模板、历史问题处理记录等，可借鉴成熟做法，避免重复踩坑。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助资深项目经理、顾问或干系人本人的经验，判断干系人诉求背后的真实动机，评估参与策略的可行性，预测干系人行为走向。
- **沟通技能**：包括反馈、演示、写作、非语言技能。强调双向互动，通过“反馈”确认对方真正理解，避免单向灌输造成误解。
- **人际关系与团队技能**：本过程最核心的工具组，包含——
  - **冲突管理（Conflict Management）**：运用冲突解决五方式处理干系人之间、干系人与团队之间的分歧。①合作/解决问题（Collaborate）：双方公开坦诚地共同寻找双赢方案，是“Win-Win”的最佳方式，适用于关系重要且需长期合作的情形；②妥协/调解（Compromise）：双方各让一步、部分满足、达成暂时一致，适用于时间紧迫或双方势均力敌；③缓和/包容（Smooth/Accommodate）：求同存异、强调共同点而淡化分歧，用于维护关系优先的场合，但问题并未真正解决；④强制/命令（Force/Direct）：一方凭借职权或优势强压另一方接受，是“Win-Lose”，仅在紧急情况（安全、法律、时间极紧迫）下使用，长期使用会严重损害关系；⑤回避/退出（Withdraw/Avoid）：推迟或搁置冲突，仅在问题不重要、或双方需要时间冷静、或需第三方介入时使用。总原则：合作优先，妥协次之，强制与回避慎用。
  - **基本规则（Ground Rules）**：为沟通与协作设定行为准则，如会议纪律、反馈时限、尊重与保密约定，通常源自团队章程并延伸到干系人互动中，让参与行为可预期。
  - **谈判（Negotiating）**：与干系人就资源、优先级、期望和变更进行协商；成功的谈判关注“利益”而非“立场”，力求达成双方都能接受的结果。
  - **文化意识（Cultural Awareness）**：理解不同文化在沟通习惯、决策风格、时间观念上的差异并给予尊重，避免文化误解激化冲突。
  - **政治意识（Political Awareness）**：识别组织内的权力关系、利益联盟和非正式影响力网络，理解干系人决策背后的政治动机，从而更精准地争取支持。
  - **观察/交谈（Observation/Conversation）**：通过非正式聊天、现场观察捕捉干系人言语之外的真实态度与潜在顾虑，发现正式渠道发现不了的信号。
  - **领导力（Leadership）**：以身作则、传达愿景，引导干系人朝着项目目标共同努力。
- **会议**：包括状态评审会、干系人沟通会、问题解决会等；会前明确目的与议程，会中充分听取意见并记录，会后分发纪要并跟踪行动项落实。`,
      "📤 输出 Outputs": `- **问题日志（Issue Log）**：记录干系人提出的问题、投诉和顾虑，包括问题描述、责任人、解决方案、解决时限与当前状态。问题日志从规划阶段建立，在本过程中持续新增与更新，是跟踪干系人诉求、验证“处理了问题”的关键文档。
- **变更请求（Change Requests）**：当干系人提出新需求、范围调整或参与策略变更时，以正式变更请求的形式提交，经实施整体变更控制审批后，方可纳入计划并执行。
- **项目管理计划更新**：主要是干系人参与计划、沟通管理计划、风险管理计划的更新——根据干系人态度变化与参与效果，调整参与策略与沟通安排。
- **项目文件更新**：包括干系人登记册（更新参与级别、态度、影响评估）、问题日志（增补新问题）、经验教训登记册（记录干系人沟通与参与的经验）等。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：从识别干系人过程获得干系人名单与分类，从规划干系人参与过程获得干系人参与计划与干系人参与评估矩阵，本过程就是把这些计划“落地执行”。
- **横向协同**：与指导与管理项目工作（提供项目状态与交付成果）、管理沟通（分发信息并获取反馈）、建设团队（团队内部协作与凝聚力）相互支撑，共同构成执行过程组的主体活动。
- **下游衔接**：本过程产生的问题日志、变更请求、更新后的登记册与计划，是监督干系人参与过程监控评估的输入；监督过程发现的参与度问题又反过来推动本过程调整参与策略。如此形成“规划→执行→监控→调整”的管理闭环，保证干系人参与不断优化。`,
      "✂️ 裁剪考虑": `- **预测型项目**：采用正式的、结构化的干系人参与机制，如定期干系人评审会、正式报告、变更控制委员会；沟通与参与记录完整。
- **适应型（敏捷）项目**：干系人参与更频繁、更非正式，通过迭代评审会、产品演示、增量反馈持续收集干系人意见；产品负责人深度参与日常决策；冲突更早暴露、更频繁处理，冲突管理技巧使用频率更高。
- **混合型项目**：对关键/高风险干系人采用正式参与机制，对其余干系人采用敏捷式的快速反馈循环。
- **行业与组织差异**：医疗、金融、政府等合规性强的行业，干系人参与更正式、更注重留痕；跨时区/跨文化项目需增强文化意识与远程参与安排。裁剪决策应记录在干系人参与计划中。`,
      "💼 实践案例": `某企业ERP系统实施项目，财务总监表面上公开支持项目，但私下对数据迁移风险顾虑重重——言语与态度明显不一致。项目经理通过非正式的“观察/交谈”察觉异常，随即安排一对一沟通，运用文化意识尊重其谨慎稳健的决策风格，通过谈判就其关心的数据迁移窗口期与回滚方案达成一致，并把顾虑记入问题日志持续跟踪。面对业务部门与IT部门的历史积怨，项目经理在启动会上运用“缓和”方式强调共同目标、淡化分歧，对数据口径之争则组织双方以“合作”方式共同制定统一方案。最终财务总监由“中立”转为“支持”，项目顺利通过关键里程碑评审。`,
    },
    keyConcepts: `- **干系人参与计划**：规定干系人所需参与级别、当前参与级别及弥合差距的行动方案，是管理干系人争取的行动指南。
- **冲突解决五方式**：合作/解决问题（Win-Win，最佳）、妥协/调解、缓和/包容、强制/命令、回避/退出。
- **情商（EI）**：识别、理解并管理自身与他人情绪的能力，对冲突管理、沟通与谈判至关重要，是项目经理的核心软技能。
- **干系人登记册**：干系人身份、利益、期望、影响力、分类与参与级别的基础文档。
- **问题日志**：集中记录并跟踪干系人问题、投诉与顾虑的文档。
- **观察/交谈**：通过非正式互动了解干系人真实态度的技巧。
- **政治意识**：理解组织权力结构与非正式影响力网络，看透决策背后的政治因素。
- **主动管理期望**：不仅回应诉求，更主动管理合理与不合理的期望，防止期望落差引发阻力。`,
    examTips: `- **冲突解决五方式高频考点**：情景题中优先选择“合作/解决问题”（Win-Win），它是处理干系人冲突的最佳默认选项。
- **强制/命令的适用边界**：仅用于紧急情况（安全、法律、时间极紧迫）；平时使用会损害关系，不应作为常规手段。
- **回避/退出的使用前提**：仅当“问题不重要”或“双方需要冷静”时使用，不能把回避当作处理问题的常规策略。
- **关键词对应**：“双方各让一步”→妥协；“求同存异、强调共同点”→缓和；“一方压服另一方”→强制。
- **观察/交谈的考查**：题干出现“项目经理私下发现干系人真实顾虑”时，最恰当做法是通过观察/交谈进一步了解，而非直接开会质问。
- **过程定位**：管理干系人争取是“执行”过程、持续实施，不是一次性的启动活动。
- **情商定位**：情商（EI）是冲突管理与沟通的关键能力，注意与“智商（IQ）”区分。
- **问题处理流程**：干系人提出的问题先记入问题日志并跟踪解决，不能只口头承诺而无后续跟踪。`
  },
  "proc-manage-communications": {
    overview: `【过程概述】管理沟通是执行过程组中的过程，涉及与项目团队内部和外部（如外部供应商、客户、监管机构）的干系人建立和开展沟通。其目的是确保及时且恰当地收集、创建、分发、存储、检索、管理、监督和最终处置项目信息，即覆盖信息的全生命周期。该过程的关键收益是：能够在项目团队与干系人之间实现高效且有效的信息流动。

- **全生命周期管理**：信息从产生（收集、创建）到使用（分发、存储、检索）再到治理（管理、监督、处置）的每一个环节都要有计划地执行，防止信息遗漏、失真或过期。
- **方式方法灵活**：管理沟通明确了有效沟通的所有方面——选择合适的技术（面对面/视频/即时消息）、方法（推式/拉式/交互式）和技巧，并根据干系人和项目不断变化的需要，动态调整沟通方式。
- **遵循沟通计划**：所有沟通活动都应遵循沟通管理计划中定义的策略与流程，确保信息内容、格式、频率和渠道的一致性。
- **克服沟通障碍**：需考虑文化差异、语言障碍、时区差异、技术限制等因素；对虚拟团队，要综合运用视频会议、即时通信、协作平台等多种工具，弥补面对面交流的缺失。
- **确认理解到位**：信息分发后还要确认接收者是否真正理解——这就是“反馈循环”，只发不收不算有效沟通。
- **关键收益**：高效且有效的信息流动，是所有干系人协作顺畅的基础。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目的高层背景信息，包括项目目的、关键干系人、总体范围与高层级要求，是沟通的基础语境来源。
- **项目管理计划**：核心是沟通管理计划，规定了谁、何时、以何种渠道、向谁传递什么信息；还包括干系人参与计划、资源管理计划等，为沟通对象与内容提供依据。
- **项目文件**：干系人登记册（沟通对象与偏好）、需求文件、问题日志、变更日志、经验教训登记册等，为沟通内容提供素材与上下文。
- **事业环境因素**：组织沟通文化与惯例、信息系统的可用性、干系人的地理分布与时区差异、语言与文化多样性等，直接影响沟通技术与方法的选择。
- **组织过程资产**：沟通模板、历史项目报告范例、沟通相关政策与程序、信息发布渠道等，可提高沟通的标准化程度与效率。`,
      "🔧 工具与技术 Tools": `- **专家判断**：对沟通渠道选择、信息分发方式、特殊干系人的沟通偏好、疑难沟通情境的处理等提供专业意见。
- **沟通需求分析**：确定干系人对信息的需求种类、数量与时限——谁需要什么信息、何时需要、以何种形式需要；依据需求选择合适的沟通方式，避免“信息过载”或“信息不足”。（在规划沟通时系统开展，执行阶段持续校验需求变化。）
- **沟通技术**：信息传递与检索的具体手段，如面对面会议、视频会议、即时消息、电子邮件、协作平台、项目门户网站等。选择时需权衡可用性、成本、保密要求、文化习惯与干系人偏好；虚拟团队往往需要组合多种技术，以同步（实时）与异步（非实时）方式互补。
- **沟通模型**：完整的沟通模型为：发送方→编码→选择媒介→传输→解码→接收方→反馈。核心要点：发送方负责把信息编码为清晰易懂的形式，并对“信息被正确理解”负责；接收方负责解码并给出反馈；噪声（物理的、语义的、心理的干扰）可能出现在任何环节。沟通只有在接收方反馈确认后才算完成——确认理解靠“反馈”，而非“发送”。
- **会议**：状态会、规划会、评审会、每日站会、头脑风暴等。会前明确目的与议程并提前分发，会中聚焦决策、充分讨论，会后立即分发纪要并跟踪行动项；虚拟会议还需考虑时区并全程记录。`,
      "📤 输出 Outputs": `- **沟通管理计划（更新）**：本过程实施中，若发现沟通策略不再适用（如干系人偏好改变、渠道失效、信息需求变化），经变更程序对沟通管理计划进行更新，并同步反映到项目管理计划中。
- **项目管理计划更新**：沟通管理计划更新、干系人参与计划更新等均作为项目管理计划更新的组成部分。
- **补充说明**：本过程实际“分发出去的信息”即项目沟通（状态报告、会议纪要、通知、演示材料等），虽然未单列，但它正是干系人接收到的沟通成果，是反馈循环和后续监控的依据。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：从规划沟通管理过程获得沟通管理计划（做什么、如何做），本过程把计划“执行”出来——规划沟通决定“该沟通什么”，管理沟通负责“实际去沟通”。
- **横向协同**：与指导与管理项目工作（项目状态信息）配合，为执行活动提供信息支撑；为监督干系人参与提供沟通反馈；干系人的回应信息反过来推动调整沟通与参与策略。
- **下游衔接**：本过程分发的项目沟通是编制工作绩效报告、监督干系人参与、实施整体变更控制等监控活动的输入；干系人的反馈是后续计划更新的重要依据。`,
      "✂️ 裁剪考虑": `- **预测型项目**：以正式书面沟通为主，报告周期固定（周报/月报），会议结构化，文档完整留痕。
- **适应型（敏捷）项目**：面对面沟通优先，每日站会、迭代评审会、演示会；广泛使用信息辐射源（看板、燃尽图）实现高频透明的信息共享；强调口头沟通与即时反馈。
- **虚拟/分布式团队**：加大即时通信与视频会议使用，明确异步沟通规则与响应时限，文档化程度更高以弥补时差与面对面交流的缺失。
- **项目规模差异**：小型项目采用轻量沟通（群聊+周会）；大型项目需建立分级沟通矩阵，按干系人层级定制信息内容与频率。
- **合规与保密行业**：金融、医疗、政府项目的沟通受法规约束，渠道受限、记录严格、敏感信息分级处理。`,
      "💼 实践案例": `某跨国软件项目，团队成员分布在三个时区，干系人包括客户IT主管与采购部门。项目经理依据沟通需求分析确定：IT主管需要每周状态报告与每轮迭代演示，采购部门只需月度成本简报。针对跨时区协作，采用“视频会议（同步）+即时通信（异步）”的组合，并将关键决策形成书面纪要分发、由对方邮件确认——形成完整反馈循环。初期客户IT主管只看报告不提问，项目经理通过一对一非正式沟通发现其对演示节奏不满，随即调整演示形式与频率。此后每次分发信息都附带简短确认请求，确保“已接收且已理解”，项目误解与返工明显减少。`,
    },
    keyConcepts: `- **沟通模型**：发送方→编码→选择媒介→传输→解码→接收方→反馈，噪声可能干扰全过程；确认理解靠反馈。
- **有效沟通**：在正确的时间、以正确的格式、通过正确的渠道、传递给正确的对象。
- **沟通障碍**：噪声、文化差异、语言障碍、信息过载、选择性接收等，会降低沟通有效性。
- **倾听技能**：主动倾听、复述确认、给予反馈、澄清疑问，是接收方正确解码的前提。
- **非语言沟通**：肢体语言、语调、表情等，在虚拟团队环境中容易被忽略，需要刻意管理。
- **反馈循环**：接收方向发送方确认理解，实现沟通闭环，是有效沟通的关键环节。
- **沟通技术分类**：交互式（会议、电话）、推式（邮件、报告）、拉式（门户、知识库）。
- **虚拟团队沟通**：多种工具组合、同步与异步互补、规则明确。`,
    examTips: `- **沟通模型核心考点**：发送方负责“确保信息被正确理解”，接收方负责解码与反馈；确认理解靠“反馈”，不是靠“发送”。常考“如何确认干系人理解了信息”→选择主动请求反馈/确认。
- **有效沟通四要素**：正确的时间+正确的格式+正确的渠道+正确的对象，缺一不可。
- **非语言沟通**：肢体语言、语调在虚拟团队中易被忽略，考查虚拟团队需加强明确表达与书面记录。
- **常见沟通障碍**：噪声、文化差异、语言障碍、信息过载、选择性接收；出现障碍时的首选对策是反馈与澄清。
- **过程定位**：管理沟通是“执行”过程；信息传递后需确认接收与理解，形成闭环。
- **沟通技术三类**：交互式/推式/拉式要能区分。
- **标准ITTO区分（重点提醒）**：批次数据将规划沟通的输入（项目章程、沟通需求分析）与输出（沟通管理计划）并入管理沟通，便于学习记忆；严格按PMBOK标准，规划沟通（输出沟通管理计划）属规划过程组，管理沟通（输出项目沟通）属执行过程组，考试以PMBOK标准为准。`
  },
  "proc-monitor-stakeholder-engagement": {
    overview: `【过程概述】监督干系人参与是监控过程组中的过程。其目的是：评估干系人参与工作的有效性，识别改进关系所需的调整，并优化参与策略或计划，以更好地满足干系人参与的需要。该过程的关键收益是：随着项目的推进和环境的变化，能够维持或提高干系人参与活动的效率和效果。

- **监督关系与策略**：持续监督干系人关系，通过调整计划和策略来裁剪干系人参与策略，使参与方式始终与干系人当前状态匹配。
- **评估参与度变化**：干系人的参与度会随项目进展而变化——原先支持的干系人可能转为抵制，原先抵制的也可能转为支持；本过程持续跟踪这一动态。
- **监控关键信号**：重点监控的行为信号包括干系人行为变化、沟通反馈质量、会议出席率、投诉频率、信息响应速度等。
- **持续收集反馈**：通过调查、访谈、观察、会议等多种渠道持续收集干系人反馈，将主观判断与客观指标交叉验证，避免只凭印象管理。
- **及时干预调整**：一旦发现参与度下降，应立即分析原因并调整策略——增加沟通频率、改变沟通方式，必要时调整项目策略，重新赢得支持，而不是等问题恶化。
- **闭环管理**：与管理干系人参与（执行）配合，形成“计划→执行→监控→调整”的持续改进闭环。
- **关键收益**：维持或提高干系人参与的效率与效果，为项目成功提供持续的干系人支持基础。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：核心是干系人参与计划（规定所需参与级别、评估方法），还有沟通管理计划、资源管理计划等，提供监控的基准与预期。
- **项目文件**：干系人登记册（记录当前参与级别）、问题日志、变更日志、经验教训登记册、干系人参与评估数据等，是评估参与度变化的事实依据。
- **工作绩效数据**：与干系人参与相关的原始记录，如会议出席情况、投诉数量、沟通响应时间、问题关闭率等，是数据分析的原料。
- **事业环境因素**：组织文化、干系人所在组织的关系变化、外部政策与市场环境等，可能改变干系人态度。
- **组织过程资产**：历史项目的干系人参与评估方法、参与度监控模板、经验教训库等，可借鉴成熟做法。`,
      "🔧 工具与技术 Tools": `- **数据分析**：本过程最常用的工具，包括——
  - **干系人参与度评估**：运用干系人参与评估矩阵，逐项对比“所需参与级别”与“当前参与级别”，量化参与差距，找出需要加强的干系人；评估可借助问卷调查、访谈等数据来源，并定期刷新评估结果。
  - **根本原因分析**：当参与度下降时，深入分析其根本原因（是信息不足、期望落空、还是关系破裂），避免就事论事；可结合“五个为什么”、因果图等方法层层追问。
  - **备选方案分析**：对多个策略调整方案进行评估比较，综合考虑影响、成本与可行性，选择最合适的调整路径。
  - **趋势分析**：通过沟通频率、出席率、投诉量等指标的时间趋势，提前发现参与度下滑苗头，实现前瞻性干预。
- **决策**：包括投票（用于综合干系人反馈意见）与多标准决策分析（用于在调整参与策略时，按标准权衡多个备选方案）等。
- **会议**：状态评审会、干系人反馈会、经验教训会；会上直接收集干系人意见、评估参与情况，并讨论策略调整方向。`,
      "📤 输出 Outputs": `- **工作绩效信息**：将工作绩效数据（原始记录）经数据分析后形成的、关于干系人参与有效性的结论性信息，如参与度变化趋势、问题解决情况、策略调整建议等；它是编制状态报告、开展绩效评审、监督其他领域的重要输入。
- **变更请求**：当监控发现参与策略需要调整、或干系人诉求引发范围/进度/计划变化时，提出变更请求，经实施整体变更控制审批后执行。
- **项目管理计划更新**：主要包括干系人参与计划、沟通管理计划等的更新——把经批准的策略调整固化到计划中，指导后续执行。`,
      "🔗 与其他过程的相互作用": `- **上游衔接**：从规划干系人参与获得干系人参与计划与参与评估矩阵；从管理干系人参与（执行）获得问题日志、更新后的干系人登记册与沟通反馈——本过程在此基础上评估“执行得怎么样”。
- **监控协同**：本过程产生的工作绩效信息是状态报告、监督风险、控制进度成本等监控活动的输入；发现的偏差通过变更请求进入实施整体变更控制流程。
- **下游衔接**：经批准的变更与更新的计划，重新驱动管理干系人参与过程的执行，实现“监控发现→执行调整”的动态循环，使干系人参与策略随环境持续优化。`,
      "✂️ 裁剪考虑": `- **预测型项目**：采用定期干系人评审会、正式参与度评估、量化报告等方式，监控频率与项目阶段挂钩（里程碑前后加强）。
- **适应型（敏捷）项目**：通过迭代评审、演示、每日互动高频地自然评估干系人参与；参与度问题能在几天内暴露并快速调整，无需正式报告。
- **分布式团队**：通过在线调查问卷、虚拟反馈会、参与度分析工具（如响应率、点击率）来评估无法当面观察的干系人。
- **低风险/小型项目**：采用轻量监控，聚焦少数关键信号（出席率、投诉）即可，避免过度管理。
- **监控强度随干系人重要性与项目阶段裁剪**：关键干系人重点监控，一般干系人例行关注。
- **组织与行业文化差异**：高合规行业（医疗、金融）的参与度监控更依赖正式记录与量化指标；强调人际关系文化的组织则更依赖非正式观察与访谈。`,
      "💼 实践案例": `某大型基建项目进入中期，项目经理发现关键干系人——政府部门联络人连续缺席两次月度评审会，邮件回复明显变慢。通过数据分析（会议出席率、沟通响应时间趋势）确认其参与度确在下降；进一步用根本原因分析定位到其对项目进度放缓的不满。项目经理随即安排一对一沟通，调整干系人参与计划，新增每月专项进度汇报并优化沟通内容；经多标准决策分析后提出变更请求，更新沟通策略。此后该干系人恢复出席、转为支持，干系人参与评估矩阵显示其参与级别由“中立”回升至“支持”。若放任不管，其对项目验收的否决权很可能演变为重大风险。`,
    },
    keyConcepts: `- **干系人参与评估矩阵**：对比所需参与级别与当前参与级别，量化参与差距的核心工具。
- **参与度监控**：持续跟踪干系人参与级别变化，掌握动态趋势。
- **早期预警信号**：沟通减少、会议缺席、投诉增加、响应变慢，是参与度下降的前兆。
- **策略调整**：依据监控结果及时调整干系人参与策略与计划，必要时提出变更请求。
- **工作绩效数据 vs 工作绩效信息**：数据是原始记录，信息是整合分析后的结论，二者不能混淆。
- **反馈收集方式**：调查、访谈、观察、会议，多渠道交叉验证。
- **干系人参与级别**：不知晓→抵制→中立→支持→引导，五个递进级别。
- **根本原因分析**：参与度下降时先究因再施策，避免表面化处理。`,
    examTips: `- **过程定位**：监督干系人参与是“监控”过程、持续进行，不是项目结束时的一次性检查。
- **动态视角**：干系人参与度是动态的——原先支持的可能变为抵制，监控时必须关注变化而非只看现状。
- **早期预警信号（高频考点）**：沟通减少、会议缺席、投诉增加、响应变慢，出现这些信号应立即关注并干预。
- **处理顺序**：发现参与度下降→先分析根本原因→再调整参与计划与策略（必要时提出变更请求），不要跳过分析直接采取行动，也不要停止沟通。
- **评估工具**：评估参与度使用“干系人参与评估矩阵”，对比“所需级别 vs 当前级别”。
- **数据→信息**：工作绩效数据（原始）经数据分析转化为工作绩效信息（结论），再支撑决策。
- **情景题陷阱**：题干给出“干系人参与度下降”，最优做法是重新评估干系人参与计划并调整策略，而非简单地增加会议或忽略问题。
- **与管理干系人参与的区别**：管理是“执行参与策略”，监督是“评估策略是否有效”，注意区分执行过程组与监控过程组。`
  },
  "proc-monitor-communications": {
    overview: `【过程概述】监督沟通过程属于监控过程组、沟通管理知识领域，目的是按需监督和评估项目沟通活动及其结果，确保项目及其干系人的信息需求得到满足。该过程的关键收益是：确保在正确的时间、以正确的形式、通过正确的渠道，向正确的干系人提供正确、及时且有用的信息，实现沟通管理计划和干系人参与计划中定义的最佳信息流动。该过程在整个项目期间持续实施。

监督沟通涉及收集沟通活动数据并评估沟通效果。需要持续监控的关键问题包括：信息是否按时、按正确格式发送给了正确的接收者？接收者是否真正理解并使用了这些信息？沟通渠道是否畅通有效？是否存在信息过载（信息过多、重复、难以消化）或信息不足（干系人缺乏决策所需信息）的情况？

当发现沟通效果不佳时，应及时分析原因并调整沟通策略：改变沟通频率、切换更合适的渠道、简化信息内容、调整分发范围，或指定专门的沟通负责人。评估沟通效果通常依托三类量化指标——及时性、准确性、完整性——并据此判断信息过载还是信息不足。在虚拟团队和分布式环境中，尤其要关注沟通的及时性、准确性和完整性。监督沟通的成果（工作绩效信息）会作为输入用于其他监控过程，并触发必要的变更请求，形成持续改进的闭环。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：包含沟通管理计划和干系人参与计划，前者定义了信息传递的对象、方式、渠道与频率，后者定义了为争取干系人参与所计划的行动，为监督沟通提供评估基准——实际沟通与计划不符之处即为监控对象。
- **项目文件**：包括问题日志（记录已识别的沟通障碍与干系人问题）、经验教训登记册（沉淀历史沟通经验以指导改进）、项目沟通记录（已发送的会议纪要、报告、演示文稿等），用于核对实际发生的沟通活动。
- **工作绩效数据**：关于实际沟通活动与结果的原始数据，如已发送信息的时间与对象、会议召开情况、干系人反馈与提问、信息查阅情况等，是评估沟通效果的事实来源。
- **事业环境因素**：组织的沟通政策与标准、沟通工具与信息管理系统（协作平台、知识库等）、组织文化与汇报层级，决定了可用的沟通方式和可采用的监控手段。
- **组织过程资产**：沟通管理计划模板、会议纪要和报告模板、问题跟踪系统、经验教训知识库、历史干系人反馈数据等，为监督沟通提供方法与历史参照。`,
      "🔧 工具与技术 Tools": `- **专家判断**：征询干系人、沟通专家、职能经理或外部顾问，借助其对项目与组织的了解判断信息是否被正确理解、渠道是否恰当、是否需要调整沟通方式。
- **干系人参与度评估矩阵**：将干系人当前参与水平（不知晓、抵制、中立、支持、领导）与期望参与水平进行对比，识别参与差距；若差距未随沟通活动开展而缩小，说明沟通策略需要调整。
- **人际关系与团队技能**：通过观察/交谈（观察干系人在会议中的行为与非语言信号，进行非正式交谈获取真实反馈）和积极倾听（确认信息被完整准确地理解）两种方式，直接感知沟通是否有效。
- **数据分析**：基于工作绩效数据对沟通效果进行量化评估，重点关注三类指标——及时性（信息是否在干系人需要的时间到达，可统计平均发送延迟、响应时长）、准确性（信息内容是否无误、符合事实，可通过核对与反馈确认）、完整性（信息是否涵盖决策所需的全部内容，可对照干系人信息需求清单逐项核查）；还可分析干系人参与度变化趋势、问题日志中沟通类问题的发生频率、不同渠道的送达与回复情况，据此判断是信息过载还是信息不足，并定位问题出在内容、渠道还是频率上。
- **会议**：通过状态评审会、干系人反馈会、一对一沟通等正式和非正式会议，直接听取干系人对信息充分性、渠道有效性和频率合理性的意见，是发现沟通问题、评估沟通效果的重要途径。`,
      "📤 输出 Outputs": `- **工作绩效信息**：整合并分析工作绩效数据后形成的沟通绩效信息，如信息送达率、干系人反馈处理情况、沟通指标达成情况等，供项目经理和干系人了解沟通现状，并作为其他监控过程和经验教训沉淀的输入。
- **变更请求**：当评估发现沟通方式、渠道或内容需要调整时，提出变更请求（预防措施或纠正措施），经实施整体变更控制过程批准后执行，使沟通策略与实际需求重新对齐。
- **项目管理计划更新**：更新沟通管理计划（调整沟通渠道、频率、内容格式与分发对象）和干系人参与计划（调整参与争取策略），使计划与实际情况保持一致。
- **项目文件更新**：更新问题日志（记录新发现的沟通问题及解决情况）、经验教训登记册（沉淀沟通改进经验）、项目沟通记录和干系人登记册，为后续阶段提供参考。`,
      "🔗 与其他过程的相互作用": `上游关系：规划沟通管理定义了应当如何沟通（对象、渠道、频率、格式），监督沟通以此为基准评估实际沟通是否达到预期；管理沟通负责实际发送信息，监督沟通评估这些沟通活动的效果。横向关系：监督沟通输出的工作绩效信息是监控过程组各过程（如监督进度、监督成本、监督干系人参与）的重要输入；它与监督干系人参与过程紧密配合——沟通效果不佳往往伴随干系人参与不足，两个过程需要联动分析。下游关系：发现偏差后提出变更请求，进入实施整体变更控制过程审批；经批准的更新回流到沟通管理计划、干系人参与计划和项目文件，形成规划—执行—监督—改进的闭环。监督沟通的发现还会沉淀为经验教训登记册，供后续项目和阶段借鉴。`,
      "✂️ 裁剪考虑": `- **预测型项目**：沟通计划详尽、格式固定，监督重点放在按计划核查信息是否及时、准确、完整地送达。
- **适应型/敏捷项目**：沟通更轻量，以面对面交流和即时协作工具为主，监督更多依赖日常交互、每日站会和回顾会议的即时反馈，及时性指标权重更高，文档类沟通监控大幅减少。
- **混合型项目**：对关键里程碑和合规报告采用预测式监控，对开发团队内部采用敏捷式即时反馈。
- **虚拟团队**：成员分布在不同时区，沟通监控需更关注时差导致的延迟、渠道有效性，以及非语言信息缺失时的补偿措施。
- **大型/跨国项目**：干系人数量大、文化差异明显，需强化信息完整性与一致性的监控，并部署标准化的监控工具与指标看板。`,
      "💼 实践案例": `某跨国软件实施项目，项目经理通过干系人参与度评估矩阵发现关键业务干系人的参与水平低于预期，同时干系人在月度评审会上反馈决策所需数据总是太晚收到。通过数据分析发现：周报平均延迟3天，且技术细节占比过高，导致业务干系人陷入信息过载。项目经理据此提出变更请求，将技术报告与业务简报拆分、缩短发送周期、改用仪表盘实时推送关键指标。执行后干系人参与度提升两个等级，决策周期明显缩短，项目重新获得关键干系人的认可与支持。此后项目经理将及时性、准确性、完整性三项沟通指标纳入月度监控，持续跟踪偏差并滚动更新沟通管理计划，使沟通改进形成常态化闭环。`,
    },
    keyConcepts: `- **信息过载**：干系人接收的信息超出其处理能力，导致关键信息被忽略；应精简内容、分类分级分发。
- **信息不足**：干系人缺少决策或履职所需的信息，需补充发送或提高发送频率。
- **沟通效果评估**：确认信息是否被正确理解并实际使用，而不仅仅停留在已发送层面。
- **沟通指标**：评估沟通效果的量化标准，核心是及时性、准确性、完整性，还可包括渠道有效性、受众覆盖面、干系人反馈率。
- **沟通渠道有效性**：评估所采用的渠道（会议、邮件、即时消息、仪表盘等）能否高效送达信息并唤起反馈，是沟通监控中常被忽略的检查项。
- **沟通障碍识别**：发现并消除阻碍信息流动的因素，如语言、时区、文化差异、层级过滤、技术故障等。
- **沟通管理计划更新**：根据监控结果动态调整沟通策略，而不是一次制定后保持不变。
- **干系人参与度评估矩阵**：对比当前与期望参与水平以识别差距，是判断沟通是否有效的重要工具。`,
    examTips: `- 监督沟通属于监控过程组，其典型输出是工作绩效信息，注意与工作绩效数据区分——数据是原始记录，信息是分析后的成果。
- 题干出现干系人反馈没收到信息、信息不够、沟通效果不佳时，正确选项是调整沟通管理计划，而不是盲目扩大沟通范围或更换工具。
- 沟通过度和沟通不足都是问题：过度沟通会淹没关键信息，不足则导致干系人决策受阻。
- 评估沟通效果常用三类指标：及时性、准确性、完整性，三者需同时关注。
- 干系人参与度评估矩阵是高频考点，考查当前参与水平与期望参与水平的差距识别。
- 监督沟通持续整个项目期间，不是一次性活动；注意区分规划沟通管理（规划组）、管理沟通（执行组）与监督沟通（监控组）三个过程的输入输出，防止混淆。
- 虚拟团队场景下，优先考虑沟通渠道有效性与时差导致的延迟问题。`
  },
  "proc-plan-resource-mgmt": {
    overview: `【过程概述】规划资源管理过程属于规划过程组、资源管理知识领域，目的是定义如何估算、获取、管理和利用实物资源、虚拟资源以及团队资源。该过程的关键收益是：根据项目的类型与复杂性，确定管理项目资源所需的方法和管理工作的投入程度，为后续的估算资源、获取资源、建设团队、管理团队和控制资源提供框架。该过程仅执行一次或在项目预定的节点执行。

资源规划旨在确定并识别相应的方法，确保项目获得成功所需的充足资源。在有效的资源规划中，应考虑并规划稀缺资源的可用性及竞争情况——当某项关键技能或设备供不应求时，需提前规划获取策略或替代方案。

规划资源管理的主要工具与技术包括：责任分配矩阵（如RACI矩阵——R=执行、A=负责、C=咨询、I=知会，每个活动仅安排一个A）、组织理论（理解不同组织结构对资源职权和可用性的影响）、SWOT分析（评估资源相关的优势、劣势、机会与威胁）等。

资源管理计划通常包括：识别资源的需求与方法、角色与职责的明确、项目组织图、团队建设的策略与方法、培训计划、认可与奖励机制等。团队章程是规划资源管理的关键输出之一，用于确立团队价值观、沟通指南、会议规则和决策过程。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目的高层级资源需求、预算概要与关键干系人清单，是角色与职责定义的起点，也为资源规划限定边界。
- **项目管理计划**：其中的质量管理计划、范围基准、进度基准等界定了资源的用途与时间约束；团队资源与实物资源的需求必须与范围、质量、进度要求相协调。
- **项目文件**：如干系人登记册（识别需要纳入角色分配或沟通的干系人）、假设日志（记录资源可得性等假设），为资源规划补充背景信息。
- **事业环境因素**：组织结构与组织文化、现有资源池、市场资源条件、人事政策与合同协议等，直接决定资源获取方式与项目经理拥有的资源职权。
- **组织过程资产**：角色描述模板、资源管理计划模板、组织级政策与程序、历史项目的资源使用数据，帮助快速定义本项目的资源管理方法。`,
      "🔧 工具与技术 Tools": `- **专家判断**：征询项目经理、职能经理、人力资源部门与行业专家，确定角色职责、资源需求与团队建设方法。
- **数据收集**：通过头脑风暴（与干系人共同识别资源需求、障碍与风险）、访谈（与职能经理确认资源可用性与技能水平）、核对单（系统核查资源规划要素）收集决策所需信息。
- **人际关系与团队技能**：运用冲突管理、影响力、激励、谈判、团队建设等技能，协调干系人分歧、争取资源承诺、推动团队建设策略落地，是定义角色职责与团队章程的软技能支撑。
- **组织理论**：运用组织理论理解不同组织结构对资源职权和可用性的影响——在职能型组织中，职能经理掌控资源分配；在项目型组织中，项目经理拥有较高职权；在矩阵型组织（弱矩阵、平衡矩阵、强矩阵）中，项目经理与职能经理共享职权，资源获取需通过协商进行。掌握组织结构特性有助于预见资源管理中的权力博弈与资源瓶颈。
- **数据表示（责任分配矩阵/RACI）**：通过矩阵型图表展示活动与资源之间的关系。RACI矩阵定义四类角色——R（Responsible，执行，实际完成活动）、A（Accountable，负责，对活动结果负最终责任，每个活动只能有一个A）、C（Consulted，咨询，提供意见与建议）、I（Informed，知会，仅需获知结果）。RACI适用于活动级别；对可交付成果可扩展为RACI加上O（Ownership，成果归属）等变体。此外还有层级型数据表示（如组织分解结构OBS、资源分解结构RBS）和文本型表示（角色描述）用于补充说明。
- **SWOT分析**：系统评估项目资源相关的内部优势（如团队独特技能）、内部劣势（如关键人才短缺）、外部机会（如人才市场供应充足、新型设备可用）与外部威胁（如竞争者争夺同一稀缺资源），从而制定扬长避短、趋利避害的资源策略。
- **会议**：召开规划会议或研讨会，与干系人、职能经理共同确定资源管理方法、角色职责和团队章程内容。`,
      "📤 输出 Outputs": `- **资源管理计划**：定义如何分类、分配、管理和释放项目资源，通常包含：识别资源的需求与方法、获取资源的途径与时间、角色与职责（含RACI矩阵）、项目组织图、项目团队资源管理（人员配备计划）、团队建设策略与方法、资源控制（监控资源使用、纠正偏差）、认可与奖励计划以及培训计划。
- **团队章程**：由项目团队共同制定（在发起人或项目经理指导下），确立团队价值观、沟通指南、会议规则、决策标准与机制，并明确团队成员的权力与责任边界。团队章程能减少误解、促进合作与相互尊重；它与项目管理计划不同——项目管理计划由项目经理制定并经正式批准，团队章程由团队自身创建并自发遵守。
- **项目文件更新**：包括假设日志（记录资源可得性与稀缺性假设）、经验教训登记册（沉淀资源规划经验），供后续估算、获取与管理资源的过程参考。`,
      "🔗 与其他过程的相互作用": `上游关系：制定项目章程提供高层级资源需求与预算概览；制定项目管理计划确定资源规划的约束与边界；定义活动、排列活动顺序为资源规划提供对象与时间窗口。下游关系：规划资源管理输出的资源管理计划直接指导后续的估算活动资源（估算资源类型与数量）、获取资源（按计划采购与调配）、建设团队、管理团队和控制资源过程；团队章程为建设团队与管理团队提供行为规范基础。横向关系：与规划沟通管理紧密相关——角色与职责的分配决定了沟通对象与信息流向；与规划干系人参与相互呼应，团队章程中的沟通指南常与沟通管理计划联动；资源管理计划中的假设（如稀缺资源可得性）会回流到假设日志，进而影响风险识别与采购规划。`,
      "✂️ 裁剪考虑": `- **预测型项目**：制定详细、完整的资源管理计划，角色职责清晰，人员配备计划详尽。
- **适应型/敏捷项目**：资源计划轻量化，团队成员多数固定且自组织，角色精简（如Scrum Master、产品负责人、开发团队），团队章程简短、聚焦价值观与协作规则，资源管理计划内容往往合并到项目章程或简短的补充说明中。
- **混合型项目**：核心团队采用预测式角色定义，迭代团队采用敏捷自组织方式，两者通过RACI矩阵厘清职责边界。
- **小型项目**：可将资源管理计划与团队章程整合进项目管理计划；大型复杂项目需独立的资源管理计划并分区细化。
- **远程/虚拟团队**：团队章程需特别定义沟通工具、时区协调规则与异步协作规范。`,
      "💼 实践案例": `某制造企业数字化改造项目横跨IT与生产部门，项目经理在矩阵组织下编制RACI矩阵：生产部长对工艺参数上线活动担任A（负责）、IT工程师担任R（执行）、质量部担任C（咨询）、采购部担任I（知会），确保每个活动只有一个A，杜绝责任不清。团队在首次研讨会上共同创建团队章程，约定每周例会规则、决策采用多数共识、冲突先行私下解决。同时用SWOT分析识别出关键数据工程师稀缺的劣势与市场上可租用云平台的机会，提前在资源管理计划中安排人才租赁备选方案，成功规避了关键资源短缺风险。`,
    },
    keyConcepts: `- **RACI矩阵**：责任分配矩阵的一种，R（执行）实际完成工作、A（负责）对结果负最终责任、C（咨询）提供意见、I（知会）接收信息；每个活动只能有一个A，避免责任不清。
- **资源管理计划**：定义如何估算、获取、管理、利用与释放项目资源，含角色职责、项目组织图、团队建设、培训、认可奖励与资源控制等内容。
- **团队章程**：团队自主制定的价值观、沟通指南、会议规则与决策机制，减少误解、促进合作。
- **组织理论**：研究组织结构（职能型、项目型、矩阵型）对资源职权与可用性影响的理论，用于预见资源管理中的权力与协调问题。
- **资源分解结构（RBS）**：按资源类别和类型进行层级化分解的树状结构（如人力、材料、设备、用品），用于归集与汇总资源需求。
- **SWOT分析**：从优势、劣势、机会、威胁四个维度评估资源环境，辅助制定资源策略。
- **项目组织图**：以图形展示项目团队成员及其汇报关系，是资源管理计划的组成部分。`,
    examTips: `- RACI矩阵是最高频考点：牢记R=执行、A=负责、C=咨询、I=知会，且每个活动只能有一个A；选项中出现两个A即为错误。
- 团队章程与项目管理计划易混淆：团队章程由团队共同制定、自发遵守；项目管理计划由项目经理制定、正式批准。
- 组织结构影响资源职权：矩阵组织中职能经理控制资源分配，项目经理需协商获取资源；项目型组织中项目经理职权最高。
- 资源分解结构RBS是按类别和类型层级化分解的资源视图，注意与工作分解结构WBS（按可交付成果分解）、组织分解结构OBS（按组织单位分解）区分。
- 规划资源管理仅执行一次或在项目预定点执行，属于规划过程组，输出的是计划而非实际资源。
- 培训计划、认可与奖励机制都属于资源管理计划的内容。
- 团队章程内容（价值观、沟通指南、会议规则、决策过程）是记忆点，常以多选题出现。`
  },
  "proc-estimate-resources": {
    overview: `【过程概述】估算资源过程（也称估算活动资源）属于规划过程组、资源管理知识领域，目的是估算完成项目工作所需的团队资源，以及实物资源或虚拟资源的类型和数量。该过程的关键收益是：识别完成项目所需的资源类型、数量及其特性（如技能水平、性能等级），这对于项目经理有效规划并确保所有必需资源的可用性至关重要。该过程仅执行一次或在项目预定的节点执行。此外，该过程有助于预测潜在的资源短缺或过剩，从而为主动调整（提前采购、调整进度、安排培训等）创造条件。

该过程涉及对项目各方面进行详细的分析和考量，以确保高效分配适当的资源。估算资源与进度计划密切相关——资源可用性直接影响活动持续时间，进而影响项目进度计划：资源充足时活动可并行或加速，资源稀缺时活动不得不顺延或调整顺序。

资源估算应基于活动清单和活动属性，考虑资源的类型（人力、设备、材料等）、技能水平、数量、可用时间和地点。主要估算方法包括专家判断、类比估算、参数估算、自下而上估算等，其中自下而上估算准确性最高。资源分解结构（RBS）是按资源类别和类型对资源进行层级化分解的工具，用于归集和汇总资源需求。资源日历则显示每种资源何时可用、何时已被分配，是衔接资源估算与进度计划的关键信息。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：重点是资源管理计划（定义了角色职责、资源分类与获取方法，作为估算的指导框架）和范围基准（确定需要估算资源的活动范围）。
- **项目文件**：包括活动属性（含每项活动的资源需求信息）、活动清单（确定待估算的对象）、假设日志（记录资源可得性等假设）、经验教训登记册（参考历史资源使用经验）、里程碑清单（关键时点约束资源的可用时间）、项目团队派工单（现有团队成员及其角色）、资源日历（已有资源的可用时段）、资源分解结构（已有资源的层级分类）、风险登记册（识别可能影响资源可用性的风险）。
- **事业环境因素**：资源所在地点与运输条件、资源的可用性与技能水平、组织现有的资源池与市场资源供应、人事政策、行业资源标准等。
- **组织过程资产**：历史项目的资源使用数据、资源估算的既有数据库与工具、组织关于资源采购与租赁的政策程序、团队绩效评估数据。`,
      "🔧 工具与技术 Tools": `- **专家判断**：征询有经验的项目经理、领域专家、职能经理，依据过往项目经验判断资源的类型、数量、技能要求与获取方式，是资源估算最常用的起点。
- **备选方案分析**：比较实现同一活动的不同资源方案（如自建团队与外包、雇佣高级工程师与培养初级工程师、租用设备与购置设备），选择在成本、时间与质量约束下最优的方案。
- **发布的估算数据**：使用公开或商业发布的生产率数据、单位资源费率、行业数据库等作为资源估算的依据，提高估算的客观性与可靠性。
- **类比估算**：参考历史相似项目（范围、规模、复杂度相近）的资源使用情况，结合专家判断调整后得出估算，成本低、速度快，适用于早期信息不足阶段，但精度有限。
- **参数估算**：基于资源消耗量与某个可测参数（如每平方米工时、每千行代码人日数）之间的统计关系（生产率、费率）进行估算，精度取决于参数模型的可靠性，可借助行业基准数据提高可信度。
- **自下而上估算**：将活动进一步分解为更细粒度的工作，先估算每一最小组件所需资源，再逐层向上汇总得到活动、工作包乃至整个项目的资源需求；准确性最高，但耗时耗力，适用于关键或高价值活动。
- **项目管理信息系统（PMIS）**：使用进度计划软件的资源库与资源分配功能，帮助建立资源池、汇总资源需求、查看资源日历、识别资源冲突或过度分配（资源负载超限），并支持资源平衡与资源平滑的模拟。`,
      "📤 输出 Outputs": `- **资源需求**：以活动清单或工作分解结构为基础，汇总每项工作所需的资源类型与数量，形成活动—资源类型—数量（含技能/规格）的清单，可细化到工作包层级；是获取资源、估算成本、制定进度计划的基础输入。
- **估算依据**：记录资源估算所依据的信息，包括估算方法、估算所依据的假设与约束、范围与证据、制约因素，以及估算的可信度区间，用于支持资源估算的可信度，便于评审与追溯。
- **资源分解结构（RBS）**：按资源类别和类型对项目资源进行层级化分解的树状结构（第一层如人力、材料、设备、用品，第二层继续细分到技能等级、型号规格），帮助归集资源需求、识别缺口，并支持资源汇总与报告。
- **项目文件更新**：包括活动属性（补充或修订资源需求字段）、假设日志（更新资源相关假设）、经验教训登记册（沉淀资源估算经验），供后续过程参考。`,
      "🔗 与其他过程的相互作用": `上游关系：估算资源以资源管理计划（来自规划资源管理）为框架，以活动清单与活动属性（来自定义活动）为对象，并参考进度计划的工作安排确定资源使用时段。与成本估算的衔接：资源需求是估算成本的基础——将资源数量乘以资源费率即得人工与材料成本，因此资源估算不准确会直接传导为成本估算误差；资源类型（人力、设备、材料）与成本估算的成本类别一一对应。与进度计划的衔接：资源日历显示资源的可用时段，直接影响活动持续时间与进度网络——资源不足导致持续时间延长，资源可用后活动才能启动；制定进度计划时若发现资源过载，需进行资源平衡或资源平滑，结果再回流调整资源需求。横向关系：资源估算揭示的稀缺资源与短缺风险应记入风险登记册和假设日志，触发风险应对规划；资源需求的变化会更新项目文件，并可能引发范围、进度、成本的连锁调整。下游关系：资源估算的输出为获取资源过程提供明确清单，并为控制资源过程提供监控基准。`,
      "✂️ 裁剪考虑": `- **预测型项目**：资源估算详尽，方法正式（常用自下而上估算），资源日历与资源需求文档完备。
- **适应型/敏捷项目**：团队自组织、资源多为固定角色，估算轻量且偏向团队集体估算，重点关注可用带宽与工作负载而非详细的资源规格；资源日历简化为团队可用时段。
- **混合型项目**：核心活动采用正式估算，迭代开发活动采用相对估算（如故事点）并映射到团队带宽。
- **项目规模与复杂度**：小型项目可合并资源估算与成本估算、简化估算依据；大型多专业项目需对每个工作包分别估算并建立RBS统一归集。
- **虚拟/外包团队**：需特别考虑时区协作成本、沟通工具资源，以及外包服务契约中的资源条款。`,
      "💼 实践案例": `某数据中心迁移项目需在6个月内完成。项目经理基于活动清单，对核心设备迁移活动采用自下而上估算，细分为机柜搬运、线缆部署、系统测试等工作包，分别估算工程师、搬运工、测试设备等资源的数量；对历史相似项目采用类比估算快速得到总体资源轮廓；参数估算则利用每台服务器迁移需2人·天的行业基准估算服务器迁移人力。通过RBS归集发现测试设备存在缺口，结合资源日历确认该设备在项目中期才可到位，于是与进度计划衔接：将测试工作顺延并预先安排替代租赁方案，同时将短缺风险记入风险登记册。最终项目资源计划与进度计划高度一致，未发生资源闲置或短缺。`,
    },
    keyConcepts: `- **资源需求**：详细说明每项活动或工作包所需资源的类型、数量与特性（技能、规格、等级），是成本估算与进度计划的基础。
- **资源日历**：显示每种（类）资源何时可用、何时已分配，识别可用时段；资源可用性直接决定活动持续时间，是衔接资源估算与进度计划的关键。
- **估算方法**：专家判断（经验驱动）、类比估算（参考历史相似项目，快而粗）、参数估算（基于生产率等统计关系）、自下而上估算（逐层汇总，最准确最耗时）。
- **资源分解结构（RBS）**：按资源类别和类型对资源进行层级化分解的工具，用于归集、汇总与报告资源需求。
- **备选方案分析**：对比多种资源方案在成本、时间、质量约束下的优劣，选择最优配置。
- **发布的估算数据**：引用行业公开的生产率与费率数据，提升估算的客观性。
- **估算依据**：记录估算方法、假设、约束与可信度区间的文档，支撑评审与追溯。`,
    examTips: `- 资源估算是成本估算的基础：资源数量乘以资源费率得到人工与材料成本；题干考察两者关系时，答案常为资源估算不准确会导致成本估算偏差。
- 资源日历直接影响活动持续时间，进而影响进度计划；资源不足导致持续时间延长，是进度与资源关联的高频考点。
- 自下而上估算最准确，类比估算最快但精度最低；早期信息不足时倾向使用类比估算。
- 矩阵组织中资源可用性受职能经理控制，获取稀缺资源需提前规划备选方案。
- RBS是按类别和类型的层级分解，注意与WBS（按可交付成果）、OBS（按组织单位）区分。
- 估算资源与估算成本易混淆：前者输出资源需求，后者输出成本估算，注意输出命名与输入工具的差异。
- 资源需求的汇总是按工作分解结构层级逐层向上汇总（活动→工作包→项目），而非直接按时间汇总。
- 识别到资源短缺应更新风险登记册与假设日志，并准备备选方案（如外包、替代设备、加班培训）。`
  },
  "proc-acquire-resources": {
    overview: `【过程概述】获取资源（Acquire Resources）过程属于执行过程组，其目的是根据活动清单获取完成项目工作所需的团队、实物或虚拟资源。这里的“获取”不只是把人招进来或把设备买进来，而是通过一系列决策与协商手段，把合适的资源在合适的时间、以合适的成本配置到项目当中，并正式明确资源的角色与职责。该过程的关键收益是：能够明确并指导资源的选择，并将资源分配到对应的活动，从而为后续执行与监控奠定资源基础。获取资源过程并非只在项目启动时执行一次，而是根据需要在整个项目期间定期执行——当新阶段产生资源需求、出现资源短缺或计划发生重大调整时，都需要再次触发该过程。

在获取项目资源时，项目经理需要重点关注以下因素：第一，项目经理或项目团队应与能够提供资源的相关方充分协作、进行有效谈判并施加正向影响，常见谈判对象包括职能经理（获取内部团队资源）、其他项目经理（共享稀缺人才）、供应商与外包商（获取实物与外部资源）等。第二，如果无法获取项目所需资源，可能直接影响进度、预算、客户满意度、质量与项目风险水平。第三，如果因预算限制、市场短缺、法律约束等制约因素而无法获取首选资源，项目经理或团队必须评估替代资源，并分析替代方案对项目目标的影响。

资源获取方法主要包括：预分派（某些资源在项目启动前已被章程或合同明确指定）、谈判（与职能经理或其他项目团队协商获取资源）、多标准决策分析（使用多个加权标准评估和选择候选资源）。对于虚拟团队，需要特别关注沟通渠道设计与信任建设。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：为获取资源提供整体指导与约束，主要包括：
  - **资源管理计划**：定义如何获取、分配、监控和释放资源，包括识别与获取资源的政策、方法、角色与职责，以及团队与实物资源的管理方式，例如其中明确了“内部优先还是外购优先”的获取策略。
  - **成本基准**：用于评估资源获取成本，核实资源预算是否足够；若实际获取资源成本超出基准，则需通过变更请求调整。
- **项目文件**：提供获取资源所需的详细需求信息，主要包括：
  - **资源需求**：列出每个活动或工作包所需的资源类型与数量，是获取资源的直接依据。
  - **资源分解结构（RBS）**：按类别和类型分层展示项目所需的全部资源，帮助识别缺口与重复。
  - **活动清单与活动属性**：说明各活动的资源需求、技能要求以及活动之间的逻辑关系。
  - **项目进度计划**：显示各项活动的开始与完成日期，是判断资源需要在何时到位的依据。
  - **干系人登记册**：识别谁掌握资源、谁对资源获取有影响，是谈判与沟通的对象清单。
  - **项目团队派工单（如已存在）**：记录已分配到项目的团队成员及其角色职责，作为继续获取资源的现状基础。
  - **经验教训登记册**：提供以往项目在资源获取方面的经验与教训。
- **事业环境因素**：包括组织现有的员工信息（技能、经验、可用性数据库）、组织所在地区的劳动力与市场资源状况、组织的采购政策与合同类型、以及虚拟协作工具等基础设施条件，这些都会影响资源获取的方式与可行性。
- **组织过程资产**：包括组织关于资源可用性、资源管理与报告的政策与程序，历史项目积累的资源信息库、供应商与承包商名单，以及资源获取相关模板（如派工单模板、谈判指引）和经验教训。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具备资源管理经验的人员提供建议，例如如何与职能经理谈判、如何评估候选资源资质、如何在组织内部寻找替代资源等。项目经理可借助人力资源部门、采购专家、职能经理和历史项目团队的经验作出更合理的资源选择。
- **谈判**：获取团队资源的核心手段。项目经理通常需要与下列对象谈判：职能经理或部门负责人（争取高技能的内部人员并协商其投入项目的时间）、其他项目经理（在组织资源池中共享或调配稀缺人才）、供应商与承包商（就价格、交付时间、质量保证达成一致）。谈判的目标是在不损害组织整体利益的前提下为项目争取最优资源条件；当内部资源不足时，谈判还用于争取外部资源或替代资源。
- **预分派**：指某些资源在项目启动前就已确定，通常出现在三种情形：一是项目竞标过程中承诺了特定的关键人员（写入投标书）；二是项目取决于特定人员的专业技能（如只有某位专家能胜任的技术工作）；三是项目章程中明确规定了某些角色。预分派的资源无需再经过选择过程，直接写入项目团队派工单。
- **多标准决策分析**：当候选资源不止一个时，使用该方法系统评估并择优。典型做法是建立评估标准（如可用性、成本、经验、能力、知识、技能、态度、跨区域经验等），为每个标准赋予权重，再对每位候选资源打分并排序，选出综合得分最高者。该技术既可用于选择团队资源，也可用于评估实物资源（如设备品牌与型号）。
- **虚拟团队**：由地理上分散、依赖电子协作工具共同工作的成员组成。使用虚拟团队可以打破地域限制、利用全球人才库、降低差旅与办公场地成本。但虚拟团队也带来沟通、信任、文化差异等挑战，因此必须投入精力制定沟通规范、建立信任机制、明确时区与工作重叠时间，必要时安排线下见面以增强凝聚力。`,
      "📤 输出 Outputs": `- **项目团队派工单**：记录团队成员及其角色与职责的正式文件，列出被指派到项目的人员姓名、角色、职责和联系信息，是后续开展团队建设、绩效评估与沟通的基础；团队变化时可更新。
- **资源日历**：显示每个资源何时可用、可用多长时间的日历，是制定与更新进度计划的重要输入。资源日历分团队资源日历与实物资源日历，识别资源在不同时段是否可用（如休假、加班、设备检修），避免把资源安排在其不可用期间。
- **变更请求**：当获取资源过程中出现与计划不一致的情况时（如资源成本超出基准、资源可用日期变化、不得不采用替代资源），需提出变更请求并提交实施整体变更控制过程评估与审批。
- **项目管理计划更新**：主要更新资源管理计划与成本基准等组件，反映资源获取过程中的实际变化，使计划与实际保持一致。`,
      "🔗 与其他过程的相互作用": `获取资源过程处于资源管理链的中间环节，与前后过程紧密衔接。输入方面：它使用规划资源管理过程制定的资源管理计划，以及估算活动资源过程输出的资源需求与资源分解结构。输出方面：项目团队派工单与资源日历传递给制定进度计划过程，用于形成和优化进度安排；项目团队派工单还供建设团队与领导团队过程使用，作为开展团队激励、培训与绩效管理的对象基础。若资源获取引发变更，则触发实施整体变更控制过程；若涉及外部采购资源，则与实施采购过程协作（签署合同、接收供应商资源）。此外，获取资源过程中发现的资源缺口或过剩，会成为监控资源过程的关注对象。可以说，获取资源是“规划资源”与“使用并监控资源”之间的桥梁。`,
      "✂️ 裁剪考虑": `- **预测型（瀑布）**：资源需求在项目早期已详细规划，通常启动阶段一次性或分阶段集中获取资源，强调与职能经理的正式谈判与资源承诺，资源利用率相对可预测。
- **适应型（敏捷）**：资源往往按需、准时获取（just-in-time），强调跨职能自组织团队、成员一专多能；虚拟团队与外部短期资源（如专家顾问）更常见；资源需求随迭代变化而频繁调整。
- **混合型**：实物资源（设备、场地）可按预测方式提前获取，团队资源采用敏捷方式灵活配置，项目经理需同时管理两种获取节奏。
- **其他裁剪因素**：团队与资源的地理位置（本地还是跨时区）、资源获取成本、组织资源池规模与共享程度、以及外包程度，都会影响获取资源策略的详简与方式选择。`,
      "💼 实践案例": `某金融科技公司启动一个为期9个月的核心系统升级项目，需要5名后端开发、2名数据库专家和1名安全架构师。项目经理先在项目章程中获得预分派的安全架构师（因其掌握该系统的专有技术）。随后与产品线职能经理谈判，争取到3名资深开发，但仍有2名开发空缺。通过多标准决策分析（按技能匹配度、可用时间、成本、跨团队合作记录等加权标准打分），从外部资源池中选出2名顾问，并明确他们前3个月全职、之后按需投入的可用时间，据此更新资源日历。考虑到其中1名顾问在异地，项目组制定了虚拟团队沟通规范（固定晨会、共享协作平台、每月一次线下集中）。最终资源全部到位，进度计划得以顺利执行。`,
    },
    keyConcepts: `- **预分派**：项目启动前就已明确的资源，通常源于竞标承诺、专有技能需求或项目章程规定。
- **谈判**：与职能经理、其他项目经理、供应商等协商资源分配，是获取团队资源最常用的手段。
- **多标准决策分析**：按加权标准对多个候选资源进行评估和排序，提高选择客观性。
- **虚拟团队**：地理分散、依赖电子协作的团队，可降低差旅成本、扩展人才池，但需加强沟通与信任建设。
- **资源日历**：标明每个资源在何时可用、可用多长时间，是进度计划与资源调度的依据。
- **项目团队派工单**：正式记录团队成员、角色与职责的文件。
- **替代资源**：当首选资源因制约因素不可用时启用的备选方案，需评估其对项目目标的影响。
- **实物资源 vs 团队资源**：实物资源（设备、材料、场地）按数量获取，关注可用时间与地点；团队资源（人员）按技能与能力获取，关注可用性、经验与工作负荷；两者都要记入资源日历。
- **事业环境因素与组织过程资产**：组织的资源库、采购政策、历史资源数据等，都是获取资源的重要依据。`,
    examTips: `- 高频考点一：预分派的三类触发情形——竞标承诺、专有技能、章程规定。题目常问“该资源是否属于预分派”。
- 高频考点二：获取团队资源最常用的工具是谈判，谈判对象常为职能经理；资源不足时优先考虑谈判与替代资源，而不是直接拒绝或拖延。
- 高频考点三：多标准决策分析适用于候选资源有多个、需要系统择优的场景；注意题干给出的评估标准与权重。
- 虚拟团队是常考概念：优点（人才全球化、降低成本）、挑战（沟通与信任）；处理虚拟团队问题应先加强沟通与信任建设，而非立即要求线下见面。
- 资源日历是进度计划的重要输入；“某专家下周休假”意味着资源日历上该时段不可用，需相应调整进度。
- 获取资源发生在执行过程组，且“根据需要定期执行”而非一次性；若资源获取导致成本、进度变化，应提出变更请求。
- 易错点：把“获取资源”误当作“规划资源管理”或“估算活动资源”——估算活动资源回答“需要多少、什么类型”，获取资源回答“从哪里来、如何拿到手”。`
  },
  "proc-lead-team": {
    overview: `【过程概述】领导团队（Lead Team）过程属于执行过程组，是项目管理中“人”的维度的核心过程。其目的是运用知识、技能、工具与技术，通过提高团队成员的工作能力、促进成员互动、改善团队整体氛围来管理和领导团队，进而提高项目绩效。该过程还包括跟踪团队成员绩效、提供反馈、解决或上报问题、以及管理团队变更，从而持续优化项目绩效。它是决定团队能否高效协作、能否共同攻坚克难的关键。

领导团队过程包含两类相辅相成的活动：管理活动侧重实现项目目标的方法与流程，例如建立有效的过程、进行规划、协调、测量和监督工作；领导活动则侧重人员本身，包括影响、激励、倾听、赋能以及为团队扫清障碍。项目经理的角色是管理与领导的统一，二者缺一不可。

高绩效项目团队通常具备以下特征：开放沟通、共同理解、共同担当、信任、协作、适应性、韧性、赋能与授权及自主性、相互认可。Tuckman团队发展阶段模型描述了团队成长的一般路径：形成（Forming）→震荡（Storming）→规范（Norming）→成熟（Performing）→解散（Adjourning），每个阶段团队的氛围、凝聚力与效率各不相同，项目经理需要识别团队所处阶段并采取相应管理策略。同时，项目经理应对团队成员完成工作的意愿和能力保持敏感，根据情境与团队成熟度灵活调整自己的领导与管理风格。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：主要是**资源管理计划**，其中定义了团队角色与职责、团队建设与培训安排、绩效评估与认可机制以及团队管理方法，为领导团队提供政策与程序依据。
- **项目文件**：主要包括：
  - **团队章程**：由团队共同制定的行为准则与价值观，是管理团队行为、解决分歧的“团队内部契约”。
  - **项目团队派工单**：列出成员角色与职责，是分工与绩效跟踪的基础。
  - **问题日志**：记录已发生问题及其状态，领导团队过程中要持续跟踪并解决或上报。
  - **经验教训登记册**：积累团队管理与协作方面的经验，供当前与后续项目借鉴。
  - **团队绩效评价（如已存在）**：反映团队当前绩效状态，帮助项目经理确定激励与改进重点。
  - **干系人登记册**：识别团队成员及关键干系人的期望与影响。
  - **风险登记册**：识别与团队管理相关的风险（如人员流失、关键人员不可用）。
- **事业环境因素**：包括组织的人力资源政策、团队管理制度、绩效评价体系、考勤与休假制度、组织文化与价值观、员工能力数据库等。
- **组织过程资产**：包括组织关于团队管理、绩效管理、认可与奖励的政策程序，以及历史项目的团队绩效数据与经验教训。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借鉴人力资源管理专家、组织行为专家或资深项目经理的经验，判断如何激励特定成员、如何处理棘手的团队冲突，以及如何评估与调整团队结构。
- **沟通技能**：领导团队的一切活动都建立在沟通之上，主要包括：
  - **积极倾听**：不仅听语言内容，还要理解情绪与意图，为成员提供安全感与尊重。
  - **反馈**：及时、具体、建设性地给予正面与改进反馈，帮助成员调整行为、纠正错误，形成反馈循环。
  - **公开透明**：就项目状态、变更、问题等信息保持透明，建立信任、减少小道消息。
- **人际关系与团队技能**：这是领导团队过程的核心工具组合，包括：
  - **冲突管理（解决冲突）**：识别并尽早处理冲突，通常有五种方法：合作/解决问题（双方协商寻找共识与双赢方案，是最理想方式）、妥协（各退一步、各自有所让步）、缓和/包容（强调一致、淡化分歧，适用于关系维护优先时）、强迫/命令（以权力强行解决，快速但可能伤及关系）、回避/撤退（暂缓处理，适用于冲突激烈或需要冷静时）。项目经理应选择与情境匹配的方法，理想目标是合作。
  - **激励**：运用激励理论激发成员工作热情。Maslow需求层次理论主张按生理、安全、社交、尊重、自我实现由低到高逐层满足；Herzberg双因素理论区分保健因素（薪酬、办公条件等只能消除不满）与激励因素（成就、认可、成长等才能真正激发积极性）；McGregor X/Y理论中，X理论假设人厌恶工作需强制管理，Y理论假设人乐于负责、具创造力，宜授权与自主——现代项目管理更倾向Y理论。
  - **情商（EI）**：识别、理解和管理自身与他人情绪的能力，包含自我意识、自我管理、社会意识、关系管理四个维度。高情商的项目经理更能处理压力、化解冲突、赢得信任。
  - **影响力**：通过说服、逻辑、愿景感召而非单纯职权来推动他人行动。
  - **制定决策**：在团队管理中作出公正、及时、合理的决策。
  - **领导力风格（情境领导力）**：根据团队成熟度（能力+意愿）调整领导方式：对低能力高意愿的新手采用**指导型**（明确指令、逐步示范）；对能力部分具备、信心不足的成员采用**教练型**（指导与支持并重）；对有能力但意愿波动的成员采用**支持型**（多鼓励、少指令）；对高能力高意愿的成熟团队采用**授权型**（充分放权）。此外，**仆式领导**（servant leadership）强调服务优先、为团队扫除障碍、培养成员成长，是敏捷项目尤其推崇的风格。
  - **团队建设**：通过团建活动增强凝聚力与信任。
  - **授权赋能**：在明确边界内把决策权与责任下放给成员，激发主人翁意识与自主性；前提是成员具备相应能力并清楚期望。
- **会议**：通过定期团队例会、一对一沟通、绩效回顾会、冲突调解会等会议形式，跟踪状态、同步信息、解决争议、庆祝成果。虚拟团队尤其依赖会议规范来维持沟通与信任。`,
      "📤 输出 Outputs": `- **问题日志**：领导团队过程中发现或新产生的问题（如成员冲突、绩效问题、协作障碍）应及时记录、跟踪并推动解决；无法解决的上报管理层。
- **变更请求**：若团队管理活动导致需要调整人员、角色、职责、进度或预算（如人员变动、绩效改进方案、重新分配工作），应提出变更请求并经实施整体变更控制过程审批。
- **项目管理计划更新**：主要是资源管理计划更新，反映团队结构、角色职责、绩效管理方法等的变化。
- **项目文件更新**：包括项目团队派工单（成员变动）、团队章程（行为规范修订）、经验教训登记册（记录团队管理经验）、干系人登记册等文件的更新。`,
      "🔗 与其他过程的相互作用": `领导团队过程位于“组建与建设团队→领导团队→监控项目”的人员管理链条上。输入方面：它使用规划资源管理过程的资源管理计划，以及建设团队过程产出的团队绩效评价等成果。输出方面：更新后的问题日志、项目文件是监控项目工作、监督风险与干系人参与的基础；提出的变更请求进入实施整体变更控制过程，审批通过后影响其他计划。领导团队与获取资源、建设团队过程相互支撑——获取资源解决“人从哪里来”，建设团队解决“团队如何成型与成长”，领导团队则持续激励、协调、纠偏。此外，领导团队的绩效表现会反映为工作绩效数据，供监控项目工作过程评估。`,
      "✂️ 裁剪考虑": `- **预测型**：团队角色与职责在前期明确，多采用分层管理，领导方式偏正式，绩效评估与认可制度较为结构化。
- **适应型（敏捷）**：推崇自组织团队与仆式领导，项目经理以服务团队、排除障碍、教练成长为核心，命令与控制色彩最弱，强调持续反馈与授权。
- **混合型**：核心团队采用敏捷式赋能管理，外部或合同团队采用较正式的管理，项目经理需在不同风格间灵活切换。
- **虚拟与跨文化团队**：需投入更多精力于沟通规范、信任建设与跨文化敏感性，领导方式要兼顾时区与文化差异。
- **团队规模**：小团队适合高授权、强互动；大规模团队需要更结构化的沟通与协调机制。`,
      "💼 实践案例": `某项目启动不久便陷入明显的震荡期：两名资深工程师因技术方案分歧激烈争执，会议气氛紧张，交付进度开始滞后。项目经理没有立即用行政命令压制，而是先分别与两人单独沟通，倾听各自顾虑（尊重其职业自尊），再组织一次冲突调解会，引导双方聚焦“哪种方案更能满足客户价值”这一共同目标，采用合作式冲突解决。同时，项目经理识别出团队整体处于能力与意愿过渡阶段，采用教练型领导风格，加强目标澄清与技术辅导；并运用Herzberg的激励因素，在里程碑达成时公开认可团队贡献。经过两周调整，团队进入规范期，凝聚力回升，进度恢复正常——这正是Tuckman模型与情境领导力在实践中的典型应用。`,
    },
    keyConcepts: `- **Tuckman团队发展阶段**：形成（成员相互试探、依赖领导者）→震荡（分歧与权力斗争、效率下降）→规范（共识建立、协作成形）→成熟（高效自主运作）→解散（任务完成、团队收尾）。
- **Maslow需求层次理论**：生理→安全→社交→尊重→自我实现，由低到高逐层满足，激励需先满足较低层次。
- **Herzberg双因素理论**：保健因素（薪资、环境、关系，只能消除不满、无法激励）vs 激励因素（成就、认可、责任、成长，真正的激励来源）。
- **McGregor X/Y理论**：X理论假设人逃避工作、需要强制；Y理论假设人乐于负责、具有创造力；Y理论更契合现代赋能式管理。
- **冲突管理的五种方法**：合作（双赢，首选）、妥协、缓和、强迫、回避；应匹配情境选择，理想目标为合作。
- **情商（EI）**：自我意识、自我管理、社会意识、关系管理，是卓越领导力的基础。
- **情境领导力**：指导型、教练型、支持型、授权型四种风格，按团队成熟度匹配。
- **仆式领导**：以服务他人、支持团队成长、排除障碍为先，是敏捷领导的核心。
- **授权赋能**：在明确边界内下放决策权与责任，激发成员自主性与主人翁意识。
- **团队绩效评价**：通过目标与指标评估团队整体绩效及改进方向，是持续改进的输入。`,
    examTips: `- Tuckman模型是必考高频点：牢记顺序形成→震荡→规范→成熟→解散，并能根据题干判断团队所处阶段——例如“成员间出现激烈分歧”通常指向震荡期。
- 激励理论三件套必背：Maslow看需求层次；Herzberg区分激励因素与保健因素（经典陷阱：“加薪属于激励因素吗？——属于保健因素，只能消除不满”）；McGregor X/Y理论（题干描述员工主动负责、乐于创造→Y理论）。
- 冲突管理五法的关键区别：目标是合作/解决（双赢）；时间紧迫、危机时刻用强迫；关系优先、分歧不严重用缓和；各方僵持时可用回避暂缓。考试问“最佳做法”通常选合作。
- 情商是领导力基础：体现为识别和管理情绪、理解他人感受；问“项目经理如何赢得团队信任”往往对应高情商的倾听与坦诚。
- 情境领导力：按团队成熟度选择风格——新成员多指导、成熟团队多授权；仆式领导关键词是服务、扫除障碍、培养成长。
- 管理vs领导的区别是常考点：管理=流程/规划/控制；领导=影响/激励/赋能。
- 授权赋能不等于放任不管：授权需明确边界、提供支持、跟踪结果。
- 团队绩效评价关注团队整体而非单纯个人考核，目的是改进协作与绩效。`
  },
  "proc-monitor-resources": {
    overview: `【过程概述】监控资源（Monitor Resources）过程属于监控过程组，其目的是确保分配给项目的实物资源或团队资源能够按照计划提供，并持续监督资源的计划使用与实际使用情况，在发现偏差时及时采取纠正措施。该过程的关键收益是：确保所分配的资源在恰当的时间、恰当的地点可用于项目，并且在不再需要相关资源时予以释放——从而避免资源闲置浪费、资源短缺导致停工或紧急采购。监控资源过程应在所有项目阶段和整个项目生命周期中持续执行，而非只在里程碑处检查一次。

监控资源过程主要关注六个方面：监督资源支出（成本是否超支）；及时识别并处理资源缺乏或过剩；确保按照计划和项目需求使用与释放资源；在出现与资源相关的问题时及时通知干系人；识别并影响可能导致资源使用变更的因素；在实际变更发生时进行管理。在监控时还需区分团队资源与实物资源：团队资源重点监控工作负荷、技能匹配与利用率，实物资源重点监控数量、质量、消耗与库存；两类资源都要结合资源日历与实际使用记录加以核对。

资源管控不力会直接威胁项目成功。例如：未能及时获取关键设备可能造成生产延误；订购低质量材料可能损害产品质量并导致频繁返工或召回；库存过多推高运营成本，库存过少则可能无法满足客户需求。因此，监控资源不仅是“记账”，更是主动的风险与绩效管理。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：主要是**资源管理计划**，规定了资源监控的方式（如何跟踪、评估和报告资源使用）与偏差处理程序；项目进度计划用于判断资源使用是否与进度匹配。
- **项目文件**：包括**资源需求**（明确各类资源的数量与类型，作为对比基准）、**资源日历**（显示资源的计划可用时间，用于核对实际使用）、**项目团队派工单**（成员角色与职责）、**进度计划与进度数据**、**问题日志**（记录与资源相关的问题）、**经验教训登记册**、**干系人登记册**等。
- **工作绩效数据**：反映资源实际使用情况的原始数据，例如已完成的工作量、实际使用的工时与设备小时数、已领用的材料数量、资源成本的实际发生额等，是“计划vs实际”对比的基础。
- **协议**：包括与供应商、承包商签订的采购协议，其中明确了资源交付、数量、质量、违约条款等，是核查实物资源是否符合要求的依据。
- **组织过程资产**：包括组织关于资源监控的政策与程序、历史项目资源使用数据、资源利用率基准、以及资源报告模板。`,
      "🔧 工具与技术 Tools": `- **数据分析**：对资源数据进行分析以发现偏差，常用方法包括：
  - **资源利用率分析**：比较资源的实际使用与可用情况，计算利用率（实际使用/可用），识别资源闲置或过载。
  - **挣值分析（EVA）**：通过进度偏差（SV）与成本偏差（CV）等指标，综合判断资源使用是否导致进度与成本偏离计划。
  - **趋势分析**：观察资源使用的历史变化趋势，预测未来资源需求与短缺风险。
  - **绩效审查**：定期对比资源计划绩效与实际绩效，识别偏差原因。
  - **对比分析**：将计划资源使用与实际资源使用进行对比，找出差异并分析根因。
  - **数据表现（图表）**：利用直方图显示资源在时间段内的计划与实际使用量，利用累计流量图展示资源消耗趋势，直观识别资源过载或闲置时段，辅助决策。
- **问题解决**：当发现资源不足、过剩或质量问题时，采用结构化的问题解决流程：定义问题→分解根本原因（如利用根本原因分析、因果图）→生成备选方案→评估并选择方案→实施并验证，目的是把资源偏差彻底解决，而非临时凑合。问题解决强调先找根因再行动，避免头痛医头、脚痛医脚。
- **人际关系与团队技能**：包括**谈判**（与职能经理、供应商协商资源调配或补充）、**影响力**（推动干系人接受资源调整方案）、**冲突管理**（协调因资源争夺引发的冲突）、**协调**（在多项目共享资源时协调优先级）。
- **项目管理信息系统（PMIS）**：使用资源管理软件、进度管理工具、库存系统等自动跟踪资源的使用、记录工时、管理库存、生成资源报告，提高监控的实时性与准确性，减少人工差错。`,
      "📤 输出 Outputs": `- **工作绩效信息**：将工作绩效数据经过分析与整合后形成的信息，例如资源利用率报告、实际vs计划资源对比结果、资源偏差及其原因、趋势预测等。它是监控项目工作过程的重要输入，供项目经理与干系人了解资源绩效状态并作出决策。
- **变更请求**：当监控发现资源偏差需要调整计划时（如追加资源、替换低效资源、调整资源分配、变更采购数量），提出变更请求（纠正措施、预防措施、缺陷补救或更新）并提交实施整体变更控制过程审批。
- **项目管理计划更新**：主要是资源管理计划更新，包括资源分配、监控方法、利用率基准等的调整；如资源调整影响进度或成本，还需经变更审批后更新进度计划与成本基准。`,
      "🔗 与其他过程的相互作用": `监控资源是资源管理链的“闭环”环节。输入方面：它接收执行过程中产生的资源工作绩效数据、获取资源过程的成果（资源日历、项目团队派工单）以及规划资源管理过程的资源管理计划。输出方面：形成的工作绩效信息供监控项目工作过程进行整体绩效评估；提出的变更请求进入实施整体变更控制过程，审批后更新相应计划并反馈给执行。当监控发现资源不足或质量问题时，可能需要重新触发获取资源过程，或与实施采购过程协作（补充采购、更换供应商）。此外，监控资源发现的资源约束与风险会更新风险登记册并反馈给规划过程，实现资源管理的持续改进。`,
      "✂️ 裁剪考虑": `- **预测型**：资源监控较正式，通常按固定周期（如每周、每月）开展绩效审查与资源报告，强调计划vs实际的严格对比。
- **适应型（敏捷）**：资源在迭代中动态配置，监控更关注团队资源利用与产能（如速度、在制品数量），实物资源常按需小批量补充，监控轻量而频繁（如每日站会中的瓶颈识别）。
- **混合型**：实物资源按预测方式严格监控，团队资源按敏捷方式灵活调整；两类资源的监控频率与粒度不同。
- **其他因素**：项目规模、资源成本与关键性、是否涉及外部供应商、组织资源管理制度，决定监控的严格程度；关键实物资源（如唯一的生产设备）需更高频、更精细的监控。`,
      "💼 实践案例": `某制造项目按计划应使用1000吨特种钢材，采用预测型方式一次性订购。监控资源过程中，项目经理发现第二季度实际领用仅完成计划的70%，而库存已接近全部到位——意味着资金占用与仓储成本上升，且后续几个月可能出现过剩。项目经理通过数据分析（实际vs计划对比、趋势分析）确认钢材消耗速度低于预期，立即与干系人沟通，协调将部分批次延迟交付（与供应商谈判），同时根据最新进度计划重新计算资源需求。这一调整避免了库存积压导致的运营成本上升，也确保了关键工序的钢材不断供。这正是“及时识别资源过剩、主动采取纠正措施”的监控资源典型做法。`,
    },
    keyConcepts: `- **资源利用率**：实际使用资源与可用资源的比率，反映资源充分利用程度；过高可能过载，过低可能闲置。
- **资源绩效**：资源使用的效率与效果，包括按时、按质、按量完成工作的程度。
- **资源平衡（Resource Leveling）**：当资源过度分配或数量不足时，调整活动的开始或完成日期以匹配资源可用性；它可能改变活动计划日期，从而**延长关键路径**，甚至改变网络逻辑关系。
- **资源平滑（Resource Smoothing）**：仅在活动的总浮动时间（Float）内调整活动，使资源需求波动最小化；它**不会影响关键路径**，因为关键路径活动没有浮动时间。
- **库存管理**：管理实物资源的库存水平，在“库存过多导致成本高”与“库存过少导致断供”之间取得平衡，常涉及订货点、批量与经济订货量等概念。
- **工作绩效数据 vs 工作绩效信息**：数据是未经处理的原始记录；信息是经过分析、可供决策使用的加工结果。
- **纠正措施**：为消除已发现的资源偏差而采取的行动。
- **资源负荷 vs 资源产能**：负荷是计划分配给资源的工时总量，产能是资源可用工时；负荷超过产能即为资源过载，是触发资源平衡或资源平滑的信号。`,
    examTips: `- 资源平衡vs资源平滑是最经典考点：平衡可能延长关键路径、可改变网络逻辑；平滑只在浮动时间内调整、不改变关键路径。判断题常设置陷阱。
- 资源利用率=实际使用/可用：题目问某设备利用率含义，或判断利用率过高/过低时的对策。
- 监控资源关注实物与团队资源的使用情况，核心是“计划vs实际”对比——工作绩效数据是原始数据，工作绩效信息是分析后的信息。
- 监控资源输出的是“工作绩效信息”而非“工作绩效数据”；数据→信息是监控过程的增值。
- 库存管理是重要概念：库存过多=成本高、资金占用；库存过少=断供风险；要在二者间取得平衡。
- 监控资源过程持续执行于整个生命周期而非一次性；发现问题应及时提出变更请求（纠正措施或预防措施）。
- 工具中“数据分析”常考具体方法（挣值分析、趋势分析、对比分析）；“项目管理信息系统”用于自动跟踪与报告。
- 易错点：把监控资源误当成“控制进度/成本”——监控资源的重点是资源本身（可用性、利用率、库存），而非整体进度成本绩效。
- 监控时先看“计划vs实际”：偏差小可继续观察，偏差大要分析根因并采取纠正措施，而不是一上来就修改计划。
- 当资源负荷超过产能（过载）时，优先判断能否在浮动时间内用资源平滑解决；若平滑无法满足，再考虑资源平衡（允许延长关键路径）。`
  },
  "proc-plan-risk-mgmt": {
    overview: `规划风险管理过程旨在，在项目早期（从项目构思阶段启动）就明确各类风险管理活动的开展方式。该过程回答"如何在项目中开展风险管理"这一根本问题，为后续所有风险活动定下基调与规则。
- **过程目的**：确定风险管理的方法论、角色与职责、预算与时间安排、风险类别、评估标准与报告方式，使风险管理有章可循。
- **关键收益**：确保风险管理的程度、类型和可见度与风险本身及项目对组织的重要性相匹配——风险管理工作既不过度、也不不足。
- **执行时机**：应在项目构思阶段启动，并在项目早期完成；风险管理计划作为项目管理计划的一个子计划，在批准后为整个项目风险管理提供框架。
- **动态特性**：风险管理不是一次性活动，风险管理计划可随项目推进与组织环境变化在监督风险过程中更新。

风险管理计划记录了如何开展风险管理活动，通常包括：风险管理策略（定义通用方法）、角色与职责（定义谁负责什么）、资金（确定风险管理的预算和时间）、时间安排（定义何时进行风险管理活动）、风险类别（如使用风险分解结构RBS）、干系人风险偏好、风险概率和影响的定义（定义评估标度）、概率和影响矩阵（确定风险优先级）、修订的干系人风险临界值、报告格式、跟踪方法。

风险分解结构（RBS）是按风险来源和类别进行层级化分解的工具，帮助团队系统地识别风险。风险偏好是组织愿意接受的不确定性程度；风险承受力是对某一目标可接受偏差的度量；风险临界值是触发特定行动的特定数值，三者含义不同，是高频辨析考点。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：提供项目目的、高层级需求、总体里程碑、总体预算与时间约束，以及主要干系人与发起人信息。规划风险管理据此判断项目对组织的重要性，从而校准风险管理工作的规模与可见度——例如高战略价值的项目需要更精细的风险管理。章程中高层级的不确定性描述也是风险类别设定的参考起点。
- **项目管理计划**：包含范围、进度、成本、质量、资源、沟通、干系人等各子计划，为风险管理策略提供项目上下文。例如，进度管理计划中的变更阈值、成本管理计划中应急储备的管理方式，直接影响风险管理计划中临界值与资金安排的设定。编制风险管理计划时需确保与其他子计划的假设和方法保持一致。
- **事业环境因素**：组织文化、市场条件、行业标准与监管法规、组织内部的政策与风险偏好、干系人数据库等。这些内外部环境决定了组织能够接受的风险程度和可用的风险管理资源，直接影响风险管理策略的选择——例如高度监管行业的组织必须采用更保守的风险管理方法。
- **组织过程资产**：组织的风险管理政策与程序、风险类别模板、风险分解结构模板、概率与影响标度模板、以往项目的经验教训登记册与风险登记册数据。充分复用这些资产可显著提高规划效率，并保持组织内风险管理实践的一致性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由具有风险管理经验的干系人（如项目经理、PMO、组织风险管理专家、主题专家、外部顾问）提供。作用在于确定适合本项目的风险管理策略、裁剪组织标准的模板与类别、判断概率影响标度与临界值设置是否合理，并评估干系人对风险的态度。专家判断应结合多元视角，避免单一判断偏差。
- **数据分析**：在规划风险管理过程中主要用于干系人分析——识别干系人对风险的态度与风险偏好差异，例如有的干系人是风险厌恶型，有的是风险追求型，这些差异会影响风险临界值的设定与风险管理策略的制定。也可用于分析历史数据（如以往项目的风险分布规律）来指导类别与标度设计。
- **会议**：通常召开规划风险管理会议，由项目经理召集项目团队与关键干系人（发起人、客户、主题专家）参加。会议讨论并确定：风险管理策略与方法论、角色与职责、资金与时间安排、风险类别（RBS）、概率与影响定义、概率和影响矩阵、干系人风险临界值、报告格式与跟踪方法，会议成果汇总形成风险管理计划。若组织已有成熟模板，会议可更聚焦于裁剪与确认。`,
      "📤 输出 Outputs": `- **风险管理计划**：这是本过程唯一的输出，是项目管理计划的子计划之一，描述如何安排与执行风险管理活动。内容通常包括：风险管理策略（通用方法，如预测型还是敏捷型、定性与定量结合程度）、方法论、角色与职责（谁负责什么，含风险责任人制度）、资金（风险管理活动的预算与应急储备安排）、时间安排（何时开展各类风险活动）、风险类别（RBS）、干系人风险偏好、风险概率和影响的定义（评估标度，如"概率极高=80%~100%"）、概率和影响矩阵（分级规则）、修订的干系人风险临界值、报告格式（报告频率与分发对象）、跟踪方法（如何记录与审计风险活动）。风险管理计划是后续识别风险、实施风险分析、规划与实施风险应对、监督风险等过程的行动指南。`,
      "🔗 与其他过程的相互作用": `规划风险管理是风险知识域中的第一个过程，是所有风险活动的"总纲"。它输出的风险管理计划直接指导后续过程：识别风险（提供风险类别与RBS）、实施风险分析（提供概率影响定义、矩阵与临界值）、规划与实施风险应对、监督风险（提供报告格式与跟踪方法）。同时，风险管理计划作为项目管理计划的一部分，与范围、进度、成本、质量、沟通、干系人等子计划相互协调——风险管理预算须纳入成本基准，风险活动的时间安排须纳入进度计划。此外，规划风险管理还会参考项目章程与整体项目管理计划，并与干系人识别、沟通规划等活动联动。`,
      "✂️ 裁剪考虑": `- **预测型（瀑布）**：在项目规划阶段集中制定详细的风险管理计划，强调完整的RBS、概率影响矩阵与正式的审批流程。
- **适应型（敏捷）**：风险管理常简化为轻量机制，可能没有独立的风险管理计划，而是把风险作为待办事项列表中的条目，在迭代规划与回顾中持续处理；RBS可精简为若干大类。
- **混合型**：在骨架计划上采用预测型方法，同时允许交付层面的迭代式风险管理。
- **规模裁剪**：小型项目可使用组织模板快速生成风险管理计划，减少正式文档；大型复杂项目则需要更细的RBS、更严格的数据定义与更高的可见度。
- **行业裁剪**：监管严格的行业（医药、金融、航空航天）需强化合规类风险类别与审计跟踪；创新研发项目则需更关注机会类别。`,
      "💼 实践案例": `某中型软件公司承接一个为期10个月的核心系统迁移项目。项目经理在项目构思阶段召集发起人、客户代表、技术负责人与财务专家召开规划风险管理会议。会议确定：风险管理采用定性为主、必要时定量的混合策略；按组织惯例采用RBS四类分解（技术、外部、组织、项目管理）；定义五级概率与影响标度（如"概率极高=80%~100%"），建立5×5概率和影响矩阵，规定高概率高影响（红色区）风险需优先应对；根据公司"风险中立"的偏好，将进度偏差临界值设为±10%、成本偏差临界值设为±5%；明确每月召开风险评审会及其报告格式与跟踪方法。最终形成的风险管理计划获得发起人批准，作为后续所有风险活动的统一依据。`,
    },
    keyConcepts: `- **风险管理计划**：定义如何在项目中开展风险管理活动的子计划，涵盖策略、角色与职责、资金、时间、类别、评估定义、概率影响矩阵、临界值、报告格式与跟踪方法。
- **风险分解结构（RBS）**：按风险来源和类别进行层级化分解的工具，帮助团队系统、无遗漏地识别风险；注意它是按"风险来源"分类，而非按部门或WBS分类。
- **风险偏好（Risk Appetite）**：组织愿意接受的不确定性程度，是组织层面的态度，回答"愿意承担多少风险"。
- **风险承受力（Risk Tolerance）**：对某一具体目标可接受偏差的程度或范围，是"能容忍多大偏差"的量化口径，如进度偏差±10%。
- **风险临界值（Risk Threshold）**：触发特定行动（如上报告、启动应对）的特定数值，如成本超预算5%即触发预警。
- **概率和影响矩阵**：把概率标度与影响标度交叉分级、据此确定风险优先级的工具，高概率高影响的风险优先应对。
- **风险类别**：将潜在风险按来源归组，常通过RBS体现，用于提高识别效率与一致性。`,
    examTips: `- RBS按"风险来源"分类——不要误选"按部门"或"按WBS"分类。
- 风险偏好（愿意接受的不确定性程度）vs 风险承受力（可接受偏差的范围）vs 风险临界值（触发行动的特定数值）三者必须区分清楚，考概念辨析。
- 规划风险管理应在项目构思阶段启动、项目早期完成——不是执行阶段才开始。
- 风险管理不是一次性活动，风险管理计划可在项目期间更新。
- 风险管理计划的内容构成是常考点：策略、角色与职责、资金、时间、类别、概率影响标度、矩阵、临界值、报告格式、跟踪方法。
- 注意"风险管理的程度、类型和可见度须与风险及项目重要性相匹配"——既不过度、也不不足。
- 概率和影响矩阵在规划风险管理中定义，在实施风险分析中使用，要分清两者的归属。`
  },
  "proc-identify-risks": {
    overview: `识别风险过程旨在发现负面风险（威胁）和正面风险（机会）。该过程贯穿项目始终，是一个迭代过程。
- **过程目的**：尽可能完整地识别出可能影响项目目标的不确定性事件（包括机会与威胁），并将其记录在风险登记册中。
- **关键收益**：为项目团队建立风险初始清单，同时区分真实风险与非风险因素（如顾虑和问题）——顾虑是未经分析的担心，问题是已发生需要处理的事项，而风险是尚未发生的不确定事件，三者不能混淆。
- **执行方式**：由项目经理召集团队与干系人，借助专家判断、头脑风暴、德尔菲技术、访谈、SWOT分析、假设与制约因素分析、核对单、提示清单等多种方法开展。风险识别通常在规划阶段系统进行，并在执行与监控阶段持续迭代。
- **固有不确定性**：并非所有风险都能在一开始就被识别出来，因为项目启动时就存在固有的不确定性和未知因素。因此风险识别随项目推进、信息完善不断补充，是一个持续演进的迭代过程。

风险描述强调按"原因→事件→后果"的结构书写，帮助团队讲清风险链条。所有已识别的风险记入风险登记册，整体项目风险敞口信息记入风险报告——二者是识别风险的主要输出，并在整个项目期间持续更新。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：风险管理计划提供风险类别、RBS、概率与影响标度定义等框架；范围、进度、成本、质量、资源、采购、沟通、干系人等子计划提供识别风险的上下文——例如采购计划中的外部供应商依赖、进度计划中的关键路径活动都可能成为风险来源。
- **项目文件**：假设日志（逐条检验假设是否成立）、成本估算与持续时间估算（估算的不确定性即潜在风险）、问题日志（已发生问题可能衍生新风险）、经验教训登记册（以往项目的风险教训）、资源需求、干系人登记册、进度计划与成本基准等。项目文件是识别风险最丰富的来源之一。
- **协议**：合同中的条款、交付要求、处罚与奖励机制、责任界定，可能引出供应商不履约、法律纠纷、付款条件变化等风险。
- **采购文档**：招标文件、供应商建议书、报价单等，可从中识别供应商能力不足、交付延迟、价格上涨等采购相关风险。
- **事业环境因素**：市场与行业条件、法规环境、天气与地理条件、外部竞争、政治稳定等因素，是外部风险的重要来源。
- **组织过程资产**：历史项目的风险登记册、经验教训、风险类别与核对单模板、以往项目数据的统计规律，可显著加速并校准风险识别。`,
      "🔧 工具与技术 Tools": `- **专家判断**：邀请具备项目经验、行业知识或领域专长的干系人（主题专家、发起人、PMO、外部顾问）参与，帮助确认已识别风险的完整性，并从多视角补充潜在风险。专家判断常与访谈、德尔菲等数据收集方法结合使用。
- **数据收集**：包括四种常用方法——**头脑风暴**（团队集思广益，主持人引导先发散后收敛，快速产出大量风险想法，期间禁止批评以保护创意，适合产生新风险清单）；**核对单**（基于历史经验与组织模板列出常见风险条目逐项核对，速度快但可能遗漏清单之外的新风险）；**访谈**（与资深干系人或专家一对一深入交流，获取其对具体风险的洞察）；**问卷调查/德尔菲技术**（向多位专家匿名发放问卷，多轮汇总与反馈直至意见收敛达成共识，可消除权威影响与群体思维压力，尤其适合专家地理分散或需要避免权威主导的场景）。
- **数据分析**：包括**根本原因分析**（追查问题或风险的深层原因，从原因端识别风险，避免"头痛医头"）；**假设与制约因素分析**（逐一检验假设日志中的假设是否成立、制约因素可能引发哪些风险）；**SWOT分析**（Strengths优势与Weaknesses劣势来自组织内部，Opportunities机会与Threats威胁来自外部环境，通过内外交叉分析，用优势捕捉机会、弥补劣势带来的威胁）；**文件分析**（审查项目文件，识别其中的不一致、缺口与隐含风险）。
- **人际关系与团队技能**：主要是**引导**——由具备引导技能的引导者主持风险识别研讨会，确保所有参与者平等发言、聚焦主题、高效产出，避免少数人主导讨论。
- **提示清单**：用于系统性地提示风险来源的清单，常见的有**PESTLE**（政治Political、经济Economic、社会Social、技术Technological、法律Legal、环境Environmental）、**TECOP**（技术Technological、环境Environmental、商业Commercial、运营Operational、政治Political）、**VUCA**（易变性Volatility、不确定性Uncertainty、复杂性Complexity、模糊性Ambiguity）等。提示清单帮助团队从宏观维度逐一扫描，防止遗漏大类风险。
- **会议**：风险识别研讨会，由项目团队、干系人与专家参加，使用上述技术与提示清单系统开展；由于风险识别是迭代过程，此类会议在项目期间需多次召开。`,
      "📤 输出 Outputs": `- **风险登记册**：识别风险的关键输出，记录每个已识别风险的详细信息。典型结构包括：风险编号、风险描述（按"原因→事件→后果"结构，如"由于供应商产能不足（原因），导致关键组件交付延迟（事件），进而造成项目进度延误两周（后果）"）、风险类别、概率与影响评估（初步或后续补充）、风险应对策略（后续过程填充）、风险责任人、触发条件等。风险登记册在项目期间持续更新，是风险管理的核心数据载体。
- **风险报告**：汇总整体项目风险敞口的信息，包括整体风险的评估结论、影响项目关键目标的风险概览、风险所有权分配等，供管理层与干系人了解全局风险态势。
- **项目文件更新**：识别风险后可能更新假设日志（假设被证伪或产生新假设时）、问题日志（识别出的问题）、经验教训登记册（风险识别的教训与来源），确保项目文件与最新认识一致。`,
      "🔗 与其他过程的相互作用": `识别风险承接规划风险管理的输出——风险管理计划提供风险类别、RBS与评估框架；同时大量使用规划过程产出的项目文件、协议与采购文档。识别风险是风险分析的前置环节，其输出的风险登记册与风险报告直接作为实施风险分析的输入。识别过程中发现的"问题"需转入问题日志，由问题管理流程处理，并与干系人沟通活动联动。由于风险识别是迭代过程，它持续发生在规划、执行与监控各阶段，与监督风险过程循环联动，形成"识别→分析→应对→监控→再识别"的闭环。`,
      "✂️ 裁剪考虑": `- **预测型**：通常在规划阶段举办集中的风险识别研讨会一次性系统识别，随后在里程碑处补充。
- **适应型（敏捷）**：识别风险融入迭代规划会议与迭代回顾，风险条目进入待办事项列表并持续重新评估；团队通常使用轻量的"风险待办"机制，而非厚重的风险登记册。
- **混合型**：高层级风险在规划阶段识别，交付层面的风险在迭代中持续识别。
- **规模裁剪**：小型项目可只用头脑风暴加核对单快速识别；大型复杂项目则需访谈、德尔菲、SWOT、文件分析等全套手段并多次迭代。
- **参与范围裁剪**：高风险项目应扩大干系人参与范围，必要时引入外部专家与独立审查者，以提高识别的完整性。`,
      "💼 实践案例": `某银行核心系统升级项目召开风险识别研讨会，参会者包括项目经理、业务分析师、架构师、合规官与供应商代表。团队先用SWOT分析识别内部优势（成熟团队）与劣势（遗留系统复杂），再扫描外部机会（云技术降低成本）与威胁（监管新规、供应商依赖）。随后用核对单复用本行过往项目的常见风险，并对供应商交付风险使用德尔菲技术征询多名专家意见，经两轮匿名反馈达成共识。会议最终识别出38项风险，并逐条按"原因→事件→后果"写入风险登记册，例如"由于监管政策修订（原因），可能导致合规改造工作量激增（事件），从而影响系统上线进度并增加成本（后果）"。项目经理同时将识别出的两个新问题记入问题日志，将整体风险态势汇入风险报告供管理层审阅。`,
    },
    keyConcepts: `- **风险识别**：发现威胁与机会，区分真实风险与顾虑、问题，是一个贯穿始终的迭代过程。
- **SWOT分析**：Strengths/Weaknesses来自内部，Opportunities/Threats来自外部，内外交叉分析识别风险与机会。
- **德尔菲技术**：专家匿名、多轮意见征询与反馈、最终达成共识，可避免权威主导与群体思维。
- **提示清单**：PESTLE（政治/经济/社会/技术/法律/环境）、TECOP（技术/环境/商业/运营/政治）、VUCA（易变性/不确定性/复杂性/模糊性），用于系统性扫描风险来源。
- **风险登记册**：记录每个已识别风险的详细信息，核心字段包括风险描述（原因→事件→后果）、类别、概率与影响、应对策略、责任人、触发条件。
- **风险报告**：汇总整体项目风险敞口的信息。
- **风险描述结构**："原因→事件→后果"，把风险的来龙去脉讲清楚。`,
    examTips: `- SWOT分析：Strengths/Weaknesses是内部因素，Opportunities/Threats是外部因素——勿混淆。
- 德尔菲技术：专家匿名、多轮迭代、达成共识；若题中强调"匿名""避免权威影响"，选德尔菲。
- 识别风险是迭代过程，不是一次性活动；风险登记册需在整个项目期间持续更新。
- 要区分真正的风险与顾虑、问题：问题已发生需立即处理，风险尚未发生。
- 头脑风暴强调先发散后收敛、期间不批判；核对单快速但可能遗漏清单外风险。
- VUCA各维度：V易变性、U不确定性、C复杂性、A模糊性，考字母含义。
- 风险描述按"原因→事件→后果"结构书写，原因在前、后果在后。
- 提示清单（PESTLE/TECOP）是"工具与技术"中的独立工具，不是数据收集方法。`
  },
  "proc-perform-risk-analysis": {
    overview: `实施风险分析过程旨在，采用迭代方法（可能结合定性和定量风险分析）对风险进行分析，评价单个风险与整体项目风险。
- **过程目的**：对已识别风险进行优先级排序，理解单个风险的概率与影响，以及整体项目风险敞口对项目目标（进度、成本、质量、收益）的综合影响，为规划风险应对提供依据。
- **定性分析**：贯穿项目始终，通过评估风险发生的概率和影响程度来评价单个项目风险，核心工具是概率和影响矩阵。风险的其他特征还包括：对目标的影响程度、可管理性（应对的难易）、邻近性（风险可能发生的时间远近）、连通性（风险之间的关联）、共同成因或连带后果。
- **定量分析**：并非必须，应结合项目的实际需求而定，用于量化整体项目风险敞口与高风险项。常用方法：蒙特卡洛模拟（通过大量随机试验模拟项目结果分布）、决策树分析（评估不同决策路径的期望值）、敏感性分析（用龙卷风图识别对项目目标影响最大的因素）。
- **关键原则**：所有风险都应先进行定性分析；定量分析仅针对优先级高、影响大的风险，且通常先定性后定量。
- **EMV（期望货币价值）= 概率 × 影响**，是决策树分析中量化风险预期价值的基本公式。

实施风险分析为规划风险应对提供输入：风险登记册记录每个风险的评级与优先级，风险报告汇总整体项目风险敞口。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：风险管理计划提供概率影响标度定义、概率和影响矩阵、风险类别与临界值等分析框架；范围、进度、成本基准为评估风险对目标的影响提供参照基线。
- **项目文件**：风险登记册（核心输入，含每个风险的描述与初步信息）、假设日志（分析假设不确定性的影响）、成本估算与进度估算（量化影响的计算基础）、成本预测与进度预测（评估偏差）、干系人登记册（了解干系人风险偏好）等。
- **协议**：合同条款影响风险的概率与影响评估，例如处罚条款会放大交付延迟风险的影响程度。
- **采购文档**：供应商建议书等信息支持对采购相关风险的概率与影响分析。
- **事业环境因素**：市场数据、行业基准、利率与汇率等外部数据，为定量分析的参数设定提供依据。
- **组织过程资产**：历史项目的数据分布（如成本偏差经验数据）、风险分析模板、以往定量分析成果，可提高分析效率与准确性。`,
      "🔧 工具与技术 Tools": `- **专家判断**：具有项目、行业与风险管理经验的专家对风险概率、影响及各特征提供判断，尤其在数据不足时，专家经验是定性分析的重要来源。
- **数据收集**：主要是**访谈**——向干系人与主题专家收集单个风险的概率与影响数据；访谈中应清晰定义概率与影响标度，避免因理解不一致产生偏差。
- **数据分析**：包含定性与定量两大类工具——
  - **数据质量评估**：评估用于分析的风险数据质量（准确性、客观性、可靠性、完整性），数据质量低时需补充收集，否则分析结论不可靠；
  - **概率和影响矩阵**：将每个风险的概率标度与影响标度映射到矩阵中，得到高/中/低风险等级并据此排定优先级——高概率高影响（红色区）的风险优先应对；
  - **风险数据评审**：评审风险信息的充分性与时效性，剔除过时或不可靠的信息；
  - **风险紧迫性评估**：考虑风险发生的临近时间窗口与时间敏感度，同样概率影响下更紧迫（更早发生）的风险优先；
  - **敏感性分析**：逐个变动不确定因素，观察其对项目目标的影响程度，用**龙卷风图**呈现——条形越长表示该因素对目标影响越大，用于识别最关键因素；
  - **决策树分析**：以树形结构展示决策路径、各分支的概率与收益/损失，计算各路径的**EMV（期望货币价值=概率×影响）**并选择期望值最优的方案；
  - **模拟**：最常用**蒙特卡洛模拟**——先建立成本或进度的计算模型，为每个不确定变量设定概率分布（如三角分布、正态分布），再运行成千上万次随机试验，得到项目目标的结果分布，从而回答"在85%置信水平下成本不超过X元"这类问题。
- **人际关系与团队技能**：主要是**引导**——引导风险分析研讨会议，确保干系人就概率、影响与优先级评估达成共识，避免个别强势干系人左右结论。
- **提示清单**：PESTLE、TECOP、VUCA等提示清单也可在分析阶段辅助提示可能被遗漏的风险维度，确保分析全面。
- **会议**：风险分析研讨会，团队与专家共同完成评级、排序与定量分析，会议结论更新至风险登记册与风险报告。`,
      "📤 输出 Outputs": `- **风险登记册更新**：为每个已评估风险补充概率评级、影响评级、风险等级（高/中/低）、总体优先级排序，以及紧迫性、邻近性、连通性等特征信息，供规划风险应对使用。
- **风险报告更新**：更新整体项目风险敞口的量化评估（如蒙特卡洛模拟得出的成本/进度结果分布与置信区间），以及优先级最高的风险清单，供管理层决策。
- **项目文件更新**：可能更新假设日志（评估假设不确定性对风险的影响后补充记录）、经验教训登记册（分析过程的方法与教训）。`,
      "🔗 与其他过程的相互作用": `实施风险分析承接识别风险，输入其产出的风险登记册与风险报告，同时复用风险管理计划中的概率影响矩阵、标度与临界值定义。分析结果直接作为规划风险应对的输入——只有完成优先级排序，团队才能决定对哪些风险投入应对资源、采用何种策略。定量分析的结果（如成本风险分析得出的应急储备金额）还会反馈给成本与进度估算过程，支持应急储备的制定。定性分析贯穿项目始终、随风险识别迭代进行；定量分析通常在高价值项目或高风险项上一次性或周期性开展。`,
      "✂️ 裁剪考虑": `- **预测型**：在规划阶段对全部风险做定性分析，对重要风险追加定量分析（模拟、敏感性分析、决策树），结果用于确定应急储备。
- **适应型（敏捷）**：以定性分析为主，在迭代中持续评估风险优先级，通常不开展正式的定量分析；如需定量，多用相对估算而非精确模拟。
- **混合型**：骨架项目采用正式的定性加定量分析，交付层面的迭代采用轻量优先级评估。
- **规模与重要性裁剪**：小型或低风险项目可只做定性分析；大型、高不确定或高投入项目应进行定量分析。定量分析"可选但非必选"，必须与项目价值相匹配，避免过度投入。`,
      "💼 实践案例": `某桥梁工程项目对已识别的60项风险实施分析。团队先用5×5概率影响矩阵对全部风险做定性排序，筛出12项高优先级风险；随后对其中"钢材价格上涨"与"地质条件不确定"两项高风险开展定量分析——用蒙特卡洛模拟运行5000次成本仿真，得出在90%置信水平下成本不超过1.2亿元，据此确定了800万元的应急储备。针对"地基施工方法选择"，团队绘制决策树：方案A（盾构法，成本较高但地质风险小，EMV=1.05亿元）与方案B（明挖法，成本低但地质风险大，EMV=1.15亿元），通过比较EMV选择方案A。敏感性分析龙卷风图显示"钢材价格"对总成本影响最大，团队据此优先制定价格对冲策略。`,
    },
    keyConcepts: `- **定性风险分析**：用概率和影响矩阵评估单个风险，贯穿项目始终，所有风险都需进行。
- **定量风险分析**：量化整体项目风险敞口，可选；只对优先级高的风险做，且先定性后定量。
- **概率和影响矩阵**：概率标度与影响标度交叉分级，高概率高影响的风险优先应对。
- **EMV（期望货币价值）= 概率 × 影响**：用于决策树分析中比较各决策路径的期望价值，取期望值最优方案。
- **决策树分析**：树形展示各路径的概率与损益，通过计算EMV辅助决策。
- **敏感性分析/龙卷风图**：识别对项目目标影响最大的因素，条形越长影响越大。
- **蒙特卡洛模拟**：建立模型→设定概率分布→运行大量随机试验→输出结果分布与置信区间。
- **风险的其他特征**：紧迫性（时间临近度）、邻近性、可管理性、连通性、共同成因或连带后果。`,
    examTips: `- "定性必做、定量可选，且先定性后定量"是核心考点。
- EMV=概率×影响：给出概率与金额即可计算；决策树分析比较各路径EMV，取期望值最优方案。
- 龙卷风图：条形最长的因素是影响最大的因素——不是"最可能发生的"因素。
- 概率和影响矩阵评级：高概率高影响=高风险，优先应对。
- 蒙特卡洛模拟输出的是结果分布与置信区间（如"90%概率成本不超过1.2亿元"），不是单一确定值。
- 定量分析不是对每个风险都做——只针对高优先级风险，或用于评估整体项目风险敞口。
- 紧迫性≠概率：同样概率影响下，更早发生或时间更敏感的风险更紧迫、更优先。
- 数据质量评估：数据质量差时应先改善数据再分析，否则结论不可靠。`
  },
  "proc-plan-risk-responses": {
    overview: `规划风险应对（Plan Risk Responses）过程旨在开发应对方案、选择应对策略并商定应对行动，以处理项目整体风险敞口（overall project risk exposure）并对待单个项目风险（individual project risks）。该过程的关键收益是：为项目整体风险和单个项目风险确定合适的应对方式，把威胁的不利影响降至最低、把机会的正面影响放到最大。该过程需要在整个项目期间持续执行，属于风险管理知识领域中的核心规划活动。

在风险管理流程中，规划风险应对位于识别风险之后、实施风险应对之前，起着承上启下的作用：它把风险分析阶段获得的"风险清单与优先级排序"转化为"可执行的具体行动方案"。本过程同时处理两类风险：一是项目整体风险，即项目整体不确定性的大小，它影响整个项目，需要项目层面甚至组织层面的应对策略；二是单个项目风险，即某个不确定事件或条件，一旦发生会对一个或多个项目目标产生正面或负面的影响，需要针对每个已识别的重大风险分配应对策略和风险责任人。

规划风险应对需要应对与平衡多种情况：既要为高优先级的威胁制定应对措施，也要为高价值的机会制定利用方案；既要处理已识别并需要应对的风险，也要考虑次生风险和残余风险；还要为未来可能出现的情况预留储备，并为部分风险设置应急应对策略及其触发条件。风险应对的投入应与风险的优先级相匹配——并不是所有风险都需要应对，对于影响很小或发生概率很低的风险，可以选择接受。本过程强调明确风险责任人（Risk Owner），确保每一项应对措施都有人负责落实并接受问责。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：提供风险应对的总体框架与约束。其中风险管理计划定义了风险类别、风险承受力、应对策略使用规则、应对工作的预算与时间安排；范围基准、进度基准、成本基准限定了应对措施可投入的资源空间；资源管理计划、采购管理计划、干系人参与计划等为选择应对方式提供依据，例如转移策略要结合采购管理计划，沟通类应对要结合干系人参与计划。
- **项目文件**：本过程最重要的输入。其中**风险登记册**记录了每个已识别风险的概率、影响、风险责任人、优先级与风险评分，是选择应对策略的直接依据；**风险报告**汇总了整体项目风险敞口和单个风险的整体视图；**干系人登记册**帮助确定哪些干系人可作为风险所有者或需要参与风险应对决策；此外还包括范围、进度、成本等计划文件与估算，用于判断应对措施的可行性与成本；**经验教训登记册**可提供以往项目应对措施有效性的信息，供借鉴。
- **事业环境因素**：如组织的风险承受力与风险偏好、市场环境、法律法规约束、行业标准等，它们决定了某些应对策略（例如向保险公司转移）是否可行，以及组织能接受多大的风险。
- **组织过程资产**：组织已有的风险模板、历史项目风险数据、已识别的风险教训、风险应对政策与程序等，为选择应对策略提供参照依据和经验支持。`,
      "🔧 工具与技术 Tools": `- **专家判断**：项目经理借助具备风险管理、领域或组织经验的专家（包括组织内部专家、顾问、关键干系人）来确定最佳应对策略，评估应对措施的成本效益与可行性，并对不确定情况作出专业判断。
- **数据分析**：主要用于在备选应对方案中作出比较选择。其中**备选方案分析（Alternative Analysis）**对不同应对策略的优缺点、成本、时效进行系统对比；**成本效益分析（Cost-Benefit Analysis）**评估应对措施的实施成本与其带来的风险减轻或机会增强收益之间的关系，确保应对投入是值得的——应对成本不应超过风险一旦发生可能造成的潜在损失。
- **决策**：主要指**多标准决策分析（Multi-Criteria Decision Analysis）**。借助决策矩阵，对多个应对方案按多个标准（如成本、时效、可行性、可接受度、对项目目标的潜在影响）打分排序，从而在团队中形成一致的应对选择。
- **人际关系与团队技能**：主要指**引导（Facilitation）**。通过召开引导式研讨会，让具备技术、运营、财务等不同视角的干系人共同研讨风险应对方案，消除偏见、达成一致，确保应对措施被相关方接受和支持。
- **威胁应对策略（Threat Response Strategies，5种）**：为应对可能带来负面影响的单个风险而使用，5种策略按主动程度从强到弱排列：
  - **上报（Escalate）**：当威胁超出项目经理或团队的权限、影响范围，或威胁只有在项目之外的更高层级（如项目组合、项目管理办公室、组织高管、客户等）处理时才有效时，采用上报。上报后由组织更高层直接管理，项目经理不再承担主要应对责任，但需在风险登记册中记录并跟踪。
  - **规避（Avoid）**：最彻底的应对方式，通过消除威胁或其根源来消除风险。典型做法包括：取消高风险的进度活动或工作包、改变项目范围或项目方法、延长进度计划、采用不同的资源或技术。例如，为避免采用不成熟技术带来的风险，改为选用已验证的成熟技术。
  - **转移（Transfer）**：把风险应对的所有权（及其财务后果）转移给第三方，但风险本身并未消失。典型手段包括：购买保险、签订固定总价合同让承包商承担成本风险、采用担保或保函、外包给专业供应商、把性能风险转移给担保方。转移通常需要支付溢价，且通常只转移财务责任，并不转移知识、信誉等风险。
  - **减轻（Mitigate）**：降低风险发生的概率或减少其发生后的影响，是成本收益比较均衡的常用策略。例如：采用更简单的流程、开展更多测试、选择更稳定的供应商、增加冗余设备、为关键活动安排备用资源、提前采购关键部件。
  - **接受（Accept）**：当风险发生的概率和影响处于可承受范围内，或没有经济可行的应对方式时，选择不采取主动行动。接受分两种：**主动接受（Active Acceptance）**——预先建立应急储备（预算或时间缓冲）并在特定条件下动用，设置应急应对策略或触发条件；**被动接受（Passive Acceptance）**——不采取任何预先安排，只定期复查，风险发生时再酌情处理。
- **机会应对策略（Opportunity Response Strategies，5种）**：为抓住可能带来正面影响的单个机会而使用，同样5种：
  - **上报（Escalate）**：当机会超出项目团队权限，或需要在组织更高层把握时才有效时，上报给更高层级，例如利用公司层面的市场优势、获取总部资源。
  - **利用（Exploit）**：确保机会一定发生。采用最有把握的方式主动创造机会，例如为领先市场的目标组建精锐团队、采用先进的技术或方法、把项目目标定得更有挑战性以获取奖励。
  - **分享（Share）**：把把握机会的责任和收益与能更好利用该机会的第三方合作承担，例如组建合资企业、建立合作伙伴关系、与专业机构共同开发，双方共享收益。
  - **增强（Enhance）**：提高机会发生的概率或增大其正面影响。例如：向更多潜在客户推广产品以增加销售量、为高潜力机会配置更多资源、提升功能特性使其更具吸引力。
  - **接受（Accept）**：不刻意追求，但保持开放心态，机会出现时再加以利用。
- **应急应对策略（Contingent Response Strategies）**：针对某些只有在特定条件下才会触发应对行动的风险，预先设定应对计划及其触发条件（Trigger Conditions）。只有触发条件满足时才执行相应的应急应对，例如"若项目进度落后超过10%，则启动加班计划"。这种方式把"是否行动"的决策在事先转化为"条件满足即行动"，避免事到临头慌乱决策。
- **整体项目风险应对策略（Overall Project Risk Response Strategies）**：当项目整体风险敞口超出组织可接受水平时，需要采取项目层面乃至组织层面的整体应对，包括：规避（如缩小项目范围、推迟项目）、转移（如把项目转给其他组织承担）、减轻（如改变项目方法或增加缓冲）、接受（如调整组织风险承受力、接受风险并相应增加储备），或上报（如提请组织层面决策项目是否继续）。
- **会议**：通过风险应对规划研讨会等会议，组织干系人集中讨论已识别风险，逐项确定应对策略与责任人，并就应对方案达成一致决策。`,
      "📤 输出 Outputs": `- **变更请求**：风险应对通常需要变更项目计划或范围，例如增加测试活动、购买保险、调整进度安排，因此往往伴随变更请求，经实施整体变更控制过程批准后纳入计划。并非所有风险应对都产生变更请求。
- **项目管理计划更新**：批准的应对措施可能需要更新项目计划的相关部分，例如风险管理计划、进度管理计划、成本管理计划、质量管理计划、采购管理计划等，把应对活动与储备安排反映到相应基准或计划中。
- **项目文件更新**：主要是**风险登记册更新**——为每个风险记录选定的应对策略、应对行动、风险责任人、应急应对方案及其触发条件、次生风险和残余风险，以及应对成本估计；**风险报告更新**——更新整体项目风险现状、单个风险的应对进展、残余风险与次生风险汇总、储备使用情况等，供干系人审阅。`,
      "🔗 与其他过程的相互作用": `本过程前接**识别风险**：识别风险输出风险登记册和风险报告，规划风险应对正是基于这两份文件为每个风险选择策略。识别风险时使用的工具，如风险概率和影响评估、概率和影响矩阵、不确定性表现、风险分类，决定了风险的优先级排序，而优先级是决定"是否应对、如何应对"的前提——未被优先处理的风险往往直接选择接受。本过程后接**实施风险应对**：这里确定的应对措施由实施风险应对过程在项目执行中落实。本过程还与**监督风险**构成闭环：监督风险持续检查应对措施的实施效果，若应对无效或风险状况变化，将触发回到本过程重新规划，形成"识别→规划→实施→监督→再规划"的持续循环。此外，本过程与**制定预算、制定进度计划**衔接，为应对措施分配资金（应急储备）和进度缓冲；与**实施整体变更控制**衔接，应对方案若涉及范围、进度、成本基准的变更，须通过变更控制流程批准后方可实施。`,
      "✂️ 裁剪考虑": `- **预测型（瀑布）**：风险应对通常在规划阶段集中完成，输出完整的风险登记册更新与应对计划，应对措施纳入进度和预算，强调正式文档与审批流程。
- **适应型（敏捷）**：风险（尤其技术风险与产品风险）在每次迭代计划（如冲刺计划）中持续审视，应对措施以小型、增量方式落地，通过频繁集成、迭代评审、原型试错来减轻风险；储备以产品待办事项中的缓冲或团队专注度体现，更强调快速反馈而非一次性完备的应对文档。
- **混合型**：对高风险、不确定性大的部分采用敏捷式迭代应对，对低风险部分按预测式流程管理。
- **规模与复杂度**：小项目可用简化登记册并直接选择应对策略；大项目（尤其跨组织、跨供应商的项目）则需更正式的决策矩阵、多标准分析和上报机制。`,
      "💼 实践案例": `一家大型制造企业计划上线新的ERP系统，替换多个老化的遗留系统。在识别风险阶段发现若干高风险：①切换期间数据迁移失败（概率中、影响极高）；②关键业务部门抵触变革（概率高、影响高）；③第三方集成接口延迟交付（概率中、影响中）。
- 对风险①选择**减轻+应急应对**：制定数据迁移演练计划，先在测试环境完整演练两次，并设定应急计划"若正式切换前演练通过率低于95%，则执行回滚到旧系统的方案"，触发条件明确写进风险登记册。
- 对风险②选择**减轻**：提前开展变革管理培训、设置业务部门联络员，同时接受部分残余抵触并纳入残余风险登记。
- 对风险③选择**转移**：在合同中明确接口延迟的罚款条款，并要求供应商提供履约担保。
- 对整体项目风险（切换失败导致业务中断）选择**规避**：错峰切换，选择业务量最低的节假日窗口并安排全员值守。
以上应对方案均记录到风险登记册，分配风险责任人，并为整体项目风险预留应急储备和应急计划，为实施风险应对过程提供了清晰、可执行的行动清单。`,
    },
    keyConcepts: `关键术语——
- **威胁应对策略**：针对负面风险（威胁）的5种应对——上报、规避、转移、减轻、接受。
- **机会应对策略**：针对正面风险（机会）的5种应对——上报、利用、分享、增强、接受。
- **次生风险（Secondary Risk）**：因实施某项风险应对措施而产生的新风险。例如为应对服务器故障风险而购买备用服务器，新购置设备本身可能带来新的配置兼容风险。次生风险同样需要被识别与应对。
- **残余风险（Residual Risk）**：采取应对措施后仍然存在的风险，包括未完全消除的部分，通常以主动或被动接受方式处理。
- **应急应对策略（Contingent Response Strategy）**：为特定触发条件预先设计好、触发时才执行的应对计划，多用于高优先级风险。
- **主动接受 vs 被动接受**：主动接受=预留应急储备并设触发条件、预案先行；被动接受=不做任何预案，风险发生时再处理。
- **上报（Escalate）**：特指把风险（威胁或机会）交给项目之外的更高管理层或组织层面处理，超出项目经理权限；一旦上报，项目团队不再主导该风险的应对。
- **风险责任人（Risk Owner）**：被分配负责某个风险应对计划制定与实施的人员，承担问责。
- **整体项目风险应对策略**：针对项目整体不确定性（如范围、方法、缓冲）的应对，可在项目层面或组织层面执行。`,
    examTips: `考试重点/常见陷阱——
- **必背5+5策略**：威胁——上报/规避/转移（保险、外包、担保）/减轻/接受；机会——上报/利用/分享/增强/接受。两类策略前三项一一对应但名称不同，注意区分。
- **高频陷阱1**：转移≠消除风险，转移只是把风险及其财务后果转给第三方，项目仍可能受影响；**规避才是消除风险或其根源**。
- **高频陷阱2**："上报"特指超出项目经理权限、交给**组织更高层**管理，不是简单的"向领导汇报"；一旦上报，项目经理不再承担主要应对责任。
- **高频陷阱3**：主动接受=设应急储备+设触发条件、预案先行；被动接受=无预案。题目常考两者区别。
- **次生风险**是因应对措施产生的新风险；**残余风险**是应对后仍剩的风险。两者定义对比是常考点。
- **应急应对策略**与触发条件绑定，触发条件满足时应**立即自动执行**，而非等待再次开会决策。
- 风险应对成本应与其效果相称：为概率低、影响小的风险花费高昂应对成本是不经济的，选择接受更合理。
- 每个重要风险必须有明确的风险责任人（Risk Owner），这是问责制的基础，也是实施风险应对的前提。
- 规划风险应对属于**规划过程组**；若应对方案涉及基准变更，须通过**实施整体变更控制**流程批准。`
  },
  "proc-implement-risk-response": {
    overview: `实施风险应对（Implement Risk Responses）过程旨在执行商定的风险应对计划，落实为应对单个项目风险和整体项目风险而规划的行动。该过程的关键收益是：确保按计划执行商定的风险应对措施，从而处理整体项目风险敞口，将单个项目威胁的影响降至最低，并将单个项目机会的收益最大化。该过程属于"执行"过程组，与指导与管理项目工作并行开展。

风险应对不是一次性活动，而是需要在整个项目期间持续执行和监控的动态工作。风险具有时效性：威胁的应对应在威胁尚未发生、影响最小的窗口期内尽早执行；机会的应对应在机会可能实现的时间窗口内果断行动，否则机会可能稍纵即逝。

实施风险应对需要把应对措施真正"落进"项目日常执行中去，具体可能包括：在项目进度计划中为应对活动安排专门的进度活动和时间；在项目预算中分配应对所需的资金；在WBS中新增应对工作包；调整资源配置；修改采购安排或合同条款等。该过程还强调：**风险所有者（Risk Owner）**负责确保应对措施按计划实施并达到预期效果，承担问责；项目经理负责协调资源、跟踪进度、扫清实施障碍。如果一项应对措施实施后被发现无效，或风险状况发生了变化，应回到规划风险应对过程重新评估和调整应对策略，而不是机械地坚持原方案。

本过程还强调对应对投入的约束：实施风险应对通常需要动用事先分配的应急储备（预算或时间缓冲），应对活动的成本、资源占用应控制在风险应对规划阶段约定的范围之内。同时，整体项目风险的应对往往涉及跨组织、跨供应商的协调，需要项目经理与组织高层管理者共同推进；及时、有效地落实应对行动，是降低风险损失、兑现机会收益的关键环节，也是后续监督风险过程能够客观评估应对效果的前提。无论项目采用何种开发方法，把风险应对"融入"实际的项目执行而非停留在纸面，正是本过程区别于规划过程的核心价值。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：其中**风险管理计划**定义了风险应对实施的责任分工、预算与时间安排规则；其他计划（进度、成本、资源、采购等）为落实应对活动提供执行框架与约束条件。
- **项目文件**：主要是**风险登记册**——记录每个风险的应对策略、应对行动、风险责任人、应急应对方案及触发条件，还包含风险的优先级评分、概率与影响等级以及最新的应对状态字段，是实施风险应对的直接行动清单；**风险报告**——提供整体项目风险现状、单个风险的应对进展与残余风险等信息；还包括**问题日志**——记录已发生风险转化的问题及处理进展，以及**经验教训登记册**——记录以往应对措施的有效做法，供本次实施借鉴。
- **组织过程资产**：组织的风险管理政策、风险应对模板、历史项目应对数据与教训等，为实施应对行动提供参照与支持。`,
      "🔧 工具与技术 Tools": `- **专家判断**：在实施应对过程中，借助专家判断评估应对措施的可行性、判断应对行动的优先级、识别实施过程中的障碍并确定最佳执行顺序；在应对措施需要调整时，也依赖专家判断作出合理决策。
- **人际关系与团队技能**：主要是**影响（Influence）**能力。风险应对往往需要跨部门、跨干系人协调，风险所有者和项目经理需要运用影响力、谈判与沟通技巧，推动干系人配合执行应对行动，说服相关方接受应对安排或及时调整资源。
- **项目管理信息系统（PMIS）**：用于跟踪风险应对行动的执行进度、记录应对状态、分配与更新风险应对任务，借助项目管理软件、风险看板、待办事项跟踪系统等电子工具，实现应对措施的可视化监控与团队协同。`,
      "📤 输出 Outputs": `- **变更请求**：实施应对过程中若发现需要调整计划，例如追加应对资金、增加应对活动、更换资源或修改合同，应通过提交变更请求并走实施整体变更控制流程来落实；批准的变更将更新相应基准或计划。
- **项目文件更新**：包括**风险登记册更新**——记录风险应对措施的实施状态、实际执行时间、应对效果、风险状态变化（如某威胁已按计划被消除，或某机会已被利用）；**问题日志更新**——记录因风险发生或应对过程中暴露的问题及处置情况；**经验教训登记册更新**——记录应对措施实施过程中的经验教训，供后续项目借鉴。`,
      "🔗 与其他过程的相互作用": `本过程前接**规划风险应对**：本过程执行的是规划风险应对阶段确定并经批准的应对措施，风险登记册中的应对策略与行动清单是其行动依据。本过程与**监督风险**形成闭环：监督风险过程持续检查应对措施是否按计划实施、是否有效；若发现应对无效、风险状况变化或出现新的风险，将触发回到规划风险应对过程进行再规划，即"应对无效→返回重规划"。本过程与**指导与管理项目工作**（执行工作的其他过程）并行，风险应对活动往往是日常执行活动的一部分，与可交付物的生产、质量检查等同步开展；应对措施可能产生变更请求，进入**实施整体变更控制**流程。此外，应对措施的实施会消耗时间、资金和资源，因此与**控制进度、控制成本、控制资源**等监控过程联动，储备的动用情况会被持续跟踪。风险应对实施中出现的偏差也会反馈到监督风险过程，作为判断应对有效性、决定是否重新规划应对策略的直接依据，从而把"执行—监督—再规划"串成一个完整的闭环。`,
      "✂️ 裁剪考虑": `- **预测型（瀑布）**：应对措施按规划逐一执行，通常在阶段或里程碑节点集中检查应对执行状态，变更走正式审批流程。
- **适应型（敏捷）**：风险应对融入每次冲刺迭代，团队通过冲刺计划会、每日站会持续落实应对行动；应对"工作项"直接放入产品待办事项或冲刺待办事项，随迭代评审检查效果，反应更快、更频繁。
- **混合型**：高风险应对走正式变更与跟踪流程，低风险应对由团队在迭代内自主执行。
- 可依据组织对风险问责的要求，明确风险所有者的职责范围与汇报机制；小项目可由项目经理兼任多数风险所有者。
- 对涉及合规、安全或外部监管的项目，应对实施过程需要更严格的正式记录与审批留痕；对创新性、探索型项目则可更多依赖团队的自主判断与快速试错。`,
      "💼 实践案例": `继续ERP上线项目。规划阶段已批准多项应对措施，实施阶段按计划逐项落实：
- 风险①数据迁移失败：风险所有者带领团队在测试环境执行两轮数据迁移演练，把演练结果（通过率、耗时）记录到风险登记册，据此判断触发条件是否满足；通过率达标，未触发回滚应急计划，正式迁移按期推进。
- 风险②部门抵触变革：风险所有者联合人力资源部门开展3轮变革管理培训，通过沟通看板收集员工反馈，抵触信号明显下降，残余风险降至可接受水平。
- 风险③接口延迟：合同补充罚款与担保条款后，供应商按期交付接口，未触发罚款；发现接口性能低于合同约定，及时提交变更请求追加性能优化任务。
- 过程中发现一项次生风险（新接口与旧系统字符集不兼容），团队立即登记并上报，调整应对计划。
应对状态每周在项目例会上更新，应对效果交由监督风险过程持续评估；某项应对被证实无效后，团队返回规划风险应对重新选择了策略。最终，所有既定应对行动在项目上线前全部完成闭环，关键威胁被有效控制，机会类应对也如期落地，为项目顺利上线提供了切实保障。`,
    },
    keyConcepts: `关键术语——
- **风险所有者（Risk Owner）**：被分配负责特定风险应对计划制定与实施的人员，需对应对措施的执行效果负责并接受问责；风险应对的实施主体责任在风险所有者，而不只是项目经理。
- **权变措施（Workaround）**：针对**未识别风险**（或已识别但未规划应对的风险）采取的**临时的、现场应变**的应对行动，事先没有预案，靠即兴解决。权变措施通常不产生变更请求。
- **应急计划（Contingency Plan）**：针对已识别、可能在特定触发条件下发生的风险，**事先规划**好的应对方案，触发条件满足时自动执行。
- **应急储备（Contingency Reserve）**：为应对"已知-未知"（已识别风险）预留的预算或时间缓冲，用于支付应急计划的执行，属于成本基准。
- **管理储备（Management Reserve）**：为应对"未知-未知"（未识别风险）预留的项目预算，动用需管理层批准，不属于成本基准。
- **应对无效→返回重规划**：若应对措施实施后效果不佳，应回到规划风险应对过程重新选择策略，而非硬着头皮继续。
- **触发条件（Trigger）**：表明风险即将或已经发生的信号，用于启动应急计划。`,
    examTips: `考试重点/常见陷阱——
- 实施风险应对属于**执行过程组**，是"做"的过程，不是"规划"的过程。
- **权变措施（Workaround）vs 应急计划（Contingency Plan）**是最高频辨析题：权变措施针对**未识别**风险的**临时**现场应变，应急计划针对**已识别**风险的**事前预案**、触发条件满足即执行。权变措施通常不产生变更请求；应急计划执行时动应急储备并需记录。
- **风险所有者（Risk Owner）**负责确保应对措施实施，是问责的核心；考试常问"谁负责风险应对"，应答风险所有者而非项目经理。
- 风险应对需要**纳入执行活动**：进度上安排活动、预算上分配资金、WBS上增加工作包——这三点常被考到。
- 若应对措施**无效**，应**返回规划风险应对重新规划**，而不是继续执行或直接忽视。
- 机会的应对要在**机会窗口期**内执行，错过窗口机会可能消失——这是机会应对的关键特征。
- 注意区分：**应急储备**（应对已识别风险/已知-未知，属于成本基准）与**管理储备**（应对未识别风险/未知-未知，不属于成本基准，须管理层批准），题目常混考两者。
- 实施风险应对过程中发现需调整计划，应走**实施整体变更控制**流程，先提交变更请求。
- 实施风险应对动用的通常是**应急储备**（为已识别风险预留的预算），而不是管理储备；动用应急储备后应更新风险登记册并持续跟踪其使用情况。`
  },
  "proc-monitor-risks": {
    overview: `监督风险（Monitor Risks）过程旨在：监督风险应对计划的实施、跟踪已识别的风险、识别和分析新风险、为新风险制订应对计划，并在整个项目生命周期中评价风险应对措施与风险管理过程的有效性。该过程的关键收益是：推动项目决策基于对整体风险敞口的当前、最新理解来作出，明确风险责任人，确保风险管理的连续性，从而高效、及时地应对突发风险。该过程贯穿项目全程持续开展，属于"监控"过程组。

监督风险的核心活动包括：持续跟踪已识别风险的状态（风险是否已发生、概率或影响是否变化、是否仍应作为重点关注对象）；识别新风险（项目环境、干系人、技术方案的变化都可能引入新的不确定性）；评估风险应对措施的有效性（应对是否按计划实施、是否达到预期效果，若无效则触发重新规划）；进行储备分析（判断剩余应急储备是否足以应对剩余风险，是否需要追加或可以释放）；开展风险审计（评估风险管理过程本身是否有效）；使用技术绩效测量（通过可量化的技术指标判断应对是否把风险控制在预期水平）。

触发条件（Trigger Conditions）是表明风险即将或已经发生的事件或指标。当触发条件满足时，应立即执行预设的应急应对策略，无需再开会讨论。对于未识别、突发的风险，则采用权变措施现场应变。监督风险过程会持续输出变更请求与项目文件更新，并与识别风险、规划风险应对、实施风险应对形成持续闭环。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：重点是**风险管理计划**，其中定义了风险登记册和风险报告的使用方式、风险应对的跟踪要求、储备使用规则、风险审计与风险评审会的安排等，为监督提供框架。
- **项目文件**：包括**风险登记册**（监督的对象清单——每个已识别风险的概率、影响、责任人、应对计划与当前状态）、**风险报告**（提供整体项目风险敞口视图与单个风险的汇总状态）、**问题日志**（已发生风险转化的问题及处理进展）、**经验教训登记册**（为评价应对有效性提供历史参照），以及范围、进度、成本等计划文件（用于对照应对效果）。
- **工作绩效数据与工作绩效报告**：收集并呈现实际的项目执行情况（如进度、成本、质量数据），用于判断风险是否发生、概率与影响是否变化、应对措施是否发挥作用。
- **组织过程资产**：组织的风险政策、风险审计程序、历史项目风险绩效数据等，用于支持监督与评估。`,
      "🔧 工具与技术 Tools": `- **专家判断**：借助专家判断解读风险监测数据、判断风险状态变化的意义、评估应对措施的效果，并对储备是否充足、是否需要再识别新风险等作出专业判断。
- **数据分析**：是监督风险最核心的工具，主要包括：
  - **技术绩效测量（Technical Performance Analysis）**：把项目执行过程中的技术成果（如功能完成度、性能指标、可靠性指标）与计划中的技术目标进行对比，判断偏差是否落在预期范围。若技术绩效偏离计划目标，往往预示对应风险可能发生或应对措施未达预期，应提前预警。
  - **储备分析（Reserve Analysis）**：比较剩余应急储备与剩余风险（残余风险）所需的资金或时间，判断储备是否充足。若剩余储备明显不足，应申请追加或提交变更；若剩余储备明显富余，可建议释放部分储备。
  - **趋势分析（Trend Analysis）**：观察风险相关指标随时间的变化趋势（如缺陷率、进度偏差、成本偏差的走势），预测风险是否在向不利方向演化，从而提前介入。
- **审计（Audits）**：**风险审计（Risk Audit）**是对风险管理过程有效性的独立审查，检查风险管理政策、程序和应对措施是否得到遵守、是否有效，并识别风险管理过程中的改进机会。风险审计可在项目例会上开展，也可由独立第三方进行，审计结果用于持续改进风险管理。
- **会议**：通过定期**风险评审会（Risk Review）**审查风险登记册，逐项核对风险状态、应对进展与有效性；通过项目例会讨论整体风险敞口的变化；风险审计结果与储备分析结论也在会议上向干系人沟通。
- **决策**：主要是多标准决策分析，在风险状态发生变化、需要决定是否调整应对或触发应急计划时，帮助团队在多个选项中作出一致选择。
- **人际关系与团队技能**：主要是**引导（Facilitation）**，在风险评审会中引导不同干系人坦诚交流风险信息，避免隐瞒问题，达成对风险状态的一致理解。`,
      "📤 输出 Outputs": `- **工作绩效信息**：将工作绩效数据与风险管理相关基准（如储备使用、应对执行进度）对比后形成，反映风险管理状况，是干系人了解项目风险健康度的重要信息，也输入给项目报告。
- **变更请求**：监督过程中可能产生多种变更请求，包括应对计划调整、储备追加或释放、进度成本计划调整、问题处理的纠正措施等，均须通过实施整体变更控制流程评估与批准。
- **项目管理计划更新**：若批准的变更涉及风险管理计划或其他计划部分，需相应更新项目管理计划。
- **项目文件更新**：主要是**风险登记册更新**——记录风险状态变化、触发条件是否满足、应对措施执行结果、新识别的风险（**再识别的新风险**要加入登记册并分配责任人与应对），以及**残余风险的再评估**结果；**风险报告更新**——更新整体风险敞口、关键风险清单、储备使用情况；此外还有**问题日志更新**与**经验教训登记册更新**。
- **组织过程资产更新**：积累风险管理的经验教训，更新组织风险模板与风险数据库，供后续项目参考。`,
      "🔗 与其他过程的相互作用": `本过程前接**实施风险应对**：监督风险检查已实施应对的效果，判断应对是否按计划推进、是否达到预期，形成"实施→监督"的执行闭环。本过程联动**识别风险**：监督过程中项目环境变化可能引入**新的风险**，须回到识别风险过程将其纳入登记册并评估，也可直接在本过程内登记新风险。本过程联动**规划风险应对**：若监督发现应对无效、残余风险超出可接受水平或储备不足，应回到规划风险应对过程**重新规划**应对策略；若触发条件满足，则执行应急计划。本过程还与其他监控过程协同：风险的变化会反映在进度、成本、质量等绩效数据上，监督风险与监督进度、监督成本、控制质量等过程共享工作绩效数据，共同支撑项目整体监控；输出的变更请求进入实施整体变更控制流程。`,
      "✂️ 裁剪考虑": `- **预测型（瀑布）**：通过定期的风险评审会、阶段里程碑检查、正式风险审计开展监督，风险状态与储备使用情况在报告中正式记录。
- **适应型（敏捷）**：风险监督融入每日站会与迭代评审、迭代回顾，团队频繁审视产品风险与技术风险；风险以"风险待办项"形式进入产品待办事项，随迭代持续更新；强调短反馈环、快速识别与即时应对，正式文档较少。
- **混合型**：高风险与合规类风险按预测式严格监督，其余风险按敏捷方式快速响应。
- 监督频率与投入应与项目风险水平相匹配：高风险项目更频繁地开展风险评审与审计，低风险项目可降低监督频度。`,
      "💼 实践案例": `在ERP项目上线窗口期，项目经理每周召开风险评审会：
- 跟踪已识别风险：数据迁移演练按计划完成，通过率99%，优于目标，该风险标记为"已缓解、残余风险可接受"；接口风险已消除，从重点关注清单移除。
- 识别新风险：评审中发现第三方接口在高峰期出现响应延迟的新风险，立即登记并指定风险所有者，采取增加缓存节点的减轻措施。
- 储备分析：估算剩余应急储备足以覆盖剩余残余风险，结论为"储备充足"无需追加；同时发现部分储备因风险消除可释放，提交变更请求予以释放。
- 风险审计：独立的内部审计抽查了风险管理过程，发现部分风险应对状态未及时更新，提出改进建议，团队随即整改并更新风险登记册。
- 趋势分析：缺陷率趋势显示系统集成阶段的缺陷率持续下降，判断整体技术风险呈收敛趋势，支持"按计划推进"的决策。
最终项目按时上线，风险管理闭环运转顺畅。`,
    },
    keyConcepts: `关键术语——
- **触发条件（Trigger）**：表明风险即将或已经发生的事件或指标；触发条件满足时应立即执行应急应对策略，无需重新决策。
- **风险审计（Risk Audit）**：对风险管理过程有效性的独立、结构化审查，检查政策与应对措施是否被遵守且有效，输出改进建议。
- **储备分析（Reserve Analysis）**：对比剩余应急储备与剩余风险所需资源，判断储备是否充足；不足则追加，富余则释放。
- **技术绩效测量（Technical Performance Analysis）**：通过对比计划技术指标与实际技术成果，识别风险是否发生或应对是否有效。
- **趋势分析（Trend Analysis）**：观察风险相关指标随时间的变化方向，预测风险演化并提前介入。
- **权变措施（Workaround）**：对**未识别**突发风险的临时现场应对。
- **应急计划（Contingency Plan）**：为已识别风险预设、触发条件满足即执行的应对方案。
- **再识别新风险**：监督过程中随时识别环境变化引入的新风险并纳入管理。
- **残余风险再评估**：持续复核残余风险水平是否仍在可接受范围。
- **风险敞口（Risk Exposure）**：整体项目风险的大小，是项目层面决策的基础。`,
    examTips: `考试重点/常见陷阱——
- 监督风险属于**监控过程组**，贯穿**整个项目生命周期**，不是只在项目后期。
- **触发条件**是信号——"风险即将或已经发生"，触发条件满足就**立即执行**应急计划，这是常考点。
- **风险审计**评估的是**风险管理过程**的有效性（过程好不好），而不是管理者的绩效本身；审计发现的是流程改进机会。
- **储备分析**判断"剩余储备够不够应对剩余风险"：不足→追加（走变更），富余→释放。
- **技术绩效测量**通过量化技术指标（如性能、可靠性）对比计划目标来评估应对效果，这是它区别于其他数据分析工具的关键。
- **趋势分析**看方向不看绝对值，用于预测风险演化、提前预警。
- **权变措施≠应急计划**：权变针对**未识别**风险（临时、突发应对），应急计划针对**已识别**风险（事前预案、触发即执行），此辨析高频出现。
- 监督过程强调**再识别新风险**（项目环境变化会引入新风险）与**残余风险的再评估**，这两点常被忽视。
- 监督风险的输出以**变更请求**与**项目文件更新**为主（不是可交付物），其中工作绩效信息是一项重要输出。
- 风险应对无效时应**返回重规划**（回到规划风险应对过程），而不是在监督过程里反复修补。`
  },
  "agile-manifesto": {
    overview: `《敏捷宣言》（Agile Manifesto）于2001年2月由17位软件行业思想领袖（包括Scrum与极限编程等不同流派的代表人物）共同发表，正式宣告敏捷开发运动的开始。敏捷方法是一个涵盖性术语，指任何符合《敏捷宣言》价值观和原则的方法、技术、框架、手段或实践，例如Scrum、极限编程（XP）、看板（Kanban）、精益（Lean）、水晶方法（Crystal）、功能驱动开发（FDD）、动态系统开发方法（DSDM）等。其核心思想可以概括为：以人为中心，以小步快跑的方式持续交付价值，拥抱变化而非抗拒变化，并通过自组织团队与持续反馈实现改进。

《敏捷宣言》包含四大价值观：1. 个体与互动高于流程和工具——人是最重要的资产，团队成员之间以及团队与客户之间的有效沟通与协作，优于机械地依赖流程和工具；2. 可工作的软件高于详尽的文档——交付能正常运行的成果比编写详尽文档更重要，文档应当“恰到好处”地服务于交付；3. 客户合作高于合同谈判——与客户持续紧密协作、共同发现和澄清需求，胜过墨守合同条款的字面意义；4. 响应变化高于遵循计划——灵活适应不断变化的需求与环境，胜过刻板地遵循初始计划。需要强调的是：右边的各项同样有其价值，只是左边的各项被赋予更高优先级——这是“高于”（over）而非“取代”。

宣言还包含十二大原则，它们把抽象的价值观转化为可操作的行为指引。价值观界定敏捷思维模式，原则指导敏捷实践，各种框架（Scrum、XP、看板等）则是价值观与原则的具体实现形式，形成“价值观→原则→实践→框架”的清晰层次。在PMP考试中，敏捷宣言是判断情景题答案的“锚点”——任何违背宣言精神的选项几乎都是错误选项。`,
    details: {
      "🧩 核心要素": `- **个体与互动高于流程和工具**：强调人比流程更关键。实践中表现为重视面对面沟通、自组织团队、为团队成员提供环境与支持并信任他们。流程和工具只有在帮助人们更好协作时才有效，不应为了流程而流程。
- **可工作的软件高于详尽的文档**：衡量进度的核心是“可工作的成果”，文档只应承载必要信息。例如用户故事卡片只需一两句描述（角色+需求+价值），而非厚厚一本需求规格书；轻量文档被鼓励，详尽而无用的文档被反对。
- **客户合作高于合同谈判**：敏捷通过频繁评审、演示、与业务干系人每日协作，把客户当作团队的一分子（如Scrum中的产品负责人），持续澄清需求、调整优先级，而非只在签约和验收时互动。
- **响应变化高于遵循计划**：计划是弹性的，需求可随时调整。迭代与增量交付、欢迎变更、短反馈回路都源于这条价值观。
- **价值观→原则→实践→框架的层次**：四大价值观回答“为什么”，十二大原则指明“做什么方向”，具体实践（每日站会、结对编程、测试驱动开发）是“具体动作”，而框架（Scrum、XP、看板）把这些实践组织成完整的方法。考试常考这一层次关系，例如“某实践违背了哪条价值观”。
- **左右并非对立**：右边（流程、文档、合同、计划）并非毫无价值，只是在取舍时左边优先。这是“高于”的准确含义，常见陷阱是把“高于”误读为“不要”。`,
      "🔧 关键实践": `- **短周期迭代/冲刺**：以1-4周为周期开发可工作的成果，贯彻“持续交付有价值的软件”与“响应变化”两大原则。
- **每日站会（Daily Stand-up）**：团队每天同步进展、障碍与下一步计划，贯彻“业务人员和开发人员必须每日协作”“面对面交流最有效”。
- **用户故事（User Story）**：以“作为X，我希望Y，以便Z”的格式表达需求，确保价值导向、可讨论，避免过度文档化。
- **测试驱动开发（TDD）**：先编写会失败的测试，再写代码使其通过，保障技术卓越与良好设计。
- **结对编程（Pair Programming）**：两人共同编写代码、即时评审，提升质量与知识共享，落实“个体与互动”。
- **持续集成与持续交付（CI/CD）**：频繁集成、自动化部署，使软件随时处于可发布状态，支持“频繁交付可工作的软件”。
- **回顾（Retrospective）**：每个迭代结束团队反思流程并制定改进措施，落实“团队定期反思如何变得更有效，并相应调整行为”。
- **自组织与授权**：团队自行决定如何完成任务，管理者提供环境与支持并信任团队，对应“围绕有动力的个体构建项目”。
- **看板（Kanban）**：可视化工作流、限制在制品（WIP）、管理价值流动，支持“可持续开发”与透明性。
- **待办事项列表（Backlog）与优先级排序**：持续维护待办列表并按价值排序，客户代表参与排序，体现“客户合作”与“简洁”。`,
      "⚖️ 与传统方法对比": `- **计划方式**：传统方法（预测型/瀑布）在项目开始就进行大量详细计划并一次性执行；敏捷对按价值排序的待办列表持续规划，计划是滚动式的，只有临近的工作才详细规划。
- **需求管理**：传统假设需求可在早期确定并保持稳定；敏捷承认需求必然变化，“欢迎变更”并为之设计短反馈回路。
- **交付方式**：传统在项目末尾一次性交付全部成果，中途客户看不到可用产品；敏捷每个迭代（几周）交付一个可工作的增量，价值提前释放。
- **沟通方式**：传统依赖文档交接与里程碑会议，团队与客户沟通频率低；敏捷强调日常面对面协作，客户/产品负责人深度参与。
- **进度衡量**：传统以“完成了多少计划工作/文档”衡量进度；敏捷以“可工作的软件”衡量进度。
- **对变更的态度**：传统视变更为风险，通过变更控制流程加以控制；敏捷视变更为机遇，主动接纳并及时响应。
- **人员与角色**：传统角色细分、层级分明（业务分析、开发、测试分工明确）；敏捷团队自组织、跨职能，共同对结果负责。
- **适用场景**：传统适合需求明确、变更成本高、确定性高的项目（如基建）；敏捷适合需求模糊、不确定性高的项目（如软件开发、产品创新）。二者并非优劣之分，而是适应不同情境。`,
      "📊 度量指标": `- **交付速率（Velocity）**：团队每个迭代完成的用户故事工作量之和，用于预测后续迭代的交付能力，体现“以可工作软件衡量进度”。
- **周期时间（Cycle Time）**：从开始工作到完成一个工作项所花的时间，反映交付效率。
- **前置时间（Lead Time）**：从需求提出到交付的总时长。
- **累积流图（Cumulative Flow Diagram）**：可视化各阶段在制品队列与交付流，帮助识别瓶颈。
- **迭代燃尽图（Iteration Burn-down）**：显示迭代内剩余工作量随时间的下降趋势，衡量对迭代目标的推进。
- **缺陷逃逸率（Defect Escape Rate）**：发布后才发现缺陷的比例，衡量“技术卓越与良好设计”是否落地。
- **干系人/客户满意度**：通过评审反馈、演示反馈来衡量“客户合作”是否到位。
- **要点**：敏捷度量以成果交付与流程效率为核心，而非文档数量或投入工时——这些指标共同支持价值交付与持续改进。`,
      "💼 实践案例": `- 某软件开发公司从传统瀑布转向敏捷：过去项目周期长达一年，需求文档上百页，但客户只在项目结束时见到产品，变更须走变更控制委员会流程，交付后大量返工。
- 转型后，团队以两周为一个冲刺、使用Scrum框架：产品负责人与客户每日沟通、持续细化并排序产品待办列表；每日站会同步进展、消除障碍；每个冲刺结束进行评审，客户当场试用增量并调整需求；回顾会上团队反思改进（例如把文档精简为“用户故事+验收标准”）。
- 结果：产品每两周就有可交付版本，客户反馈及时融入，最终以更少的返工和更高的满意度交付核心功能，因为团队始终在“响应变化”而非“遵循过时计划”。
- 案例启示：宣言的四条价值观协同起作用——个体与互动（每日协作）、可工作的软件（增量演示）、客户合作（产品负责人与评审）、响应变化（待办动态调整）共同创造价值。`,
    },
    keyConcepts: `敏捷——符合《敏捷宣言》价值观与原则的任何方法、框架或实践的总称，含Scrum、XP、看板、精益等。
四大价值观——个体与互动>流程和工具；可工作的软件>详尽的文档；客户合作>合同谈判；响应变化>遵循计划。“高于”不等于“不要”，取舍时左边优先。
十二大原则——早期持续交付价值；欢迎需求变更；频繁交付；业务与开发每日协作；信任有动力的个体；面对面沟通最有效；可工作的软件衡量进度；可持续开发；持续关注技术卓越与良好设计；简洁（最大化未完成工作的艺术）；最佳架构/需求/设计出自自组织团队；定期反思如何变得更有效并调整行为。
敏捷思维模式（Agile Mindset）——由价值观界定、受原则指导、通过实践实现。真正的敏捷是文化与思维方式，而非仅仅套用某个框架的名称。
价值观→原则→实践→框架——四层递进关系，是理解全部敏捷内容的主线。
文档“恰到好处”——敏捷不反对文档，只反对“详尽而无用”的文档；文档应服务于交付。`,
    examTips: `敏捷占比高——PMP考试中敏捷相关内容占比约50%，《敏捷宣言》是全部敏捷题目的逻辑基石，务必熟记四价值观与十二原则。
“高于”不是“不要”——情景题中若选项说“敏捷不要文档”“敏捷不需要计划”，这是错误选项；正确表述是“最小化必要文档”“以滚动式规划替代一次性详细计划”。
价值观优先级——题干同时涉及价值观冲突时，左边（个体、可工作软件、客户合作、响应变化）优先。
高频原则——“欢迎需求变更，即使在开发后期”与“可工作的软件是衡量进度的主要指标”出现频率最高。若问如何衡量敏捷项目进度，优先选“可工作的软件/已交付的功能”，而非“文档完成度”或“工时”。
情景判断技巧——遇到敏捷情景题，先判断选项是否符合宣言精神：“让业务人员每日与开发团队协作”“在冲刺中接纳变更”多半正确；“严格控制变更”“先写完所有需求再开发”“靠详尽文档沟通”多半错误。
层次关系——区分“价值观（为什么）/原则（方向）/实践（动作）/框架（组织形态）”，题目可能要求归类。
勿混淆框架——宣言是总纲，Scrum、XP、看板是具体实现；判断“哪个属于敏捷实践”时以宣言为依据。`
  },
  "agile-lifecycle": {
    overview: `项目有多种形式，也有多种实施方式。项目团队需要认识各种生命周期的特征与可选方案，才能选择最可能使项目成功的方法。在PMP考试中，判断“用预测还是敏捷”是情景题的重要线索，而生命周期正是这一判断的起点。

四种生命周期的主要特征：预测型生命周期——更传统的方法，在项目开始前进行大量计划工作，然后一次性执行，预计会从高确定性的明确需求、稳定的团队和低风险中获益。迭代型生命周期——允许对未完成的工作进行反馈，从而改进和修改该工作，通过连续的原型或概念验证（Proof of Concept）逐步改进产品或成果，重点在于“通过学习完善”而非尽早交付。增量型生命周期——向客户提供各个已完成、可能立即使用的可交付成果，经常为发起人或客户交付价值，重点在于“分批加速交付”，但早期增量未必包含完整反馈回路。敏捷型生命周期——同时具备迭代与增量的特点：每个迭代既完善已有功能又交付新功能，通过短迭代频繁交付可用增量并快速获取反馈，全面拥抱变化。

这四种生命周期并非离散的类别，而是落在一条连续区间上：预测型在一端，敏捷型在另一端，中间分布着更多迭代型或增量型的形态。没有哪种生命周期能完美适用于所有项目。每种生命周期都有计划要素——区别不在于“是否计划”，而在于“完成了多少计划、何时完成”。此外，项目还常采用混合型生命周期，把预测、迭代、增量、敏捷的要素组合使用。理解这些特征，是选择生命周期与裁剪方法的前提。`,
    details: {
      "🧩 核心要素": `- **预测型生命周期**：特征为需求确定、变更成本高、团队经验成熟、风险低。流程基本顺序化（需求→设计→开发→测试→交付），计划在开工前一次性完成（如完整的工作分解结构WBS与进度计划），交付只在项目末尾一次性进行。适合确定性高、监管严格、范围稳定的项目（如建筑工程、合规系统）。
- **迭代型生命周期**：通过不断重复“开发-反馈-改进”循环来完善产品。每一次迭代产出原型或概念验证供干系人反馈，工作可能尚未达到可交付标准，但价值在于“早期验证、逐步收敛”。非常适合需求理解不充分、技术方案待探索的项目。
- **增量型生命周期**：把产品切分为多个可独立交付的部分，每完成一部分就向客户交付可立即使用的增量。价值分批提前释放，客户能尽早使用部分功能，但增量之间可能缺乏反馈驱动的修正；若同时强调“每次交付后改进”则演进为敏捷。
- **敏捷型生命周期**：是“迭代+增量”的结合：每个短迭代（如1-4周冲刺）内既进行迭代改进又交付可用增量，通过频繁演示和短反馈回路持续调整，欢迎需求变更。自组织团队、持续测试、回顾改进是其配套要素。
- **混合型生命周期**：组合不同生命周期的要素。典型形式：合同与监管部分用预测型管理、开发与交付部分用敏捷；或以预测为主、在关键环节引入敏捷实践（每日站会、回顾）；或以敏捷为主、对监管强制的文档按预测方式管理。混合型是近年考试的新宠。
- **连续区间与计划时点**：从预测到敏捷，计划颗粒度从“一次做完”过渡到“滚动细化”；所有生命周期都有计划，差异只在“完成多少计划、何时完成”。
- **共同核心**：无论哪种生命周期，交付价值、管理变更、干系人参与等基本项目管理活动都存在，只是表现形式不同。`,
      "🔧 关键实践": `- **评估需求不确定性**：需求是否明确稳定？需求模糊或经常变化时，迭代/敏捷更合适；需求稳定清晰时预测型可行。
- **评估技术不确定性**：技术方案是否成熟？存在未知技术难题时，用迭代型做概念验证（POC），或敏捷快速试错。
- **考虑组织文化与团队经验**：组织是否支持自组织与频繁变更？团队是否熟悉敏捷实践？文化与能力不匹配时强行敏捷会失败，需培训或分步推进。
- **明确风险偏好**：组织/干系人更愿接受哪种风险？预测型把风险集中在前期分析，敏捷把风险分散到频繁的小交付中逐步暴露。
- **确定交付频率要求**：客户是否需要尽早、分批使用成果？需要则选增量/敏捷；能接受项目末尾一次交付，预测型可选。
- **评估变更成本与管控要求**：变更成本高、监管严格（如医疗、航空）倾向于预测型加变更控制；变更成本低、市场变化快的产品开发倾向于敏捷。
- **干系人参与度**：干系人/客户能否深度持续参与（评审、反馈）？能则敏捷可行，不能则需更多书面约定（预测型倾向）。
- **用斯泰西模型定位**：以“需求不确定性×技术不确定性”双轴定位项目——低不确定性区域选预测型，中等不确定性选迭代/增量型，高不确定性区域需敏捷方法；双高导致“混乱”时，应先设法降低或约束其中一个变量（如锁定需求范围或简化技术方案）。
- **裁剪与组合**：不必二选一，可在同一项目的不同阶段或不同部分采用不同生命周期（混合型），关键是“依据项目情境裁剪”。`,
      "⚖️ 与传统方法对比": `- **计划与执行**：传统方法“先计划后执行、一次到位”；敏捷“边计划边执行、滚动计划”。
- **交付节奏**：传统项目末尾一次性交付；敏捷每1-4周持续交付可用增量。
- **需求与变更**：传统视需求为前期可确定、后期尽量不变；敏捷承认变化是常态并主动拥抱。
- **客户/干系人参与**：传统主要在需求与验收时点互动；敏捷全程深度参与（产品负责人角色、评审会、每日协作）。
- **风险应对**：传统以详尽前期分析尽量消除不确定性；敏捷以短反馈回路快速暴露并消化不确定性。
- **文档与沟通**：传统以文档为沟通媒介、按里程碑评审；敏捷以面对面沟通为主、文档轻量化。
- **团队形态**：传统角色分工明确、由项目经理协调；敏捷自组织、跨职能团队共同负责。
- **适用情境**：传统适合需求确定、不确定性低、变更成本高的项目；敏捷适合需求与市场变化快、需要快速试错与价值提前交付的项目。二者是同一连续区间的两端，选择取决于项目特征而非个人偏好。`,
      "📊 度量指标": `- **交付频率（Frequency of Delivery）**：单位时间内交付可工作增量的次数，敏捷项目通常以周为单位，衡量“加速价值交付”是否实现。
- **前置时间/周期时间（Lead/Cycle Time）**：从需求提出到交付、从开始到完成的时长，用于识别流程瓶颈。
- **变更成本曲线**：预测型项目中变更越晚成本越高（曲线陡峭上升）；敏捷通过短反馈与迭代把变更成本压低。可用“需求变更数量与所处阶段”观察应对能力。
- **在制品（WIP）与累积流图**：可视化在制品堆积与流动状态，衡量流动效率，常用于看板/增量式交付。
- **需求不确定性下降速度**：通过原型/概念验证（迭代型）或早期增量（增量/敏捷型）减少需求模糊的程度，衡量“通过反馈完善工作”的成效。
- **首次交付时间（Time to First Delivery）**：从项目启动到首个可用增量交付的时长，反映价值前置程度。
- **注意**：度量应服务于“所选生命周期是否达成设计目标”——预测型关注计划符合度（进度偏差、范围偏差），敏捷关注价值交付与流动效率，不可用单一指标评判所有生命周期。`,
      "💼 实践案例": `- 案例一（混合型）：某银行核心系统升级项目受监管要求详尽的合规文档（预测要素），但业务需求多变。团队采用混合型生命周期：合同与监管交付物用预测型管理（阶段评审、正式文档），功能开发用敏捷（2周冲刺、每日站会、评审会、回顾会），产品待办列表由业务负责人排序。结果既满足监管又快速响应业务变化。
- 案例二（迭代型）：某公司开发全新机器学习产品，技术路线不确定。团队先用迭代型生命周期做概念验证：每个迭代产出一个原型，由干系人试用并反馈，逐步收敛算法与交互方案，验证可行后才进入正式开发。这体现了“通过反馈完善、技术不确定性驱动迭代”。
- 案例三（增量型）：某电商平台分阶段上线支付功能。团队按增量型拆分：先交付“扫码支付”增量供部分客户使用，再交付“分期支付”增量，价值分批释放，客户提前受益。
- 案例四（斯泰西定位）：某项目需求极不确定但技术成熟（高需求+低技术不确定性），落在“复杂”区域，选迭代/增量型；另一项目两者不确定性都高，先锁定需求范围（降低需求不确定性）再进入敏捷开发，避免陷入混乱状态。`,
    },
    keyConcepts: `预测型生命周期——提前大量计划、单次交付，从需求确定、团队稳定、低风险中获益。
迭代型生命周期——通过原型/概念验证反复反馈改进产品，学习导向，早期产出未必可交付。
增量型生命周期——分批交付可立即使用的成果，加速价值释放。
敏捷型生命周期——迭代+增量结合，短周期持续交付可用功能并频繁反馈，全面拥抱变化。
混合型生命周期——组合预测、迭代、增量、敏捷要素，按项目情境裁剪。
连续区间——预测型与敏捷型之间还存在迭代/增量等中间形态，没有一种能完美适用所有项目。
每种生命周期都有计划要素——差异在“完成多少计划、何时完成”。
斯泰西复杂性模型——以需求不确定性（Y轴）×技术不确定性（X轴）双轴定位项目：低→预测，中等→迭代/增量，高→敏捷；双高→混乱，需先约束一个变量。`,
    examTips: `必考斯泰西模型——题目给出“需求变化大但技术成熟”等信息时，应选迭代/增量型；低需求+低技术不确定性选预测型；双高则先约束一个变量再迭代。注意方向：需求是Y轴、技术是X轴，且“混乱”区域不是用敏捷硬冲，而是先降低不确定性。
区分迭代与增量——迭代=重复循环+反馈改进（关注“学习”）；增量=分批交付可用成果（关注“交付”）；敏捷=两者兼备。问“哪种生命周期允许对未完成工作反馈并改进”→迭代型。
“计划”误区——凡选项说“敏捷不需要计划”均错；正确表述是“滚动式计划，细节在临近时确定”。每种生命周期都有计划要素。
混合型是新宠——近年高频考“预测+敏捷如何组合”，如“合同/监管用预测、开发用敏捷”，选同时包含两者的选项。
生命周期选择是情景题前置判断——题干给项目特征（需求稳定度、变更频繁度、交付频率要求、团队经验、监管约束），先判断生命周期，再据此选答案。
连续区间意识——不要陷入“预测或敏捷二选一”的二元思维，中间形态与混合始终存在。
共同活动——无论何种生命周期，价值交付、变更管理、干系人参与等基本活动都存在，只是形式不同；选项若说“预测型项目不需要管理变更”则错。`
  },
  "agile-scrum": {
    overview: `Scrum是PMP考试中最常考的敏捷框架，也是《敏捷实践指南》重点覆盖的方法。它由Jeff Sutherland与Ken Schwaber等人于1990年代初开发，是一种用于复杂产品开发的框架，强调通过“经验过程控制”——三大支柱：透明、检查、适应——在小步迭代中交付价值。Scrum本身不提供具体做事技巧，只提供一个由角色、事件、工件与规则构成的最小结构，让团队在框架内自行选择适合的实践。

三大支柱：透明——过程与成果对团队可见；检查——通过站会、评审、回顾定期检查；适应——发现偏差及时调整。Scrum的最小结构可概括为“三三五五”：

三个角色：产品负责人（PO）决定“做什么”（What），管理产品待办、确定优先级、最大化产品价值；敏捷教练（SM）负责“过程”（Process），确保Scrum被理解与执行、消除障碍、促进持续改进；开发团队（Developers）负责“怎么做”（How），跨职能、自组织、通常3-9人，在冲刺内交付“完成”的增量。

五大事件：冲刺（Sprint，1-4周时间盒）、冲刺规划（Sprint Planning）、每日站会（Daily Scrum，15分钟）、冲刺评审（Sprint Review）、冲刺回顾（Sprint Retrospective）。

三大工件：产品待办事项列表（Product Backlog）、冲刺待办事项列表（Sprint Backlog）、增量（Increment），并结合“完成定义”（DoD）作为完成标准。

Scrum的核心思想是：通过短周期时间盒、明确角色职责与频繁的检查适应，把不确定性转化为快速反馈，从而持续交付价值并持续改进。`,
    details: {
      "🧩 核心要素": `- **产品负责人（PO）**：唯一对产品价值负责的人，负责“做什么”。职责包括：维护并排序产品待办事项列表；代表客户/干系人澄清需求、确定优先级（最高价值优先）；决定何时发布；是唯一有权调整待办顺序和取消冲刺的人。PO与团队协作，但不替团队决定“怎么做”，也不是指挥团队的“老板/经理”。
- **敏捷教练（SM）**：服务型领导者，负责“过程”。职责包括：确保Scrum框架被理解并正确执行；引导五大事件；为团队清除障碍并推动组织层面解决；教练团队自组织与持续改进；保护团队免受外部干扰。SM不分配任务、不作产品决定，是“教练”而非“裁判”。
- **开发人员/开发团队（Developers）**：负责“怎么做”。跨职能（含设计、开发、测试等技能）、自组织（自己决定任务分配与实现方式）、通常3-9人（5-9人为较理想规模）、在冲刺内交付“完成”增量。团队整体对交付负责，任务由团队自组织分配，而非项目经理指派。
- **冲刺（Sprint）**：1-4周的时间盒，期间创建“完成”的可用增量；冲刺长度在项目内保持一致，不随意更改。
- **冲刺规划（Sprint Planning）**：每个冲刺开始时的会议，受时间盒约束（4周冲刺约8小时）。团队共同确定冲刺目标（Sprint Goal），从产品待办中选择本冲刺的工作项，形成冲刺待办事项列表，回答“本冲刺交付什么、如何交付”。
- **每日站会（Daily Scrum）**：每天15分钟，时间盒固定。团队同步对冲刺目标的进展、今日计划、识别障碍。它不是向经理汇报的状态会，而是团队自我规划与相互承诺的会议。
- **冲刺评审（Sprint Review）**：冲刺结束时举行（时间盒上限约4小时），团队演示“完成”的增量，干系人与客户试用并反馈，PO据此更新产品待办事项列表。目的是“检查+适应产品”，不是正式验收/批准。
- **冲刺回顾（Sprint Retrospective）**：评审后、下一冲刺前举行，团队检查自身过程（协作、工具、流程、DoD执行情况）并制定改进计划。它是“持续改进的核心”、敏捷最重要的实践之一。区别：评审看产品（面向客户），回顾看过程（面向内部）。
- **产品待办事项列表（Product Backlog）**：所有已知需求的优先级排序列表，动态演进；条目由粗到细，高优先级条目细化到可开发程度；由PO维护。
- **冲刺待办事项列表（Sprint Backlog）**：当前冲刺要完成的工作项及实现它的计划，由开发团队在规划会上从产品待办中选取并承诺。
- **增量（Increment）**：冲刺内完成且符合DoD的可用产品版本，是可发布/可演示的功能总和。每个冲刺必须产出增量。`,
      "🔧 关键实践": `- **完成的定义（DoD，Definition of Done）**：团队共同认可、可交付物被视为“完成”前必须满足的一组标准（如已编码、已测试、已评审、已集成、可运行）。DoD适用于所有工作项，保证团队对“完成”理解一致。DoD一经建立，通常不逐项更改。
- **验收标准（AC，Acceptance Criteria）**：针对单个用户故事/待办事项的具体、可测试条件，回答“这个条目满足什么条件才算通过”。AC由PO定义并逐项确认。
- **DoD与AC的区分（高频考点）**：DoD是“团队对任何工作完成的标准”（全局、面向质量），AC是“单个条目的业务验收条件”（局部、面向功能）。两者都满足才真正“完成”。
- **冲刺目标（Sprint Goal）**：每个冲刺设定的单一明确目标，指导团队“为何做这些工作”，是冲刺的“北极星”。需求不清或取舍两难时以冲刺目标为准。
- **待办事项列表精化（Backlog Refinement）**：团队持续把较大的待办条目拆分、细化、估算、重新排序，使高优先级条目达到“就绪”（Ready）状态；通常约占冲刺时间的5%-10%。它是持续活动，不必是正式召开的会议。
- **冲刺取消规则**：只有产品负责人有权取消冲刺，通常因冲刺目标已过时（市场或需求变化）。取消后，已完成且符合DoD的工作保留为增量，未完成条目放回产品待办列表重新排序。团队、SM、干系人均无权取消。
- **Scrum五大价值观（高频）**：承诺（Commitment）——团队承诺达成冲刺目标；专注（Focus）——聚焦冲刺内工作；开放（Openness）——对工作与挑战保持透明；尊重（Respect）——尊重彼此能力与意见；勇气（Courage）——敢于直面困难、说真话、挑战现状。SM要营造让价值观落地的环境。
- **燃尽图（Burn-down Chart）**：显示冲刺内“剩余工作量随时间的下降趋势”，纵轴为剩余工作量，横轴为时间。用于监控冲刺进展：将实际曲线与理想线对比，若偏离（如剩余工作不降反升）说明有阻碍，团队在站会中讨论并解决。它是检查工具，不是KPI考核工具。
- **燃起图/累积流图**：燃起图显示已完成累计工作量，累积流图可视化全流程在制品与交付流。`,
      "⚖️ 与传统方法对比": `- **角色**：传统有项目经理（分配任务、管进度）以及独立的需求/设计/测试角色；Scrum由PO（做什么）、SM（过程）、自组织开发团队（怎么做）构成，没有传统意义上的“项目经理”——SM承担部分教练与障碍清除职责，而非指挥者。
- **计划**：传统开工前一次性详细计划；Scrum滚动规划，规划粒度随接近而细化，冲刺规划每个迭代重做。
- **需求**：传统锁定范围、走变更控制流程；Scrum产品待办动态排序，欢迎变化，PO随时可调优先级。
- **进度**：传统用甘特图/关键路径衡量计划完成度；Scrum用燃尽图、速率与可工作增量衡量价值交付。
- **质量**：传统把测试集中在“测试阶段”集中验收；Scrum每个冲刺内持续集成测试，DoD内嵌质量要求，缺陷不跨迭代积压。
- **检查与适应**：传统通过里程碑评审；Scrum通过站会（日）、评审（每迭代）、回顾（每迭代）三个节奏持续检查与适应。
- **文档**：传统以文档为契约媒介；Scrum以面对面沟通为主，用轻量文档（用户故事、待办列表）支撑。
- **价值观基础**：传统重过程合规、服从计划；Scrum重承诺、专注、开放、尊重、勇气——处理不确定性的方式根本不同。`,
      "📊 度量指标": `- **速率（Velocity）**：团队每个冲刺完成的用户故事点数之和，用于预测后续冲刺的交付能力与发布规划。速率用于预测而非考核，跨团队比较无意义。
- **冲刺燃尽图**：展示冲刺剩余工作量的下降趋势，识别阻碍与进度偏差；偏离理想线时应深入调查原因。
- **冲刺燃起图/累积流图**：展示已完成工作的累计或全流程流动状态，识别瓶颈与在制品积压。
- **周期时间/前置时间**：完成一个条目或从提出到交付的耗时，衡量流动效率。
- **产品质量指标**：缺陷逃逸率（发布后缺陷比例）、测试通过率、技术债务趋势，与DoD执行相关。
- **团队/干系人反馈指标**：评审会参与度、干系人满意度、回顾改进项落实率，衡量持续改进是否闭环。
- **价值指标**：按价值排序后的交付完成情况、已交付功能的使用率。
- **要点**：Scrum度量服务于透明与适应——数据用于团队自我调整，不用于外部奖惩；最常见错误是把速率当考核、把燃尽图当KPI。`,
      "💼 实践案例": `- 某移动应用公司使用Scrum开发新产品。产品负责人维护产品待办列表，按业务价值排序，将“登录注册”“消息推送”等需求拆成用户故事并撰写验收标准（AC），如“输入正确验证码后30秒内完成登录”。
- 冲刺规划会上，团队设定冲刺目标“完成首版注册登录流程”，从产品待办选取条目形成冲刺待办，并对照团队统一的DoD（编码完成、单元测试通过、UI测试通过、可部署、无已知阻塞级缺陷）确认可承诺。
- 冲刺中，每日站会同步进展；燃尽图显示中途剩余工作上升——发现推送接口依赖的外部厂商延误，SM及时协调、消除障碍。
- 冲刺末，评审会向客户演示增量并获反馈，客户要求调整登录方式；PO据此更新待办，团队将未完成条目放回待办列表。回顾会上，团队决定缩短接口联调周期并改进测试流程。
- 期间，因市场策略剧变，客户提出新功能优先级更高，PO行使唯一权力取消了当前冲刺，已完成且符合DoD的部分保留为增量。五大价值观（承诺冲刺目标、专注迭代工作、开放分享进展、尊重彼此专长、勇气承认接口延误）贯穿整个过程。`,
    },
    keyConcepts: `三三五五结构——3角色（PO/SM/开发人员）、5事件（Sprint、规划、站会、评审、回顾）、3工件（产品待办、冲刺待办、增量）、5价值观（承诺、专注、开放、尊重、勇气）。
What/How/Process——PO决定What（做什么与优先级）；开发团队决定How（如何实现与分工）；SM负责Process（过程与框架执行）。这是PMP高频考点。
DoD vs AC——DoD是团队统一的“完成”标准（全局质量），AC是单个条目的验收条件（局部功能）。
冲刺目标（Sprint Goal）——冲刺的单一目标，指导范围取舍。
Backlog精化——持续拆分、细化、估算、排序待办条目，使高优先级条目达到“就绪”。
Sprint取消——仅PO有权，多因冲刺目标过时；已完成增量保留、未完成条目回待办。
时间盒——Sprint 1-4周、每日站会15分钟、冲刺规划（4周冲刺约8小时）、评审约4小时、回顾约3小时。
三大支柱——透明、检查、适应。
燃尽图——剩余工作量随时间下降的曲线，用于监控冲刺进展。`,
    examTips: `角色职责辨析（最高频）——情景题问“谁负责X”：产品内容与优先级→PO；过程、障碍、框架执行→SM；如何实现与自组织分工→开发团队；取消冲刺/调整优先级→仅PO。
站会定位——每日站会不是向PM汇报的状态会，而是团队自我组织的15分钟同步；不解决具体问题（会后另约讨论）。
评审 vs 回顾——评审=向干系人展示增量（看产品、面向客户）；回顾=团队反思过程改进（看流程、面向内部）。“回顾是持续改进的核心”常考。
DoD与AC——题干问“团队确认工作完成的标准”→DoD；问“某用户故事满足的条件”→AC。选项混淆两者是经典陷阱。
Scrum没有传统项目经理——“项目经理分配任务”“PM批准变更”在情景题中均为错，正确方向是SM教练+自组织团队。
燃尽图——纵轴剩余工作量、随时间下降；剩余上升=有阻碍。问“用什么监控冲刺进展”→燃尽图。
Sprint长度一致性——一个项目内冲刺长度应保持一致，不随意变更。
价值观情景——情景题（如团队隐瞒问题）体现“开放/勇气”被违背。
数字记忆——冲刺时间盒1-4周、每日站会15分钟、团队规模3-9人（5-9为较理想）。`
  },
  "agile-servant-leader": {
    overview: `仆人式领导（Servant Leadership）是敏捷环境中项目经理、敏捷教练与Scrum Master的核心领导方式。《敏捷实践指南》指出，仆人式领导是一种通过服务团队来领导团队的实践，它强调理解和关注团队成员的需要与发展，旨在使团队尽可能达到最高绩效。仆人式领导的作用是促进团队发现和定义敏捷——他不是替团队决定敏捷是什么，而是引导团队自己去理解、拥抱和运用敏捷。

仆人式领导从事项目工作遵循目的—人员—过程的顺序：首先是目的（Purpose），与团队一起定义为什么或项目的意义，使团队成员能够围绕项目目标进行合作互动；其次是人员（People），目标确立后，鼓励团队创造一个人人都能成功的环境，关注团队成员的需求与成长；最后才是过程（Process），不要计划遵循一套完美的敏捷过程，而应注重结果——只要跨职能团队能够持续交付价值，并定期反思产品与过程，团队就是敏捷的。

在敏捷环境中，项目经理的角色发生根本转变：从传统团队的中心协调者，转变为管理与服务团队的仆人式领导。其工作重点不再是分配任务、发号施令，而是引导需要帮助的人、促进团队合作、保持与干系人需要的一致，并为团队清除通往成功的障碍。这一转变深刻体现了敏捷以人为中心的核心价值观，也是PMP考试中敏捷角色类题目的关键判断依据。`,
    details: {
      "🧩 核心要素": `- **定义**：仆人式领导是一种领导哲学，核心信念是先服务、后领导。领导者把团队的需要放在第一位，通过服务团队赢得信任与影响力，而非依靠职位权威发号施令。在敏捷框架中，Scrum Master与敏捷教练正是这一角色的典型化身。
- **特征与品质**：仆人式领导具备一系列可识别的品质，包括提升自我意识（Self-awareness）、积极倾听（Listening）、真诚地为团队服务（Serving others）、帮助他人成长（Helping others grow）、引导而非控制（Guiding rather than controlling）、促进安全、尊重与信任（Promoting safety, respect and trust）。这些品质共同构成服务型而非控制型的领导风格。
- **目的—人员—过程顺序**：仆人式领导先与团队澄清为什么（目的），再创造人人能成功的环境（人员），最后才关注采用何种敏捷过程（过程）。顺序不可颠倒——没有明确目的就空谈过程，团队会迷失方向。
- **角色转变**：项目经理从团队的中心转变为为团队服务。在敏捷环境中，项目经理充当仆人式领导，关注点从指挥与控制转向引导与支持，包括引导需要帮助的人、促进团队内外合作、使工作与干系人需要保持一致。
- **与命令-控制型管理对立**：仆人式领导不依靠权威命令团队，而是通过授权、服务与教练让团队自我管理。团队的自组织能力越强，越不需要领导者的直接指挥。
- **仍是领导者**：仆人式领导不是无为而治或放弃领导责任，而是换一种更有效的方式承担责任——对结果负责、对团队的成长负责、对障碍的清除负责。`,
      "🔧 关键实践": `- **消除障碍（Removing Impediments）**：这是仆人式领导的核心职责。障碍可分为三类——组织障碍（Organizational Impediments），如冗长的审批流程、财务部门/变更控制委员会/审计部门造成的瓶颈；过程障碍（Process Impediments），如不清晰的需求、无效率的会议、不合理的分工；资源障碍（Resource Impediments），如人员、工具、环境、经费不足。领导者需主动发现、沟通并消除这些障碍，为团队铺路。
- **保护团队免受外部干扰**：冲刺期间团队需要专注；仆人式领导在团队与外部干系人之间充当缓冲带，拦截不必要的中断、会议与请求，让团队保持专注与节奏，同时向干系人解释敏捷规则、管理其预期。
- **促进团队内外的合作与对话**：引导团队内部协作（站会、结对工作、回顾），也促进团队之间以及团队与干系人之间的对话，打破信息孤岛，推动价值流顺畅流动。
- **帮助发现瓶颈并沟通**：通过观察价值流，帮助团队识别流程中的瓶颈与延迟（如等待审批、等待测试），将其透明呈现，推动相关方共同解决。
- **教育干系人了解敏捷**：向业务方、发起人与管理层解释敏捷的价值、节奏与术语（冲刺、待办列表、评审、回顾），争取理解与支持，减少来自组织层面的摩擦。
- **通过指导、鼓励、帮助为团队提供支持**：教练团队成员提升技能、鼓励尝试与容错、在困难时提供帮助，促进团队持续成长，而非替团队解决问题。
- **庆祝团队的成功**：及时认可并庆祝团队的成果与进步，营造积极氛围，强化成就感与归属感。
- **关键行为三原则**：提问而非指令（Ask vs. Tell）——用教练式提问启发团队自己找到答案；赋能而非控制（Empower vs. Control）——授权团队自组织并信任他们；引导而非指挥（Guide vs. Direct）——在旁引导方向，而非发号施令。这三条是考试高频考点。`,
      "⚖️ 与传统方法对比": `- **权威来源**：传统命令-控制型领导依赖职位权威与正式职权发号施令；仆人式领导依靠服务、信任与影响力赢得追随，权威来自团队的自愿认可。
- **沟通方式**：传统领导以下达指令—执行—汇报为主；仆人式领导以提问、倾听、教练式对话为主，鼓励团队自主决策。
- **团队状态**：传统领导把团队视为被管理的对象，强调服从与流程合规；仆人式领导把团队视为有动力的专业人士，强调自组织、自主与成长。
- **项目经理定位**：传统项目经理位于团队中心，负责计划、分配任务、监控与控制；敏捷环境中项目经理转变为服务者，负责清除障碍、促进协作、教练支持，具体任务由团队自组织分配。
- **对错误的处理**：传统方法出错往往追责；仆人式领导营造心理安全的环境，鼓励从失败中学习，把错误视为改进机会。
- **目标一致性**：两者都追求项目成功，但传统以遵循计划、完成交付物为标尺，仆人式领导以团队持续交付价值、成员成长、障碍被清除为标尺。仆人式领导并不等于放弃对结果负责。`,
      "📊 度量指标": `- **障碍清除指标**：已识别障碍的数量、平均清除时间、给定迭代内被清除的障碍比例。障碍清除越快，团队流动越顺畅，这是仆人式领导工作成效的直接体现。
- **团队健康与满意度**：团队士气、员工净推荐值、成员对是否被支持与被信任的主观评价。仆人式领导的目标之一就是让成员在心理安全的环境中工作。
- **团队自组织程度**：团队自行决策的频率、依赖领导者决策的比例。自组织程度上升意味着领导者成功地从控制转向赋能。
- **交付成效指标**：速率（Velocity）的稳定性与趋势、周期时间/前置时间的缩短、吞吐量的提升。领导有效时，团队交付能力应持续改善。
- **回顾改进落实率**：回顾会上提出的改进项被实际落实的比例。仆人式领导推动持续改进闭环，而非空谈改进。
- **注意**：仆人式领导的效果难以用单一财务指标衡量，应组合使用过程健康、团队感受、交付成效多类指标，并避免把度量用作对领导者的惩罚工具。`,
      "💼 实践案例": `- 某银行开发团队按Scrum转型，新任Scrum Master践行仆人式领导。团队在每日站会中多次反馈部署需要三天审批、拖慢交付。Scrum Master将其识别为组织障碍——源于变更控制委员会（CCB）的冗长审批流程，而非团队成员能力问题。他没有直接命令团队加快部署，而是：先与团队一起澄清为什么快速部署重要（目的），再组织团队讨论可行的应对方案（人员），最后主动与CCB沟通，推动建立了低风险变更走快速通道的新策略（过程）。同时他拦截了多个与冲刺无关的会议，保护团队专注；在回顾会上引导团队提出改进项并跟进落实；项目取得阶段成果时主动组织庆祝。两个月后，部署审批从三天缩短到数小时，团队速率稳步上升，成员反馈我们感到被支持而不是被管束。这个案例体现了仆人式领导的全部要点：消除障碍、保护团队、促进协作、帮助成长、提问而非指令。`,
    },
    keyConcepts: `仆人式领导——通过服务团队来领导团队的实践，注重理解和关注团队成员的需要与发展，使团队达到最高绩效。
目的—人员—过程——仆人式领导的工作顺序：先定义为什么（目的），再创造成功环境（人员），最后关注过程与结果。
核心职责——消除障碍、保护团队免受外部干扰、促进协作、帮助团队成长、教育干系人、庆祝成功。
障碍分类——组织障碍（流程/部门瓶颈）、过程障碍、资源障碍三类。
关键行为——提问而非指令、赋能而非控制、引导而非指挥。
角色转变——项目经理从团队中心协调者转变为为团队服务的管理者。
赋能——授权团队自组织并信任他们，而非替团队做决定。
心理安全——团队成员敢于试错、坦言的氛围，由仆人式领导营造，是持续改进的前提。
教练式提问——通过提问启发团队自行找到答案，而非直接给出指令。
与传统管理对比——命令-控制型依靠职权，仆人式领导依靠服务与信任。`,
    examTips: `仆人式领导不等于无为而治——情景题中领导者什么都不管、完全放手是错误选项；仆人式领导仍然对交付结果负责，只是换一种领导方式。
谁负责消除障碍——敏捷场景题中，识别并清除组织/过程/资源障碍是Scrum Master/仆人式领导/敏捷教练的职责，不是团队成员，也不是产品负责人。
角色辨析——产品内容与优先级归产品负责人；过程与障碍归仆人式领导；如何实现归开发团队。
关键行为三原则——提问而非指令、赋能而非控制、引导而非指挥是高频原文考点，看到选项与此相反（命令、控制、指挥）即为错。
保护团队——冲刺期间拦截外部干扰、维护团队专注是仆人式领导的重要职责；选项出现让团队自行应付所有会议、为管理方便插入新需求即为错。
目的—人员—过程顺序——先澄清目的再谈过程；情景题中团队不知为何而做，应选先与团队确认项目目的/愿景。
教育干系人——仆人式领导还需向发起人与管理层解释敏捷、管理其预期；情景题中领导者向业务方解释冲刺规则、引导干系人理解敏捷节奏属于正确行为。
与传统对比——凡选项强调项目经理分配任务、下达命令、严格控制，在敏捷情景中多为错误选项。`
  },
  "agile-kanban": {
    overview: `看板（Kanban）方法源于精益制造体系（丰田生产系统），是精益思想在知识型工作中的具体应用。它于2000年代中期出现，作为当时盛行的敏捷方法的一种替代方案。看板方法不像某些敏捷方法那样规定性强，破坏性也较小，其本质是一种原地出发（Start Where You Are）的方法——团队可以从现有流程开始，逐步引入改进，无需推翻既有工作方式。

看板方法通过可视化工作流、限制在制品（WIP）、管理工作流、使过程策略明确化、使用反馈循环、协作式改进等核心实践，帮助团队平滑、持续地交付价值。其核心机制是限制在制品：为工作流的每个环节设置最大工作项数量上限，防止过载、暴露瓶颈，从而让工作顺畅流动。

看板方法不需要预设的时间盒迭代，变更可以随时加入，因此特别适合运维型工作、持续交付场景以及需求流式到达的项目。它与Scrum形成鲜明对比：Scrum有固定的冲刺（Sprint）时间盒，冲刺内通常不接受变更；看板没有迭代边界，工作项持续流动。看板方法采用渐进式变革哲学——每次改进一小步，尊重现有角色与流程，让团队在低破坏性的前提下持续进化，而不是推倒重来。因其低门槛、低破坏性与高适应性，看板方法也是许多团队迈向Scrum等更结构化敏捷框架的友好起点。`,
    details: {
      "🧩 核心要素": `- **可视化工作流（Visualize the Workflow）**：使用看板面板（Kanban Board）把工作流程的各个环节展示为列，如待办、分析、开发、测试、完成。每个工作项用卡片代表，卡片随流程逐列移动。这样所有人的工作状态一目了然，谁在做、做多少、卡在哪，都能看到。可视化是一切管理的前提。
- **限制在制品（Limit WIP）**：为每一列设置最大工作项数量（WIP上限），超过上限该列不再接收新工作。WIP限制强制团队少做多完成，防止过度并行导致的工作堆积与上下文切换，同时逼出瓶颈——当某列达到上限而下游堵塞时，瓶颈立刻暴露。
- **管理工作流（Manage Flow）**：监控工作项在流程中的移动，识别并消除瓶颈、延迟与浪费，让工作以可预测的节奏平滑流动。管理者关注流动效率，即工作项实际被处理的时间占总周期时间的比例。
- **使过程策略明确化（Make Process Policies Explicit）**：把何时工作可以进入某列、何时算完成、WIP上限多少、紧急工作如何插队等规则写清楚并公布。显式策略让团队对如何工作达成共识，是讨论与改进的基础。
- **使用反馈循环（Use Feedback Loops）**：通过多种节奏的反馈机制持续改进，包括每日站会、服务等级评审、交付节奏评审、过程策略评审、运营评审等，让团队定期检视流动情况并调整。
- **协作式改进（Improve Collaboratively）**：团队共同识别改进机会，运用模型与科学方法（实验、度量、假设检验）验证改进措施，实现共同演进。改进不是领导者的单向指令，而是团队共同的持续过程。
- **服务类别（Classes of Service）**：按工作项的风险、价值、时间约束分成类别，分别设定处理策略。常见类别包括紧急（Expedite，立即处理，如生产故障）、固定日期（Fixed Date，必须在特定日期前完成）、标准（Standard，常规工作）、无形（Intangible，无明确外部依赖的背景工作）。不同类别配不同WIP与优先级策略，防止紧急工作挤占全部产能。
- **渐进式变革哲学**：看板方法的核心哲学是从现状开始、逐步改进，尊重现有角色、职责与头衔，鼓励各层级发挥领导力，一次只引入一项改进，让团队在低破坏性中持续进化。`,
      "🔧 关键实践": `- **从现有流程开始（Start Where You Are）**：不重设岗位与角色，先把现有真实流程画到看板上。这大幅降低引入门槛，团队可以边看边改，逐步向更敏捷的工作方式演进。
- **设定并严格执行WIP上限**：每列明确写一个数字上限（如开发列最多3项）。达到上限后团队应暂停取新工作，先帮助下游清空瓶颈。WIP限制不能形同虚设，它是看板的心脏。
- **按服务类别管理优先级**：为每类工作（紧急/固定日期/标准/无形）定义进入条件与处理规则。例如紧急工作可有限度插队，但要明确其数量上限与成本，避免所有工作都标紧急。
- **缩短周期时间与前置时间**：周期时间（Cycle Time）是工作项从开始处理到完成的时间；前置时间（Lead Time）是从请求提出到交付的总时长。团队通过减少等待、消除浪费、稳定批量来压缩这两个时间，从而提升交付速度与可预测性。
- **用累积流图（CFD）监控与预测**：累积流图展示各状态工作项数量随时间的变化。理想状态下各区域线条平行且稳定；若某一区域线条变宽，说明该处工作堆积，即瓶颈所在。CFD还可用于预测交付日期：用平均吞吐量推算存量工作项的完成时间。
- **结合精益度量驱动改进**：吞吐量（Throughput，单位时间完成的工作项数）、WIP与周期时间之间存在李特尔定律（Little's Law）关系：WIP = 吞吐量 × 周期时间。团队用这些度量设计实验、验证改进假设，形成度量、假设、实验、验证的科学改进循环。
- **多节奏反馈会议**：除每日站会外，看板还常用服务等级评审（检视服务类别的绩效）与过程策略评审（检视看板规则是否还合适），形成多层反馈闭环。
- **从看板走向更敏捷**：看板作为原地出发方法，常是团队向Scrum等更结构化方法过渡的起点；当团队准备好引入时间盒与角色时，可自然迁移。`,
      "⚖️ 与传统方法对比": `- **交付节奏**：传统/预测型按阶段顺序推进、项目末期一次交付；看板无迭代边界，工作持续流动、随完成随交付。
- **变更处理**：传统通过变更控制流程管理变更；看板欢迎变更，新工作随时进入待办列（受WIP限制约束），只要团队有产能。
- **计划方式**：传统开工前一次性详细计划；看板不做大版本计划，按优先级持续取单（Pull），工作由下游拉动而非上游推动。
- **进度度量**：传统用甘特图/关键路径衡量计划完成度；看板用前置时间、周期时间、吞吐量与CFD衡量流动效率与交付可预测性。
- **管控机制**：传统靠时间盒、里程碑与审批控制；看板靠WIP限制、显式策略与反馈循环自我调节。
- **Kanban vs Scrum（高频对比）**：看板无预设迭代、变更随时可加、WIP限制为核心、角色与事件不强制，适合持续交付与运维；Scrum有固定冲刺（1-4周时间盒）、冲刺内通常不接受变更、有明确角色（产品负责人/Scrum Master/开发团队）与事件（规划/站会/评审/回顾），适合增量式产品开发。看板是连续流，Scrum是分批迭代。`,
      "📊 度量指标": `- **在制品（WIP）**：各列当前工作项数量，核心监控对象；WIP过高意味着过载与瓶颈。
- **周期时间（Cycle Time）**：工作项从开始处理到完成的时间，反映单件处理速度。
- **前置时间（Lead Time）**：从需求提出到交付的总时长，是客户感知的等待时间。
- **吞吐量（Throughput）**：单位时间内完成的工作项数量，反映系统交付能力。
- **累积流图（CFD）**：各状态工作项数量随时间的变化曲线，用于识别瓶颈、预测交付日期。线条发散/变宽表示瓶颈；各线平行且间距稳定表示流动顺畅。
- **李特尔定律**：WIP = 吞吐量 × 周期时间。三者相互约束：想缩短周期时间，要么降低WIP，要么提升吞吐量。
- **流动效率（Flow Efficiency）**：实际处理时间/总周期时间，衡量等待浪费的比例。
- **服务类别绩效**：分别统计紧急、固定日期、标准、无形类工作的按时交付率与周期时间，检视服务策略是否有效。`,
      "💼 实践案例": `- 某技术支持团队过去没有固定交付流程：新需求随意插入，人人手头堆着十几个任务，经常加班却交付缓慢。团队引入看板方法。第一步，把真实流程画成看板：待办、排期、开发、测试、发布、完成，并为每列设定WIP上限（开发3项、测试2项）。第二步，定义服务类别：生产故障为紧急（设单独紧急车道，上限1项）、合同要求的升级为固定日期、其余为标准。第三步，每日站会检视流动，团队发现测试列频繁积压，瓶颈在测试人力。于是团队把测试前移到开发早期介入，并推动显式策略开发完成前先与测试对齐验收标准。第四步，团队用累积流图观察：测试区线条曾持续变宽，加入并行测试改进后逐渐恢复平行。三个月后，前置时间从平均12天缩短到6天，吞吐量翻倍，紧急工作不再挤占全部产能。这个案例展示了可视化、WIP限制、服务类别、反馈循环与协作式改进如何协同作用，也说明看板是原地出发、低破坏性的渐进改进方法。`,
    },
    keyConcepts: `看板方法——精益制造思想在知识型工作中的应用，2000年代中期兴起，是一种规定性较弱、破坏性小的原地出发方法。
六大核心实践——可视化工作流、限制在制品（WIP）、管理工作流、使过程策略明确化、使用反馈循环、协作式改进。
WIP限制——为每列设置最大工作项数量，防止过载与瓶颈，是看板的核心机制。
服务类别——紧急、固定日期、标准、无形四类，分别设置不同进入条件与处理策略。
累积流图（CFD）——各状态工作项数量随时间的变化图，用于识别瓶颈与预测交付。
前置时间——从请求提出到交付的总时间；周期时间——从开始处理到完成的时间；吞吐量——单位时间完成的工作项数。
李特尔定律——WIP = 吞吐量 × 周期时间。
渐进式变革——从现状开始，尊重现有角色与流程，一次一小步持续改进。
Kanban vs Scrum——看板无迭代、变更随时可加、以WIP限制为核心；Scrum有固定冲刺、冲刺内通常不接受变更、有明确角色与事件。`,
    examTips: `Kanban vs Scrum——最常考的对比。题目说没有预设迭代、变更可随时加入、以WIP限制为核心，答案指向看板；说固定时间盒冲刺、冲刺内不接变更、有产品负责人/Scrum Master/开发团队角色，答案指向Scrum。
WIP限制的作用——防止过载、暴露瓶颈、减少上下文切换。看到限制在制品选项多半正确；看到无限制地并行处理所有任务多半错误。
累积流图（CFD）——识别瓶颈的标准工具。题干问哪一区域线条变宽/工作堆积，答案指向瓶颈所在。
服务类别——紧急工作要有限度（单独车道、设上限），不能说所有需求都优先。题目中标记为紧急的工作立即处理但数量受控，是正确的看板做法。
看板不强制角色与事件——看板方法没有强制要求的角色与事件，但可自愿采用；选项说看板必须设置冲刺即为错。
原地出发——看板强调从现有流程开始、渐进改进、破坏性小；选项强调推倒重来、全面重构流程不符合看板哲学。
度量记忆——前置时间=提出到交付；周期时间=开始到完成；吞吐量=单位时间完成数；CFD=瓶颈识别。注意前置时间与周期时间的区分，这是高频易混点。`
  },
  "agile-hybrid": {
    overview: `项目没有必要在整个项目周期内只用单一方法。为达成特定目标，项目经常需要结合不同的生命周期要素，预测、迭代、增量和/或敏捷方法的组合，就构成混合（Hybrid）方法。混合方法不是把敏捷和预测简单拼在一起，而是基于项目各组成部分的不确定性特征，为每个部分选择最合适的生命周期，从而在全局上实现最佳价值交付。

采用混合方法的常见原因包括：项目由多个子项目/组件构成，各部分的需求确定性与技术不确定性不同（例如硬件部分适合预测型，软件部分适合敏捷）；监管或合同约束要求某些部分采用预测型（如详尽的合规文档、固定验收标准）；组织尚未准备好全面转向敏捷，需要渐进过渡；或者某些要素不可协商（如硬性发布时间、法定合规要求），无法用纯敏捷方式执行。

项目管理的目标是：在给定的当前环境下，尽可能以最好的方式创造商业价值。因此，选择混合方法时提出的关键问题是我们怎样做才能最成功，而不是我们如何更敏捷。最终目标不是为了敏捷而敏捷，而是为了持续向客户交付价值流、达成更好的商业成果。理解为什么选择混合、在何处混合、如何切换，是掌握混合模式的核心。`,
    details: {
      "🧩 核心要素": `- **混合的定义**：混合方法是预测、迭代、增量和/或敏捷方法要素的组合。它认可一种方法走天下的不现实性，主张依据项目各部分的不确定性、风险与约束，为每个部分选择最合适的生命周期，再统一成完整的项目交付方案。
- **形式一：敏捷开发+预测型发布**：当开发部分存在不确定性、复杂性或风险，可以从敏捷方法中受益时，用敏捷（短迭代、持续反馈）完成开发；随后进入一个明确、可重复的发布阶段，用预测型方式管理（如正式的发布计划、验收、部署窗口）。适合开发探索性强、发布必须可控的场景。
- **形式二：同时结合敏捷与预测**：在同一项目中，部分环节采用短迭代、每日站会、回顾等敏捷实践（如需求分析、功能开发），其他环节仍遵循预测方法（如前期的商业评估、进度跟踪、监管汇报）。两者并行共存，各管一段。
- **形式三：以预测为主、敏捷为辅**：项目主体用预测型管理（详细计划、里程碑、变更控制），但对不确定性或复杂度较高的局部（如某个新模块、某项新技术），引入敏捷实践（短迭代、原型、评审）加以应对。适合大项目整体稳健、局部快速试错的场景。
- **形式四：以敏捷为主、预测为辅**：项目主体用敏捷（短冲刺、自组织团队、持续交付），但当某个特定要素不可协商或无法用敏捷方式执行时（如法定合规文档、硬性固定日期、监管审批），用预测型手段补充管理。适合创新驱动为主、局部受约束的场景。
- **分区决策方法**：判断哪里用敏捷、哪里用预测的关键是考察各部分的特征：需求是否清晰稳定？技术是否成熟？变更成本高低？监管与合同约束是否存在？可预测、低不确定性、强约束的部分用预测型；不确定、复杂、需求多变的部分用敏捷。把项目拆成若干决策单元逐一选择，再组合为整体混合方案。
- **作为过渡策略**：混合型生命周期常用于组织从预测型向敏捷的渐进过渡。许多团队无法一夜之间切换为敏捷：可以先在风险不大、不确定性中低的项目中引入迭代技术，再逐步增加增量技术，逐步扩大敏捷覆盖面，最终实现全面敏捷。渐进过渡降低转型阻力与失败风险。
- **Dev to Done与混合交付**：混合模式常把开发（Dev）到完成（Done）串成连续流：开发阶段用敏捷持续产出可用功能，交付/发布阶段按预测节奏批量发布，兼顾灵活性与稳定性。`,
      "🔧 关键实践": `- **识别各部分的不确定性**：开工前对项目各部分做不确定性体检：需求是否明确、技术是否成熟、干系人参与度、变更成本、监管约束。不确定性强的地方用敏捷，确定性强的地方用预测。这是选择混合形态的基础。
- **明确不可协商要素**：列出必须满足的硬约束（法定合规、固定发布日期、合同验收条款、安全认证）。不可协商的部分用预测型管理，可协商、可演进的部分用敏捷。先固定边界，再在边界内灵活。
- **统一治理与沟通节奏**：混合项目同时存在敏捷团队（看板/冲刺）与预测管理层（里程碑、阶段门）。需要建立统一的沟通机制：敏捷团队用站会/评审同步进展，向管理层用里程碑报告与状态看板汇报，避免两套体系信息脱节。
- **设计发布策略**：区分开发节奏与发布节奏。敏捷开发可以持续产出增量，但发布可合并为定期批次（如每两周、每月一次），或按功能开关灰度发布，兼顾价值前置与发布可控。
- **管理接口与依赖**：敏捷部分与预测部分的接口（交付物交接、验收标准、进度衔接）需要显式定义并监控，防止敏捷团队交付了、预测部分接不住的断档。
- **渐进实施与扩展**：作为过渡策略时，从小范围试点开始：先在一个风险不大、中低不确定性的项目尝试迭代技术，验证有效后逐步增加增量技术与敏捷实践，再扩展到更复杂的项目。每步保持可控，积累组织能力。
- **持续评估与调整**：混合不是一劳永逸的方案。随着项目推进、不确定性下降（如原型验证成功），可把更多部分切向敏捷；反之，若发现敏捷部分失控，可收回为预测管理。混合方案应随情境动态调整。`,
      "⚖️ 与传统方法对比": `- **方法观**：传统方法信奉一种方法从头用到尾（通常为瀑布/预测型）；混合方法承认项目各部分的差异性，主张按需裁剪、组合使用。
- **计划方式**：传统一次性详细计划；混合中预测部分做详细计划与里程碑，敏捷部分滚动规划，计划颗粒度依部分而定。
- **变更管理**：传统用统一变更控制流程约束变更；混合中，预测部分严格走变更控制，敏捷部分欢迎变更（受待办排序与WIP约束），两套规则并行。
- **交付节奏**：传统项目末期一次性交付；混合项目敏捷部分持续交付增量，预测部分按阶段/里程碑批量交付，兼顾灵活与稳定。
- **团队形态**：传统角色分工明确、受项目经理指挥；混合项目中敏捷团队自组织、预测部分保留传统职能管理，两个团队并存协作。
- **适用情境**：传统适合需求确定、监管严格的简单稳定项目；混合适合局部不确定与局部受约束并存的复合型项目（如硬件+软件的智能产品、合规要求高的行业软件）。混合不是预测与敏捷的折中妥协，而是按情境最优组合。`,
      "📊 度量指标": `- **敏捷部分**：速率、前置时间/周期时间、吞吐量、累积流图、燃尽图，衡量开发流动与价值交付速度。
- **预测部分**：进度偏差（SV）、成本偏差（CV）、挣值指标（SPI/CPI）、里程碑达成率，衡量计划符合度。
- **接口指标**：敏捷交付增量被预测部分接收/验收的按时率、集成点缺陷率，衡量两套体系衔接是否顺畅。这是混合项目的特有监控点。
- **发布指标**：发布批次按时率、灰度发布成功率、发布后缺陷，衡量敏捷开发+预测发布结合的效果。
- **转型指标**：采用敏捷实践的团队比例、试点项目成功复制数、组织从混合走向更敏捷的进度，衡量混合作为过渡策略的推进成效。
- **注意**：混合项目必须区分用哪个度量评估哪部分——用流动指标（前置时间）评估敏捷部分，用偏差指标（SV/CV）评估预测部分，不可混用；同时重点监控两者接口，因为接口是混合模式最大的风险源。`,
      "💼 实践案例": `- 某汽车电子企业开发一款智能车载终端，硬件与软件混合交付。硬件部分：受供应链与认证约束，需求与技术路线明确，采用预测型管理——里程碑计划、阶段评审、严格验收。软件部分：功能需求多变、用户体验待探索，采用敏捷——两周冲刺、每日站会、评审与回顾，产品负责人持续排序待办。两部分在集成点衔接：软件按冲刺产出可刷写固件增量，硬件按里程碑提供硬件平台，团队设专项接口看板监控集成就绪状态。发布阶段采用预测型：累计多个冲刺的稳定增量后，按季度发布窗口统一部署、通过监管审批。整个项目还承担组织转型试点：团队先在软件部分引入敏捷，验证后逐步扩展到更多项目。最终，软件价值提前交付、硬件交付稳定可追溯，监管合规零事故。这个案例完整覆盖了敏捷开发+预测型发布、以预测为主+敏捷为辅、混合作为过渡策略三种混合形态的实际运用。`,
    },
    keyConcepts: `混合方法——预测、迭代、增量、敏捷方法要素的组合，基于项目各部分的特征选择最适合的生命周期。
四种形式——①敏捷开发+预测型发布；②同时结合敏捷与预测；③以预测为主、敏捷为辅；④以敏捷为主、预测为辅。
分区决策——按各部分的确定性/不确定性特征决定哪里用敏捷、哪里用预测。
不可协商要素——法定合规、固定日期等硬约束用预测型管理，是混合的重要驱动因素。
过渡策略——混合作为从预测型向敏捷渐进过渡的路径：先低风险试点、再逐步扩展。
Dev to Done——开发用敏捷持续产出，交付/发布按预测节奏批量进行。
最终目标——不是为了敏捷而敏捷，而是持续交付价值流、达成更好商业成果。
情景判断——混合的选择基于各部分的不确定性与约束特征，而非个人偏好。
渐进过渡——从低风险、中低不确定性项目试点敏捷，逐步扩大覆盖面，最终实现全面敏捷。
混合不是折中——而是针对项目各部分特征的最优组合，目标是价值交付与商业成果。`,
    examTips: `混合场景是高频新考点——PMP情景题常给同一项目中硬件用预测型、软件用敏捷的复合项目，应选按部分特征分别选择生命周期/混合方法的选项。
理解为什么混合——题干给出约束（监管合规、固定发布日期、合同要求）时倾向预测部分；给出不确定性（需求多变、技术未明）时倾向敏捷部分。先判约束，再选混合形态。
不可协商要素用预测型——如某项法定文档必须按指定格式提交，正确做法是保留预测型的文档管理，而非强行完全敏捷化。
混合作为过渡策略是渐进式的——先小范围试点、再逐步扩展；选项说一夜之间全面切换敏捷不符合渐进过渡思想。
最终目标不是更敏捷而是更成功——凡选项说为了让组织更敏捷而强行混合/强行转型，方向错误；正确导向是价值交付与商业成果。
不要非此即彼——题目涉及预测或敏捷二选一时，若有组合/混合选项且符合情境，往往是更优答案。但题干若明确强调某部分确定性强，则保留预测做法是正确的。
Dev to Done与发布节奏——敏捷开发持续产出、按批次发布是合理做法；每个冲刺都强制全量发布不一定正确，需结合发布约束判断。`
  },
  "agile-metrics": {
    overview: `【核心定义】敏捷度量（Agile Metrics）是敏捷项目采用的一套基于经验与价值的衡量体系，其核心思想是：敏捷衡量团队“已经交付的成果”，而不是“预测将要交付的成果”。在预测型项目中，人们习惯用“计划完成量与实际完成量的偏差”来度量项目，例如进度偏差（SV）、成本偏差（CV）；而敏捷从经验主义出发，认为变化与不确定性是常态，因此更关注团队实际交付的价值与流程的健康度。敏捷度量不是目的而是手段——它的作用是支持适应性规划、识别流程瓶颈、暴露系统性问题，并为持续改进提供数据支撑。

核心度量指标包括：Velocity（速率）——每个迭代完成的故事点总数，反映团队稳定的交付能力，通常需要四到八次迭代才能趋于稳定，并用于预测后续迭代的交付能力；Lead Time（交付周期）——从需求被提出、加入待办列表，到最终交付给客户的全部时间，反映端到端的交付速度；Cycle Time（周期时间）——团队实际“处理”一个工作项所花费的时间，反映加工效率；响应时间（Response Time）——工作项处于等待、尚未开始处理的时间；吞吐量（Throughput）——单位时间内交付的工作项数量，与周期时间互为倒数关系。

在可视化工具方面，燃尽图（Burndown Chart）显示剩余工作与剩余时间的关系，燃起图（Burnup Chart）显示已完成工作量，累积流图（Cumulative Flow Diagram, CFD）则显示看板上各列进行中的工作数量，用于识别瓶颈与流程问题。此外，预测型挣值（EVM）指标也可以转换为敏捷术语加以理解。敏捷度量的最终价值在于“用数据驱动改进”，而非“用数据评判团队”。`,
    details: {
      "🧩 核心要素": `- **Velocity（速率）**：每个迭代完成的故事点总数，反映团队的实际交付能力，用于预测未来迭代能完成多少工作。通常在4-8个迭代后趋于稳定，只有稳定的速率才有预测价值；速率是历史经验的体现，因此不同团队之间不可直接比较。
- **Lead Time（交付周期）**：从工作项进入看板（需求提出或加入待办列表）到完成交付的全部时间。它既包含处理时间也包含等待时间，衡量端到端的响应速度，是客户可直接感知的指标，反映整体交付的敏捷性。
- **Cycle Time（周期时间）**：团队真正着手处理一个工作项到其完成的时间，不包含等待时间。周期时间越短，说明流程越顺畅、在制品越少；常与Lead Time、响应时间配合使用以定位等待发生在哪个环节。
- **响应时间（Response Time）**：工作项等待处理开始的时间。等待时间过长说明团队产能被占用或优先级混乱，是流程拥堵的前兆。
- **吞吐量（Throughput）**：单位时间内（通常按每个迭代）完成并交付的工作项数量。与周期时间互为倒数关系（平均吞吐率≈1/平均周期时间），是与业务产出直接挂钩的指标。
- **故事点（Story Point）**：对用户故事相对工作量、复杂度与风险的综合相对评估，是计算Velocity的基础单位；故事点强调“相对大小”而非绝对工时，由团队用自己的尺度打点。`,
      "🔧 关键实践": `- **燃尽图（Burndown Chart）**：以迭代或发布为横轴（时间），纵轴显示剩余工作量（故事点或任务数）。图中通常有两条线：一条是按计划匀速消耗的理想直线（计划线），一条是实际剩余工作的曲线。实际曲线持续高于计划线，说明可能无法按时完成，需要调整范围或增援。
- **燃起图（Burnup Chart）**：纵轴显示累计已完成的工作量，同时通常标出总工作量的“范围线”（scope line）。当范围线上升说明范围被追加，能直观暴露“工作量增长”这一在燃尽图中容易被掩盖的信息。
- **累积流图（CFD，Cumulative Flow Diagram）**：看板上各列的累计工作项数量随时间的变化曲线，从下到上依次堆积为若干“色带”。判读机制：某一条色带持续变宽，说明该列工作项不断积压，即该阶段出现积压或瓶颈；任意两条相邻曲线之间的垂直间距，代表该阶段正在处理的平均在制品数量（平均WIP）；整体曲线从左向右的水平斜率反映吞吐率，斜率越平缓说明交付速度越慢；结合利特尔法则，用“平均WIP÷平均吞吐率”即可推算出平均交付周期（Lead Time），实现“看图即可预估交付时长”。
- **预测（Forecast）方法**：当Velocity趋于稳定后，用“剩余故事点÷稳定Velocity”估算完成剩余工作所需的迭代（Sprint）数量。例如剩余300个故事点、稳定速率每迭代50点，则预计还需约6个迭代。这是敏捷发布计划与“何时完成”预测的常用方法。
- **基于迭代的度量回顾**：每个迭代结束时回顾度量数据，将指标变化与流程调整关联起来，驱动持续改进，避免“只度量、不行动”。`,
      "⚖️ 与传统方法对比": `- **度量对象不同**：预测型度量“计划vs实际”的偏差（如SV、CV），回答“与计划相比差多少”；敏捷度量“实际交付的价值与流程状态”，回答“我们真正交付了什么、流程是否健康”。
- **指标来源不同**：预测型依赖前期详细估算与基准；敏捷依赖经验数据（已完成的历史迭代），强调基于事实而非预测。
- **挣值换算到敏捷**：EVM指标可转换为敏捷术语。例如迭代计划完成30个故事点，实际完成25个，则进度绩效指数SPI=25/30≈0.83，表示只完成计划的83%；成本绩效指数CPI=已完成功能的价值÷实际成本，衡量每投入1单位成本获得的功能价值。需要说明，敏捷中的故事点本质是相对工作量而非货币价值，这类换算主要用于沟通与理解，而非精确的财务核算。
- **“西瓜项目”陷阱**：预测型度量容易制造“外面绿、里面红”的假象——报告显示计划（绿色），实际早已严重落后或质量低劣（红色）。这是预测型指标只关注形式进度而忽视真实价值的典型问题，也是敏捷采用经验度量的重要动因。`,
      "📊 度量指标": `- **质量类指标**：缺陷逃逸率（Defect Escape Rate，缺陷逃逸到生产环境的比例）、测试覆盖率、已修复缺陷数等。“交付的速度”必须与“交付的质量”联动，避免一味追求Velocity而牺牲质量。
- **流程类指标**：WIP（在制品数量）、流动效率（处理时间÷交付周期，越高说明等待越少）、瓶颈识别结果、吞吐量趋势等，反映流程健康度。
- **客户价值类指标**：已交付功能的使用率、客户满意度、业务价值实现情况，反映“是否交付了客户真正需要的价值”。
- **指标组合使用**：单一指标容易失真，应组合使用——例如“Velocity+质量+客户价值”三者并重，才可能反映真实绩效。
- **度量陷阱（Measurement Traps）**：
  - 不要跨团队比较Velocity：各团队的故事点口径、经验不同，跨团队比较毫无意义。
  - 不要用Velocity考核团队：一旦把速率与奖惩挂钩，团队就会通过夸大故事点、缩减范围等方式“操纵”数据，指标随即失真（古德哈特定律）。
  - 不要只看单一指标：如只看燃尽图会掩盖范围蔓延，只看Velocity会忽略质量下滑。
  - 度量是为改进服务而非评判：数据应驱动回顾与流程调整，而不是用来追责。`,
      "💼 实践案例": `某支付网关团队在第5个迭代时发现交付周期持续上升。通过绘制累积流图（CFD），团队观察到“测试”列对应色带逐渐变宽，判定测试是瓶颈；同时利用利特尔法则，以平均WIP（12个待测试项）除以平均吞吐率（每迭代3项），估算平均交付周期约为4个迭代，与Lead Time统计数据吻合。团队随后限制该阶段WIP、引入自动化测试与测试结对，将测试色带收窄，交付周期缩短至约2.5个迭代。同时，团队用稳定的Velocity（每迭代45个故事点）和剩余工作量（450点）预测还需约10个迭代完成全部功能，并向干系人如实沟通——全程基于真实经验数据，而非“感觉良好”的乐观估算。`,
    },
    keyConcepts: `- **Velocity（速率）**：每迭代完成的故事点总数；通常4-8个迭代后趋于稳定，稳定后可用于预测；不可跨团队比较。
- **Lead Time（交付周期）**：从需求提出到交付的全部时间，包含等待时间，衡量端到端响应速度。
- **Cycle Time（周期时间）**：实际处理一个工作项的时间，不含等待，反映加工效率。
- **响应时间（Response Time）**：工作项等待开始处理的时间，反映流程拥堵程度。
- **吞吐量（Throughput）**：单位时间完成交付的工作项数量，与平均周期时间互为倒数。
- **故事点（Story Point）**：对工作相对工作量、复杂度和风险的综合评估，是Velocity的计算单位。
- **燃尽图**：显示剩余工作与剩余时间，虚线为计划线，实际曲线可判断能否按时完成。
- **燃起图**：显示已完成工作量并标出总范围线，能暴露范围蔓延。
- **累积流图（CFD）**：按阶段展示累计工作项，色带变宽=积压/瓶颈；相邻曲线垂直间距=平均WIP；结合利特尔法则可由WIP÷吞吐率推算平均交付周期。
- **利特尔法则（Little's Law）**：周期时间=在制品数量÷吞吐率；限制WIP可直接缩短交付周期。
- **预测（Forecast）**：稳定Velocity下，剩余故事点÷Velocity≈预期迭代数。
- **西瓜项目**：外表绿（计划达标）实际红（严重落后或质量差），是预测型度量的陷阱。`,
    examTips: `- Velocity稳定需要4-8个迭代：考题常问“经过多少个迭代后Velocity可稳定并用于预测”，记住4-8。
- 绝不跨团队比较Velocity：每个团队故事点口径不同，这是高频陷阱。
- 燃尽图显示剩余工作（对剩余时间）；燃起图显示已完成工作（并标出总范围）。这是最常见的易混点。
- CFD判读三要点：某列色带变宽=该阶段积压/瓶颈；相邻曲线垂直间距=平均WIP；结合利特尔法则用WIP÷吞吐率推算交付周期。
- 利特尔法则：周期时间=WIP÷吞吐率——限制WIP可缩短交付时间，是看板度量的核心。
- SPI的敏捷换算：实际完成故事点÷计划故事点，如计划30完成25则SPI=0.83。
- “西瓜项目”指报告与实际严重不符（外面绿、里面红），是预测型度量的典型问题。
- 度量陷阱：不用Velocity做绩效考评、不只看单一指标、度量目的是驱动改进而非追责。`
  },
  "agile-xp": {
    overview: `【核心定义】极限编程（Extreme Programming，XP）是Kent Beck于20世纪90年代提出的一种敏捷软件开发框架，被公认为最早的敏捷方法之一，其设计目标直指软件开发中“需求频繁变化、交付周期长、风险高”的痛点。XP把一些公认的良好工程实践“发挥到极致”（故名“极限”）：例如把代码评审发挥到极致就是结对编程，把测试发挥到极致就是测试驱动开发（TDD），把持续集成发挥到极致就是每天甚至每小时的代码整合。因此XP的核心不是一套繁复的管理流程，而是一组深入骨髓的工程实践与价值观。

XP特别适用于需求不稳定、风险较高、中小规模的软件开发项目，其成功高度依赖团队的技术能力与纪律性。XP的价值观体系（沟通、简单、反馈、勇气、尊重）是12大实践的灵魂——实践是价值观的具体化，价值观又反过来支撑实践在压力下被坚持执行。在项目管理语境下，XP为适应型（敏捷）方法提供了详细的技术实践清单，这些实践常作为PMP考试中敏捷技术与质量实践的高频考点。理解XP，就是理解“高质量软件如何通过纪律性的工程实践被持续交付出来”。`,
    details: {
      "🧩 核心要素": `- **沟通（Communication）**：团队内部、团队与客户之间保持持续、开放的交流。XP通过现场客户、计划游戏、每日站会等机制强制各方高频对话，让信息在第一时间流动，减少误解与返工。
- **简单（Simplicity）**：做最简单且能正确工作的事，只设计当前需求所需，不为未来过度设计。简单的系统更易理解、更易修改，也就更易维护；“够用就好”是XP的设计哲学。
- **反馈（Feedback）**：通过频繁测试、小发布、持续集成、客户评审获得快速而具体的反馈，让团队尽早发现偏差。反馈越快，纠错成本越低。
- **勇气（Courage）**：敢于直面问题——勇于重构糟糕的代码、坦诚告知客户进度问题、果断采用新技术、敢于重新设计。勇气让团队在困难面前不回避、不粉饰。
- **尊重（Respect）**：尊重每位成员的贡献、时间与尊严。没有尊重，沟通会失真、反馈会被掩盖、勇气无从谈起；尊重是其他价值观能够落地的人际基础。`,
      "🔧 关键实践": `- **持续集成（Continuous Integration, CI）**：将代码频繁（每天甚至更频繁）整合到主干，每次整合都自动构建并运行测试，确保整个产品仍然按预期工作。价值在于尽早发现集成问题，避免“集成地狱”。
- **测试驱动开发（Test-Driven Development, TDD）**：先写失败的测试，再写让测试通过的最小代码，最后重构。形成“红-绿-重构（Red-Green-Refactor）”循环：红——先写一个会失败的测试，明确预期行为；绿——编写最少代码让测试通过；重构——在测试保护下持续改进代码结构而不改变外部行为。TDD使代码始终被测试覆盖，并提供不断回归的安全网。
- **结对编程（Pair Programming）**：两名开发人员在同一台电脑上共同编写代码，角色分工为“驾驶员（Driver）”与“领航员（Navigator）”：驾驶员专注于当前代码的实现细节（敲击键盘），领航员从更高视角审查逻辑、思考下一步与潜在问题；两人定期互换角色。价值在于实时评审、知识共享、减少缺陷、降低对关键人员的依赖。
- **代码集体所有权（Collective Code Ownership）**：任何团队成员都可以修改任何代码，不设“代码领主”。配以编码标准与充分的测试，集体所有权可避免瓶颈并加速交付。
- **编码标准（Coding Standards）**：全体遵守统一的命名、格式与编码约定，使代码风格一致、可读可维护，也是集体所有权能够成立的前提。
- **简单设计（Simple Design）**：只满足当前需求、消除重复、减少不必要的复杂性；设计保持“刚好够用”，待需求明确再演进。
- **重构（Refactoring）**：在不改变代码外部行为的前提下持续改进内部结构，消除重复、改善可读性。重构依赖测试提供保障，是TDD循环的必要一环。
- **小发布（Small Releases）**：频繁地发布小而完整的价值增量，让客户尽早使用、尽早反馈，缩短反馈周期、降低发布风险。
- **计划游戏（Planning Game）**：客户（业务方）对用户故事排序、设定优先级，团队评估工作量，双方共同把故事分配到迭代，实现“业务价值与开发能力”的平衡。
- **现场客户（On-site Customer）**：客户代表常驻团队，随时回答问题、明确需求优先级、参与验收，确保团队始终做“客户真正想要的”。
- **系统隐喻（System Metaphor）**：用团队共同熟悉的事物或比喻来描述系统架构，例如把系统比作“书店”“邮局”，使复杂架构对所有人都可理解、可讨论。
- **可持续节奏（Sustainable Pace）**：保持稳定、可长期维持的工作强度，避免长时间加班——长期透支会累积技术债与质量滑坡，反而降低整体效率。
- **验收测试驱动开发（ATDD）**：团队与干系人共同商定工作产品的验收标准，先写验收测试再实现功能，确保“做的是客户要的”。
- **行为驱动开发（BDD）**：从用户行为视角以“Given-When-Then”格式描述需求（如“当……时，那么……”），让非技术人员也能理解需求与测试。`,
      "⚖️ 与传统方法对比": `- **开发方式**：瀑布/预测型先完整设计、再集中编码、最后集中测试；XP以迭代为单位边设计、边编码、边测试，小步快跑。
- **需求管理**：瀑布依赖前期详尽的需求规格与严格变更控制；XP以现场客户、用户故事、计划游戏应对变化，欢迎需求演进。
- **质量保证**：瀑布常把测试放在阶段末尾；XP把测试前置（TDD、持续集成、结对评审），质量内建于开发过程。
- **风险应对**：瀑布后期才暴露集成与需求问题，返工成本高；XP通过小发布、持续集成、频繁反馈把风险分散到全过程。
- **适用场景**：瀑布适合需求稳定、可充分预见的项目；XP适合需求易变、技术风险高的中小型软件项目。需要说明，XP并非适用于一切场景——它的技术实践要求团队具备较高的工程纪律与能力。`,
      "📊 度量指标": `- **迭代速率（Velocity）**：每个迭代完成的用户故事点数，反映团队交付能力，用于计划游戏中的发布规划。
- **测试覆盖率（Test Coverage）**：被自动化测试覆盖的代码比例，是TDD与重构安全网的衡量。
- **测试通过率（Pass Rate）**：每次持续集成后自动化测试的通过比例，反映主干质量是否健康。
- **缺陷率与缺陷逃逸率（Defect Escape Rate）**：单位迭代发现的缺陷数，以及逃逸到生产环境的缺陷比例，衡量质量内建的效果。
- **交付周期与周期时间（Lead Time / Cycle Time）**：小发布要求缩短端到端交付时间，这两个指标用于验证发布节奏是否真正“小而频繁”。
- **客户参与度与反馈响应速度**：现场客户模式下，需求澄清与反馈的响应时长是衡量沟通与反馈机制是否有效的指标。`,
      "💼 实践案例": `一家创业公司开发移动支付App，需求几乎每周都在变。团队采用XP：产品经理作为“现场客户”驻场，随时澄清需求；开发采用TDD，通过红-绿-重构循环为每个故事建立测试；两人一组结对编程，驾驶员与领航员定期互换，资深与新手搭配实现知识传递。团队每天多次持续集成，自动化测试使主干始终处于可发布状态，每两周一次小发布让用户尽早试用并反馈。通过简单设计与定期重构，系统始终保持结构健康。该团队以约80%的测试覆盖率支撑起频繁变更，缺陷逃逸率显著低于同行业水平——XP的纪律性实践在需求动荡的环境中保证了交付的速度与质量。`,
    },
    keyConcepts: `- **XP的12大实践**：持续集成、测试驱动开发（TDD）、结对编程、代码集体所有权、编码标准、简单设计、重构、小发布、计划游戏、现场客户、系统隐喻、可持续节奏。
- **5大价值观**：沟通、简单、反馈、勇气、尊重。
- **TDD红-绿-重构**：先写失败测试（红）→写最少代码使其通过（绿）→在不改变外部行为前提下改进结构（重构）。
- **结对编程角色**：驾驶员负责当前实现细节，领航员负责整体视角审查与思考；定期互换。
- **持续集成**：频繁整合代码到主干并自动构建测试，尽早发现集成问题。
- **ATDD**：团队先共同定义验收标准并写验收测试，再开发功能，确保交付符合期望。
- **BDD**：以“Given-When-Then”格式从用户行为角度描述需求。
- **小发布**：频繁发布小而完整的增量，缩短反馈周期。
- **现场客户**：客户代表驻场实时反馈，确保做客户真正需要的。`,
    examTips: `- TDD口诀：先写测试再写代码，顺序是“红-绿-重构”；考题常问“哪项实践最先做”——先写失败的测试。
- 结对编程两角色：驾驶员（Driver）管实现细节、领航员（Navigator）管整体视角；二人是实时协作而非一人写一人旁观。
- 持续集成=频繁整合代码+自动化测试，目的是尽早发现集成问题，防止“集成地狱”。
- 12大实践常考核心：TDD、持续集成、结对编程、重构、小发布；其余了解即可。
- 5大价值观记忆口诀：沟通、简单、反馈、勇气、尊重。
- ATDD关注“验收标准”，BDD关注“行为描述（Given-When-Then）”，二者易混，注意区分。
- 注意适用性：XP的技术实践要求高工程纪律，并非适合所有团队或项目；题目问适用场景时，应结合需求多变、中小规模软件项目判断。`
  },
  "agile-lean": {
    overview: `【核心定义】精益（Lean）思想起源于20世纪中叶的丰田生产系统（Toyota Production System, TPS），其奠基人包括大野耐一等丰田工程师。精益的核心理念是“用更少的资源创造更多的客户价值，同时消除一切浪费”。精益最初应用于制造业，后被拓展到软件开发和项目管理领域，成为敏捷运动的重要思想源头之一——许多敏捷实践（小批量、持续流动、消除浪费、看板等）都直接源自精益理念。

精益把“价值”定义为“由客户定义、客户愿意为之付费的东西”。凡是不为价值作贡献的活动，都被视为浪费（Waste / Muda）。围绕这一思想，精益发展出七大浪费（TIMWOOD）与五大原则。精益项目管理的目标是：通过价值流分析识别增值与非增值活动，通过限制在制品（WIP）、建立拉动机制让工作顺畅流动，通过持续改进（Kaizen）不断逼近完美。

精益是一种管理哲学与思维方式，而不是具体的框架——Scrum、Kanban、看板方法等都是将精益理念落地的具体手段。在PMP语境下，理解精益有助于回答“为什么看板要限制WIP”“为什么强调小批量”“MVP为何有价值”等问题，是敏捷知识体系中的底层逻辑。`,
    details: {
      "🧩 核心要素": `- **运输（Transport）**：不必要的物料、产品或信息移动，如文件在多个部门间反复传递、代码在多人间反复转手。运输不创造价值，却消耗时间与资源，应尽量缩短传送路径。
- **库存（Inventory）**：超出即时需求的任何积压，如过多的工作队列、未完成的在制品（WIP）、大量待办项积压。库存占用资金、掩盖问题，还使缺陷更难及时发现。
- **动作（Motion）**：人员不必要的走动与操作，如寻找工具、在不同系统间重复录入、为找文件反复翻找。动作浪费消耗人力却无产出。
- **等待（Waiting）**：工作项在流程中空闲等待，如任务等待审查、信息等待决策、人员等待他人完成上游工作。等待直接延长交付周期。
- **过度加工（Over-processing）**：超出客户需求的额外工作或加工，如为不需要的环节添加不必要的功能、反复审核低风险变更、产出无人使用的报表。做得多不一定好，多余即浪费。
- **过度生产（Over-production）**：生产超出客户需求的数量或过早生产。它被称为“浪费之母”，因为过多产出会引发库存、运输、等待等一系列连锁浪费。
- **缺陷（Defects）**：因错误、返工、质量不达标造成的浪费。缺陷需要额外时间修复，并消耗检查与返工资源，是质量层面的根本浪费。`,
      "🔧 关键实践": `- **确定价值（Define Value）**：一切从客户视角出发，明确客户真正愿意为之付费的价值是什么，把它作为评判一切活动的标准。
- **价值流映射（Value Stream Mapping, VSM）**：绘制从需求到交付的端到端流程，标注每个步骤的增值与非增值属性、耗时、等待与库存点，据此识别并消除浪费。它是精益分析的核心工具。
- **创建流动（Create Flow）**：消除瓶颈与等待，使工作像水流一样持续流动。手段包括：减小批量、按工作顺序排列流程、平衡各环节负荷。
- **建立拉动（Establish Pull）**：由下游需求“拉动”上游生产，而非上游“推动”批量产出。下游何时要、何时取，上游就何时生产，从而杜绝提前过量生产。
- **追求完美（Pursue Perfection）**：通过持续改进（Kaizen）不断消除浪费、逼近理想状态，永不满足于现状。完美是方向而非终点。
- **单件流（Single-Piece Flow）**：一次只处理一个工作项并使其连续通过全部流程，是减少库存、加快反馈、暴露问题的最彻底方式；批量越大，等待与返工风险越高。
- **拉动系统 vs 推动系统**：推动（Push）系统按预测计划向下游批量交付，易造成过量生产与库存；拉动（Pull）系统按下游信号（如看板卡片、WIP限额）补充生产，只在被需要时才生产，从根本上抑制过度生产。看板方法即拉动系统的典型实现。
- **Kaizen（改善/持续改进）**：全员参与的小步持续改进活动，强调“每天进步一点点”，通过频繁小改（如回顾会的改进项）累积成系统级提升，而非一次性大变革。
- **MVP（最小可行产品，Minimum Viable Product）**：以最低成本构建一个包含核心价值、足以让客户使用并获得真实反馈的产品版本，尽早验证假设、避免在错误方向上投入过多。MVP是精益“尽早交付价值、快速学习”理念在软件开发中的体现。`,
      "⚖️ 与传统方法对比": `- **生产逻辑**：传统批量生产按预测推动、大批量、重库存；精益按需求拉动、小批量或单件流、以零库存为目标。
- **价值视角**：传统以企业内部效率为中心；精益以客户定义的价值为中心，凡不增值皆为浪费。
- **对浪费的态度**：传统把库存看作资产、把满负荷生产看作效率；精益把库存与过度生产视为最大的浪费。
- **改进方式**：传统靠管理者主导的大规模变革；精益靠全员参与的持续小步改进（Kaizen）。
- **与敏捷的关系**：精益是思想源头，Scrum与Kanban是落地手段；精益聚焦“消除浪费、优化价值流”，敏捷聚焦“拥抱变化、快速交付”，二者互补。`,
      "📊 度量指标": `- **利特尔法则（Little's Law）**：周期时间=在制品数量÷吞吐率（CT=WIP÷Throughput）。这是精益/看板最核心的定量关系：限制WIP即可直接缩短交付周期；也可反推“要保持交付周期不超标，WIP应控制在多少”。
- **在制品（WIP）**：流程中正在处理的工作项数量。WIP过高是库存浪费的体现，是拉动系统最直接的管控对象。
- **吞吐率（Throughput）**：单位时间完成的工作项数量，反映流程产能。
- **交付周期（Lead Time）/ 周期时间（Cycle Time）**：端到端总时长与纯处理时长，反映流动顺畅程度。
- **增值时间占比（Flow Efficiency）**：处理时间÷交付周期，占比越高说明等待浪费越少。
- **一次性合格率与缺陷率**：衡量缺陷浪费的改善效果。`,
      "💼 实践案例": `一家电商公司的客服工单团队长期交付缓慢。通过价值流映射（VSM），团队发现从“客户提交工单”到“问题解决”的12个环节中，真正增值的时间占比仅约30%，其余都是等待与反复确认。团队首先应用拉动系统：在客服看板上为每个阶段设置WIP限额，工单按下游领取而非批量派发；接着缩小批次，将批量处理改为单件处理，让工单连续流动。两个迭代后，团队用利特尔法则验证改善效果：平均WIP从40件降至15件，吞吐率从每天5件提升到8件，则平均交付周期由8天缩短到约1.9天。同时，团队定期开展Kaizen回顾，持续消除剩余浪费。整个改善过程完全遵循“价值流分析→消除浪费→建立拉动→持续改进”的精益路径。`,
    },
    keyConcepts: `- **精益（Lean）**：源自丰田生产系统的管理哲学，目标是用更少的资源创造更多客户价值并消除浪费。
- **七大浪费（TIMWOOD）**：运输、库存、动作、等待、过度加工、过度生产、缺陷。
- **五大原则**：确定价值→价值流映射→创建流动→建立拉动→追求完美。
- **价值流映射（VSM）**：端到端流程分析工具，识别增值与非增值步骤。
- **单件流**：一次处理一个工作项，减少库存与等待，最彻底地暴露问题。
- **拉动 vs 推动**：拉动按下游需求生产，推动按预测批量生产；拉动抑制过度生产。
- **Kaizen（改善）**：全员参与的小步持续改进。
- **MVP（最小可行产品）**：以最低成本验证核心假设、尽早获取真实反馈。
- **利特尔法则**：周期时间=WIP÷吞吐率，限制WIP可缩短交付周期。
- **看板方法**：在知识工作中应用精益理念的主要框架，核心是可视化工作流、限制WIP、管理工作流。`,
    examTips: `- TIMWOOD七浪费必须背熟：Transport（运输）、Inventory（库存）、Motion（动作）、Waiting（等待）、Over-processing（过度加工）、Over-production（过度生产）、Defects（缺陷）；考题常给场景问“属于哪种浪费”，如“文件反复转手”=运输，“任务排队等待”=等待，“为不需要的功能增加复杂度”=过度加工。
- 五大原则的顺序：价值→价值流→流动→拉动→完美（Value→Value Stream→Flow→Pull→Perfection）。
- 利特尔法则：周期时间=WIP÷吞吐率，常考“限制WIP可缩短交付时间”的推导。
- 拉动vs推动：拉动=下游要才产（看板、JIT）；推动=按计划批量生产。
- 精益是哲学而非框架：Scrum、Kanban是实现手段——这是常见辨析题。
- MVP关键词：低成本、验证假设、快速反馈，是精益“尽早交付价值”的体现。
- 价值流映射的核心目标是区分“增值活动”与“非增值活动”。`
  },
  "agile-estimation": {
    overview: `敏捷估算（Agile Estimation）是团队对产品待办事项列表中各工作项「大小」进行相对估计的过程。其核心认知基础是：人在判断「相对大小」时比判断「绝对大小」更准确——比较两块石头哪块更重，比报出每块的公斤数更容易且误差更小。因此敏捷估算使用故事点（Story Points）这类相对单位，而非人天、小时等时间单位来表达工作规模。

敏捷估算由谁来做？答案是真正执行工作的团队——跨职能开发团队集体估算。只有实际动手的人最了解某项工作的复杂度、所需技能、涉及的风险与历史经验，因此「由执行团队共同估算」是敏捷估算的基石。产品负责人（PO）提供需求背景、解答疑问并参与优先级排序，但不代表团队给出估算值；项目经理或敏捷教练也不越俎代庖。这与传统预测型方法中的类比估算（拿历史项目类比）、参数估算（单位费率乘以数量）形成鲜明对比：后者通常由项目经理或估算专家在项目早期一次性完成，依赖历史数据库与参数模型，追求绝对数值；前者是团队协作、随待办列表精化持续更新的相对判断。

敏捷估算服务于两个目的：一是预测交付能力——用每个迭代完成的点数（速率Velocity）推算剩余工作还需要几个迭代；二是促进讨论与共识——估算中的「为什么是8不是3」对话常暴露需求盲点与隐含风险。它不追求精确的时间预测，而是追求在不确定性下做出足够好的相对判断，并随信息增加持续修正。`,
    details: {
      "🧩 核心要素": `- **故事点（Story Points）**：相对大小单位。一个故事点代表「团队内一份标准工作量」，所有工作项都与这份基准比较。它是三个维度综合的体现——工作量（做这件事要花多少功夫）、复杂性（技术上多难解决）与风险或不确定性（有多少未知因素）。故事点不是时间单位，不能简单折算为「1点=1天」。
- **相对估算原则**：不追求绝对精度，只追求相对次序正确——「功能A比功能B大2倍」这一判断，比「功能A要13天」更可靠。相对判断受团队经验与个体差异的影响较小，结果更稳定、更可复用。
- **估算单位选择**：故事点为主流；也可用理想时间（无干扰、专注工作的净时间）作为补充；T恤尺码等粗略单位用于早期。日历时间（实际时间）受会议、上下文切换、中断等变量影响大，不适合直接作为估算基准。
- **执行团队共同估算**：估算由自组织的执行团队集体完成，吸收开发、测试、设计等不同角色的视角，避免单人盲区；产品负责人不主导估算数值。
- **基准故事点校准（Baseline Story Point）**：团队先共同选定一个「大小适中、理解一致」的工作项作为基准故事并赋予点数（如8点），其他工作项都相对它来定大小——这保证了估算的一致性，尤其对新加入团队的成员是重要参照，也是「校准（Calibration）」一词的含义。
- **斐波那契序列（1/2/3/5/8/13/20/40/100）**：故事点的常用刻度。相邻数字差距随数值增大而增大，反映「越大越模糊、越不确定」的认知——小功能可自信报3点，史诗（Epic）只能模糊报40或100。序列刻意避开2、4、6、8等差数列，防止团队陷入「精确性幻觉」。`,
      "🔧 关键实践": `- **Planning Poker（计划扑克/规划扑克）**：德尔菲技术（Delphi Technique）的变体，是最著名的敏捷估算实践。完整流程：①团队每人持一套斐波那契扑克牌；②产品负责人或需求人朗读一个工作项并解答疑问；③成员各自思考后同时亮牌——同时亮牌保证独立判断、不受他人影响；④若牌面出现较大分歧，亮出最高值与最低值的两人分别解释理由（通常最高值是因为发现了被忽视的复杂性或风险，最低值是因为认为可复用已有方案）；⑤全员讨论后再重新出牌；⑥重复「亮牌-讨论-重投」直到意见收敛趋近一致（相同或相邻两档），记录最终点数。过程中，「同时亮牌」才能揭示真实分歧，是收敛的关键机制。
- **T恤尺码（T-Shirt Sizing）**：用XS/S/M/L/XL（可选XXL）粗略划分工作大小，不追求点数精度。适用于需求还很粗略、信息不足的早期阶段（如对史诗级条目做初步分层），后期可映射为具体故事点区间（如S=3、M=5、L=8）。优点是快速、低认知负荷；缺点是粒度粗、不便于直接做发布规划，通常作为「先分层、后精算」的过渡手段。
- **亲和估算（Affinity Estimation）**：把大量工作项「相对彼此」排列分组到预先设定的尺码桶中，一次性完成批量估算。操作上可以把纸卡式用户故事按大小聚类到S/M/L等分组，或先在白板上摆成一条序列再切分成档位。适用场景：待办列表条目非常多（几十上百个）、需要快速建立全局大小观感、或在项目启动时对史诗做初步分层。它牺牲精度换取速度，适合「先铺开再精修」。
- **待办列表精化中的估算**：估算不是一次性活动，而是随待办事项列表精化（Backlog Refinement）持续进行——条目被拆分、细化、补充验收标准后团队重新估算；通常每个迭代安排约5%-10%的时间做精化与重估。
- **基准校准与新人融入**：每次估算前可先快速对齐「基准故事」是多少点，帮助新成员与老团队建立共同的相对尺度；跨团队协作时也可约定共同基准，但通常不建议跨团队直接比较点数。
- **估算产出与记录**：估算结果记录在产品待办事项列表的每个条目上，并随精化更新；估算值用于统计速率、绘制燃尽/燃起图与发布规划。
- **重估触发条件**：需求理解发生重大变化、条目被拆分或合并、技术方案改变时，应重新估算该条目，而不是死守旧值。`,
      "⚖️ 与传统方法对比": `- **类比估算（Analogous Estimation）**：用历史项目中「类似工作项」的实际数据推算本项大小，依赖历史数据库与项目相似性；而敏捷故事点靠团队内部相对判断，不依赖外部历史数据，更适合没有历史数据可参考的全新产品。
- **参数估算（Parametric Estimation）**：用单位费率乘以数量（如每人月乘以代码行或功能点）计算，需要可量化的参数与统计关系；敏捷估算以团队讨论的方式对不确定性建模，不假设线性的参数关系。
- **三点估算（PERT）**：对单项给出乐观、最可能、悲观三个时间估计并加权平均，仍属于「预测型、面向时间、专家单点」的思路；敏捷用非线性尺码与共识讨论来吸收不确定性，而非计算加权平均。
- **谁在估算**：传统常由项目经理或估算专家单方完成；敏捷由执行团队集体估算，吸收多角色视角。
- **何时估算**：传统在项目早期一次性做完整估算（自上而下的WBS）；敏捷随待办精化滚动估算，越临近越细化。
- **用什么单位**：传统以时间（人天、人时、人月）与货币为主；敏捷以故事点等相对单位为辅，再结合速率换算时间。
- **追求什么目标**：传统追求「绝对准确」的承诺数字；敏捷接受「相对正确+持续修正」，把精确留给未来信息更充分的时刻，避免过早承诺带来返工与博弈。`,
      "📊 度量指标": `- **速率（Velocity）**：团队在每个迭代（冲刺）中「完成」的故事点总数，是敏捷最核心的度量。只有满足完成定义（DoD）的工作才计入速率。速率需要约4-8个迭代（2-3个月）才趋于稳定，之后才可作为发布预测的依据；早期速率波动大，不宜过早外推。
- **剩余故事点（Remaining Story Points）**：产品待办中尚未完成的故事点总和，是发布规划的基础数据。
- **发布规划计算**：所需迭代数 = 剩余故事点 ÷ 每迭代平均速率。示例：产品待办还剩120点，团队平均速率30点/迭代，则预计还需 120÷30=4 个迭代完成；可叠加风险缓冲（如增加1-2个迭代的应急时间）。
- **燃尽图（Burn-down Chart）**：显示剩余工作量随时间下降的曲线，用于迭代内与发布层面的进度监控。
- **燃起图（Burn-up Chart）**：显示已交付点数累计上升的曲线，与总范围线对比可看出范围增长对交付的影响。
- **每迭代平均故事点**：取近3-5个迭代的均值作为稳定速率，比单次值更可靠。
- **注意**：速率用于预测与团队自省，不用于团队间比较或考核——每个团队的点数尺度（什么样的活算1点）不同，跨团队比速率为无意义操作。`,
      "💼 实践案例": `某移动应用开发团队（8人Scrum团队）在新产品启动时使用敏捷估算：
- 项目初期，团队先选定一个中等难度的用户故事「登录功能」作为基准故事，共同评估为8点（工作量适中、含3种登录方式、涉及外部认证服务的不确定性）。
- 对产品待办中的100多个史诗与故事，先用T恤尺码快速分层（XS/S/M/L/XL），把同类尺码的工作归组；再用亲和估算把大量条目一次性聚类到各尺码桶中，快速建立全局大小观感。
- 对进入近期冲刺的高优先级条目，召开Planning Poker：产品负责人朗读「支付功能」故事并解答疑问；团队亮牌出现3/5/8的分歧，最高分者解释「涉及第三方支付合规审计，存在政策不确定性」，最低分者解释「可复用团队已完成的支付SDK」；讨论后重投收敛为5点。这次讨论还暴露了一个此前未考虑的安全合规风险，产品负责人将其加入待办。
- 经过4-8个迭代，团队速率稳定在30点/迭代。此时产品待办剩余120点，团队据此预测还需120÷30=4个迭代可完成剩余全部功能，并在发布规划中预留1个迭代作为缓冲。
- 迭代中，燃尽图显示某迭代剩余点数不降反升，站会中团队发现接口联调受阻，敏捷教练协调解决后曲线恢复正常；某条需求范围大幅扩大，团队重新估算该故事点数并更新待办。
最终团队提前验证了「登录+支付+个人中心」等核心价值并按期发布，估算-速率-发布规划的闭环运转顺畅。`,
    },
    keyConcepts: `关键术语——
- **故事点（Story Points）**：相对大小单位，综合工作量+复杂性+风险，不是时间单位。
- **相对估算**：比较相对大小而非绝对数值，是敏捷估算的认识论基础。
- **基准故事点（Baseline Story Point）**：团队选定的校准参照（如8点），保证估算一致性。
- **斐波那契序列**：1/2/3/5/8/13/20/40/100，非线性刻度反映不确定性递增、避免精确性幻觉。
- **Planning Poker**：德尔菲技术变体，同时亮牌→分歧者发言→讨论→重投→收敛。
- **T恤尺码（T-Shirt Sizing）**：XS~XL粗略分层，用于早期快速估算。
- **亲和估算（Affinity Estimation）**：大量条目相对彼此聚类，批量快速估算。
- **速率（Velocity）**：每个迭代完成的故事点总数，4-8个迭代后趋于稳定，用于预测。
- **发布规划**：剩余故事点÷每迭代平均速率=剩余迭代数。
- **理想时间 vs 实际时间**：理想时间=无干扰的专注工作时间，敏捷倾向使用；实际时间含会议、上下文切换、中断，变量多不稳定。`,
    examTips: `考试重点/常见陷阱——
- **估算主体**：问「谁做敏捷估算」→执行团队共同估算，不是项目经理或产品负责人单独定值；产品负责人提供需求与优先级，不主导估算。
- **故事点≠时间**：经典陷阱。故事点反映相对大小（工作量+复杂度+风险），不能简单折算为「1点=1天」；如需换算成时间，须结合速率。
- **Planning Poker流程**：同时亮牌→最大分歧者发言→讨论→重投→趋近一致。「同时亮牌防止跟风、保证独立判断」是常考点。
- **斐波那契的意义**：非线性序列避免精确性幻觉；相邻档差距随值增大而增大，反映「越大越不确定」。
- **不跨团队比较速率**：每个团队的基准与点数尺度不同，比速率无意义；速率用于自省与预测，不用于考核。
- **速率稳定前提**：需要4-8个迭代后才稳定，之前不宜作为发布预测依据。
- **发布规划计算**：会用「剩余故事点÷速率=迭代数」做算术题（如120点÷30=4个冲刺）。
- **理想时间vs实际时间**：敏捷倾向用理想时间或故事点规划，因为实际时间受会议、中断等变量影响。
- **与传统估算区别**：类比/参数估算靠历史数据与参数模型、由专家在早期完成；敏捷靠团队相对判断、持续更新，这是对比题的区分点。`
  },
  "agile-risk": {
    overview: `敏捷环境中的风险管理不是一次性的、文档驱动的「前期活动」，而是嵌入每个迭代的持续实践。与传统「识别→分析→规划应对→实施→监督」的线性流程不同，敏捷把风险管理融入日常工作节奏：通过频繁交付小增量、短反馈回路和集体仪式，把风险敞口压缩在很小的窗口内。

其根本逻辑是「渐进式风险降低（Progressive Risk Reduction）」：每1-4周交付一个可工作的增量，快速获得真实反馈，使错误在小范围内及时被发现和纠正——即使某次迭代方向错了，损失也被时间盒限制在1-4周内，避免「大爆炸式」的最终失败。产品风险（做错了东西）、技术风险（不知道怎么做）、过程风险（流程有缺陷）、市场风险（需求变了）都通过频繁交付与反馈被提前暴露、提前消化。

敏捷风险管理的主要载体包括：每日站会识别阻碍（Impediments）——阻碍是风险的早期信号；迭代评审（Sprint Review）让干系人看到可用成果并反馈，及早发现期望偏差；迭代回顾（Retrospective）反思过程层面的风险与改进机会；基于风险的刺探（Spike）专门探索未知技术，降低技术不确定性；风险燃尽图（Risk Burn-down Chart）跟踪风险敞口的下降趋势；信息发射源（Information Radiators）让风险可视化；风险还可以作为待办列表中的工作项，与功能一样被估算、排序和完成。敏捷风险管理并未抛弃风险管理的底层逻辑，而是以更轻量、更即时、更贴近执行的方式践行「识别→分析→应对→监督」的闭环。`,
    details: {
      "🧩 核心要素": `- **渐进式风险降低**：敏捷通过频繁、小批量交付，把风险敞口限制在小时间窗内。风险不是「一次消除」，而是随每个迭代的交付、反馈与验证逐步下降。
- **阻碍（Impediments/障碍）**：任何妨碍团队推进冲刺目标的事项（环境问题、依赖延误、资源缺口、需求不清等）。阻碍是风险的早期信号——每日站会中团队成员主动报告阻碍，敏捷教练（SM）负责消除或升级。「把阻碍当作风险预警信号」是敏捷风险管理的核心习惯。
- **基于风险的刺探（Spike）**：时间盒（Time-box）限定的技术探索活动，专门用于回答「这个技术方案能不能行」「这个集成接口怎么设计」等未知问题。Spike的产出通常是研究结论、决策建议或概念验证原型，而非可交付的产品功能；它把「技术不确定性」这个风险提前消化，为后续正常迭代的规划提供依据。
- **风险作为待办列表工作项**：风险可以转化为「风险故事」或专门的储备任务放入产品待办事项列表，与功能条目一样被估算、排序、排入迭代。例如「完成支付接口的可用性验证」本身就是一条风险缓解工作项，确保风险应对真正被执行而非停留在文档上。
- **信息发射源（Information Radiators）**：以白板或电子看板张贴、让信息「自动发射」给所有路过的人的可视化工具——燃尽图、看板面板、风险登记表等。它不同于「信息制冷器」（只在需要时才去查的数据库），强调被动可见、人人可见、实时更新。
- **风险储备与缓冲**：在发布规划中预留时间或预算缓冲（如增加1-2个迭代或固定比例预算）以吸收不确定性；也可在待办列表中保留专门的「风险储备工作项」。
- **风险调整的待办排序**：将高风险的工作项提前排入早期迭代——「先啃硬骨头」。越早做，越早验证假设、越早暴露问题、风险敞口越小；把高风险项拖到后期，等于把风险爆发点集中到交付末端。
- **快速失败（Fail Fast）**：在低成本窗口期快速测试假设，若失败则以小代价学习。失败的实验不被视为浪费，而是「学习投资」。`,
      "🔧 关键实践": `- **每日站会识别阻碍**：15分钟同步中，每个成员汇报「昨天做了什么、今天做什么、有什么阻碍」。阻碍登记后由敏捷教练协调解决；重大阻碍升级为风险或问题并进入风险跟踪。这是频率最高的风险侦测机制。
- **迭代评审（Sprint Review）**：冲刺结束时向干系人演示可工作的增量，获取真实反馈，及早发现「做错了方向」的产品风险；干系人反馈还能揭示市场变化、期望偏差等新风险。
- **迭代回顾（Retrospective）**：团队反思「过程哪里可以改进」，把过程层面的风险（测试不足、沟通不畅、技术债累积）转化为改进措施并纳入下一迭代。回顾是「持续改进」的引擎，也是过程风险的出口。
- **基于风险的刺探（Spike）**：当技术不确定性阻塞规划时，安排一个时间盒受限的探索任务（如1-3天）。Spike开始时明确目标与时间盒，结束时产出决策建议，不追求完整产品功能。典型例子：集成未知第三方API前先做一个原型验证。
- **风险燃尽图（Risk Burn-down Chart）**：纵轴为「剩余风险敞口」，横轴为时间（迭代）。团队把已识别风险按其概率乘以影响的综合评分（风险敞口）列表化，每个迭代结束后重新评估并更新分值，将总分连成下降曲线。曲线下降表明风险管理有效；若停滞或上升，说明需要加强应对或新风险正在积聚。
- **风险待办与优先级排序**：把风险映射为待办工作项（预防措施、验证任务、储备缓冲），并据此调整功能排序——高风险故事提前做，同时安排应对措施条目，保证风险缓解真正「做了」而不是「写了」。
- **测试驱动开发与持续集成**：TDD、结对编程、持续集成等工程实践本身就是技术风险的预防手段——频繁集成让小冲突及时暴露，自动化测试让回归风险可控。
- **发布与迭代缓冲规划**：在发布计划中预留缓冲迭代，把「残余不确定性」显式计入计划，而不是假装没有风险。
- **快速失败实验设计**：为高风险假设设计低成本的小实验（原型、A/B测试、概念验证），在小窗口内验证，失败则快速转向。`,
      "⚖️ 与传统方法对比": `- **时机**：传统风险管理集中于项目前期（规划阶段一次性识别分析），后续通过定期评审更新；敏捷将风险管理嵌入每个迭代的日常节奏，持续发生。
- **载体**：传统用正式风险登记册、风险评审会与风险审计；敏捷用站会、评审、回顾、看板、信息发射源等轻量载体，文档最小化。
- **应对方式**：传统把应对措施写进计划、等触发条件满足再执行；敏捷把风险转成待办工作项，直接排入迭代「做掉」，例如用Spike消除技术不确定性。
- **风险数据**：传统强调概率/影响矩阵、期望货币值等量化分析；敏捷更强调相对排序（高/中/低）与可视化跟踪（燃尽图、看板），量化程度较低但更即时。
- **风险暴露窗口**：传统风险敞口在长周期内累积，风险在项目后期集中暴露；敏捷通过频繁交付把风险敞口限制在1-4周内。
- **对失败的态度**：传统把失败视为应避免的事件；敏捷把早期失败视为学习投资（快速失败），以低成本换取信息。
- **风险责任人**：传统设风险所有者（Risk Owner）负责单项风险；敏捷整个团队共同对风险负责，敏捷教练负责扫除障碍。
- **两者共通**：都遵循「识别→分析→应对→监督」的底层逻辑，只是节奏与形式不同。`,
      "📊 度量指标": `- **风险燃尽图（Risk Burn-down Chart）**：跟踪「剩余风险敞口」随时间的下降趋势；每个迭代重估概率与影响、更新总分。
- **风险敞口（Risk Exposure）**：通常以概率乘以影响的综合评分表示单个风险；将所有风险的评分加总可得整体敞口，是风险燃尽图的纵轴数据。
- **阻碍数量与解决时长**：每日站会记录阻碍；阻碍累积数量与平均解决周期反映风险侦测与清除效率。
- **刺探（Spike）投入与产出**：Spike数量、时间盒遵守情况、Spike后技术不确定性的下降程度。
- **迭代燃尽/燃起图**：进度维度的风险信号——剩余工作不降反升往往预示范围蔓延或技术受阻。
- **缺陷逃逸率**：发布后发现的缺陷比例，衡量质量风险是否被控制在测试阶段之前。
- **干系人反馈频率与满意度**：迭代评审的参与度与反馈质量，衡量产品/市场风险是否被及时捕获。
- **信息发射源的更新即时性**：看板与风险表是否实时反映最新状态，反映透明这一支柱的落地程度。`,
      "💼 实践案例": `某金融科技团队开发一款新的移动支付App，采用Scrum并结合看板管理风险：
- 项目启动时，团队识别出五大风险：第三方支付合规政策不明（高）、核心加密算法性能不达标（高）、接口集成依赖外部厂商延误（中）、需求频繁变更（中）、团队缺少iOS经验（低），并把它们登记为待办列表中的风险工作项，同时为发布计划预留1个缓冲迭代。
- 对「加密算法性能不达标」，团队安排一个2天的Spike：在时间盒内做加密算法原型并压测，结论是「现有算法不可行、需更换方案」，并产出替换方案评估报告——技术不确定性被提前消化，后续迭代据此规划。
- 对「第三方合规政策不明」，产品负责人牵头与合规部门开展一次Spike式研究并提前排入首迭代，验证通过后才大规模开发，避免做错方向。
- 每个冲刺评审会上，团队向干系人演示增量；客户反馈「支付流程太繁琐」，这暴露了产品风险，产品负责人据此调整待办优先级并增加简化流程的功能故事。
- 团队维护风险燃尽图：每次冲刺结束重新评估五类风险的概率与影响，更新风险敞口总分并连线。第4个冲刺后曲线明显下降；第6个冲刺因外部厂商接口延误，风险敞口小幅回升，站会中敏捷教练及时协调并申请了补偿时间。
- 每日站会中，测试工程师报告「回归测试环境不稳定」的阻碍，敏捷教练当天排查解决，避免其升级为延误风险。
最终App按期发布，核心风险均在早期迭代被验证与消化，风险燃尽曲线持续下行。`,
    },
    keyConcepts: `关键术语——
- **渐进式风险降低**：通过频繁交付把风险敞口限制在小时间窗内，风险随迭代逐步下降。
- **阻碍（Impediments）**：妨碍冲刺推进的事项，是风险的早期信号，站会识别、敏捷教练清除。
- **基于风险的刺探（Spike）**：时间盒限定的技术探索，产出决策建议或原型，而非产品功能。
- **风险燃尽图（Risk Burn-down Chart）**：跟踪剩余风险敞口随时间下降的曲线。
- **信息发射源（Information Radiators）**：被动可见、人人可见、实时更新的可视化工具（燃尽图、看板、风险表）。
- **风险作为待办工作项**：风险转成可估算、可排序、可排入迭代的工作条目，确保应对被真正执行。
- **风险调整的待办排序**：高风险故事提前做，「先啃硬骨头」。
- **快速失败（Fail Fast）**：在低成本窗口期验证假设，失败也是学习投资。
- **时间盒（Time-box）**：为Spike等活动设定的固定时长上限。`,
    examTips: `考试重点/常见陷阱——
- **Spike vs 常规工作**：刺探是时间盒限定的技术探索，产出研究结论或原型，不是交付功能；考试把「Spike」与「常规迭代开发」区分开是重要区分点。
- **高风险项提前做**：情景题「技术不确定性高/风险高，如何排序待办」→把高风险故事排到早期迭代，先验证假设；不要选「推迟高风险项」。
- **快速失败≠真正的失败**：敏捷把早期小成本失败视为「学习投资」，选项出现「失败是浪费」→错误；「快速失败以获取信息」→正确。
- **信息发射源**：识别「燃尽图、看板面板、风险登记表」属于信息发射源；「只在需要时才去查的数据库」属于信息制冷器，后者不被提倡。
- **风险燃尽图**：纵轴是剩余风险敞口（概率乘以影响的总和），随时间下降；题目可能给曲线让判断「风险管理是否有效」。
- **站会识别阻碍**：阻碍在每日站会暴露，敏捷教练负责清除；「把阻碍当作风险预警」是核心习惯。
- **风险=待办工作项**：风险可以作为故事或储备任务进入产品待办列表，与功能一样排序，这是敏捷「把风险管理落到执行」的关键。
- **与传统区别**：传统前期集中、文档驱动；敏捷嵌入迭代、轻量持续。题问「敏捷环境如何做风险管理」→选嵌入迭代/频繁交付/Spike/风险燃尽图相关选项。
- **与PMBOK风险流程的联系**：底层仍符合识别→分析→应对→监督，只是以敏捷节奏执行。`
  },
  "agile-contracts": {
    overview: `敏捷与采购合同的交汇处充满张力：传统固定总价（FP）合同锁定范围、以符合书面规格为付款依据，与敏捷「拥抱变更、增量交付」的理念根本冲突。敏捷合同（Agile Contracts）探索的是：如何设计一种采购关系，让买卖双方从「对抗性」转向「协作式」，共同对项目成果负责。

敏捷合同的核心思想：合同不应锁定「如何做」，而应围绕「交付什么价值」与「如何分担不确定性」来设计。敏捷项目需求不确定性高、范围会演进，因此付款与验收标准须与「成果（Outcome）」绑定而非「输出（Output）」——付款看的是实现的业务价值，而非交付的文档或代码行数；变更不再走正式合同变更流程，而是通过调整产品待办事项列表的优先级来吸收。

常见的敏捷合同模式：目标成本加激励酬金合同约定目标成本，节余或超支按约定比例分享或分担，激励双方共同控制成本；分阶段合同（Phased Contracts）在初始阶段只定义一部分范围，后续阶段根据已验证的学习与新信息逐步扩围，双方保留退出或重谈权利；时间与材料合同（T&M）按实际投入计费，适合高度不确定、难以事先定价的探索型工作；增量交付合同（Incrementally Delivered Contracts）按「交付的成果价值」而非「符合书面规范」测量并付款，每个增量验收合格即付款。敏捷合同还有四个关键原则：关注成果而非输出；变更通过待办列表管理；共享风险与奖励；把供应商当作团队成员。`,
    details: {
      "🧩 核心要素": `- **目标成本加激励酬金（Target Cost + Incentive Fee）**：买卖双方事先约定一个「目标成本」，实际成本低于目标（节余）时，按约定比例（如60/40）把节余分享给卖方作为奖励；实际成本超支时，也按比例分担超支。激励结构让买卖双方利益一致，共同致力于控制成本、提高效率。它属于成本补偿合同加激励条款的变体，买方承担部分成本风险，但激励酬金机制降低了「成本无上限」的失控风险。
- **分阶段合同（Phased/Staged Contracts）**：把合同拆成若干阶段，初始阶段只定义明确的部分范围并定价，后续阶段根据已验证的学习、市场变化与新信息再决定是否继续、如何调整，双方有权退出或重新谈判。它把「重新谈判」内建于合同而非视为违约，非常适合需求持续演进的项目。
- **时间与材料（Time & Materials，T&M）**：按实际投入的人工/材料单价乘以用量结算。买方承担数量风险，卖方承担单价风险，适用于范围模糊、难以事先定价的工作；缺点是缺乏成本上限激励，需配合预算上限、里程碑验收与透明度约束。
- **增量交付合同（Incremental Delivery Contract）**：工作被拆成多个增量，每个增量交付并验收后即付款；付款与验收依据「增量实现了多少业务价值、满足哪些验收标准」，而非「符合厚厚一本书面规范」。它让资金流与价值流同步，鼓励尽早交付可用成果。
- **买方/卖方风险分配**：不同合同类型把成本、范围与绩效风险在买卖双方之间分配——FP合同买方风险低、卖方风险高（范围锁定后超支由卖方承担）；T&M买方风险高（成本不限）、卖方风险低；目标成本加激励合同双方共担成本风险、共享收益。敏捷合同设计的关键是「让承担风险的一方有能力控制该风险」。
- **成果vs输出**：付款与验收的基准是成果（实现的业务价值、可工作的功能），而非输出（文档、工时、代码行）。这是敏捷合同区别于传统合同的最核心价值取向。
- **供应商纳入团队**：把外部供应商当作项目团队的一员——共同参加站会、规划、评审与回顾，共享信息发射源与待办列表，保持透明协作，而非仅在里程碑节点做「交接-验收」。`,
      "🔧 关键实践": `- **面向价值的付款计划**：把付款节点绑定到「增量交付与验收」，而非时间里程碑或文档提交；每个增量的付款金额与其业务价值挂钩。
- **验收标准前置并共同定义**：买卖双方在合同或工作说明书中共同定义每个增量的验收标准（验收条件），避免事后争论「什么叫完成」；这与敏捷的完成定义（DoD）与验收标准（AC）思想一致。
- **待办事项列表驱动变更**：范围变更不触发合同变更流程，而是通过产品负责人在待办列表中的优先级调整实现；合同约定「范围允许在交付的总价值内演进」，把变更机制内建于合同。
- **预算与范围锚点**：即使敏捷也不可无预算——约定一个预算上限（或价格上限），在预算内优先交付最高价值项；若预算耗尽仍未完成全部范围，则交付已完成的价值最高的增量（范围收缩而非预算超支）。
- **激励设计**：激励与成果绑定（如按时交付达标增量、用户满意度、缺陷率），而非奖励「多写代码」或「早报工时」。
- **透明与联合治理**：卖方开放工作进度（燃尽图、看板、每日状态），买方提供及时反馈；举行联合评审会、联合冲刺评审，共享受益与代价。
- **分阶段规划与重谈机制**：每阶段末设「继续/调整/终止」的检查点，依据已验证学习决定后续阶段的范围、价格与优先级；把「重新谈判」正常化。
- **混合场景合同组合**：同一项目中，硬件/合规部分用传统合同（如FP、固定总价加激励），软件/高不确定性部分用T&M或增量合同，形成「预测采购+敏捷采购」的混合组合。
- **供应商能力评估与团队融合**：选择供应商时不仅看报价，还要评估其敏捷协作能力；签约后尽快把供应商团队融入开发团队流程（共同站会、评审）。
- **风险共担条款**：把重大风险的识别与应对写进合同（如技术不确定性高的部分先用Spike验证再定价），明确双方在风险应对中的责任分担。`,
      "⚖️ 与传统方法对比": `- **合同本质**：传统合同以「符合书面规格/交付物清单」为履约标准，变更走正式合同变更流程；敏捷合同以「实现业务成果/可工作增量」为标准，变更通过待办列表优先级吸收。
- **买卖双方关系**：传统多为对抗性——各自追求条款利益最大化、在验收时刻争论；敏捷合同追求协作式——共同对成果负责、透明共享信息。
- **风险分配**：FP把成本与范围风险压给卖方（买方低风险），T&M把成本风险给买方（买方高风险）；目标成本加激励双方共担共享；敏捷强调「风险由有能力控制的一方承担」。
- **付款依据**：传统按交付物、里程碑或文档付款；敏捷按增量价值与验收结果付款。
- **变更处理**：传统变更是例外、须走审批；敏捷变更是常态、通过待办排序随时吸收。
- **供应商定位**：传统视供应商为外部承包商、里程碑交接；敏捷把供应商纳入团队、共同工作、共享信息。
- **合同灵活性**：传统合同希望一次把范围、价格、时间锁死；敏捷合同（分阶段、T&M）接受不确定性，把灵活机制（重谈、退出、预算上限内收缩范围）写入合同。
- **适用情境**：传统合同适合需求确定、变更成本高、合规严格的项目（基建、采购）；敏捷合同适合需求模糊、技术不确定、需要快速迭代的产品开发。`,
      "📊 度量指标": `- **成本绩效**：实际成本与目标成本的偏差，是目标成本加激励合同的奖励/惩罚计算基础；挣值管理指标（CV/CPI）适用于有预算基线的部分。
- **交付价值比例**：已交付增量所实现的业务价值占合同总价值目标的比例，衡量「面向成果」是否达成。
- **增量验收通过率**：交付的增量中一次通过验收的比例，反映需求理解与协作质量。
- **变更处理效率**：通过待办列表吸收的需求变更数量与平均响应时间——敏捷合同中变更不应被合同流程阻塞。
- **激励/惩罚结算**：按约定公式计算的激励酬金或成本分担金额，验证激励机制的激励效果。
- **供应商协作指标**：供应商参与站会与评审的频率、信息发射源更新及时性、缺陷逃逸率。
- **预算消耗率**：累计支出占预算上限的比例，配合「预算耗尽则收缩范围」的规则使用。
- **买卖双方满意度**：通过阶段性联合评审收集双方对协作关系的评价，衡量「对抗→协作」是否真正落地。`,
      "💼 实践案例": `某传统零售企业委托一家软件公司开发新电商平台（含硬件POS系统与软件App），需求高度不确定，双方采用混合采购策略：
- 硬件POS系统：需求明确、规格稳定，使用固定总价（FP）合同，买方承担低风险，交付与验收按规范进行。
- 软件App：需求持续演进，使用「目标成本加激励酬金」的增量交付合同：约定目标成本，验收标准由双方共同定义；每个冲刺结束演示增量，验收通过的增量按比例付款；发布后按缺陷逃逸率结算激励或惩罚。合同明确「在预算上限内，通过调整产品待办优先级吸收变更」——范围变更不触发合同变更流程。
- 项目初期技术不确定性高（支付对接、推荐算法），双方又签订了一个T&M补充合同，用于2周的Spike探索：团队验证支付接口可行性与算法性能，产出决策建议；验证结果反过来固化了后续增量合同的范围与定价。
- 供应商团队被纳入敏捷流程：共同参加每日站会、冲刺评审与回顾，共享燃尽图与看板；产品负责人（买方）与卖方开发团队每日协作，需求细节在待办精化中澄清，而非通过合同附件传递。
- 第3个冲刺的评审中，业务方提出调整首页推荐策略，产品负责人直接在待办中提高该需求优先级并删除两项低价值功能，未走任何合同变更流程——这是合同预设的「价值范围内演进」机制在起作用。
- 项目结束时，核心功能全部交付，成本控制在目标成本内并获得约定激励；双方评分均认可「协作式关系」显著降低了沟通摩擦与验收争议。
该案例体现了敏捷合同的核心：成果导向、待办驱动变更、风险共担、供应商即团队。`,
    },
    keyConcepts: `关键术语——
- **固定总价（FP）**：锁定范围与价格，卖方承担成本与范围风险，与敏捷「拥抱变更」理念冲突。
- **目标成本加激励酬金**：约定目标成本，节余或超支按比例分享或分担，激励双方共同控制成本。
- **分阶段合同**：初始只定部分范围，后续按已验证学习扩围，含退出与重谈机制。
- **时间与材料（T&M）**：按实际投入计费，买方承担成本风险，适合高不确定性工作。
- **增量交付合同**：按交付的成果价值付款，而非按文档/规范合规付款。
- **成果vs输出**：付款验收看「实现的业务价值」而非「产出物数量」。
- **协作式合同**：把买卖双方从对抗转向合作，供应商纳入团队而非外部承包商。
- **合同管理≠范围控制**：敏捷中变更通过待办列表优先级实现，而非正式合同变更流程。
- **预算上限+范围收缩**：预算内优先高价值项，预算耗尽则交付已完成增量。`,
    examTips: `考试重点/常见陷阱——
- **敏捷合同场景**：PMP考试近年增考敏捷合同。原则：合同应激励合作而非惩罚变更；选项「激励协作/共享风险/成果导向」正确，「锁定范围惩罚变更/文档合规验收」错误。
- **变更机制**：敏捷合同中范围变更通过「产品待办列表优先级调整」实现，不走正式合同变更流程——这是高频辨析点。
- **供应商定位**：把供应商纳入团队（共同站会、评审、回顾）而非视为外部承包商；选项「把供应商隔离在团队外/仅里程碑交接」错误。
- **合同类型对比**：FP=买方低风险、卖方高风险；T&M=买方高风险、卖方低风险；目标成本加激励=双方共担共享。题目常考「哪种合同适合高不确定性」→T&M或增量/分阶段合同。
- **混合项目**：硬件用FP、软件用T&M或增量合同是典型混合采购答案，选项通常同时包含两者。
- **成果vs输出**：付款与验收标准是「实现的业务价值」，不是「文档数量/工时/代码行」。
- **目标成本加激励**：节余按比例分享、超支按比例分担——理解激励的方向是双方共同控制成本。
- **分阶段合同**：记住「初始阶段定义范围+后续按学习调整+退出/重谈权利」三要素。
- **对抗vs协作**：题干出现「买方与卖方相互防备/验收争议」→应选「建立协作式关系、共同定义验收标准、透明共享信息」。
- **与采购管理过程联系**：敏捷合同仍是「规划采购→实施采购→控制采购」的一部分，只是形式不同；投标人会议、建议书评估等工具仍然存在，只是评估标准向「协作能力/增量交付能力」倾斜。`
  },
  "agile-scaled": {
    overview: `【规模化敏捷】敏捷方法最初是为单一小团队（通常5-9人）设计的，例如Scrum要求开发团队规模为3-9人。当产品规模扩大、参与团队增多、组织需要同时协调多个产品线时，单团队的敏捷实践将无法应对，需要把敏捷的价值观与实践扩展到项目群（Program）和组织（Organization）层面，这就是规模化敏捷。

何时需要规模化？以下信号提示应考虑引入规模化框架：团队之间的依赖频繁出现，导致进度不可控；多个团队需要共享架构或设计决策；跨团队协调成本呈指数增长；单个团队无法按时交付大型集成产品。但规模化是一把双刃剑——它带来协调与集成的收益，也会引入额外的仪式、角色与官僚成本。因此在规模化之前必须冷静自问：能否通过缩小产品范围、优化团队边界或重组团队来避免过早、过度的规模化？

主流规模化框架各有侧重：SAFe强调企业级四层对齐与发布节奏；LeSS主张用一个产品、一个产品负责人、一个产品待办列表保持简洁；Scrum of Scrums与Nexus聚焦多Scrum团队协调；Scrum@Scale与Disciplined Agile（DA）是其他扩展选项。核心挑战一致：跨团队依赖管理、架构一致性、角色扩展与组织文化变革。`,
    details: {
      "🧩 核心要素": `- **SAFe（Scaled Agile Framework）**：目前最流行的企业级规模化敏捷框架，主张四层对齐、按节奏发布。它把组织划分为团队层、项目群层、大型解决方案层和投资组合层，强调各层目标与投资组合战略对齐，通过固定的节奏（8-12周PI）实现跨层同步，并把精益思想、敏捷实践与系统思考整合为一体，是规模化敏捷的代表性框架。
- **团队层（Team Level）**：SAFe的最底层，由多个敏捷团队（Scrum或看板）组成，每个团队运行自己的冲刺（通常1-2周）并交付增量，工作来自项目群层的项目群待办事项列表（Program Backlog）。
- **项目群层（Program Level）**：核心概念是敏捷发布火车（ART，Agile Release Train）——一个50-125人的长期跨职能团队，由多个敏捷团队加上项目群层角色组成，以8-12周为一个PI（Program Increment）发布节奏，把多个团队的工作整合为可演示的解决方案增量。
- **PI Planning（项目群增量规划）**：SAFe的核心仪式，每个PI开始前所有ART内团队面对面（或同步）共同规划下一个PI的工作，识别依赖、确定PI目标，为整个项目群建立对齐与承诺。
- **大型解决方案层（Large Solution Level）**：当解决方案规模超出单一ART的能力时，由多个ART协作交付，需要额外的解决方案级协调角色与同步机制。
- **投资组合层（Portfolio Level）**：对接组织战略与执行，通过投资组合待办列表（Portfolio Backlog）管理价值流投资，确定哪些价值流与项目应获得资金和资源。
- **LeSS（Large-Scale Scrum）**：极简主义规模化方法，坚持一个产品、一个产品负责人（PO）、一个产品待办事项列表，由2-8个团队（最多约50人）共同开发同一产品，取消一切不必要的附加角色与工件；LeSS Huge面向更大的多产品领域，以需求领域（Requirement Area）分组。
- **Scrum of Scrums**：多Scrum团队间的协调机制，每个团队派一名代表（又称Scrum of Scrums大使）定期（通常每日或每周）参加Scrum of Scrums会议，同步各团队进展、识别并协调跨团队依赖、解决阻碍跨团队的问题。它不是独立框架，而是Scrum的扩展协调实践。
- **Nexus**：由3-9个Scrum团队组成、共同交付一个集成增量的框架。它引入Nexus集成团队（负责集成工作的统筹）、Nexus冲刺（与各团队冲刺同步的协调冲刺）、Nexus冲刺待办事项列表与Nexus每日站会，强调每个周期都要产出经过集成的可工作增量。
- **扩展角色**：规模化后需要新增协调角色——RTE（Release Train Engineer，发布列车工程师）是ART层面的服务型协调者（类似放大版的Scrum Master），负责协调ART内团队、引导PI规划、清除跨团队障碍；产品经理（Product Manager）负责项目群待办事项列表的内容与排序（对应团队层的PO）；首席产品负责人（Chief PO）在多个产品团队间协调优先级与决策。注意：RTE对应SAFe，Scrum of Scrums大使对应Scrum扩展，二者职责相似但框架不同。
- **组件团队 vs 特性团队**：组件团队（Component Team）围绕技术组件（如数据库、UI、中间件）组建，专业性强、局部效率高，但交付一个端到端特性需要跨多个组件团队协作，协调成本高；特性团队（Feature Team）围绕端到端用户特性组建，成员跨职能、可独立交付完整特性，减少跨团队依赖，是规模化敏捷更推崇的组织方式。权衡在于：特性团队降低协调成本但要求更宽的技能集，组件团队专业化更强但增加依赖与集成负担。`,
      "🔧 关键实践": `- **跨团队依赖管理**：规模化敏捷最大的工程挑战。在PI规划等大型规划会议中显式识别依赖，用依赖矩阵（Dependency Matrix）记录团队间依赖，通过专门的依赖协调会议跟踪解决，使依赖透明化、可预测，避免临时救火。
- **分层待办事项列表**：规模化后待办列表分层管理——投资组合待办→项目群待办→产品待办→团队待办，各层有对应负责人（产品经理、PO等），逐层细化并保持对齐。
- **按节奏发布（Cadence-based Delivery）**：所有团队在同一个时间盒内工作（如统一的冲刺长度或ART的8-12周PI），固定的节奏降低同步成本，使规划、评审可预测。
- **系统级演示（System Demo）**：在每个PI/发布周期末尾，整个ART（而非单个团队）演示集成的解决方案，让干系人看到集成后的整体效果，尽早发现集成问题。
- **同步与协调会议**：除Scrum of Scrums外，规模化框架普遍采用定期同步机制（如SAFe的PI规划、Nexus每日站会、LeSS多团队回顾），确保跨团队信息及时流动。
- **待办列表精化与优先级统一**：多个团队共享同一产品待办列表（LeSS）或通过分层待办对齐（SAFe），确保所有团队朝同一优先级努力，避免局部优化。
- **保持团队级敏捷的本质**：规模化只是叠加协调层，不改变单团队内完整的敏捷实践（站会、评审、回顾、持续集成），否则会演变成僵化的官僚流程。`,
      "⚖️ 与传统方法对比": `- **协调机制**：传统项目群管理（Program Management）依赖层级式项目管理办公室（PMO）、正式里程碑评审与详尽的前期计划来协调多个项目；规模化敏捷以固定节奏、可见的待办分层和跨团队协作会议（如PI规划）进行协调，计划是滚动式的。
- **角色构成**：传统以项目经理、职能经理、PMO逐层管控；规模化敏捷新增RTE、产品经理、Scrum of Scrums大使等协调角色，强调服务型领导与自组织团队。
- **计划与变更**：传统一次性制定详细计划、变更须经变更控制委员会（CCB）批准；规模化敏捷在固定节奏（冲刺/PI）内滚动规划，在节奏点拥抱变更。
- **对不确定性的态度**：传统通过详尽前期分析减少不确定性；规模化敏捷通过频繁集成与系统级演示尽早暴露跨团队的不确定性。
- **组织文化**：传统倾向于命令-控制与职能分工；规模化敏捷要求文化转型——从局部优化转向端到端价值流，从个人绩效转向团队与ART整体交付。
- **适用场景**：传统项目群适合需求稳定、集成复杂度可控的大型工程；规模化敏捷适合需求多变、需要持续交付集成价值的软件与产品型组织。`,
      "📊 度量指标": `- **不跨团队比较Velocity**：每个团队的速率（Velocity）取决于团队规模、估算粒度与上下文，直接比较无意义，还可能诱导团队虚报估算；应比较团队自身的预测准确度而非团队间的速率大小。
- **价值交付度量**：聚焦已交付的端到端特性数量、发布频率、系统级演示的通过情况，而非单个团队产出。
- **流动效率度量**：前置时间（Lead Time）、周期时间（Cycle Time）、在制品（WIP）水平与累积流图，用于识别跨团队流动的瓶颈。
- **依赖度量**：跨团队依赖的数量、平均解决时长、依赖导致的延期次数，衡量依赖管理是否有效。
- **PI进度燃尽图（Program Increment Burn-down）**：显示整个PI内剩余工作的下降趋势，用于监控发布节奏的进展。
- **质量与满意度**：集成缺陷逃逸率、干系人在系统级演示中的反馈、团队与干系人满意度，衡量规模化是否真正改善了交付。`,
      "💼 实践案例": `- 某大型保险公司的核心系统覆盖理赔、承保、客户服务等多个领域，由7个功能团队共同开发。由于团队间对共享客户数据模型、结算服务等存在大量依赖，进度反复失控。公司引入SAFe：按领域把团队编组成一条ART（约70人），每12周一个PI；PI规划会上各团队用依赖矩阵显式登记跨团队依赖并当场排定解决顺序；每2周做一次系统级演示，让业务干系人看到集成后的整体效果。结果跨团队依赖的延期显著下降，发布节奏稳定在每12周一次，业务满意度提升。同时公司把原组件团队重组为特性团队——每个团队都能独立交付从界面到数据库的端到端特性，进一步减少依赖。`,
    },
    keyConcepts: `规模化敏捷（Scaled Agile）——把敏捷扩展到多团队、项目群与组织层面的框架与实践集合。
SAFe——企业级规模化框架，四层结构（团队/项目群/大型解决方案/投资组合），核心是ART。
ART（敏捷发布火车）——50-125人的长期跨职能团队，以8-12周PI为节奏发布集成增量。
PI Planning——SAFe的核心仪式，每8-12周跨团队共同规划下一个PI并识别依赖。
RTE（发布列车工程师）——ART层面的服务型协调者，类似放大版的Scrum Master。
LeSS——极简规模化，一个产品、一个PO、一个产品待办，2-8个团队（最多约50人）。
Scrum of Scrums——多Scrum团队协调机制，各团队派代表（大使）定期同步。
Nexus——3-9个Scrum团队共同交付一个集成增量的框架，含Nexus集成团队与Nexus冲刺。
组件团队 vs 特性团队——前者按技术组件组建、局部专业但跨团队依赖多；后者按端到端特性组建、独立交付能力强。
规模化决策信号——团队间依赖频繁、需共享架构决策、协调成本指数增长；不到必要时不规模化。`,
    examTips: `Scrum of Scrums是高频考点——题目问多个Scrum团队如何协调，首选各团队派代表参加定期的Scrum of Scrums会议；注意它与每日站会不同，前者是团队间协调、后者是团队内同步。
ART概念必记——SAFe偶尔考到，记住ART=敏捷发布火车=50-125人的长期跨职能团队、8-12周一个PI；RTE是其协调角色（类比放大版Scrum Master）。
LeSS vs SAFe区分——LeSS追求极简（一个产品/一个PO/一个待办列表、最多约8个团队），SAFe是完整企业级框架（四层）；问最轻量的规模化方式倾向LeSS或Scrum of Scrums。
不要为了规模化而规模化——情景题中团队规模尚小、依赖不严重时，正确做法是先优化团队划分、限制WIP、加强协调，而非立即上重框架；过度规模化导致官僚化是常见陷阱。
组件团队 vs 特性团队——问如何减少跨团队依赖，特性团队（feature team）是最佳选项。
规模化度量警告——不跨团队比较Velocity是考试明确否定项；比较应聚焦团队自身的预测准确度与整体价值交付。
扩展角色辨析——RTE（SAFe的ART协调者）、产品经理（项目群待办负责人）、Scrum of Scrums大使（团队代表）的职责要能区分，勿与PO、SM混淆。`
  },
  "agile-change-mgmt": {
    overview: `【组织变革管理】项目管理与组织变革管理（OCM，Organizational Change Management）经常重叠但侧重点不同。项目管理关注我们是否按计划交付了可交付物，即范围、进度、成本、质量的达成；变革管理关注这些可交付物是否被组织中的人员接受并使用，即行为、心态与文化是否真正转变。一个功能强大的新系统，如果员工拒绝使用，那么项目在交付层面成功了，在变革层面却失败了——这正是考试中项目成功不等于变革成功的含义。

变革管理是一套结构化方法，帮助个人与团队从当前状态（Current State）过渡到目标状态（Target State），并巩固过渡后的成果。它包含变革准备度评估、变革管理计划、变革代理人的动员、干系人沟通与培训、变革进展的度量与巩固。在敏捷转型中，变革管理的挑战通常是文化性的而非技术性的——团队需要从命令-控制心态转向协作-赋能心态，从职能分工转向跨职能自组织，这需要时间、领导力与持续支持，而不是一次培训或一次制度发文就能完成。

变革管理的关键概念还包括：变革代理人（Change Agent）——帮助他人适应变革的人，常由项目经理或敏捷教练（Scrum Master）兼任；变革饱和（Change Saturation）——组织同时启动太多变革导致员工变革疲劳与抗拒；变革度量——采用率、使用率与员工净推荐值等，用于衡量变革是否真正落地。`,
    details: {
      "🧩 核心要素": `- **ADKAR模型**：由Prosci提出，把组织变革转化为个人层面的五个连续阶段：Awareness（认知）——人们意识到变革的必要性；Desire（意愿）——人们有意愿参与和支持变革；Knowledge（知识）——人们知道如何改变；Ability（能力）——人们能够实施所需的技能和行为；Reinforcement（强化）——通过认可与奖励巩固并维持变革。五步必须依次推进、缺一不可——例如员工有认知却无意愿，变革就会受阻。
- **Kotter八步变革模型**：经典的组织变革框架：①建立紧迫感→②组建指导联盟→③形成战略愿景→④沟通变革愿景→⑤授权广泛行动→⑥产生短期胜利→⑦巩固成果并推进更多变革→⑧将变革锚定于文化。考试可能给出某一步的描述，要求识别所属步骤。
- **项目成功 vs 变革成功**：项目成功衡量交付物是否按时、按预算、符合范围与质量；变革成功衡量交付物是否被目标人群接受、采用并产生期望行为与收益。两者都实现才算完整成功。
- **变革饱和（Change Saturation）**：组织同时启动过多变革（如敏捷转型+新工具上线+组织重组+裁员）时，员工吸收变化的能力有限，产生变革疲劳、抗拒与倦怠。应对方法是评估变革组合、安排优先级、分阶段推进，必要时暂缓或合并部分变革。
- **变革代理人（Change Agent）**：推动并支持他人接受变革的个人。在敏捷转型中，项目经理、Scrum Master、产品负责人以及组织内的种子用户都可充当变革代理人，帮助团队理解新工作方式、示范新行为、收集反馈、消除障碍。
- **创新采纳曲线**：源自Rogers的创新扩散理论，按接受新事物的先后把人员分为五类——创新者（Innovators，约2.5%，乐于尝新）、早期采用者（Early Adopters，约13.5%，有影响力）、早期大众（Early Majority，约34%）、后期大众（Late Majority，约34%，多疑）、落后者（Laggards，约16%，抗拒）。变革管理应优先争取创新者与早期采用者作为杠杆，再通过口碑扩散影响大众，而不是试图一次性说服所有人。
- **变革阻力类型**：被动抵制（Passive Resistance）——表面配合但实际不作为、拖延、回避、消极怠工，如口头说试试却没行动；主动抵制（Active Resistance）——公开反对、拒绝执行、散布负面信息。识别阻力类型是应对的前提：对主动抵制先倾听并了解根本原因，对被动抵制通过澄清预期、提供支持与示范来化解。`,
      "🔧 关键实践": `- **变革准备度评估（Readiness Assessment）**：变革启动前评估组织是否准备好——人员能力、领导者支持度、文化适应性、资源投入，判断变革土壤是否肥沃，并据此设计导入策略。
- **变革管理计划**：像项目管理计划一样制定变革管理计划，明确变革目标、受影响人员范围、关键干系人、沟通策略、培训安排、变革代理人选、里程碑与度量指标。
- **结构化变革流程**：典型流程包括评估变革准备度→制定变革管理计划→执行沟通与培训→动员变革代理人→监控采用情况→处理阻力→巩固成果并制度化（把新行为融入流程、文化与绩效体系）。
- **有效沟通与干系人参与**：用多样化的渠道（大会、一对一、演示、邮件）持续讲清楚为什么变革、对我有什么影响，让干系人参与设计而非被动接受。
- **领导力而非职权**：变革需要领导者（Leader）通过愿景、信任与激励带动，而非仅靠职权（Authority）强制命令；项目经理在变革中应发挥领导力，并争取高层发起人的积极支持。
- **与敏捷理念结合**：在敏捷转型中用短迭代、快反馈的方式推进变革——小步试点、展示早期成功、根据反馈调整，契合Kotter的短期胜利与ADKAR的强化阶段。
- **巩固与制度化**：变革不是一次性的，需要在过程中持续强化（认可、奖励、纳入绩效指标与工作流程），把新行为锚定于文化，防止回退到旧习惯。`,
      "⚖️ 与传统方法对比": `- **关注焦点**：项目管理关注交付物完成与否（范围、进度、成本、质量）；变革管理关注人员采纳与行为转变与否（采用率、使用率、满意度）。
- **作用对象**：项目管理作用于工作产品与过程；变革管理作用于人与文化。
- **衡量标准**：项目成功以可交付物符合验收标准衡量；变革成功以目标人群的行为改变与收益实现衡量。
- **时间跨度**：项目有明确的起止时间；变革可能跨越项目结束，持续到行为固化、成果锚定于文化。
- **驱动力量**：项目靠项目经理与团队执行；变革靠领导力、高层发起人与遍布组织的变革代理人推动。
- **互补关系**：两者不是二选一——项目交付技术变革（系统、流程、方法），变革管理确保人员变革跟上，缺一不可。考试中新系统上线却无人使用的情景，正确方向是加强变革管理（沟通、培训、参与、处理阻力），而非仅仅修复系统。`,
      "📊 度量指标": `- **采用率（Adoption Rate）**：目标人群中实际开始使用新方法或系统的人员比例，是最核心的变革度量。
- **使用率（Utilization Rate）**：已采用者中的实际使用频率与深度，衡量用了还是用好了。
- **员工净推荐值（eNPS，Employee Net Promoter Score）**：员工是否愿意向他人推荐公司或新工作方式，反映对变革的整体认同度。
- **员工满意度与敬业度**：变革期间的满意度调查，监测变革疲劳与抗拒信号。
- **KPI变化**：对比变革前后的关键业务指标（缺陷率、交付周期、客户满意度、产能），用结果证明变革价值。
- **里程碑完成度**：变革管理计划中沟通、培训、试点等里程碑的实际完成情况。
- **阻力监测**：投诉数量、负面反馈、人员流失率等作为阻力与变革疲劳的预警信号。`,
      "💼 实践案例": `- 某制造企业推行敏捷转型。第一步用变革准备度评估发现：中高层支持度高，但一线工程师担心流程太随意、缺乏安全感，已出现主动抵制的苗头。项目经理兼变革代理人没有强制推行，而是先组织一对一倾听会了解顾虑，再用ADKAR逐层推进：先让全员认识到市场变化要求更快交付（Awareness）；邀请两三位有影响力的工程师成为早期采用者并参与试点团队（Desire）；随后系统化培训Scrum实践（Knowledge）；在试点中提供教练支持（Ability）；最后把敏捷实践纳入季度绩效与认可机制（Reinforcement）。同时识别变革饱和风险，与HR协调错开同期上线的其他变革。经过两个季度的试点推广，试点团队采用率从30%提升到85%，eNPS回升，敏捷实践成功固化到日常流程。`,
    },
    keyConcepts: `组织变革管理（OCM）——帮助个人与团队从当前状态过渡到目标状态并巩固新状态的结构化方法。
ADKAR——Awareness→Desire→Knowledge→Ability→Reinforcement，个人变革五阶段模型，顺序不可跳跃。
Kotter八步——紧迫感→指导联盟→愿景→沟通愿景→授权行动→短期胜利→巩固成果→锚定文化。
项目成功 vs 变革成功——交付物按时交付不等于被接受使用；两者都实现才算完整成功。
变革饱和——同时进行太多变革导致员工疲劳与抗拒。
变革代理人——帮助他人适应变革的人，常由PM/SM兼任。
创新采纳曲线——创新者→早期采用者→早期大众→后期大众→落后者；优先争取前两类。
变革阻力——主动抵制（公开反对）与被动抵制（表面配合实则拖延）。
变革度量——采用率、使用率、员工净推荐值（eNPS）。`,
    examTips: `高频情景——新系统或新流程上线后员工抗拒、不使用，正确做法是先了解原因（倾听、对话、理解顾虑），再采取行动（沟通、培训、争取早期采用者、争取高层支持），而非强制推行或只怪罪员工。
项目成功不等于变革成功——题干给出项目按时交付但用户不采用，问成功与否，答案应聚焦人员采纳与行为转变，不能只看交付。
ADKAR是个人层面——题目问员工知道该做什么但做不到（有Knowledge无Ability），应补能力、资源、教练支持，而不是再讲道理。
Kotter步骤识别——题干描述先制造紧迫感、庆祝早期小胜利、把新做法写进制度等，分别对应八步的相应步骤，要能对上号。
变革饱和——情景中公司同时上多个新系统并组织重组，正确应对是评估优先级、分阶段推进、暂缓部分变革，而非照单全收。
优先争取早期采用者——问如何让变革被接受，先找有影响力的支持者（创新者/早期采用者）试点并示范，优于一次性全员强制。
领导力 vs 职权——变革靠领导力（愿景、信任、激励）而非职权（命令），含强制、命令字样的选项通常不是最佳。
阻力类型辨析——主动抵制=公开反对；被动抵制=表面配合实际拖延或不落地；应对被动抵制要先澄清预期、提供支持，而不是认为对方已同意。`
  },
  "agile-charter": {
    overview: `【敏捷项目章程】敏捷项目同样需要章程来正式授权项目启动，但形式远比传统（预测型）章程轻量。敏捷章程（Agile Charter，又称项目愿景文档或宪章）通常只有1-2页，其目的不是罗列详细的约束与控制规则，而是回答几个核心问题：我们为什么做这个项目（愿景与深层目的）？我们要交付什么（高层次的任务描述）？什么才是成功（高层级验收标准）？受什么约束（固定的预算、时间或范围）？谁参与（发起人、产品负责人、核心团队、客户代表）？以及我们怎样一起工作（工作协议）？

敏捷章程的三要素是：愿景（Vision）——项目为什么存在，指明方向与深层动机；使命（Mission）——项目是什么，高层次描述要交付的内容；验收标准（Success Criteria）——项目怎么才算成功，高层级、可衡量的成功定义。三者共同回答Why、What与How-to-measure-success。

敏捷章程由发起人（通常为执行发起人）与产品负责人签发，但更重要的是在团队高度参与下共同创建——团队参与创建本身就是建立承诺与共识的过程，这与预测型章程由高层单独批准形成鲜明对比。敏捷章程通常通过协作式工作坊产出，并随项目推进持续检视与更新，保持活文档属性。在混合型项目中，轻量级章程可以满足高层治理需求，而无需生成完整的项目管理计划文档集。`,
    details: {
      "🧩 核心要素": `- **愿景（Vision）**：回答我们为什么做这个项目，是章程的北极星。好的愿景应能激励团队、指向深层目的，通常用愿景陈述（Vision Statement）表达，常用Elevator Pitch（电梯演讲）模板提炼。
- **使命（Mission）**：回答项目具体交付什么，是愿景在高层次的落地，描述产品的目标用户、核心功能与价值主张，但不陷入细枝末节的规格。
- **验收标准（Success Criteria）**：回答什么才算成功，是高层级、可测量的成功定义（如上线6个月内达到X万活跃用户、缺陷率低于Y%），不同于用户故事层面的验收条件——章程层面的验收标准是项目级的。
- **轻量1-2页**：敏捷章程刻意保持简短，通常1-2页，聚焦Why与What，把How的细节留给产品待办事项列表与迭代规划，使其易于理解、易于沟通、易于更新。
- **团队共同创建**：章程不是高层单方面批准的文件，而是通过协作式工作坊（如愿景工作坊、团队启动会）由发起人、产品负责人、团队成员与关键干系人共同创建；共创过程建立共识、承诺与心理所有权。
- **创建时机与持续更新**：章程在项目启动阶段创建、先于详细规划；它不是一次性死文档，可随项目学习与市场变化定期检视与更新（如每个发布周期开始时），保持与当前现实一致。
- **与产品待办事项列表的关系**：章程不能替代产品待办事项列表——章程定义为什么与是什么（Why & What），待办事项列表定义具体怎么做（How in detail）；章程是稳定的方向指引，待办事项列表是动态演化的细节清单。
- **工作协议（Working Agreement）**：团队共同约定的行为准则与决策规则（如每日站会15分钟、评审后48小时内反馈、冲突先面对面沟通），常作为章程的组成或附件，是团队协作的社会契约。
- **混合型项目中的轻量治理**：在混合型项目中，用1-2页的轻量章程满足高层对治理与授权的需求（谁批准、什么边界、如何汇报），而不必像预测型项目那样生成整套管理计划文档，显著降低治理开销。`,
      "🔧 关键实践": `- **Elevator Pitch（电梯演讲）模板**：把愿景浓缩成一段话——我们项目是为[目标客户]创建的[产品/服务]，它解决[关键问题]，提供[核心收益]，不同于[现有替代品]的是[独特卖点]。该模板强制团队把愿景说得具体、对客户有价值、有差异化，是章程共创工作坊的常用工具。
- **愿景工作坊（Vision Workshop）**：召集发起人、产品负责人与核心团队，用头脑风暴、电梯演讲模板、用户画像与价值主张讨论，共同提炼愿景并达成一致。
- **团队启动会（Kickoff / Team Startup）**：项目启动时召开，除宣布章程外，重点是让团队互相认识、共同制定工作协议、确认沟通渠道与决策规则，把一起怎么工作落地。
- **章程评审与检视（Charter Review）**：在发布周期或里程碑节点重新审视章程——愿景是否仍然成立？验收标准是否需要调整？通过定期检视让章程保持活的状态。
- **与待办列表衔接**：把章程中的高层次范围与验收标准逐步分解为产品待办事项列表条目，由产品负责人持续精化与排序，实现从方向到细节的平滑过渡。
- **持续验证愿景**：在每个冲刺评审中对照章程的愿景与验收标准检查方向是否偏移，实现方向-交付的闭环。
- **轻量治理**：在混合型项目中，章程配合定期的章程级评审、里程碑汇报与变更协商，为发起人提供足够的治理可见性，而无需厚重的文档集。`,
      "⚖️ 与传统方法对比": `- **篇幅与内容**：预测型章程通常较长（10页以上），包含详细的范围、预算、里程碑、风险与组织信息；敏捷章程通常1-2页，聚焦愿景、使命、验收标准与工作协议。
- **创建方式**：预测型章程多由发起人或项目经理在启动阶段起草并正式签发；敏捷章程在团队参与下通过工作坊共同创建，共创即承诺。
- **关注焦点**：预测型章程聚焦What、How much、When（详细范围、预算、时间表）；敏捷章程聚焦Why与What（目的与方向），把How留给待办列表与迭代规划。
- **变更态度**：预测型章程是正式基线，重大变化需正式变更控制；敏捷章程是活文档，随学习持续检视更新，拥抱变化。
- **治理方式**：预测型靠完整计划与正式评审治理；敏捷或混合型用轻量章程配合定期检视满足治理需求，治理开销更低。
- **文档角色**：预测型中章程与计划是契约与控制的载体；敏捷中章程是方向与共识的载体，细节由待办列表承载。`,
      "📊 度量指标": `- **章程级验收标准的达成**：把章程中的高层验收标准转化为可测量的项目级指标（如用户采用率、上线里程碑、关键质量阈值），作为衡量章程承诺的成功是否达成的依据。
- **愿景一致性检查**：在每个发布周期评审时对照章程的愿景评估当前产品方向是否仍然对齐，衡量有没有跑偏。
- **团队承诺与共识度**：通过共创工作坊的参与度、团队对章程的理解度调查、对愿景表述的一致认可度，衡量章程的凝聚作用是否生效。
- **章程更新频率与质量**：记录章程的检视与更新活动，判断其是否保持活文档状态——长期不更新说明可能过时，过于频繁说明方向不稳。
- **治理有效性**：混合型项目中，章程评审是否能及时发现方向与边界问题，衡量轻量治理是否够用。`,
      "💼 实践案例": `- 某金融科技公司启动智能信贷审批敏捷项目。发起人、产品负责人与7人核心团队在启动工作坊中共同创建一页章程：用Elevator Pitch模板写出愿景——我们为中小微企业主创建一款3分钟完成信贷预审的移动应用，它解决传统信贷流程冗长、材料繁琐的问题，提供实时额度预估与进度透明，不同于银行App的是基于行业数据的智能预审与透明审批规则；随后写下使命（MVP交付范围）与验收标准（上线90天内1万家企业完成预审、平均审批时长从7天降到1天、错误拒批率低于5%），并约定工作协议（站会15分钟、评审后48小时反馈、冲突面对面沟通）。章程由发起人签署授权，团队在共创中建立了承诺。每个季度团队对照章程检视方向，产品待办事项列表则在每个冲刺持续精化，从章程的使命逐步展开为用户故事。在混合治理下，管理层只通过季度章程评审与里程碑汇报掌握项目，无需查看全套文档。`,
    },
    keyConcepts: `敏捷章程——1-2页的轻量授权文件，定义愿景、使命、验收标准、约束、干系人与工作协议，用于启动并持续指导项目。
三要素——愿景（Why）→使命（What）→验收标准（How to measure success）。
Elevator Pitch模板——为[目标客户]创建[产品]，解决[问题]，提供[收益]，区别于[替代品]的是[卖点]。
工作协议（Working Agreement）——团队约定的协作行为与决策规则。
共创——章程由发起人、PO与团队共同创建，创建过程即建立承诺。
活文档——章程随项目推进定期检视更新。
章程不等于产品待办事项列表——章程定义方向（Why/What），待办列表定义细节（How）。
混合型轻量治理——1-2页章程满足高层治理需求，无需完整的管理计划文档集。`,
    examTips: `高频区分题——问敏捷章程与传统章程的区别，要点是更简洁（1-2页 vs 10+页）、团队共创、聚焦Why与What、更具适应性；凡选项强调详尽的范围与预算明细、高层单独批准即可，多为错误选项。
章程不等于待办事项列表——题目问章程能否替代产品待办列表，答案是否定的：章程定义为什么和是什么，待办列表定义具体细节；此点几乎必考。
三要素归类——愿景=为什么（Why）；使命=是什么（What）；验收标准=怎么算成功；给出描述要能正确归类。
团队共创的意义——情景题中团队对项目目标缺乏承诺，正确方向是让团队参与章程共创或愿景工作坊以建立共识，而非领导单方面发文。
创建时机——章程在项目启动阶段创建、先于详细规划，且持续更新（活文档）；一次制定、永不更改是错误选项。
混合型轻量治理——题目问混合型项目如何满足高层治理，用轻量章程加定期检视或里程碑汇报即可，无需完整的管理计划文档集。
Elevator Pitch模板——考试可能给出一段愿景描述，要求识别其要素（目标客户、问题、收益、差异化卖点）或判断是否完整。`
  },
  "proc-plan-procurement": {
    overview: `【过程概述】规划采购管理过程属于规划过程组，其目的是记录项目采购决策，明确采购方法，识别潜在卖方。该过程用于确定项目是否需要获取外部资源，如何获取、获取多少以及何时获取。对于项目团队决定从外部采购的产品、服务或成果，需要据此制定采购管理计划和采购策略，为后续实施采购、控制采购与合同收尾奠定基础。该过程的关键收益是：通过自制或外购分析确认哪些工作应由内部完成、哪些应委托外部卖方，从而降低只依赖内部能力或盲目外包带来的风险，并形成可供招标与授予合同依据的完整采购文件。

采购决策的起点是自制或外购分析（Make-or-Buy Analysis）。项目团队应比较自制的全部成本（含人工、设备、间接费用与机会成本）与外购的全部成本（含采购价、运费、合同管理与监督成本），并结合项目范围、进度、质量、风险、组织能力与核心竞争力等因素综合判断。当自制成本远高于外购、组织缺乏相应能力或外部供应商交付更优时，倾向外购；反之倾向自制。独立成本估算（Independent Cost Estimate）用于独立验证供应商报价的合理性，防止报价过高或过低。

合同类型选择是规划采购中的关键决策。合同是买卖双方之间的法律约束性协议，合同类型决定成本风险的分配方式，因此必须先确定合同类型再撰写招标文件。固定总价合同（FP）在范围明确且稳定时使用，卖方承担成本超支风险；成本补偿合同（CR）在范围不确定时使用，买方承担成本超支风险；工料合同（T&M）适用于小型短期工作，风险分布介于两者之间。供方选择分析用于确定选择供应商的方法：最低成本、资质唯一来源、固定预算、基于质量。招标文件包括信息邀请书（RFI）、建议邀请书（RFP）、报价邀请书（RFQ）等。`,
    details: {
      "📥 输入 Inputs": `- **项目章程**：包含项目目标、高层级需求与范围描述，是判断哪些工作必须在内部完成、哪些可以外购的总体依据；章程中的高层级预算与风险也影响采购策略与合同类型选择。
- **项目管理计划**：本过程的输入主要是其中的若干子计划：
  - **范围管理计划**：说明项目范围如何定义与变更，为编制采购工作说明书（采购SOW）提供范围边界。
  - **质量管理计划**：规定项目与可交付物的质量标准，需把这些标准融入采购评价标准与合同条款。
  - **资源管理计划**：说明内部资源的可用性，帮助判断哪些工作内部可做、哪些必须外购，是自制或外购判断的直接背景。
- **项目文件**：提供采购需求的具体信息，主要包括：
  - **需求文件**：列出项目需求及其优先级，是界定采购范围与编制采购SOW的基础。
  - **里程碑清单**：确定关键交付日期，影响采购时间安排与供应商交付要求。
  - **项目团队派工单**：显示内部团队已分配的角色与负荷，辅助自制或外购判断。
  - **风险登记册**：记录与采购相关的风险（如单一供应商依赖、交付延迟、质量不合格），影响供方选择标准与合同条款设计。
  - **干系人登记册**：识别影响采购的干系人（法务、财务、采购部门、发起人），便于在规划中征求其意见并确认采购授权。
- **事业环境因素**：包括组织的采购政策与程序、适用的法律法规（招标法、反垄断法、合同有效性法规）、市场条件（供应商可用性与供需态势）、以及组织可用的采购人员与外部专家等，这些都会约束采购方式与合同类型的选择。
- **组织过程资产**：包括组织的合同模板（总价、成本补偿、工料合同范本）、标准招标文件模板、历史项目的供应商清单与绩效数据、合格供应商名录、以及采购相关的经验教训，可大幅提高规划效率并降低法律风险。`,
      "🔧 工具与技术 Tools": `- **专家判断**：征求具有采购、法律、合同管理与行业经验的人士意见，包括采购专业人员、法务顾问、工程与技术专家、行业供应商管理专家，用于确定合同类型、评估市场状况、设计供方选择标准与招标文件，并审查自制或外购决策。
- **数据分析**：本过程的核心分析技术是**自制或外购分析**——比较内部自制的总成本（材料、人工、设备、间接费用与机会成本）与外购的总成本（采购价、运费、合同管理与监督成本），并结合组织能力、可用资源、进度要求与风险等因素判断某项工作应由内部完成还是外包。此外可用**独立成本估算**对采购成本进行独立测算，用于后续核实供应商报价的合理性。
- **供方选择分析**：确定选择供应商的方法。常用方法包括：**最低成本法**——满足最低技术门槛后选择价格最低的供应商；**资质唯一来源法**——基于供应商独有的技术能力、专利或经验选定（单一来源采购）；**固定预算法**——在既定的固定预算内选择能够提供最优方案的供应商；**基于质量法**——给技术质量较高的方案更高权重，即使其价格略高。复杂项目常组合使用多种方法。
- **会议**：召开由项目团队与干系人（采购、法务、财务、发起人）参加的会议，审查自制或外购决策、商定合同类型与供方选择标准、审批招标文件草案，确保各方对采购方法达成一致后才正式发布招标文件。`,
      "📤 输出 Outputs": `- **采购管理计划**：规定项目团队如何从外部采购产品、服务或成果，包括采购活动的流程与授权（由谁发起采购、谁审批合同）、采购类型（分包/咨询/产品采购）、如何管理多个供应商、采购与项目进度协调的方式、合同类型选择与合同模板、风险管理安排（履约担保、保险）、以及供方选择与合同签署的管理程序。
- **采购策略**：记录项目的采购方法与总体安排，包含四个要素：**交付方法**（专业服务交付方法，或设计-招标-建造、设计-建造等建筑类交付方法，或设备与基础设施交付方法）、**合同支付类型**（总价、成本补偿、工料，可含激励条款）、**采购阶段**（将采购划分为若干阶段，明确每阶段的招投标与合同安排）、**供方选择标准**（评估与选择供应商的准绳）。采购策略决定了后续招标与合同管理的整体方向。
- **招标文件**：用于征求潜在卖方的建议或报价，常见包括：**信息邀请书（RFI）**——用于收集市场与供应商信息；**报价邀请书（RFQ）**——用于价格竞争明确的采购；**建议邀请书（RFP）**——用于需要技术方案与商业方案综合评价的采购。招标文件还应包含**采购工作说明书（采购SOW）**——清楚界定采购内容、规格、交付物、验收标准与交付时间，以及**供方评价标准**（技术、成本、管理能力、财务实力等），以便供应商按要求响应并便于公平比较。
- **供方选择标准**：一套加权评估标准，用于评估并比较各供应商的建议书。标准通常包括：技术能力与方法、报价与总拥有成本、管理能力（项目团队与项目管理水平）、财务稳定性、以往绩效、产能与供货时间、质量保证体系与售后服务等，各标准权重依项目优先级设定。供方选择标准与招标文件一起发布，确保评价过程客观透明。
- **自制或外购决策**：记录每项可外购的工作由内部完成还是委托外部供应商的决策结论及其理由，并记录决策所依据的分析与假设，作为后续采购与资源计划的输入。
- **项目文件更新**：根据规划结果更新相关项目文件，主要是**风险登记册**（新增采购相关风险，如单一供应商风险、合同风险、市场风险）与**需求文件**（补充采购需求细节）等。`,
      "🔗 与其他过程的相互作用": `规划采购管理是采购管理链的起点。输入方面，它使用项目章程、范围管理计划（范围管理）、质量管理计划、资源管理计划（规划资源管理）以及风险登记册（规划风险管理）等成果，把范围、质量、资源与风险要求转化为采购安排。输出方面：采购管理计划、采购策略、招标文件与供方选择标准是实施采购过程的直接输入——实施采购据此发布招标文件、接收建议书并选定卖方；采购SOW中的规格要求反过来约束卖方的交付范围。自制或外购决策直接影响资源管理——决定自制的部分进入内部资源需求，决定外购的部分进入采购计划。此外，采购管理计划中的合同类型决定了控制采购过程中的变更与索赔处理方式。规划采购通常在项目早期进行，但可随范围或需求变化而迭代更新，形成规划、实施、控制、再规划的持续循环。`,
      "✂️ 裁剪考虑": `- **预测型**：项目前期范围相对明确，采购规划一次性全面开展，招标文件详尽，合同类型多选择固定总价合同，供方选择标准严格按技术与价格权重评价。
- **适应型（敏捷）**：需求渐进明细，采购倾向于小批量、多批次、按需采购，合同常用工料或总价加变更条款，强调供应商尽早参与并与团队协作；招标文件与供方选择标准更轻量，可随迭代调整。
- **混合型**：核心固定范围部分按预测方式集中采购，不确定部分按敏捷方式分阶段小批采购，项目经理需同时管理两类采购节奏与合同类型。
- **其他因素**：采购金额大小、组织采购政策与合规要求（政府采购通常必须公开招标）、供应商市场结构（竞争充分与否）、项目复杂度与风险、法务审核要求等，都会影响采购规划的详简与合同类型选择。`,
      "💼 实践案例": `某政府信息化项目需建设一套数据平台。规划采购管理时，团队先做自制或外购分析：核心算法部分因组织拥有专有技术选择自制；基础设施与通用模块因内部人手不足选择外购。鉴于项目范围在需求调研后已基本清晰且预算受财政约束，团队选择固定总价合同，通过公开招标（最低成本法加技术门槛评分）确定供应商。招标文件包含详细的采购SOW（功能规格、接口标准、验收指标与里程碑）与供方选择标准（技术方案权重40%、价格权重30%、实施经验20%、服务支持10%）。同时采购部门发出RFI进行市场摸底，并参考历史供应商绩效数据更新风险登记册——将关键模块单一供应商依赖列为高风险，计划以履约保证金与阶段性验收来缓解。最终顺利发布RFP，进入实施采购阶段。`,
    },
    keyConcepts: `- **自制或外购分析（Make-or-Buy Analysis）**：比较自制的全部成本与外购的全部成本，并结合组织能力与风险，决定工作由内部完成还是外包，是采购规划的起点。
- **采购管理计划**：定义采购流程、类型（分包/咨询/产品采购）、多供应商管理、合同类型与协调方式的计划。
- **采购策略四要素**：交付方法、合同支付类型、采购阶段、供方选择标准，决定采购的整体方向。
- **合同类型全谱系**：固定总价（FP）→总价加激励费（FPIF）→总价加经济价格调整（FP-EPA）→工料（T&M）→成本加固定酬金（CPFF）→成本加激励酬金（CPIF）→成本加奖励酬金（CPAF）→成本加成本百分比（CPPC）。
- **买方/卖方风险分配矩阵**：FP类合同卖方承担成本风险最高、买方风险最低；T&M风险居中、混合分布；CR类合同买方承担成本风险最高、卖方风险最低。风险从FP到CR依次由卖方转向买方。
- **独立成本估算（ICE）**：独立于供应商报价的第三方测算，用于核实报价合理性。
- **供方选择分析**：确定选择供应商的方法——最低成本、资质唯一来源、固定预算、基于质量。
- **招标文件**：RFI（信息邀请书）/RFQ（报价邀请书）/RFP（建议邀请书），连同采购SOW与评价标准构成招标包。
- **采购SOW**：明确采购内容、规格、交付物、验收标准与交付时间的工作说明书。`,
    examTips: `- 合同类型是采购领域最高频考点：务必掌握固定总价=卖方风险最高、买方风险最低；成本补偿=买方风险最高、卖方风险最低；工料=风险居中混合。风险从FP到CR依次从卖方转向买方。
- 自制或外购分析是采购规划的第一步：凡题干出现是否外包、自制还是购买的判断，答案指向自制或外购分析。
- 区分最低成本与基于质量两种供方选择：最低成本法满足技术门槛后就选最便宜的；基于质量法技术评分权重更高、可接受较高价格。
- 独立成本估算用于核实报价合理性，防止卖方报出过高或过低的价格，常出现在供应商报价异常的情景题中。
- 记住招标文件三件套：RFI（先摸底）、RFP（要方案）、RFQ（要报价），RFP是考试最常出现的。
- 采购策略四要素（交付方法、合同支付类型、采购阶段、供方选择标准）可作为多选题考点。
- 易错点：规划采购的输出是招标文件而不是合同——合同在实施采购过程中授予，切勿混淆。
- 易错点：采购SOW描述的是采购内容与验收要求，项目管理计划中的项目范围说明书描述的是整个项目范围，两者层级不同。`
  },
  "proc-conduct-procurement": {
    overview: `【过程概述】实施采购过程属于执行过程组，其目的是获取卖方响应，选择卖方并授予合同。具体活动包括：向潜在卖方发布招标文件、召开投标人会议确保所有卖方对采购需求有一致理解、接收并评估投标书和建议书、根据供方选择标准选定卖方、谈判合同条款、最终授予合同。该过程的关键收益是：以公平、透明的方式从合格供应商中选出最具价值（而非最便宜）的卖方，并把采购协议/合同与项目计划对齐，为后续控制采购提供合同依据。

实施采购的前置条件是规划采购管理已形成采购管理计划、采购策略、招标文件与供方选择标准。本过程通常以公开或选择性招标方式发布招标文件，接收潜在卖方的建议书。投标人会议是确保公平性的关键环节——所有卖方必须获得相同的信息，任何私下披露的信息都必须同步告知全体卖方。建议书评价通过加权评分、筛选系统与独立成本估算比较等方法进行，选出最符合供方选择标准的卖方，随后进行合同谈判并签署协议。若中选卖方将部分工作分包给其他单位，买方通常需在合同中保留对分包商的批准权与监督权，确保分包工作同样满足项目要求。

在授予合同后，项目经理还需把合同信息同步到项目文档中：选定的卖方与协议内容需反映在资源日历（供应商交付时间）、采购文档（合同、履约保函等）以及相关计划中。合同是法律约束力的文件，项目经理应与法务和采购专业人员协作，避免独自做出具有法律效力的承诺；非正式口头承诺不构成合同变更。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：本过程主要使用其中的**采购管理计划**（规定采购流程、授权与合同签署程序），以及范围管理计划、需求管理计划、沟通管理计划、风险管理计划与成本基准等组件，为评价建议书、谈判与授予合同提供依据。
- **项目文件**：包括经验教训登记册（参考以往采购与谈判经验）、项目进度计划（明确供应商交付时间）、需求文件（采购内容与验收要求）、风险登记册（与供应商相关的风险）、干系人登记册（参与采购决策的法务、采购、发起人等人员）。
- **采购文档**：包括规划采购过程产出的招标文件、供方选择标准、采购SOW，以及买卖双方之间正式书面沟通的记录，是评估建议书与授予合同的主要依据。
- **供方建议书**：潜在卖方响应招标文件提交的方案与报价，通常分为技术建议书（方法、团队、进度、质量）与商业建议书（价格、付款条件、风险），是建议书评价的直接对象。
- **事业环境因素**：包括组织采购政策与程序、适用的法律法规（招标与合同法规）、市场条件与合格供应商名录、以及组织可用的采购与法务资源。
- **组织过程资产**：包括组织的合同模板、历史供应商绩效记录、以往项目的合同与采购文档、谈判指引与经验教训，用于指导合同谈判与签署。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由采购专家、法务顾问、技术专家和财务人员提供建议，用于评估建议书的技术与商业可行性、审查合同条款、判断谈判策略与授权范围。
- **广告**：向潜在卖方公布项目采购机会。公开招标通常通过政府采购门户、行业刊物、公共媒体等渠道发布招标广告，以扩大供应商覆盖面、提高竞争程度；也可通过供应商注册库定向通知。广告的范围与形式须符合组织政策与法律要求。
- **投标人会议**：由买方在正式投标前组织召开，向所有潜在卖方说明采购需求并逐一解答疑问。其核心原则是**公平一致**——所有卖方必须获得相同的信息与答疑，买方不得对个别卖方私下透露额外信息；若在非正式场合向某卖方披露了信息，必须在后续向全体卖方同步。投标人会议能确保各卖方在相同理解下投标，减少误解与无效投标。
- **数据分析**：用于系统评价建议书，主要包括三种方法：
  - **建议书评价（加权评分法）**：按供方选择标准设定权重，对每份建议书的技术与商业部分分别打分并加权汇总，选出综合得分最高者。
  - **筛选系统**：设定必须满足的硬性门槛（如资质、财务指标、合规要求），先淘汰不合格建议书，再对合格者深入评价；适用于供应商众多的场景，可提高评价效率。
  - **独立成本估算（ICE）比较**：将各供应商报价与独立成本估算进行比较，识别报价异常（过高或过低），作为选择与谈判的依据。
- **谈判**：在合同授予前与选定的卖方就范围、进度、质量、价格、付款条件、责任与争议处理等条款进行协商，目标是达成对双方公平、对项目有利的协议。谈判前应明确**BATNA（最佳替代方案）**——即谈判失败时我方的最优备选路径，BATNA越强，议价能力越强，可避免被单一供应商绑定。谈判由具有授权的人员进行，项目经理应与法务、采购专业人员共同参与。`,
      "📤 输出 Outputs": `- **选定的卖方**：通过建议书评价与谈判确定的供应商。选定后需与卖方就合同关键条款达成一致，将供应商信息记录到项目文档，并发出中标通知；同时可安排对卖方分包商的审查与批准程序。
- **协议（合同）**：买卖双方之间具有法律约束力的书面文件，明确工作范围、交付时间表、付款条件、验收标准、保证与担保、争议解决方式、终止条款等。合同经双方授权代表签字后生效，成为控制采购过程的依据。合同通常包含**投标保函/履约保函**条款——履约保函保证卖方按合同履约，若卖方违约，买方可按条款索赔。
- **变更请求**：实施采购过程中若发现采购内容、合同条款或选择结果与原计划不一致（如范围调整、供应商变更、谈判结果与原预算不符），需提出变更请求并提交实施整体变更控制过程评估与审批。
- **项目管理计划更新**：主要是**采购管理计划**更新，反映采购策略、合同安排与供应商管理方式的变化；若采购影响进度或成本，还需更新相应组件。
- **项目文件更新**：包括**风险登记册**（记录新增的供应商与合同风险）、**经验教训登记册**（记录采购与谈判经验）、**干系人登记册**等。
- **组织过程资产更新**：记录采购过程中积累的供应商信息、报价资料、谈判记录与经验教训，供未来项目参考。`,
      "🔗 与其他过程的相互作用": `实施采购承接规划采购的输出（招标文件、供方选择标准），并把结果传导给控制采购。授予的协议/合同是控制采购过程的直接输入；选定的卖方及其交付时间更新资源日历，影响进度计划；合同中的验收标准与绩效要求为控制采购中的绩效审查与检查提供基准。实施采购中提出的变更请求进入实施整体变更控制过程。对于内部资源不足的部分，实施采购获取的外部资源与获取资源过程互补——一个解决组织内部资源获取，一个解决外部供应商采购。此外，合同签订前的谈判涉及法务与财务干系人，需借助沟通管理与干系人参与相关过程协调；谈判中暴露的供应商风险需回写风险登记册。`,
      "✂️ 裁剪考虑": `- **预测型**：通常采用正式公开招标，流程严谨、文档完整，投标人会议、建议书评价与谈判按既定程序进行，合同类型多采用固定总价。
- **适应型（敏捷）**：更强调供应商作为协作伙伴尽早参与（如联合开发），采购批量小、周期短，谈判轻量高效，合同常采用工料或总价加变更条款，投标人会议可简化为与候选供应商的快速对接。
- **混合型**：核心基础设施或一次性大额采购按预测方式正式招标；敏捷迭代部分按需小批采购，供应商参与模式与评价方式分别设计。
- **其他因素**：采购金额、合规要求（政府/公共采购必须公开招标）、市场竞争程度、供应商数量、合同复杂性与风险，都会影响实施采购的正式程度、广告范围与谈判深度。`,
      "💼 实践案例": `某大型设备采购项目收到5家供应商建议书。买方先召开投标人会议，逐一澄清采购SOW中关于验收标准与交付时间的疑问，并当场把补充说明以书面形式发放给全部5家供应商，确保信息一致。随后用筛选系统剔除未满足资质与财务门槛的2家，对剩余3家用加权评分法评价：技术方案权重40%、实施经验30%、价格20%、售后10%，综合得分最高者并非价格最低。买方团队（采购、法务、技术）与中选方进行谈判，应用BATNA——因另一家报价接近且性能相当，买方得以在价格与保修期上获得让步，最终签署含履约保函的固定总价合同，并更新资源日历与风险登记册。`,
    },
    keyConcepts: `- **投标人会议**：买方组织的统一答疑会，核心原则是所有卖方获得相同信息、公平透明；私下披露的信息必须同步给所有卖方。
- **建议书评价三方法**：加权评分法（按权重打分）、筛选系统（硬门槛先行淘汰）、独立成本估算比较（核查报价合理性）。
- **BATNA（最佳替代方案）**：谈判失败时我方的最优备选路径，决定谈判底线与议价能力，BATNA越强越主动。
- **谈判**：在合同授予前就范围、价格、条款进行协商，需正式授权与专业协作；非正式口头承诺不构成合同变更。
- **投标保函 vs 履约保函**：投标保函保证投标有效；履约保函保证卖方按合同履约，违约时买方可按条款索赔。
- **选定的卖方**：基于供方选择标准与谈判结果确定的供应商，不一定是最便宜的。
- **协议（合同）**：法律约束力的书面文件，明确双方权利、义务、交付与验收安排。
- **分包商管理**：若卖方将部分工作分包，买方需在合同中保留对分包商的批准权与监督权，确保分包工作满足项目要求。
- **公平公正原则**：对个别卖方私下披露的信息必须同步告知所有卖方。`,
    examTips: `- 投标人会议是高频考点：任何私下给某卖方补充的信息必须同步给所有卖方——出现某卖方向项目经理私下提问的情景时，正确做法是把回答共享给所有卖方。
- 建议书评价常考最具价值而非最便宜：加权评分后综合得分最高者中标，即使其价格不是最低；直接选最便宜通常是错误选项。
- 建议书评价三方法要能区分：加权评分是主方法，筛选系统用于先淘汰不合格者，独立成本估算用于核实报价异常。
- BATNA是谈判核心概念：题干出现谈判失败后还有别的选择、或谈判中掌握备选供应商信息时，指向BATNA，它能增强议价能力。
- 合同签署前必须有正式授权：项目经理不应独自决定合同条款，需采购与法务团队协作；口头承诺无效、必须书面确认。
- 投标保函与履约保函要分清：前者保证投标有效，后者保证合同履约。
- 易错点：实施采购的输出是选定的卖方加协议，合同在此过程中授予；合同授予前的选择属规划/实施，授予后的管理属控制采购。
- 分包商管理：当卖方提出分包时，买方保留批准权是正确做法，而不是无条件接受或直接拒绝。`
  },
  "proc-control-procurement": {
    overview: `【过程概述】控制采购过程属于监控过程组，其目的是管理采购关系，监督合同绩效，实施必要的变更与纠正措施，并最终关闭合同。该过程确保项目团队与供应商双方都按照合同条款履行职责，把供应商的交付活动与项目整体进度、质量、成本与风险目标对齐。该过程的关键收益是：确保采购活动符合合同要求，及时处理合同变更与索赔，在合同义务全部履行完毕后顺利完成合同收尾，并为组织沉淀采购经验。

控制采购覆盖合同全生命周期的管理：**绩效审查**——检查供应商是否按合同规定的范围、质量、进度与成本交付；**付款处理**——按合同约定的里程碑或付款周期处理供应商发票；**合同变更管理**——变更需双方正式协商并以书面合同变更令记录，不能单方面实施；**索赔管理**——记录、处理、监督有争议的变更或索赔；**合同关闭**——确认可交付物验收、文档归档、支付最终款项。对于提前终止的合同，需区分因便利终止与因违约终止，并按合同规定的程序与双方约定处理结算。

控制采购还运用多种监控技术：挣值分析（EVM）把供应商的进度与成本绩效与合同基准对比，判断其绩效是否符合预期；检查用于验证交付物是否满足合同要求；采购审计用于评估采购过程的有效性与效率；供应商绩效记分卡用于系统记录并评估供应商绩效，为未来采购提供依据。特别要注意：**合同收尾（Contract Closure）先于行政收尾（Administrative Closure）**——在结束项目或阶段过程完成之前，必须先完成所有合同的关闭。`,
    details: {
      "📥 输入 Inputs": `- **项目管理计划**：主要是**采购管理计划**，规定采购活动如何管理、合同变更与付款流程、供应商绩效评价方式；项目进度计划与成本基准用于判断供应商交付与付款是否与计划匹配。
- **项目文件**：包括经验教训登记册（借鉴以往合同管理经验）等，提供管理合同所需的历史与背景信息。
- **采购文档**：包括合同、合同变更令、卖方建议书、付款记录、往来函件、索赔记录等全套采购文件，是监督合同履约与处理争议的依据。
- **协议（合同）**：买卖双方之间具有法律约束力的协议，其中规定的范围、交付时间、质量标准、付款条件、验收标准与违约条款是控制采购的基准。
- **批准的变更请求**：已通过实施整体变更控制过程审批的变更，需在控制采购中执行并反映到合同管理（如调整付款、交付或验收安排）。
- **工作绩效数据**：供应商履约的原始数据，如已完成交付物的数量与质量、实际付款额、进度与成本的实际数据，是绩效审查与挣值分析的输入。
- **事业环境因素**：包括组织的采购政策、合同管理程序、相关法律法规（合同、仲裁、诉讼法规）以及供应商市场状况。
- **组织过程资产**：包括合同管理与付款程序、历史合同绩效数据、索赔处理记录、供应商绩效评估模板等。`,
      "🔧 工具与技术 Tools": `- **专家判断**：由采购、法务、合同管理专家提供建议，用于判断合同履约偏差、处理合同变更与索赔、评估提前终止的后果。
- **索赔管理**：管理合同双方之间有争议的变更或索赔。索赔通常源于范围、进度、质量或成本方面的分歧，如卖方主张额外付款、买方主张违约赔偿。处理应遵循升级路径：**首先协商解决**（双方基于合同与事实沟通，力求互让）→协商不成进入**调解或其他替代争议解决（ADR）**（第三方中立调解）→仍无法解决则**仲裁或诉讼**。诉讼是最后手段，成本高、耗时长，优秀做法是在合同中事先约定争议解决方式（如约定仲裁）。
- **数据分析**：用于评估合同绩效，主要包括：
  - **挣值分析（EVM）**：通过进度偏差（SV）、成本偏差（CV）、进度绩效指数（SPI）、成本绩效指数（CPI）等指标，量化供应商履约与合同基准的偏差，判断是否需采取纠正措施。
  - **趋势分析**：观察供应商绩效的时间变化趋势，预测未来的履约风险。
  - **其他绩效分析**：计算供应商交付准时率、质量合格率等指标，评估履约质量。
- **检查**：由买方或其代表对供应商的工作或可交付物进行审核与检验，验证其是否满足合同规定的规格、质量标准与数量；检查结果决定是否接受交付物，是付款与验收的前提。检查可在生产现场、交付点或验收时进行。
- **审计**：**采购审计（Procurement Audit）**是对采购过程（从规划到收尾）进行系统性审查，评估其有效性、效率与合规性，识别改进机会并总结经验教训，从而为未来采购提供指导。注意：采购审计评估的是过程，而检查验证的是交付物——两者目的不同。`,
      "📤 输出 Outputs": `- **采购关闭**：确认合同项下所有工作与可交付物已验收、所有款项已结清、合同义务已履行完毕后正式关闭合同。采购关闭先于行政收尾，其成果包括验收文件、合同结算记录与归档文档。
- **工作绩效信息**：将供应商履约的工作绩效数据经挣值分析、趋势分析等处理后形成的信息（如供应商CPI/SPI、偏差与趋势、验收结论），供监控项目工作过程评估整体绩效。
- **采购文档更新**：更新合同执行过程中的全部记录，包括合同变更令、付款记录、验收报告、往来函件、索赔与争议解决记录等，作为合同结算与经验教训的原始依据。
- **变更请求**：当合同履约出现偏差需要调整时（如范围调整、工期变更、价格调整、供应商更换），提出变更请求（纠正措施、预防措施或缺陷补救），提交实施整体变更控制过程审批；合同变更必须经双方正式协商并以**书面合同变更令**记录，不能单方面实施。
- **项目管理计划更新**：主要是**采购管理计划**更新，反映合同管理程序、供应商绩效评价方法的变化；若变更影响成本或进度，还需更新成本基准与进度计划。
- **项目文件更新**：主要是**经验教训登记册**更新，记录合同管理中的教训（如供应商绩效问题、合同条款缺陷、谈判经验）。
- **组织过程资产更新**：包括供应商绩效记分卡更新、历史合同与供应商数据库更新、合同管理经验教训沉淀，供未来项目采购参考。`,
      "🔗 与其他过程的相互作用": `控制采购是采购管理链的收尾环节，与监控项目工作、实施整体变更控制、结束项目等过程紧密衔接。输入方面：它使用规划采购的采购管理计划、实施采购的协议，以及执行过程中产生的工作绩效数据。输出方面：形成的工作绩效信息供监控项目工作过程进行整体绩效评估；提出的变更请求进入实施整体变更控制过程，审批后返回本项目执行；**采购关闭**完成后才可进入结束项目或阶段的行政收尾——合同收尾必须先于行政收尾。控制采购中发现的供应商问题会更新风险登记册并触发风险应对；绩效审查与索赔结果同时为后续采购（再规划）提供经验。整个采购管理形成规划、实施、控制、关闭的完整闭环。`,
      "✂️ 裁剪考虑": `- **预测型**：合同管理较正式，按合同约定的里程碑定期开展绩效审查与检查，付款与验收程序严谨，索赔与变更流程书面化程度高。
- **适应型（敏捷）**：供应商深度协作、迭代交付，控制更轻量高频，如迭代验收与持续反馈，合同常用工料或可调整条款，变更处理灵活但仍需书面记录。
- **混合型**：固定范围部分按正式合同里程碑控制，敏捷部分按迭代节奏轻量控制，两类合同的审查与验收频度不同。
- **其他因素**：采购金额与合同风险、供应商绩效历史、组织合同管理制度、法务要求等决定控制采购的严格程度；高风险大额合同需要更高频的绩效审查与更严格的检查与审计。`,
      "💼 实践案例": `某总价合同项目在执行中，供应商在第三季度出现交付延迟与质量问题。控制采购过程中，项目经理先用挣值分析发现供应商的SPI与CPI持续低于1（进度与成本双偏差），通过趋势分析确认偏差在扩大；随即安排现场检查，发现部分交付物未达验收标准。项目经理把问题记入问题日志，与供应商协商后发出书面合同变更令调整部分交付时间，并启动索赔管理——供应商主张因需求变更要求追加付款，经协商双方达成折中方案；同时将关键供应商履约风险更新进风险登记册。合同完成后，项目组进行采购审计，评估整个采购过程的有效性并总结教训，更新供应商绩效记分卡；在完成所有可交付物验收、结清款项并归档合同文档后正式关闭合同，随后才进入行政收尾。`,
    },
    keyConcepts: `- **合同收尾 vs 行政收尾**：合同收尾先于行政收尾；前者关闭所有合同（验收、结算、归档），后者关闭整个项目或阶段。
- **索赔管理升级路径**：协商→调解/替代争议解决（ADR）→仲裁/诉讼，诉讼是最后手段。
- **合同提前终止两类**：**因便利终止**（Termination for Convenience）——买方在无违约情况下按合同约定提前结束合同；**因违约终止**（Termination for Default）——一方违约时另一方依约终止。两者都应遵循合同规定程序并处理结算。
- **挣值分析（EVM）**：用SV/CV/SPI/CPI量化合同绩效与基准的偏差，用于采购绩效评估。
- **供应商绩效记分卡**：系统记录供应商在成本、质量、交付、响应等方面的绩效评分，为未来采购选择提供依据。
- **合同变更令**：双方正式协商并书面签署的合同变更文件，是合同变更生效的唯一形式，不能单方面实施。
- **检查 vs 审计**：检查验证交付物是否满足合同要求（验收用）；审计评估采购过程的有效性与效率（改进用）。
- **采购关闭**：确认所有工作与可交付物验收、款项结清、文档归档后正式关闭合同。`,
    examTips: `- 合同收尾先于行政收尾是必考点：情景题中问项目收尾前必须先做什么，应选先完成所有合同关闭，再执行行政收尾。
- 合同变更是高频陷阱：与其他变更不同，合同变更不能单方面实施，必须双方正式协商并以书面合同变更令记录；出现卖方口头同意变更时，正确做法是书面确认并更新合同。
- 索赔首选协商解决：处理索赔的优先级为协商→调解/ADR→仲裁/诉讼；直接选诉讼通常是错误选项，除非题干明确协商已失败。
- 合同提前终止两类要分清：无违约情况下买方选择提前结束=因便利终止；一方违约被终止=因违约终止。
- EVM用于采购绩效：供应商CPI/SPI低于1说明履约偏差，需采取纠正措施或提出变更。
- 检查与审计别混淆：检查针对交付物（验收用），审计针对过程（改进用）。
- 采购关闭三要素缺一不可：验收、结算、归档；付款不是合同关闭的充分条件。
- 易错点：工作绩效数据是控制采购的输入，工作绩效信息是输出——数据经分析处理后才能用于决策。`
  },
};

export default KNOWLEDGE_CONTENT;
